t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "Zurück nach Norden an {area:918} vorbei zur Mine: Koboldbuddler arbeiten drinnen.",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Abtrünnige Hexer der Defias lagern an den Ufern von {area:86}; sie lassen auch die Roten Leinenkopftücher fallen. {object:56} liegt im Murlocdorf am Nordostufer.",
		["Fill the vial at the farm's well"] = "Füll die Phiole am Brunnen des Hofs",
		["Fill the vial at the well"] = "Füll die Phiole am Brunnen",
		["Follow the hills south to the tower."] = "Folge den Hügeln nach Süden zum Turm.",
		["Follow the road from Elwynn into {zone:1436}: the Furlbrows sit by their burned farm, the first one on the road. Pick up oats from any {object:2724} you pass on the loop: the rest are gathered in the fields here on the way back."] = "Folge der Straße von Elwynn nach {zone:1436}: Die Furlbrows wohnen bei ihrer abgebrannten Farm, die erste Familie an der Straße. Nimm Hafer von jedem {object:2724} mit, an dem du auf der Runde vorbeikommst: Der Rest wird auf dem Rückweg auf den Feldern hier gesammelt.",
		["For {npc:266} in {area:69}, Redridge"] = "Für {npc:266} in {area:69}, Rotkammgebirge",
		["Gnoll Paws"] = "Gnolltatzen",
		["Harvest Watchers"] = "Erntebehüter",
		["Head to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Geh nach {zone:1453}. Dort gibt es keinen Schamanen-Lehrer: Nimm die {area:2257} vom {object:28027} nach {zone:1455}, trainiere bei {npc:258098} und fahre dann die Straßenbahn zurück für das Schiff.",
		["It lies by the river north-west of the logging camp."] = "Er liegt am Fluss nordwestlich des Holzfällerlagers.",
		["Kobold Diggers"] = "Koboldbuddler",
		["Level 12, 14 and 16 spells"] = "Zauber der Stufen 12, 14 und 16",
		["Longshore Murloc Gills"] = "Murlockiemen von Longshore",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "Nur wenn du in Elwynn {item:1972} geplündert hast: Rechtsklicke sie",
		["Red Linen Bandanas"] = "Rote Leinenkopftücher",
		["Riverpaw Miners"] = "Minenarbeiter der Flusspfoten",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Gnolle der Flusspfoten lagern in den Hügeln westlich von {area:86}; {quest:91725} liegen in ihren Lagern.",
		["Sacks of Oats in the fields around the farm"] = "Haferbündel auf den Feldern rund um die Farm",
		["Shaman training"] = "Schamanenausbildung",
		["South along the road, past the fork. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way."] = "Südlich der Straße, vorbei an der Gabelung. {npc:233} steht draußen, {npc:235} im Haus, {npc:253395} in der Scheune im Westen. Junge Hauerzähne und Fleischreißer streifen um die Felder der Farm: Beginne unterwegs mit Lebern und dem Eintopffleisch.",
		["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "Nach Südwesten zur Küste, westlich von {area:918}. Minenarbeiter der Flusspfoten arbeiten im Steinbruch.",
		["The bridge"] = "Die Brücke",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "Das Lager liegt nordöstlich der Brücke. Kleinholzbündel liegen rund um das Lager und in den Wäldern nördlich davon.",
		["The gnoll camps"] = "Die Gnolllager",
		["The gnoll hills"] = "Die Gnollhügel",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "Die Mine liegt südwestlich der Gnolllager. {item:247816} liegen nahe dem Eingang; Koboldgeomanten halten die Tunnel.\nVorsicht: {npc:471} (7-10), die Minenspinnen (7-9) und {npc:248474} (7) sind Elitegegner tief in der Mine: Zieh die Kobolde nahe dem Eingang einzeln und zieh dich zurück, wenn eine Elite kommt; zu zweit sind sie leichter.",
		["The {area:113}"] = "{area:113}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{item:2449} für Das Heilmittel sammeln (6123) in {zone:1439}: {npc:1313}, Alchemiebedarf; Kräuterkundige pflücken es stattdessen dort",
		["{item:6529}, from {npc:5494}"] = "{item:6529}, von {npc:5494}",
		["{item:729}: Fleshrippers"] = "{item:729}: Fleischreißer",
		["{npc:1416}: his package for {npc:1343} in {zone:1432}, later on the route"] = "{npc:1416}: sein Paket für {npc:1343} in {zone:1432}, später auf der Route",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234} und {npc:821} stehen oben auf dem Steinturm. {npc:491} ist im Turm, {npc:878} auf der Südseite des Hügels, neben dem Gasthaus und {npc:523}, dem Greifenmeister.",
		["{npc:237}: Humans may have it already from {npc:963} in Elwynn"] = "{npc:237}: Menschen haben es vielleicht schon von {npc:963} in Elwynn",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092}, neben {npc:878}",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494} verkauft Angelbedarf am Kanal direkt westlich von {object:2096}; {npc:267118} angelt am Hafen, auf dem Weg zum Schiff.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, Magiersanktum: {quest:1861}",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["At the {area:2362}"] = "Am {area:2362}",
		["Back north-east into the mountains to the crystal."] = "Zurück nach Nordosten in die Berge zum Kristall.",
		["Bears and the Blackwood camp"] = "Bären und das Lager der Schwarzfelle",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Pfadfinder und Windsprecher der Schwarzfelle halten das Lager südöstlich von {area:442}.",
		["Blackwood furbolgs"] = "Furbolgs der Schwarzfelle",
		["By the bonfire closest to the river: summons Xabraxxis"] = "Am Lagerfeuer, das dem Fluss am nächsten ist: beschwört Xabraxxis",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Klettere östlich von {area:447} in die östlichen Berge; der {object:175524} liegt auf einem Felsvorsprung.",
		["Crawler Legs"] = "Kriecherbeine",
		["East of Buzzbox 323, {npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}.\nCareful: Dark Strand Voidcallers (28-29) with their voidwalkers and {npc:3660} (31) stand in the tower itself: take the parchments from the Fanatics south of it and keep away from the tower."] = "Östlich der Dröhnkiste 323 versteckt sich {npc:3661} am Fuß des Turms zwischen den Fanatikerinnen des dunklen Strangs. Behalte seinen Brief für Delgren in {zone:1440}.\nVorsicht: Leerruferinnen des dunklen Strangs (28-29) mit ihren Leerwandlern und {npc:3660} (31) stehen im Turm selbst: Hol dir die Pergamente von den Fanatikerinnen südlich davon und halte dich vom Turm fern.",
		["Fill the tube at the moonwell in the village"] = "Fülle die Phiole am Mondbrunnen im Dorf",
		["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "Flieg von {area:442} nach {area:702} und nimm das Portal hinauf zu {npc:4217} im Gebiet {area:1658}.",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "Folge den Hügeln nach Norden zum Fluss {area:456} und hinauf zu den Fällen. Zwei weitere gestrandete Überreste liegen an der Nordküste: nahe dem Gebiet {area:443} und nördlich von {quest:954}.",
		["Grell Earrings"] = "Grell-Ohrringe",
		["Highborne Relics"] = "Hochgeborenenrelikte",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Töte Tollwütige Distelbären in den Hügeln östlich von {area:442} und geh dann hinauf zum Furbolglager südöstlich davon: Dort gibt es noch nichts zu töten.",
		["Moonstalker Fangs"] = "Mondpirscher-Fangzähne",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "Mondpirscher streifen durch die Hügel zwischen {quest:954} und dem Turm. {quest:1002} steht auf dem Hügel westlich des Turms.",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "Nach Norden durch die Hügel. {npc:3650} wartet in den Ruinen von {quest:954}; Wilde Grells und Üble Grimmlinge füllen sie, Satyrn der Deth'ryll den Ostrand. {quest:1001} steht an der Straße westlich der Ruinen; eine {quest:4723} liegt auf dem Weg zu ihm am Ufer.",
		["Plagued bears"] = "Verseuchte Bären",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "Tollwütige Distelbären streifen durch die Hügel gleich östlich von {area:442}. Benutze {quest:2139} an einem und führe ihn zu ihm zurück.",
		["Read the {object:17188}"] = "Lies {object:17188}",
		["Read the {object:17189}"] = "Lies {object:17189}",
		["The WANTED poster outside the inn"] = "Der Steckbrief vor dem Gasthaus",
		["The bay wrecks"] = "Die Wracks in der Bucht",
		["The beach"] = "Der Strand",
		["The cave and the {npc:6788}"] = "Die Höhle und die {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls."] = "Die Höhle liegt südlich der Fälle: Überall darin wachsen Schorfstängel, {item:5270} ganz hinten. {npc:6788} haust in den Hügeln südlich der Fälle.",
		["The flame burns in the south of {area:447}."] = "Die Flamme brennt im Süden von {area:447}.",
		["The furbolg camp south of the {area:456} keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the {item:12347} in your bags (the {item:12346} is filled at the {object:174795}), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the {item:12355} lies in his Demon Bag."] = "Das Furbolglager südlich des {area:456} hat seine Nuss-, Frucht- und Getreidevorräte an den Lagerfeuern. Hast du von jedem eine Probe und {item:12347} in der Tasche (die {item:12346} wird an der {object:174795} gefüllt), benutze die Schale am Lagerfeuer, das dem Fluss am nächsten ist: Sie beschwört Xabraxxis, den Satyr-Verderber, und {item:12355} liegt in seinem Dämonenbeutel.",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "Die Anhängerhälften liegen in {zone:1439} und {zone:1436}: später auf der Route",
		["The northern Blackwood camp"] = "Das nördliche Lager der Schwarzfelle",
		["The red crystal"] = "Der rote Kristall",
		["The skeletal turtle"] = "Die Skelettschildkröte",
		["The {object:16393}"] = "Die {object:16393}",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Gezeitenkriecher krabbeln unterhalb des Dorfes am Ufer entlang; {quest:983} steht am Strand gleich südlich der Anlegestelle. Dunkelküstendrescher schwimmen im seichten Wasser. {object:175207} liegt gleich südlich des Dorfes am Ufer.",
		["{item:12238}: fish from the pier"] = "{item:12238}: vom Steg aus angeln",
		["{item:12347}: fill the {item:12346} at the {object:174795}"] = "{item:12347}: Fülle die {item:12346} an der {object:174795}",
		["{item:12349}, at the waterfall"] = "{item:12349}, am Wasserfall",
		["{item:12355}, in {object:177624}"] = "{item:12355}, in {object:177624}",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: am Eingang der Höhle bei den Fällen",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, aus einem {object:177785} im See",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: Satyrn der Deth'ryll",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: Fanatikerinnen des dunklen Strangs",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} steht am Nordrand der Ruinen. Verfluchte und Zuckende Hochgeborene sowie {npc:2178} spuken dort; der Geist von {npc:3667} wandelt zwischen ihnen, die Eule {npc:270196} kreist östlich davon. Die beiden Schrifttafeln liegen in den Ruinen; eine {quest:4722} liegt westlich davon am Ufer.",
		["{npc:3644}, on the pier"] = "{npc:3644}, auf dem Steg",
		["{npc:3649}, north end of the village"] = "{npc:3649}, am Nordende des Dorfes",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: für {npc:1646} in {zone:1453}",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: Fülle das Probenfläschchen an den {area:445}",
} end)()
t.guides["forever/alliance/03-darkshore-return"] = (function() return {
		["Back south"] = "Zurück nach Süden",
		["Back to {npc:11802}"] = "Zurück zu {npc:11802}",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Eskortiere sie aus der Gleve; Therysil nimmt die Abgabe in {zone:1440} entgegen",
		["Fine Moonstalker Pelts"] = "Feine Mondpirscherpelze",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Folge der Küste nach Nordosten zum Gebiet {area:443}. {quest:951} liegen in den Ruinen; Myrmidonen, Zauberhexerinnen und Krieger der Sturmschuppen halten sie, und Tierbändigerinnen der Sturmschuppen laufen am Ufer entlang.",
		["Follow the road north."] = "Folge der Straße nach Norden.",
		["Grizzled Scalps"] = "Ergraute Skalpe",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "Ergraute Distelbären streifen durch die Hügel rund um den Hain; {quest:1003} steht westlich davon zwischen ihnen.",
		["Moonstalker Sires prowl the woods around the glaive. The {object:12666} sits at the bottom of the crater; {npc:3584} stands on its north side. For {quest:948}'s quest, use the {item:5251} at the bottom of the crater: it makes the {object:10076}, and you hand the quest in to the bowl."] = "Mondpirscherpatriarchen streifen durch die Wälder rund um die Gleve. Der {object:12666} steht am Grund des Kraters; {npc:3584} steht an seiner Nordseite. Für die Quest von {quest:948} benutzt du die {item:5251} am Grund des Kraters: Sie erzeugt die {object:10076}, und du gibst die Quest an der Schale ab.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "Nachtelfen fliegen von {area:442} nach {area:702}; Himmelsgeborene nehmen das Boot von der Anlegestelle in {area:442} und holen sich dort die Flugroute von Rut'theran. Nimm das Portal hinauf zu {npc:4217} im Gebiet {area:1658}.",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "Nur falls ein Jünger oder Rohling {item:5352} gedroppt hat: Rechtsklicke darauf",
		["She gives you the {item:15826}"] = "Sie gibt dir die {item:15826}",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "Die Lunarfungusblüten wachsen in den Moonkinhöhlen in den Hügeln gleich östlich von {area:442}; die Moonkin dort sind reizbar. {item:2449} erfordert {skill:182}: Kräuterkundige pflücken es überall in {zone:1439}, alle anderen bringen es aus {zone:1453} ({npc:1313}) oder aus dem Auktionshaus mit.",
		["The WANTED poster"] = "Der Steckbrief",
		["The naga"] = "Die Naga",
		["The relics of the Barrow Dens"] = "Die Relikte der Grabhügel",
		["The {area:443}"] = "Zum Gebiet {area:443}",
		["The {object:10076}"] = "Die {object:10076}",
		["The {object:12666}"] = "Der {object:12666}",
		["{item:15851} and {item:2449}"] = "{item:15851} und {item:2449}",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: die {object:177792} unter Wasser vor der Nordküste, westlich der Ruinen",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: Twilight-Jünger und -Rohlinge",
		["{npc:10323}'s beach"] = "Der Strand von {npc:10323}",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}: der Willkommensgruß von Sheldras",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}: Benutze die {item:15826} an ihnen; sie streifen durch ganz {zone:1439}",
		["{npc:3616}, at the Grove"] = "{npc:3616}, am Hain",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667} versteckt sich auf der kleinen Insel vor den Ruinen. Die Schlüsselteile droppen Riesige Waldschreiter (oben), Murlocs der Grauflossen (Mitte) und Tobende Riffkriecher (unten).",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}: {npc:10219} bietet sie an, sobald alle neun gestrandeten Überreste abgegeben sind",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (Nachtelfen) und der {npc:272054} (Himmelsgeborene) warten im Süden von {area:493}. Die drei Relikte liegen östlich davon in {area:2363}. Berichten aus den ersten Wochen zufolge gibt ein Relikt keine Beute, während ein anderer Spieler es plündert: Warte einen Moment und versuch es erneut.",
} end)()
t.guides["forever/alliance/03-loch-modan"] = (function() return {
		["Boat to {area:150}"] = "Schiff nach {area:150}",
		["Cathedral of Light"] = "Kathedrale des Lichts",
		["Fly to {area:1537}"] = "Flieg nach {area:1537}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Through the South Gate tunnel and west along the road to {zone:1455}. Know the {zone:1455} flight path already? Fly from {area:144} instead: these two waypoints drop once you are in the city."] = "Durch den Tunnel am Südtor und auf der Straße nach Westen bis {zone:1455}. Kennst du die Flugroute nach {zone:1455} schon? Dann flieg stattdessen ab {area:144}: Diese beiden Wegpunkte entfallen, sobald du in der Stadt bist.",
		["Use the {item:6866} on {npc:6172}"] = "Benutze {item:6866} an {npc:6172}",
		["You have the {area:1537} flight path from {zone:1426}: back north to {area:144}'s gryphons, quicker than walking through the tunnel and across {zone:1426}."] = "Die Flugroute nach {area:1537} kennst du aus {zone:1426}: zurück nach Norden zu den Greifen von {area:144}, schneller als durch den Tunnel und quer durch {zone:1426} zu laufen.",
		["{area:144} flight master"] = "Flugmeister in {area:144}",
		["{area:20} and the Defias hills"] = "{area:20} und die Hügel der Defias",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}, aus den Kisten rund um {area:20}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: Hauer der Rotkammgnolle",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: Abtrünnige Hexer der Defias",
		["{npc:1343}: {npc:1416}'s package"] = "{npc:1343}: das Paket von {npc:1416}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, bei {object:32372}",
