		["Murloc heads"] = "Murlocköpfe",
		["North-east to the {area:1038}: {npc:271338} stands at the gates (use the {item:279996})."] = "Geh nach Nordosten zu den {area:1038}: {npc:271338} steht an den Toren (benutze {item:279996}).",
		["Snapjaws"] = "Schnappkiefer",
		["Syndicate camp"] = "Syndikatslager",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "Die Schnappkiefer-Schildkröten sonnen sich am Fluss östlich von {area:271}, südlich von {area:272} (Horde).",
		["The cheese shop in the {object:2096}."] = "Der Käseladen im {object:2096}.",
		["The naga hold the shore south-east of {area:271}."] = "Die Naga halten das Ufer südöstlich von {area:271}.",
		["The yetis live in the cave in the hills north of {area:271}, on the way north to the Syndicate camp.\nStay in the {area:277}: the cave further north has Mountain and Giant Yetis (32-34) in pairs and {npc:13602}, a level 36 elite."] = "Die Yetis leben in der Höhle in den Hügeln nördlich von {area:271}, auf dem Weg nach Norden zum Lager des Syndikats.\nBleib in {area:277}: In der Höhle weiter nördlich gibt es Berg- und Riesenyetis (32-34) in Paaren und {npc:13602}, eine Elite der Stufe 36.",
		["Torn Fin murlocs"] = "Murlocs der Fetzenflossen",
		["West along the road to Menethil."] = "Nach Westen die Straße entlang nach Menethil.",
		["Yeti cave"] = "Yetihöhle",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, von {npc:2381}",
		["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}, im Gasthaus: für {area:35} (04-stranglethorn-vale)",
		["{npc:2382}: the lions come later"] = "{npc:2382}: Die Löwen kommen später",
		["{npc:2695}: for King Magni, on the same {zone:1455} stop"] = "{npc:2695}: für König Magni, beim selben Halt in {zone:1455}",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: Seine Spur führt nach Arathi",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} wartet in der Taverne „Zum Schwein und Pfeife“ in {object:2100}; er und seine zwei Schläger greifen dich an, hören aber auf, sobald sie besiegt sind.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479} bildet in {object:2100} Krieger aus, neben der Taverne „Zum Schwein und Pfeife“. {npc:6236} wartet auf {area:720} im {zone:1413}, auf dem Weg nach {area:392} viel später (40-50/01).",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: für {npc:2104}",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort {npc:5644}"] = "{npc:5644} eskortieren",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Folge der Straße nach Westen an {area:460} (Horde) vorbei und nach Südwesten durch {area:465} nach {zone:1443}; {area:608} liegt oben am Pass.",
		["For {npc:5638}, at the end of this guide"] = "Für {npc:5638}, am Ende dieses Guides",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Führ {npc:5644} aus der Festung; sie geht ihrer Wege, sobald ihr draußen seid. {npc:5642} nimmt die Abgabe am Ende des Guides in {area:608} entgegen.",
		["Malem chest"] = "Truhe der Malems",
		["Out of Thunder Axe Fortress"] = "Raus aus der Festung Thunder Axe",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Die Kolkar streifen über die Ebenen um {area:609}; ihre Ohren sind für {npc:5752}.",
		["The chest lies in the ruins south-west of {area:608}."] = "Die Truhe liegt in den Ruinen südwestlich von {area:608}.",
		["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "Das Schiffswrack liegt direkt südwestlich von {npc:11863}s Turm; seine Truhe steht neben {object:177787}.",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "{npc:11596}s Lager liegt an der Straße südlich von {area:609}, beim {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "{npc:11863}s Turm steht auf dem Hügel westlich von {area:599}: Nimm zuerst seine Quest an, das Zepter, das er will, ist in der Festung.",
		["{npc:5396}, beside {npc:5752}"] = "{npc:5396}, neben {npc:5752}",
		["{npc:5638}: the satchel lies off the north-west coast, on the south loop at the end of 30-40 (06-badlands): keep it"] = "{npc:5638}: Die Tasche liegt vor der Nordwestküste, auf der Südschleife am Ende von 30-40 (06-badlands): Behalte sie",
		["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}: Die Truhe des Wracks liegt unterhalb von {npc:11863}s Turm, auf dem Weg nach {area:599}",
		["{npc:5643} and the Seer"] = "{npc:5643} und der Seher",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} versteckt sich in der Festung der Burning Blade südwestlich von {area:608}.",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Boat to {area:150}"] = "Schiff nach {area:150}",
		["East through the canyons. {area:484}, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth."] = "Nach Osten durch die Schluchten. {area:484}, ein Hordenlager mit Wachen, liegt hier auf dem Tafelberg: Bleib unten in der Schlucht und halte großen Abstand zum Fuß seiner Aufzüge.",
		["Fly to Theramore"] = "Flieg nach Theramore",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Folge den Schluchten nach Osten zur Salzebene. Die Goblins und Gnome der {area:2240} sind neutral und geben beiden Fraktionen Quests.",
		["For {quest:1132} in Theramore's inn, where this guide's boat goes"] = "Für {quest:1132} im Gasthaus von Theramore, wohin das Boot dieses Guides fährt",
		["For {quest:5762} in Stranglethorn, later"] = "Für {quest:5762} im Schlingendorntal, später",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "Auf der Straße nach Süden durch das {zone:1413} lagert {npc:6244} östlich der Straße, nordöstlich von {area:378}; komm von Osten und halte dich von den Wachen der Horde fern.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Die Murlocs der Blaukiemen am Strand südwestlich von Menethil tragen die Blöcke.",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "Der Flugmeister steht am Tor von {area:514}; {npc:5083} und {npc:4964} sind in der Zitadelle.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "Das Wrack der Flying Osprey liegt im seichten Wasser südlich der Burg.",
		["Theramore"] = "Theramore",
		["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217} steht in der {area:2104} südlich der Burg, wo auch {npc:4963} und {npc:5082} warten.",
		["{npc:4455} stands by {area:2103}'s door, just north of the flight master."] = "{npc:4455} steht an der Tür von {area:2103}, direkt nördlich des Flugmeisters.",
		["{quest:1132}, inside the inn in the north of town"] = "{quest:1132}, im Gasthaus im Norden der Stadt",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: in {zone:1440}, auf dem Weg nach {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: der Inkubus, neben dem Sukkubus; das {item:190309} liegt nahe {quest:1738}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Zurück nach Süden an Nesingwary vorbei: Panther und Schlingendornraptoren laufen auf den Lichtungen westlich des Lagers Richtung Küste; die Alten Schlingendorntiger halten die Hügel im Südwesten.",
		["Both roam the grass around the camp and along the road north."] = "Beide streifen durch das Gras um das Lager und entlang der Straße nach Norden.",
		["Down to {area:35}"] = "Hinab nach {area:35}",
		["Druid training"] = "Druidentraining",
		["Fly to {area:42}"] = "Flieg nach {area:42}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Folge der Hauptstraße durch den ganzen Dschungel nach Süden, vorbei an der Abzweigung nach {object:3202}, bis {area:35} am Südkap.",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "Nimm vom {zone:1431} die Straße nach Süden ins Schlingendorntal; die Zelte der Jäger stehen gleich westlich der Straße hinter der Abzweigung zum {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluckser, ein seltener Murloc an der Küste westlich des Lagers, lässt den {item:4614} fallen: Nimm ihn mit, falls du ihm begegnest",
		["Panthers, raptors and elder tigers"] = "Panther, Raptoren und Alte Tiger",
		["River Crocolisks swim the river by the {area:99}."] = "Flusskrokilisken schwimmen im Fluss beim {area:99}.",
		["River crocolisks"] = "Flusskrokilisken",
		["Stranglethorn Tigers"] = "Schlingendorntiger",
		["Take the road north; the camp sits in the hills to the west.\n{npc:738} offers {quest:215} only while he is out of the camp: about every half hour he walks down the path to the road, where two Kurzen's Agents ambush him. Help him kill them and take the quest at once, before he walks back up. He isn't there? Leave it: the guide passes {quest:200}, which follows from it, as well."] = "Folge der Straße nach Norden; das Lager liegt in den Hügeln im Westen.\n{npc:738} bietet {quest:215} nur an, solange er außerhalb des Lagers ist: Etwa jede halbe Stunde geht er den Pfad hinunter zur Straße, wo ihn zwei von Kurzens Agenten überfallen. Hilf ihm, sie zu töten, und nimm die Quest sofort an, bevor er wieder hinaufgeht. Er ist nicht da? Dann lass sie aus: Der Guide lässt auch die Folgequest {quest:200} aus.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Die ausgewachsenen Tiger streifen durch die Hügel gleich südlich und westlich des Lagers.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Die Alten Schlingendorntiger kommen später, auf dem Rückweg vom {area:99}",
		["The haunted island"] = "Die Spukinsel",
		["Young tigers and panthers"] = "Junge Tiger und Panther",
		["{item:190309}, north of {area:413}"] = "{item:190309}, nördlich von {area:413}",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, aus einer Kiste von {object:263}",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, oben in der Taverne",
		["{npc:469}, in the hut"] = "{npc:469}, in der Hütte",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, aus {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} sammelt die {item:2755}: Die Seiten lässt fast jeder Humanoide im Dschungel fallen. Füg die Seiten unterwegs zu Kapiteln zusammen.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} und die Schmetterschwänze",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, der große Tiger, haust auf der Hügelkuppe südwestlich des Lagers; Schmetterschwänze laufen südlich davon, auf dem Weg nach {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, in der Taverne",
		["{npc:738}, at the foot of the path"] = "{npc:738}, am Fuß des Pfads",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: Sieh dich einfach im Lager der Jäger um",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["East to the {area:99}, on the way back to Nesingwary's camp."] = "Nach Osten zum {area:99}, auf dem Rückweg zu Nesingwarys Lager.",
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "Nach Osten zu {area:101}: Herods Aufzeichnungen liegen in einer Hütte auf der Westseite.",
		["Fly to {area:42}"] = "Flieg nach {area:42}",
		["For Archmage Ansirem in {zone:1416}"] = "Für Erzmagier Ansirem im {zone:1416}",
		["For characters of 35 to 36, but several quests here are level 37-41: on purpose, for their experience. {quest:205}'s Skullsplitter trolls are 39-42, so pull them one at a time."] = "Für Charaktere der Stufe 35 bis 36, aber mehrere Quests hier sind Stufe 37-41: mit Absicht, wegen ihrer Erfahrung. Die Trolle der Skullsplitter für {quest:205} sind 39-42, also zieh sie einzeln.",
		["North along the coast to the ruins on the hill: the last two tablets lie there. Pick up Green Hills pages as they drop."] = "Nach Norden die Küste entlang zu den Ruinen auf dem Hügel: Dort liegen die letzten beiden Tafeln. Sammle Seiten aus dem Grüne-Hügel-Almanach ein, wenn sie fallen.",
		["Skullsplitter trolls"] = "Skullsplitter-Trolle",
		["Snapjaw Crocolisks"] = "Schnappkieferkrokilisken",
		["South from the compound to {area:37}: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals, and the Shadowmaw Panthers prowl stealthed in the jungle south and east of it."] = "Vom Lager nach Süden zum {area:37}: Die Geologen der Venture Co. in den Lagern an seinem Ufer tragen die Gerommelten Kristalle, und die Schattentatzenpanther schleichen getarnt im Dschungel südlich und östlich davon.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Die Skullsplitter-Trolle halten die Ruinen östlich der Straße zwischen Nesingwary und {object:3202}.",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "Die Spukinsel liegt direkt vor der Küste westlich der zweiten Tafel: Die Geringen Wasserelementare steigen aus dem Wasser um sie herum.",
		["The jungle ruins"] = "Die Dschungelruinen",
		["The {area:102}"] = "Die {area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west."] = "Nach Westen durch den Dschungel zu den Trollruinen: Jede birgt eine Steintafel der Trolllegenden, die ersten beiden in den Ruinen südwestlich von Nesingwarys Lager, die letzten beiden auf dem Hügel im Nordwesten.",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, oben in der Taverne",
		["{npc:718}: the Shadowmaw Panthers prowl around {area:37}, after {area:101}"] = "{npc:718}: Die Schattentatzenpanther streifen um {area:37} umher, nach {area:101}",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: für {npc:773} in {area:35}",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773}, oben: Diese optionale Quest braucht vier {item:4278}. Bau Geringe Blutsteinablagerungen in {zone:1417} mit {skill:186} 75 ab, kauf das Erz im Auktionshaus oder frag einen befreundeten Bergarbeiter. Die Kobolde lassen es nicht fallen; überspring diese Quest, wenn du nicht an das Erz kommst.",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks stealthed on the edge of {area:271}, and few players find him. If you spot him, kill him and read the contract he carries: {npc:2276} takes it. Don't wait for him: the rest of this step doesn't need him."] = "Ein {npc:2434} lauert getarnt am Rand von {area:271}, und nur wenige Spieler finden ihn. Wenn du ihn entdeckst, töte ihn und lies den Vertrag, den er bei sich trägt: {npc:2276} nimmt ihn an. Warte nicht auf ihn: Der Rest dieses Schritts braucht ihn nicht.",
		["Back west through {zone:1430} to {area:42}."] = "Zurück nach Westen durch {zone:1430} nach {area:42}.",
		["Below ground"] = "Unter der Erde",
		["Crushridge ogres"] = "Crushridge-Oger",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals. {quest:1392} walks a long path through the ruins: if you meet him, kill him, his cudgel starts a quest for {npc:1776}. Don't wait for him."] = "Auf der Straße nach Osten zu {area:76}. Gegner vom Typ {npc:256028} lassen die Kristalle fallen. {quest:1392} läuft einen langen Weg durch die Ruinen: Triffst du ihn, töte ihn, sein Knüppel startet eine Quest für {npc:1776}. Warte nicht auf ihn.",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "Nach Osten von {quest:681} quer durch den Norden des Hochlands; die Splitter glitzern auf dem Hügel bei {area:333}, nördlich von {area:314}.",
		["Fly to {area:271}"] = "Flieg nach {area:271}",
		["Fly to {area:42}"] = "Flieg nach {area:42}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Folge der Straße von {area:287} nach Osten über {area:1057} nach {area:320}.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings. {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps in the uplands north and north-west of the village."] = "Folge der Straße von {area:271} nach Norden in die Berge. Berglöwen streifen über die Hänge; das Syndikat in {area:280} trägt die Siegelringe. {npc:2306} (40) taucht jeweils an einem Ort auf: im Keller des Gasthauses von {area:280} oder in einem der Zeltlager des Syndikats im Hochland nördlich und nordwestlich des Dorfes.",
		["Follow the road north to the draenei of the {area:657}."] = "Folge der Straße nach Norden zu den Draenei in {area:657}.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Für {npc:1440} in {zone:1453}: behalten",
		["For {npc:2487} in {area:35}: keep it"] = "Für {npc:2487} in {area:35}: behalten",
		["For {npc:2542} in {area:35}: keep it"] = "Für {npc:2542} in {area:35}: behalten",
		["For {npc:2711} in {area:271}"] = "Für {npc:2711} in {area:271}",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "Nimm von {zone:1455} aus den Tunnel nach Osten durch {zone:1426} nach {zone:1432} und folge der Straße nach {area:144}.",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "Nach Nordwesten aus dem Witherbark-Tal hinaus; {npc:2712} und {npc:2713} lagern in den Hügeln direkt nördlich von {area:314}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Nur wenn Gluckser dir im Schlingendorntal den Anhänger gegeben hat",
		["Phizzlethorpe"] = "Phizzlethorpe",
		["South from the {object:2691}, past {area:314}, to {area:317} in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk."] = "Nach Süden vom {object:2691} an {area:314} vorbei nach {area:317} in den Hügeln: Die Hexendoktoren der Witherbark stehen zwischen den Hütten und die Schattenjäger der Witherbark bewachen das hintere Ende des Tals. Jeder Troll kann einen Stoßzahn fallen lassen.",
		["South-east along the loch to the dig site."] = "Nach Südosten am See entlang zur Ausgrabungsstätte.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Nach Südwesten zum Lager der Kirin Tor am Seeufer westlich von {area:279}, gleich hinter der Grenze in {zone:1421}: Dort steht {npc:269127}. Erzmagier Ansirem steht südöstlich davon, bei der Kuppel.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Die Kobolde der Trockenstoppel graben in der Schlucht östlich von {area:321} (Horde); umgeh den Ort im Norden. Sie lassen die Körner von Myzrael fallen, nicht Krazeks Erz. Geringe Blutsteinablagerungen brauchen {skill:186} 75: Bau vier Erz ab, kauf sie im Auktionshaus oder frag einen befreundeten Bergarbeiter. Das Erz-Ziel ist optional; mach mit Myzrael weiter, wenn du es nicht bekommst. Vorsicht: Jede Koboldart rennt bei wenig Gesundheit um Hilfe (Kobolde bei 30%, Feldvermesser und Buddler bei 15%), was weitere anlocken kann.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "Der Kurier geht mit zwei Wachen die Straße von {area:314} nach Westen quer durch das Hochland bis etwa 24,45 und wieder zurück: Der Pfeil folgt der Straße nach Westen, bis du ihn triffst. Lock sie von der Straße weg.",
		["The shards lie at the far end of {area:318}."] = "Die Splitter liegen am hinteren Ende von {area:318}.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Die beiden Wracks liegen in der Bucht westlich der Bucht der Goblins. Die Karten und Logbücher sind darin; die Edelsteine liegen um sie herum auf dem Meeresgrund. Naga der Säbelflossen schwimmen in der ganzen Bucht.",
		["The western swamp"] = "Der westliche Sumpf",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "Dies sind Elitegegner: Eine Gruppe wird empfohlen, such dir Mitspieler dafür. {npc:2417} ist ein Elitegegner der Stufe 40: Die meisten Klassen schaffen ihn auf Stufe 42 allein, aber vielleicht brauchst du Hilfe. Lass ihn aus, wenn du allein bist: Die Route lässt dich die EP wieder hereinholen.\n{npc:2417} geht vom Pfeil aus nach Nordosten durch die Ruinen bis etwa 40,47 und zurück: Wenn er nicht am Pfeil ist, folge seinem Weg.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Junge Sägezahnkrokilisken, Trauerspinner und Sumpfjaguare streifen alle durch den Sumpf um die Straße.",
		["from {quest:1392}: he walks a path through the ruins"] = "von {quest:1392}: Er läuft einen Weg durch die Ruinen",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: Crushridge-Oger",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, Straße zum {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Kathedrale des Lichts",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, die Königliche Bibliothek in der Burg",
		["{npc:185335}, at the same circle"] = "{npc:185335}, am selben Kreis",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: drei Kleintiere zum Fangen im Arathihochland, in {zone:1443} und im Schlingendorntal",
		["{npc:2434}, if you spot him"] = "{npc:2434}, wenn du ihn entdeckst",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} und {npc:2713}",
		["{npc:2713}'s errand"] = "Auftrag von {npc:2713}",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} ist am Nordende des Refugiums eingesperrt. Befreie ihn und halte ihn auf dem Weg hinaus am Leben; seine Geldkassette wartet danach an der Straße.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} bindet den Inkubus an dich",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} wartet im Keller von {object:2164} in {object:2101}. Benutze {item:6913} am Beschwörungskreis dort und besiege den herbeigerufenen Sukkubus. Wenn du {quest:65602} angenommen hast, gib ihm auch {item:190309}, stelle sie am selben Kreis ab und besiege den Inkubus.",
		["{quest:65602}, if you took it"] = "{quest:65602}, falls du sie angenommen hast",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "Ein {npc:217590} krabbelt im {area:596} herum: Fang einen mit dem Werkzeug aus dem Einsteigerpaket für Entomologen von {npc:217412}.",
		["Fly to Theramore"] = "Flieg nach Theramore",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "Folge der Straße nach Norden zu {area:608}: {npc:5396} steht am Südende, {npc:5638} in der Mitte, {npc:1182} im Norden.",
		["Follow the road south to {area:2407}."] = "Folge der Straße nach Süden zu {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Folge der Straße nach Westen durch den Norden von {zone:1443} zu den Ruinen von {area:2405}. Dort steht {npc:11863}s Turm auf dem Hügel, auf dem Weg zum Wrack.",
		["Head back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Geh zurück nach Westen zur Straße und folge ihr nach Süden aus {zone:1432} durch den Pass in die {zone:1418}. {npc:2910} und {npc:2860} lagern Seite an Seite an der Grabungsstätte.",
		["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Geh nach Nordosten zur verlassenen Grabungsstätte; die Versorgungskiste liegt dort zwischen den Ogern der Staubbäuche.",
		["Head north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Geh nach Nordosten zu den Zwergenruinen im Norden der {zone:1418}; die Truhe steht zwischen den Zwergen der Schattenschmiede. {npc:2745} in der Nähe ist Elite: Gib ihm Raum.",
		["Head south to {area:345}."] = "Geh nach Süden zu {area:345}.",
		["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Geh nach Westen in die {area:1878}; {npc:2921} arbeitet in der Mitte bei seinen Maschinen.",
		["Lesser Rock Elementals"] = "Kleine Felselementare",
		["Maraudine centaurs"] = "Zentauren der Maraudine",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "Rackmores Truhe liegt gleich südöstlich von {object:177673}.",
		["Rock Elementals"] = "Felselementare",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "Ryedols nächster Auftrag führt nach {area:1517}: Überspring ihn.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Die Zentauren der Maraudine halten das {area:607} westlich des Friedhofs; jede Art lässt die Totems fallen.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Die Felselementare streifen südöstlich von {npc:2921} umher; Riesenbussarde und Alte Klippenkojoten teilen sich die Ebene westlich davon.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Die Zwerge der Schattenschmiede lagern gleich nördlich der Ausgrabungsstätte; die zerknitterte Karte liegt zwischen ihren Zelten. Tunnelgräber und Dunkelwirker tragen Ryedols Spitzhacke. Klippenkojoten streifen über die Hänge drumherum.",
		["The Slitherblade naga hold the north-west coast north of {npc:11863}'s tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}."] = "Die Naga der Schlitterklingen halten die Nordwestküste nördlich des Turms von {npc:11863}; Karnitols Tasche liegt davor auf dem Meeresgrund, und jeder Naga kann Rackmores goldenen Schlüssel fallen lassen. Schwimm hinaus nach {area:2406} vor der äußersten Nordspitze und benutze {item:15766} an {object:177673}: {npc:12369} (38) erscheint; töte ihn für {quest:6027}.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Das zerschlagene Skelett liegt gleich östlich der Oger, am Rand des Lagers der Steingrufttroggs; die Knochenknacker und Schamanen drumherum lassen die Splitter fallen. Theldurin sitzt weiter südlich beim zerstörten Lager.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Die Muscheln liegen an der Nordwestküste des Schlingendorntals, im nächsten Guide: Behalte sie",
		["The excavation crate"] = "Die Ausgrabungskiste",
		["The next guide starts in Theramore."] = "Der nächste Guide beginnt in Theramore.",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "Die Truhe des Schiffswracks liegt gleich südwestlich von {npc:11863}s Turm.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["To {area:2101}"] = "Zum {area:2101}",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Untote Verheerer streifen über die Knochenfelder südlich des Dorfs der Magram, östlich des Kovens; ganz im Südosten benutzt du {item:15848}, um die Schreckgespenster der Magram anzulocken.",
		["escort {npc:12277} back toward the graveyard"] = "eskortiere {npc:12277} zurück zum Friedhof",
		["for {npc:2786} in {zone:1455}: keep it"] = "für {npc:2786} in {zone:1455}: behalte sie",
		["for {npc:3980} in {area:271}: keep it"] = "für {npc:3980} in {area:271}: behalte sie",
		["for {npc:5637} in {zone:1455}: keep it"] = "für {npc:5637} in {zone:1455}: behalte sie",
		["{area:144} flight master"] = "Flugmeister in {area:144}",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, an {object:177673}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, von den Naga der Schlitterklingen",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, neben {npc:2921}",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} und {npc:2817} lagern zusammen im {area:1877}, mitten im {zone:1418}.",
		["{npc:5638}, if 30-40/02 didn't take it: the wreck lies below {npc:11863}'s tower"] = "{npc:5638}, falls 30-40/02 sie nicht angenommen hat: Das Wrack liegt unterhalb von {npc:11863}s Turm",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons."] = "{npc:6019} steht am Rand des {area:596}, südwestlich von {area:2407}; {object:176751} liegen zwischen den Skeletten.",
		["{object:177787} lies beside {object:35251}. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787} liegt neben {object:35251}. Sein silberner Schlüssel wird von den Trockenschnappkrebsen rund um das Wrack fallen gelassen; der goldene stammt von den Naga der Schlitterklingen an der Nordwestküste, als Nächstes.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "Stinki Ignatz",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4732} lehrt Menschen in {area:88} im östlichen {zone:1429}, neben den Pferden von {npc:384}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4753} lehrt Nachtelfen in {zone:1457}, neben den Säblern von {npc:4730}: das Boot vom {area:17203} nach {area:442}, dann der Flug nach {area:702}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt), etwa bei {npc:4732} in {area:88} im {zone:1429}. Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:4772} lehrt Zwerge in {area:803}, östlich von {area:131} an der Straße nach {zone:1432}, neben den Widdern von {npc:1261}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Mit 40 und 100 Gold kannst du reiten lernen, und dabei erhältst du ein Reittier. {npc:7954} lehrt Gnome in {area:189}, gleich östlich von {area:131}, neben den Roboschreitern von {npc:7955}. In Forever kann womöglich jedes Volk bei jedem Reitlehrer lernen (unbestätigt). Sammelobjekte, Reittiere · Stufe 40 listet alle Farben.",
		["Bloodsail camp"] = "Lager der Blutsegelbukaniere",
		["Boat to {area:150}"] = "Schiff nach {area:150}",
		["Boat to {area:35}"] = "Boot nach {area:35}",
		["Cortello's scroll"] = "Cortellos Schriftrolle",
		["Defeat the challengers and {npc:6238}"] = "Besiege die Herausforderer und {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Jeder Blutsegelbukanier lässt Schnupftabak fallen, und einer trägt {npc:2493}s Auge; die Schwadroneure gehen gleich nördlich des Orts am Ufer entlang. Die Karten und Befehle liegen im Piratenlager an der {area:43} südlich von {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Jeder Anhänger von Zanzil kann die Mixtur fallen lassen; {npc:2537} geht im Süden des Lagers umher.",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Fly to {area:42}"] = "Flieg nach {area:42}",
		["Fly to {zone:1453}"] = "Flieg nach {zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "Folge der Straße nach Osten zurück nach Theramore. Die Offiziere sind in {area:514}.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\n{npc:4967} waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore."] = "Folge der Straße nach Nordwesten aus Theramore hinaus zum Wachturm bei {area:503}. Schlammpanzereinbuddler streifen durch den Sumpf darum herum.\n{npc:4967} wartet am Fuß des Turms: Sobald du dich umgesehen hast, gib die Quest dort bei ihm ab, nicht in Theramore.",
		["Gorilla hills"] = "Gorillahügel",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Gib die Fangzähne ab und bleib: Drei Wellen Gorillas kommen, {npc:1514} zuletzt. Kämpfe mit voller Gesundheit.",
		["Jungle Stalkers"] = "Dschungelpirscher",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Verlass den Ort durch den Tunnel und folge der Küste nach Norden; der Brief liegt im Lager der Blutsegelbukaniere am Strand, wo Schönling Duncan umhergeht.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "MacKinleys nächster Auftrag schickt dich zu Elite-Ogern: Überspring ihn.",
		["Mirefin murlocs"] = "Murlocs der Schlammflossen",
		["Naga Explorers"] = "Forscher der Naga",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "Auf dem Ritt nach Norden nach {area:392} liegt {area:720} vor der {area:391} südlich des Orts: Wate über die Untiefen der Sandbank. {npc:6236} schickt dir nacheinander vier Herausforderer und dann {npc:6238} (Stufe 33) entgegen.",
		["Optional: Cortello's scroll lies inside one of the three Bloodsail ships anchored off the coast just south of {area:35}, on a middle or lower deck, and is not always on the same ship. Their crews are 42-45 pirates: clear your way from the edge, one at a time, and leave the captains (45-48), whom the route comes back for at 48."] = "Optional: Cortellos Schriftrolle liegt in einem der drei Schiffe der Blutsegelbukaniere, die direkt südlich von {area:35} vor der Küste ankern, auf einem mittleren oder unteren Deck, und nicht immer auf demselben Schiff. Ihre Mannschaften sind Piraten der Stufe 42-45: Kämpf dich vom Rand aus vor, einen nach dem anderen, und lass die Kapitäne (45-48) in Ruhe; für sie kommt die Route auf Stufe 48 zurück.",
		["Paladin: {quest:1661}"] = "Paladin: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Reite zurück hinab in den Ort; Zitterhand steht am Tunneleingang.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Reite nach Osten; die Wuchernden Schrecken unterwegs lassen auch die Aufsätze fallen. Durchsuche den Rand des {area:74}, wo die Ruinen des Tempels aus dem Wasser ragen.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Reite ins Landesinnere zu den Gorillahügeln im Nebeltal. Alte Nebeltalgorillas lassen die Innereien fallen; {npc:1449} sitzt zwischen ihnen.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Reite nach Norden in die Hügel westlich der Straße. {npc:2535} und {npc:2536} stehen zusammen gleich nördlich von Zanzils Dorf.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Reite von der Mine nach Nordwesten zur Bucht an der Nordwestküste. Die Riesenmuscheln liegen auf ihrem Grund und enthalten die Perlen; {npc:2624} schwimmt zwischen ihnen und lässt {item:4034} fallen.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Reite nach Süden aus {zone:1432} durch den Pass ins {zone:1418}; {npc:2860} lagert bei der Ausgrabung.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Reite nach Süden zur Hütte des Riesen mitten im Sumpf.",
		["Riding at 40"] = "Reiten mit 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "Seehorns nächster Auftrag führt zurück nach Arathi: Überspring ihn.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Stinki wartet westlich des Anwesens, im Sumpf unterhalb von {area:504}. Führ ihn zu seinen Sumpfbohnenblättern und halte die Sumpfkreaturen von ihm fern.",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "Die Murlocs der Schlammflossen drängen sich an der Nordküste hinter {area:497}.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "Das abgebrannte Gasthaus Zur süßen Ruh steht an der Straße nach Westen, Richtung {zone:1413}; die Plakette der Wache liegt in der Asche.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Die Deserteure lagern südlich der Straße, westlich von {npc:4503}s Hütte.",
		["The driftwood washes up along the eastern shore."] = "Das Treibholz wird am Ostufer angeschwemmt.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Die Naga durchkämmen die Strände nördlich des Lagers der Blutsegelbukaniere; sie lassen das Schilf fallen.",
		["The north-west coast"] = "Die Nordwestküste",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "Die Schriftrolle liegt im Sumpf nördlich von Biggs. Die Sumpfwandler nördlich davon können Khadgars Aufsätze fallen lassen.",
		["The sunken temple"] = "Der versunkene Tempel",
		["Theramore"] = "Theramore",
		["Unbagwa's ritual"] = "Unbagwas Ritual",
		["Warlock: {quest:3631}"] = "Hexenmeister: {quest:3631}",
		["Zanzil's village"] = "Zanzils Dorf",
		["for the flight back to {npc:6251} at 43"] = "für den Rückflug zu {npc:6251} mit 43",
		["for the {zone:1435} later"] = "für die {zone:1435} später",
		["for {area:1438}: keep it"] = "für {area:1438}: Behalte es",
		["for {npc:2616} in Theramore: keep it"] = "für {npc:2616} in Theramore: Behalte es",
		["for {npc:5635} at {area:348}: keep it"] = "für {npc:5635} in {area:348}: Behalte es",
		["for {npc:770} at the {area:99}, on the northern loop"] = "für {npc:770} beim {area:99}, auf der nördlichen Runde",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "nur wenn du einen {item:3853} dabeihast (von Schmieden hergestellt)",
		["with the spices from Theramore"] = "mit den Gewürzen aus Theramore",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, für Sumpfauge Jarl",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} kocht im {object:2169}; {npc:5384} ist im {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: andere Farben, 20g",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, Königliche Bibliothek in {object:2117}",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, aus 30-40/05-arathi-highlands",
		["{npc:2487}, top floor"] = "{npc:2487}, oberstes Stockwerk",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "{npc:2498}s nächster Zanzil-Auftrag beginnt in {zone:1441}: Überspring ihn.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} und {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} schwimmt vor der Nordwestküste, auf der nördlichen Runde",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} lagert allein in {area:1898}, südöstlich der Ausgrabungsstätte.",
		["{npc:384}: other colours, 20g"] = "{npc:384}: andere Farben, 20g",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, im {object:2164}: {npc:6251} in {area:392} nimmt es am Ende des nächsten Guides an",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: andere Farben, 20g",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966} hält den Turm mit ein paar Deserteuren. Er wendet sich gegen dich: Schlag ihn, bis er aufgibt.\nVorsicht: Hendel hat zwei Wachen, die in den Kampf eingreifen, wenn er feindlich wird. Die Wachen fliehen, sobald er sich ergibt.\n{npc:4967} und {npc:4968} warten neben dem Turm: Sobald er aufgibt, gib bei beiden direkt vor Ort ab.",
		["{npc:4967}, at the tower"] = "{npc:4967}, am Turm",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, in der Kathedrale des Lichts",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} bietet als Nächstes Der Windbehüter (1791) an: Die Questreihe um die Waffe für Wirbelwind, mit einem Elite am Ende, steht im Kriegerklassen-Guide „Wirbelwaffe“.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: für {quest:2864} in {zone:1446}, behalte es",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: andere Farben, 20g",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} steht nahe dem Gasthaus; {npc:4897}, ein Handwerkswarenhändler ein paar Schritte südlich, verkauft die Gewürze, die Jarl will.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} hat keinen Schamanenlehrer",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Fly to {area:271}"] = "Flieg nach {area:271}",
		["Raleigh's next errand is in the {area:796}: skip it."] = "Raleighs nächster Auftrag ist im {area:796}: Überspring ihn.",
		["Ride back east to {area:1898}."] = "Reite zurück nach Osten zu {area:1898}.",
		["Ride back north to Ironband's camp."] = "Reite zurück nach Norden zu Ironbands Lager.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Reite auf der Straße nach Nordosten aus {area:271} ins {zone:1425}; {area:348} liegt gleich hinter der Grenze. {npc:5635} hält oben Hof, {quest:1450} kümmert sich um den Greifenhorst und {npc:7884} steht beim Gasthaus.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "Talonaxes nächste Aufgabe wartet auf einen späteren Guide für das {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Die Brühenden Welpen nisten in der Klamm östlich von {npc:2888}; lass die Versengten Wächter (Elite) in Ruhe. {item:4612} fällt selten: Nimm es mit, wenn es beim Grinden kommt.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Die ersten beiden Käfige stehen zusammen im Dorf der Witherbark südlich von {npc:5634}; der dritte ist im nächsten Dorf östlich davon. Jeder Troll der Witherbark kann eine Halskette fallen lassen.",
		["The {area:1517} dig"] = "Die Ausgrabung bei {area:1517}",
		["Theramore"] = "Theramore",
		["Warlock: {quest:3631}"] = "Hexenmeister: {quest:3631}",
		["Witherbark villages"] = "Dörfer der Witherbark",
		["{area:144} flight master"] = "Flugmeister in {area:144}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} steht an den Docks, wo das Schiff anlegt.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "Die nächste Quest von {npc:2817} gibt keine Erfahrung: Überspring sie.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "Die nächste Aufgabe von {npc:2888} ist eine Elitejagd: Überspring sie.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944} bleibt nicht bei {area:342}: Er läuft mit seinen Wachen eine lange Runde durch das {zone:1418}, vom Lager im Westen am Südrand der Zone entlang bis etwa 61,69, nach Norden bis etwa 49,49 und zurück nach Westen zum Lager. Der Pfeil folgt seiner Runde von hier aus nach Westen, bis du ihn triffst.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} lagert an der Straße östlich von {area:348}.",
		["{npc:7744}; below ground"] = "{npc:7744}; unter der Erde",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Zurück zu den {area:1117}. Jeder Naga der Hasskämme dort kann Schuppen droppen.",
		["Gordunni ogres"] = "Oger der Gordunni",
		["Grimtotem camp"] = "Lager der Grimmtotem",
		["Grimtotem tauren"] = "Tauren der Grimmtotem",
		["Grind to 45"] = "Grinde bis 45",
		["Hatecrest naga"] = "Naga der Hasskämme",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Reite zurück zum Gebiet {area:1108}; der Goblin steht beim Steg.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Reite nach Osten zum Lager der Gordunni in den Hügeln südöstlich des Yetitals: Hexenmeister und Schamanen halten das Lager, Schläger streifen über die Hänge drumherum und weiter nördlich.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Reite nach Norden ins Yetital. Jeder Wildschrammyeti kann einen dicken Yetibalg droppen; {npc:5346} (Stufe 48) streift durch die Mitte.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Reite nach Nordosten zum Außenposten der Nachtelfen an der Grenze zu {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Reite nach Südosten zu den Gnollen der Waldpfoten; die Rucksäcke des Kuriers liegen in ihrem südlichen Lager, und ein Paket darin startet eine Lieferung nach {area:489}. Der Stock der Zukk'ash liegt gleich südlich: Kämpf dich hinunter zur Kapsel, in der Raschal steckt, befreie ihn und halte ihn auf dem Weg nach draußen am Leben.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Uferschreiter, Tiefenschreiter und Wellenschreiter (Elite-Riesen) waten nördlich des Stegs an der Küste entlang: Triff einen mit dem {item:18904} und töte den geschrumpften Riesen. Meereselementare und Meeresschauer treiben in derselben Brandung.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Nimm das Boot zum Gebiet {area:1108} und folge dem Ufer nach Süden zum zerstörten Ruderboot am Strand.",
		["The courier's boat"] = "Das Boot des Kuriers",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Geh auf der Insel nach Süden zu den Ruinen der Naga; der Pavillon steht zwischen ihnen.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "für Tyrande in {zone:1457}: Die Route führt dich mit 47 dorthin",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "grinde an {npc:5292} im {area:1105}, {zone:1444}",
		["{item:11463}, from the backpacks"] = "{item:11463}, aus den Rucksäcken",
		["{npc:14637}'s refills are level 55: skip them."] = "{npc:14637}s Folgequests sind Stufe 55: Überspring sie.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936} bittet dich dann, Nachrichten nach {zone:1457} zu bringen: Überspring das, {area:976} schickt dich stattdessen dorthin.",
		["{npc:3936}, beside him"] = "{npc:3936}, neben ihm",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: Seine Antwort wartet später in {area:702}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, oben in der Festung",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} wartet bis zum Ende der Runde auf dem Festland.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Boat to {area:150}"] = "Schiff nach {area:150}",
		["Fly to Theramore"] = "Flieg nach Theramore",
		["Gives the {item:8585}"] = "Gibt dir den {item:8585}",
		["Pool by {area:979}"] = "Teich bei der {area:979}",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Reite nach Osten über die Dünen zum Goblinhafen an der Nordostküste.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Reite nach Nordwesten zum Trolllager der Sandfury bei der {area:979}. Benutze den {item:8584} am Rand des Teichs; die Trolle stehen dicht beieinander, also zieh zuerst den nächsten.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Reite nach Süden zum Grabungslager an der {area:1938}. {npc:7771} gibt dir einen Detektorhelm: Trag ihn, um die Hügel von {quest:3161} zu sehen, die dicht im Sand rund um das Lager und nach Südwesten Richtung Oger liegen.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Reite vom Gebiet {area:439} nach Südosten nach {zone:1446}. {area:976} liegt gleich hinter der Grenze.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Reite nach Südwesten zum Lager der Oger. Schläger und Vollstrecker (46-48) füllen es; {npc:12046} (49) steht mit Wachen um sich herum in der Mitte: Räum sie zuerst weg.",
		["The Wanted poster beside him"] = "Der Steckbrief neben ihm",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "Die kleine Schildkröte {npc:5955} versteckt sich am Nordende des Tals. Führe ihn heim zu seiner Frau {npc:6015}, am Wasser gleich östlich von {area:977}: Er läuft langsam und die Bestien der Wüste greifen ihn an, also halte ihn am Leben.",
		["The pool by {area:979}"] = "Der Teich bei der {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "Derselbe Steckbrief: {npc:7847} kommt viel später, nach {area:976}",
		["The {area:1938}"] = "Die {area:1938}",
		["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, Zamek by the goblin camp."] = "{area:2240} liegt auf {area:439} im Südosten von {zone:1441}: {npc:4454} ist im Lager der Gnome neben der Strecke, Zamek beim Goblinlager.",
		["for {zone:1457}: the route takes you there at 47"] = "für {zone:1457}: Die Route führt dich mit 47 dorthin",
		["{npc:5955}'s escort"] = "Eskorte von {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, beim Wasserturm",
		["{npc:7408}, next to him"] = "{npc:7408}, neben ihm",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: Seine Kiste geht später nach {area:702}",
		["{quest:2864}, north side of town"] = "{quest:2864}, an der Nordseite der Stadt",
} end)()
