t.guides["forever/alliance/nightelf/02-darkshore"] = (function() return {
		["Back north-east into the mountains to the crystal."] = "Zurück nach Nordosten in die Berge zum Kristall.",
		["Bears and the Blackwood camp"] = "Bären und das Lager der Schwarzfelle",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Pfadfinder und Windsprecher der Schwarzfelle halten das Lager südöstlich von {area:442}.",
		["Blackwood furbolgs"] = "Furbolgs der Schwarzfelle",
		["Class trainer"] = "Klassenlehrer",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Klettere östlich von {area:447} in die östlichen Berge; der {object:175524} liegt auf einem Felsvorsprung.",
		["Fill the tube at the moonwell in the village"] = "Fülle die Phiole am Mondbrunnen im Dorf",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Folge der Küste nach Süden an {area:447} vorbei: Eine {quest:4728} liegt am Ufer westlich des Hains, eine weitere weiter südlich nahe {area:450}. Drei weitere Überreste liegen weiter südwestlich zwischen Orakeln und Gezeitenjägern der Grauflossen (18-20): Der Guide hebt sie für die letzte Runde auf, wenn du näher an ihrer Stufe bist.",
		["Grell Earrings"] = "Grell-Ohrringe",
		["Highborne Relics"] = "Hochgeborenenrelikte",
		["Read the {object:17188}"] = "Lies {object:17188}",
		["Read the {object:17189}"] = "Lies {object:17189}",
		["The WANTED poster outside the inn"] = "Der Steckbrief vor dem Gasthaus",
		["The beach"] = "Der Strand",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Das Boot legt westlich des Dorfes an. Der Flugmeister steht auf dem Hügel südlich des Gasthauses; die Questgeber sind entlang der Hauptstraße verteilt.",
		["The red crystal"] = "Der rote Kristall",
		["The skeletal turtle"] = "Die Skelettschildkröte",
		["The southern beaches"] = "Die südlichen Strände",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Gezeitenkriecher krabbeln unterhalb des Dorfes am Ufer entlang; {quest:983} steht am Strand gleich südlich der Anlegestelle. Dunkelküstendrescher schwimmen im seichten Wasser. {object:175207} liegt gleich südlich des Dorfes am Ufer.",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: Satyrn der Deth'ryll",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} steht am Nordrand der Ruinen. Verfluchte und Zuckende Hochgeborene sowie {npc:2178} spuken dort; der Geist von {npc:3667} wandelt zwischen ihnen, die Eule {npc:270196} kreist östlich davon. Die beiden Schrifttafeln liegen in den Ruinen; eine {quest:4722} liegt westlich davon am Ufer.",
		["{npc:3649}, north end of the village"] = "{npc:3649}, am Nordende des Dorfes",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit an {npc:263664}s Lagerfeuer, bis du {spell:1229451} bekommst",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Sturmjäger und Fußsoldaten der Al'Aketh lagern direkt nördlich von {npc:257944} und lassen das Erbstück fallen; die Schattenwindkreischlinge westlich von ihr lassen die Federn und Krallen fallen; das {item:265105} wächst am Bach westlich von ihr.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "Zurück in {quest:92529}: Sturmrufer der Al'Aketh und {npc:251662} füllen das Dorf, die Sturmrufer tragen die gestohlenen Vorräte, und {npc:251966} steht am Südende.",
		["Back to the Hermit"] = "Zurück zum Einsiedler",
		["Back to {area:16622}"] = "Zurück zum {area:16622}",
		["Bandit Highwaymen"] = "Banditenstraßenräuber",
		["Below ground"] = "Unter der Erde",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon steht im Thronsaal von {object:2117}, am Nordende der Stadt. Verlass die Stadt dann durch das Haupttor nach {zone:1436}.",
		["Cast {spell:1259705} at the {object:460002}"] = "Wirk {spell:1259705} auf die Leylinie",
		["Class trainer"] = "Klassenlehrer",
		["Desperate times"] = "Verzweifelte Zeiten",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Kämpf dich nach Norden zum {area:16629} durch. Wächter, Geisterrufer und Klingenmeister halten den Zugang; {npc:253576} wartet an der Tür des Schreins, {npc:253590} im inneren Sanktum.",
		["Find {npc:258130}"] = "Finde {npc:258130}",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Folge der Straße nach Süden nach {area:16624}. {npc:263664} lagert am Feuer westlich des Dorfes; {npc:251523} und {npc:251903} stehen in der Dorfmitte.",
		["For {npc:234} at {area:108}"] = "Für {npc:234} auf der {area:108}",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Geh nach Norden in den {area:16631}. {npc:257944} lagert im Osten.",
		["Heal the injured druids in the Nightfang Den"] = "Heile die verletzten Druiden im Nachtfangbau",
		["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Spring von der Spitze des Wachturms und benutze {spell:1259416}, um zu {npc:251361} westlich des Turms hinabzuschweben.",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Verlass {zone:1453} durch das Haupttor. Der Wasserfall am {quest:1861} liegt südwestlich der Tore, auf dem Weg nach Westen nach {zone:1436}: Fülle {item:7207} an seinem Fuß.",
		["Level 4 spells"] = "Zauber der Stufe 4",
		["Listen to {npc:252448}'s story"] = "Hör dir die Geschichte von {npc:252448} an",
		["Listen to {npc:257554}"] = "Hör {npc:257554} zu",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "Nördlich der Zapfen: Die Windhüllen treiben um das Flüchtlingslager, die {item:266433} liegt zwischen den Zelten, und {npc:259013} liegt am Nordende.",
		["Prideclaws and Galestriders"] = "Rudelkrallen und Windschreiter",
		["Raw Windstones and the {npc:251404}"] = "Rohe Windsteine und die {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Reife Sturmäpfel und Hungrige Banditen findest du im Obstgarten beim Hof, {quest:92683} auf den Feldern nordöstlich davon, Störrische Windschreiter überall ringsum. Das {npc:250929} steht auf dem Feld nordöstlich des Hofs.",
		["Search the dead cultist"] = "Durchsuche den toten Kultisten",
		["Search the wardrobe"] = "Durchsuche den Kleiderschrank",
		["Shen'dar turn-ins"] = "Shen'dar: Quests abgeben",
		["Skyhoppers"] = "Himmelshüpfer",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Himmelshüpfer schwärmen über die Felder westlich von {area:16638}.",
		["Standing our ground"] = "Standhalten",
		["Tame it with the {item:15908}"] = "Zähme es mit der {item:15908}",
		["Tame {npc:250874}"] = "Zähme {npc:250874}",
		["Tame {npc:251707}"] = "Zähme {npc:251707}",
		["Tame {npc:254588}"] = "Zähme {npc:254588}",
		["Tell {npc:252800} you're ready"] = "Sag {npc:252800}, dass du bereit bist",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Die Banditenstraßenräuber halten die Hügel nördlich des Hofs.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp."] = "Die Hochlandbanditen lagern nordöstlich des Dorfes. „Übelwind“ Bennic wartet am äußersten Nordende ihres Lagers.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "Die Rohen Windsteine glitzern auf dem Boden direkt südlich des Hains. {quest:92463} schwebt weiter östlich über der Wiese, auf dem Weg zu {npc:249363}.",
		["The Windstone Formations"] = "Die Windsteinformationen",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Die Windsteinformationen stehen auf der Anhöhe westlich von Fillions Lager.",
		["The bounty board"] = "Das Kopfgeldbrett",
		["The class trainers stand together in the grove"] = "Die Klassenlehrer stehen zusammen im Hain",
		["The dead cultist"] = "Der tote Kultist",
		["The eastern watchtower"] = "Der östliche Wachturm",
		["The missing scholar"] = "Der vermisste Gelehrte",
		["The road to {area:16638}"] = "Die Straße nach {area:16638}",
		["The {area:16629}"] = "Der {area:16629}",
		["The {item:254871}"] = "Die {item:254871}",
		["The {object:581822}"] = "Der {object:581822}",
		["Village quests"] = "Dorfquests",
		["With a profession learned, {npc:263664} also offers its Camping 101, which its trainer in {area:16624} takes on the village round."] = "Hast du einen Beruf erlernt, bietet {npc:263664} auch das zugehörige Camping 101 an, das du bei seinem Lehrer in {area:16624} auf der Dorfrunde abgibst.",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Du erwachst im {area:16622}. {npc:251362} steht neben dir; {npc:251361} ist ein paar Schritte westlich, {npc:251368} am Südrand des Hains.",
		["{area:16622} turn-ins"] = "{area:16622}: Quests abgeben",
		["{area:16624} again"] = "Wieder nach {area:16624}",
		["{area:16638} turn-ins"] = "{area:16638}: Quests abgeben",
		["{area:16638}, the fate of Zephras"] = "{area:16638}, das Schicksal von Zephras",
		["{area:16638}, the turncoat"] = "{area:16638}, der Verräter",
		["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} hält östlich des Hains Wache. {npc:251143} und Konvertiten der Al'Aketh sammeln sich direkt nördlich von ihr; die Leylinie erhebt sich weiter nördlich: Wirk dort deine Volksfähigkeit {spell:1259705}.",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873} und Lästige Zirrusfliegen streifen über die Wiese südöstlich des Hains.",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: eine Notiz von deinem Lehrer",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: Lies die {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: die {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, der Druidenlehrer, im Erdgeschoss des Baumes hinter {npc:251361}",
		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379}, die Magierlehrerin: Lies zuerst den {item:282416}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, im Wachturm",
		["{npc:251913}, beside {npc:251991}"] = "{npc:251913}, neben {npc:251991}",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, im Wachturm",
		["{npc:251992}, on the south edge of the village"] = "{npc:251992}, am Südrand des Dorfes",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155} hält die westliche Wacht, südwestlich von Falaath. {npc:256966} und die gefallenen Wachen liegen direkt südlich von ihr.",
		["{npc:252373}, the mage trainer"] = "{npc:252373}, der Magierlehrer",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} hält den Wachturm nördlich von {area:16638}. Das Lager der Al'Aketh liegt direkt westlich des Turms, die Heiler bei 65,68 und 65,65; {npc:252666} steht am Nordende. Die Al'Aketh dort lassen Windsteinamulette der Al'Aketh fallen.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} und {npc:252476} stehen am Nordende von {area:16638}, {npc:252475} und {npc:253204} am Südende.",
		["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475}: {npc:259084} wartet beim Portal der Himmelsgeborenen",
		["{npc:252800} again"] = "Wieder zu {npc:252800}",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800} bewirtschaftet den Hof im südwestlichen Tiefland.",
		["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:254151}, {npc:258130} und {npc:258134} sind nordöstlich von {npc:257944}; {npc:253622} steht östlich von ihnen. Haalien lässt außerdem {quest:94490} fallen. Für {quest:94489} betritt den Nachtfangbau, heile 7 verletzte Druiden und finde {npc:258130}.",
		["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} lauert auf dem Rückweg in den Hügeln südwestlich des Dorfes. {npc:254589} ist Elite: Eine Gruppe wird empfohlen.",
		["{npc:257018}, at the south side of the village"] = "{npc:257018}, auf der Südseite des Dorfes",
		["{npc:257019}, west of {npc:251905}"] = "{npc:257019}, westlich von {npc:251905}",
		["{npc:257022}, beside {npc:251993}"] = "{npc:257022}, neben {npc:251993}",
		["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} wartet am Eingang von {quest:92529}, südlich von Shen'dar. Mit {spell:1254832} kannst du dich unter die Gläubigen mischen.",
		["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "{npc:257554} und {npc:263113} stehen oben auf dem Wachturm, ein paar Schritte nordöstlich von {npc:251368}.",
		["{npc:257944} again"] = "Wieder zu {npc:257944}",
		["{npc:257944}, the missive"] = "{npc:257944}, das Schreiben",
		["{npc:258443}, in the highlands south-west of the cultist"] = "{npc:258443}, im Hochland südwestlich des Kultisten",
		["{npc:263664}: for {npc:251913}"] = "{npc:263664}: für {npc:251913}",
		["{npc:263664}: for {npc:251991}"] = "{npc:263664}: für {npc:251991}",
		["{npc:263664}: for {npc:251992}"] = "{npc:263664}: für {npc:251992}",
		["{npc:263664}: for {npc:251993}"] = "{npc:263664}: für {npc:251993}",
		["{npc:263664}: for {npc:257018}"] = "{npc:263664}: für {npc:257018}",
		["{npc:263664}: for {npc:257019}"] = "{npc:263664}: für {npc:257019}",
		["{npc:263664}: for {npc:257020}"] = "{npc:263664}: für {npc:257020}",
		["{npc:263664}: for {npc:257022}"] = "{npc:263664}: für {npc:257022}",
		["{npc:263664}: for {npc:257024}"] = "{npc:263664}: für {npc:257024}",
		["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "{npc:270459}, neben {npc:259084}: für {npc:5504} in {zone:1453}",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} steht im Magiersanktum, dem Turm im Gebiet {object:2101}; sie gibt dir ein Fläschchen für den Wasserfall am {quest:1861}.",
		["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{npc:5504}, der Druidenlehrer von {zone:1453}, lehrt dich {spell:18960}. Der Willkommensgruß von {npc:11802} wartet am Ende von {zone:1439} auf deine Reise für {spell:499}.",
		["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159} lebt westlich von {npc:257944}. Die Zephyrzapfen liegen im Wald zwischen seiner Hütte und {npc:257944}.",
} end)()
t.guides["forever/class/druid/aquatic-form"] = (function() return {
		["At the {area:2362}"] = "Am {area:2362}",
		["Back through {area:1637} to the zeppelin towers outside its main gate: the zeppelin to the {zone:1458} lands in {zone:1420}, and {zone:1421} is south of the {zone:1458}."] = "Zurück durch {area:1637} zu den Zeppelintürmen vor dem Haupttor: Der Zeppelin nach {zone:1458} landet in {zone:1420}, und {zone:1421} liegt südlich von {zone:1458}.",
		["Cast {spell:18960} to get here: {npc:11802} stands upstairs in the building beside where you land. {quest:28} runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until {npc:11799} has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "Wirke {spell:18960}, um hierher zu kommen: {npc:11802} steht oben im Gebäude neben deinem Landeplatz. {quest:28} läuft auf einem 30-Minuten-Timer: Sobald du sie angenommen hast, kein Teleport und kein Ruhestein, bis {npc:11799} sie hat. Sechs Bauble Containers (Vasen) liegen in schmalen Mulden tief auf dem Grund von {area:656} unterhalb von {area:2361}, oft nahe den sprudelnden Spalten (die {object:177524} in der Mitte des Sees füllt deinen Atem auf); jede kommt drei Minuten nach dem Öffnen wieder, und andere Druiden nehmen sie ebenfalls. Prüfe, ob {item:15877} in deinen Taschen ist, bevor du auftauchst: Er verschwindet fünf Minuten nach dem Plündern. Schwimm ihn direkt zu {area:2362} am Nordwestufer, benutze ihn innerhalb des Schreingeländes und sprich mit {npc:11799} am Baum.",
		["Cast {spell:18960} to get here: {npc:11802} stands upstairs in the building beside where you land. {quest:29} runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until {npc:11799} has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "Wirke {spell:18960}, um hierher zu kommen: {npc:11802} steht oben im Gebäude neben deinem Landeplatz. {quest:29} läuft auf einem 30-Minuten-Timer: Sobald du sie angenommen hast, kein Teleport und kein Ruhestein, bis {npc:11799} sie hat. Sechs Bauble Containers (Vasen) liegen in schmalen Mulden tief auf dem Grund von {area:656} unterhalb von {area:2361}, oft nahe den sprudelnden Spalten (die {object:177524} in der Mitte des Sees füllt deinen Atem auf); jede kommt drei Minuten nach dem Öffnen wieder, und andere Druiden nehmen sie ebenfalls. Prüfe, ob {item:15877} in deinen Taschen ist, bevor du auftauchst: Er verschwindet fünf Minuten nach dem Plündern. Schwimm ihn direkt zu {area:2362} am Nordwestufer, benutze ihn innerhalb des Schreingeländes und sprich mit {npc:11799} am Baum.",
		["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards {npc:11800}, in the middle of {area:2361}, flies druids straight to {area:702}."] = "Wirke {spell:18960}. Wenn du beide Hälften in den Taschen hast, stell dich an {area:2362} am Nordwestufer und benutze {item:15883}, um sie zusammenzufügen. Wirke dann {spell:18960} erneut (es funktioniert in {zone:1450}), um bei {npc:11802} zu landen. Er steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden. Danach fliegt {npc:11800} in der Mitte von {area:2361} Druiden direkt nach {area:702}.",
		["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:11798} flies druids to {area:1638}."] = "Wirke {spell:18960}. Wenn du beide Hälften in den Taschen hast, stell dich an {area:2362} am Nordwestufer und benutze {item:15883}, um sie zusammenzufügen. Wirke dann {spell:18960} erneut (es funktioniert in {zone:1450}), um bei {npc:11802} zu landen. Er steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden. {npc:11798} fliegt Druiden nach {area:1638}.",
		["Fly from {area:2361} to {area:442}. The {object:177792} lies far out on the sea floor off the north coast, between tall rocks west of where the {area:456} reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water."] = "Flieg von {area:2361} nach {area:442}. {object:177792} liegt weit draußen auf dem Meeresgrund vor der Nordküste, zwischen hohen Felsen westlich der Stelle, wo {area:456} ins Meer mündet: Von der Ostseite der Felsen aus ist sie nicht zu sehen. Achte auf deinen Atem und auf die Darkshore Threshers; kämpfe über Wasser.",
		["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Head west to the coast: the {object:177790} lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue."] = "Nimm das Boot von {area:442} nach {zone:1453} und flieg nach {area:108}. Geh nach Westen zur Küste: {object:177790} liegt weit draußen auf dem Meeresgrund neben einer sprudelnden Spalte (Luft), westlich eines versunkenen Ankers. Hier streifen Haie umher; schwimm nicht am Wrack vorbei weiter hinaus, das tiefe Wasser verursacht Erschöpfung.",
		["Take the portal up to {npc:4217} in the {area:1658}. {quest:31}: swim fast and breathe underwater."] = "Nimm das Portal nach oben zu {npc:4217} in der {area:1658}. {quest:31}: schnell schwimmen und unter Wasser atmen.",
		["Take the portal up to {npc:4217} in the {area:1658}. {quest:5061}: swim fast and breathe underwater."] = "Nimm das Portal nach oben zu {npc:4217} in der {area:1658}. {quest:5061}: schnell schwimmen und unter Wasser atmen.",
		["Take {npc:11798}'s flight to {area:1638} and fly on to {area:1637}. The {object:177792} lies underwater in the {area:382} pond, a short walk out of {area:1637}'s west gate, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them."] = "Nimm den Flug von {npc:11798} nach {area:1638} und flieg weiter nach {area:1637}. {object:177792} liegt unter Wasser im Teich von {area:382}, ein kurzes Stück vor dem Westtor von {area:1637}, vor einer Holzwand. Die Venture Co. dort schließt sich schnell einem Kampf an: Komm von Westen, um die meisten zu umgehen.",
		["The {object:177790} lies at the bottom of very deep water off the coast north-west of the {area:228}, beside an air fissure where you can breathe: watch your breath on the way down. Then {spell:18960} takes you straight back."] = "{object:177790} liegt auf dem Grund von sehr tiefem Wasser vor der Küste nordwestlich von {area:228}, neben einer Luftspalte, an der du atmen kannst: Achte auf deinen Atem auf dem Weg nach unten. Dann bringt dich {spell:18960} direkt zurück.",
		["Your water travel form: swim fast and breathe underwater, with a belt and an idol besides."] = "Deine Reisegestalt fürs Wasser: schnell schwimmen und unter Wasser atmen, dazu ein Gürtel und ein Götze.",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, aus einem {object:177785} im See",
		["{item:15882}, from the {object:177790}"] = "{item:15882}, aus {object:177790}",
		["{item:15883}, from the {object:177792}"] = "{item:15883}, aus {object:177792}",
		["{item:15885}: join the halves at the shrine"] = "{item:15885}: Füge die Hälften am Schrein zusammen",
		["{npc:3033} stands in the druids' hut on {area:1639}."] = "{npc:3033} steht in der Druidenhütte auf {area:1639}.",
		["{npc:4217} stands upstairs in the druids' building of the {area:1658}. Skyborne: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up."] = "{npc:4217} steht oben im Druidengebäude der {area:1658}. Himmelsgeborene: Wirke {spell:18960} und nimm den Flug von {npc:11800} aus der Mitte von {area:2361} (sie fliegt Druiden nach {area:702}, keine Flugroute nötig), dann das Portal nach oben.",
} end)()
t.guides["forever/class/druid/bear-form"] = (function() return {
		["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "Mit Stufe 10 erreicht dich der Ruf eines Druiden: {npc:3064} in {area:222} oder {npc:6746} in {zone:1456} (der Brief von {npc:6929} in {zone:1454} geht auch). Jeder von ihnen schickt dich zu {npc:3033} im Gebiet {area:1639} in {zone:1456}.",
		["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "Mit Stufe 10 erreicht dich der Ruf eines Druiden: {npc:3602} in {area:186}, Denatharion in {zone:1457} oder Theridran in {zone:1453}. Jeder von ihnen schickt dich zu {npc:4217} in der Enklave des Cenarius in Darnassus.",
		["Back to {npc:255853} by the falls."] = "Zurück zu {npc:255853} an den Wasserfällen.",
		["Back to {npc:3033} on {area:1639}."] = "Zurück zu {npc:3033} im Gebiet {area:1639}.",
		["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, in {area:2361}. Learn the {area:493} flight path while you are here (Faustron for the Horde, south-west of the lake; {npc:10897} for the Alliance, south of it)."] = "Wirke {spell:18960}: Es setzt dich neben dem Gebäude ab, in dem {npc:11802} oben steht, in {area:2361}. Lerne hier gleich die Flugroute {area:493} (Faustron für die Horde, südwestlich des Sees; {npc:10897} für die Allianz, südlich davon).",
		["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, past the armor vendor. The {quest:5929} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {area:493} flight path ({npc:10897}, south of the lake) for later, then take {npc:11800}'s flight from the middle of {area:2361}: she flies druids straight to {area:702}, no flight path needed. Take the portal up to {zone:1457}."] = "Wirke {spell:18960}: Es setzt dich neben dem Gebäude ab, in dem {npc:11802} oben steht, hinter dem Rüstungshändler. {quest:5929} sitzt in den Wäldern im Nordwesten. Sprich ihn an und geh alle seine Worte durch (was er darstellt, die Stärke des Körpers, die Stärke des Herzens, dann bitte um seinen Segen): Das Gespräch ist das Ziel, es gibt keinen Kampf. Er verschmilzt mit dem Boden, hat kein Questzeichen und gibt einen schwachen blaugrauen Schein bei einer Gruppe aus drei Bäumen ab: Geh von {area:2361} aus nach Westen am Fuß der nördlichen Berge entlang, durch die Lücke zwischen den Bäumen und den Hügeln. Fehlt {npc:11802}, wenn du zurückkommst, geh nach draußen und wirke {spell:18960} noch einmal. Lerne für später die Flugroute {area:493} ({npc:10897}, südlich des Sees), nimm dann den Flug von {npc:11800} aus der Mitte von {area:2361}: Sie fliegt Druiden direkt nach {area:702}, keine Flugroute nötig. Nimm das Portal nach oben nach {zone:1457}.",
		["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs. The {quest:5930} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {quest:5922} flight path (Faustron, south-west of the lake); {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Wirke {spell:18960}: Es setzt dich neben dem Gebäude ab, in dem {npc:11802} oben steht. {quest:5930} sitzt in den Wäldern im Nordwesten. Sprich ihn an und geh alle seine Worte durch (was er darstellt, die Stärke des Körpers, die Stärke des Herzens, dann bitte um seinen Segen): Das Gespräch ist das Ziel, es gibt keinen Kampf. Er verschmilzt mit dem Boden, hat kein Questzeichen und gibt einen schwachen blaugrauen Schein bei einer Gruppe aus drei Bäumen ab: Geh von {area:2361} aus nach Westen am Fuß der nördlichen Berge entlang, durch die Lücke zwischen den Bäumen und den Hügeln. Fehlt {npc:11802}, wenn du zurückkommst, geh nach draußen und wirke {spell:18960} noch einmal. Lerne die Flugroute {quest:5922} (Faustron, südwestlich des Sees); {npc:11798} in {area:2361} fliegt Druiden nach {area:1638}.",
		["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Flieg zurück nach {area:702} und nimm das Portal hinauf zu {npc:4217}.",
		["Fly from {area:702} to {area:442}. The {object:177525} stands inside the nearest moonkin cave east of the village: the northern of two small rock-pile caves where the {area:442} road meets the main north-south road. Moonkin (level 11-13) stand outside, the cave is empty: slip past them. Use the {item:15208} by the stone: Lunaclaw (level 12-13) walks in towards you and stays three minutes. Kill her, then speak to the {npc:12144} that appears and ask for the strength of her body and heart: the talk is the credit. Another druid's Lunaclaw gives you the spirit too."] = "Flieg von {area:702} nach {area:442}. {object:177525} steht in der nächsten Moonkin-Höhle östlich des Dorfes: der nördlichen von zwei kleinen Felshaufenhöhlen, wo die Straße von {area:442} auf die große Nord-Süd-Straße trifft. Moonkin (Stufe 11-13) stehen draußen, die Höhle ist leer: Schleich an ihnen vorbei. Benutze {item:15208} am Stein: Lunaclaw (Stufe 12-13) läuft auf dich zu und bleibt drei Minuten. Töte sie, sprich dann mit {npc:12144}, der erscheint, und bitte um die Stärke ihres Körpers und Herzens: Das Gespräch zählt als Ziel. Auch die Lunaclaw eines anderen Druiden gibt dir den Geist.",
		["Skyboat from {area:279}"] = "Himmelsboot ab {area:279}",
		["Skyboat from {zone:1456}"] = "Himmelsboot ab {zone:1456}",
		["Skyboat to {zone:2521}"] = "Himmelsboot nach {zone:2521}",
		["Speak with the {quest:5929}"] = "Sprich mit dem {quest:5929}",
		["Speak with the {quest:5930}"] = "Sprich mit dem {quest:5930}",
		["The Skyborne Portal takes you to {zone:1453}. {npc:5504} is the city's druid trainer (the arrow points at him); he teaches you {spell:18960} with the next quest (it stays in your spellbook, Balance tab)."] = "Das Portal der Himmelsgeborenen bringt dich nach {zone:1453}. {npc:5504} ist der Druidenlehrer der Stadt (der Pfeil zeigt auf ihn); er bringt dir mit der nächsten Quest {spell:18960} bei (es bleibt in deinem Zauberbuch, Reiter Gleichgewicht).",
		["The {object:177525}"] = "Der {object:177525}",
		["The {object:177525} stands in the {zone:1413} just south-west of {area:378}, by the road out of {zone:1412}. Level 20 Thunderheads roam close by: clear the way first. Use the {item:15710} by the stone: Lunaclaw (level 12-13) appears for three minutes. Kill her, then speak to the {npc:12144} that appears and ask for the strength of her body and heart: the talk is the credit. Die in the fight? Lunaclaw stays by the stone: run back and finish her."] = "{object:177525} steht in {zone:1413} knapp südwestlich von {area:378}, an der Straße aus {zone:1412}. In der Nähe streifen Thunderheads der Stufe 20 umher: Räum zuerst den Weg frei. Benutze {item:15710} am Stein: Lunaclaw (Stufe 12-13) erscheint für drei Minuten. Töte sie, sprich dann mit {npc:12144}, der erscheint, und bitte um die Stärke ihres Körpers und Herzens: Das Gespräch zählt als Ziel. Im Kampf gestorben? Lunaclaw bleibt am Stein: Lauf zurück und erledige sie.",
		["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "Deine Tankgestalt: Forever lehrt {spell:5487} nicht mehr beim Lehrer, diese Quests geben sie dir. Schaltet auch {area:493} frei.",
		["or whichever of the three letters you carry"] = "oder welchen der drei Briefe du auch hast",
		["{npc:252359} stands in {area:16638}."] = "{npc:252359} steht in {area:16638}.",
		["{npc:255853} and {npc:258443}"] = "{npc:255853} und {npc:258443}",
		["{npc:255853} waits by the waterfall below the {area:16629}, north-east of {area:16638}. {npc:258443} (the bear you must defeat) lairs in an unmarked cave high on the cliff face west of him, where the {area:16623} meet the {area:16626}: take the path west out of {area:16638} (not north), cross the river on the log bridge and reach the cave from the cliff's upper, northern side. The cave at the foot of the cliffs and the foggy cave are the wrong ones."] = "{npc:255853} wartet am Wasserfall unterhalb von {area:16629}, nordöstlich von {area:16638}. {npc:258443} (der Bär, den du besiegen musst) haust in einer unmarkierten Höhle hoch oben an der Felswand westlich von ihm, wo {area:16623} und {area:16626} aufeinandertreffen: Nimm den Weg von {area:16638} nach Westen (nicht nach Norden), überquere den Fluss über die Baumstammbrücke und erreiche die Höhle von der oberen, nördlichen Seite der Klippe. Die Höhle am Fuß der Klippen und die neblige Höhle sind die falschen.",
		["{npc:259118} waits where the airship from {zone:2521} lands, in northern {zone:1412} beside {zone:1456}."] = "{npc:259118} wartet dort, wo das Luftschiff von {zone:2521} landet, im Norden von {zone:1412} neben {zone:1456}.",
		["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459} steht neben {npc:259084} und dem Portal der Himmelsgeborenen, westlich von {area:279}, wo der Himmelssegler von {zone:2521} landet. {npc:2543} bietet dieselbe Quest an.",
		["{npc:3033} stands in the druids' hut on {area:1639}, over the rope bridges east of the lifts. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab)."] = "{npc:3033} steht in der Druidenhütte auf {area:1639}, über die Hängebrücken östlich der Aufzüge. Er bringt dir mit der Quest {spell:18960} bei (es bleibt in deinem Zauberbuch, Reiter Gleichgewicht).",
		["{npc:3033} trains druids in the druids' hut on {area:1639}, over the rope bridges east of the lifts. He teaches you {spell:18960} with the next quest (it stays in your spellbook, Balance tab)."] = "{npc:3033} bildet Druiden in der Druidenhütte auf {area:1639} aus, über die Hängebrücken östlich der Aufzüge. Er bringt dir mit der nächsten Quest {spell:18960} bei (es bleibt in deinem Zauberbuch, Reiter Gleichgewicht).",
		["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222}; die Briefe von Pala und Gryshka führen zum selben Ort",
		["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186}; die Briefe von Denatharion und Theridran führen zum selben Ort",
		["{npc:4217} stands upstairs in the druids' building of the {area:1658}. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab)."] = "{npc:4217} steht oben im Druidengebäude der {area:1658}. Er bringt dir mit der Quest {spell:18960} bei (es bleibt in deinem Zauberbuch, Reiter Gleichgewicht).",
		["{spell:5487} and {area:493}"] = "{spell:5487} und {area:493}",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487} wird auf {zone:2521} gelehrt. Überspring das, wenn du noch auf der Insel bist; sonst nimm das Himmelsboot an den Klippen südlich des {area:17045}, nördlich von {zone:1456}.",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487} wird auf {zone:2521} gelehrt. Überspring das, wenn du noch auf der Insel bist; sonst nimm das Himmelsboot an der Nordseite von {area:279}.",
} end)()
t.guides["forever/class/druid/bloodpetal-poison"] = (function() return {
		["A five-player dungeon: needs a group of five, about level 50-55. Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. {area:1477} stands in the middle of the {area:74} in the {zone:1435}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. {npc:8580} (level 50 elite, {spell:12887} and {spell:6524}) only appears when the six serpent statues on the balcony ring above the altar pit are clicked in order: South, North, South-west, South-east, North-west, North-east (each turns green when right; a wrong order fails). Clear the trash by each statue and the pit below first; jumping down into the water is the quick way down, but a knockback near the edge can kill. The {item:22444} always drops."] = "Ein Dungeon für fünf Spieler: Du brauchst eine Gruppe aus fünf, etwa Stufe 50-55. Horde: Flieg nach {area:75}; Allianz: Flieg nach {area:1438} in {zone:1419} und reite nach Norden. {area:1477} liegt mitten in {area:74} in {zone:1435}: Steig die Treppe an der Südseite der Ruine hinauf, tauch in die geflutete Halle, schwimm durch sie nach unten und folge den Treppen und Gängen hinab zum Portal. {npc:8580} (Elite der Stufe 50, {spell:12887} und {spell:6524}) erscheint erst, wenn die sechs Schlangenstatuen auf dem Balkonring über der Altargrube der Reihe nach angeklickt werden: Süden, Norden, Südwesten, Südosten, Nordwesten, Nordosten (jede leuchtet grün, wenn sie stimmt; eine falsche Reihenfolge scheitert). Räum zuerst den Trash bei jeder Statue und die Grube darunter; der Sprung ins Wasser ist der schnelle Weg nach unten, aber ein Rückstoß nahe der Kante kann tödlich sein. {item:22444} fällt immer.",
		["Any {npc:6498} counts, the Ironhide and Tyrant Devilsaurs too. They are elite (level 54-55), hit with {spell:14099} and outrun travel form. Grouping up is encouraged, but a druid can do it alone: Hibernate or {spell:339} it from range, stab it with the {item:22432} (the barb does not break {spell:2637}), then leave. The credit counts the moment the barb lands, even if you die after. The arrow points at the plain Devilsaurs of the west and north; an {npc:6499} roams the middle of the crater's south, nearer {npc:9619}."] = "Jeder {npc:6498} zählt, auch die Ironhide- und Tyrant-Teufelssaurier. Sie sind Elite (Stufe 54-55), schlagen mit {spell:14099} zu und sind schneller als die Reisegestalt. Sich zu gruppieren wird empfohlen, aber ein Druide schafft es auch allein: Lass ihn aus der Ferne mit Winterschlaf oder {spell:339} ausschalten, stich ihn mit {item:22432} (der Stachel unterbricht {spell:2637} nicht), dann geh. Das Ziel zählt in dem Moment, in dem der Stachel trifft, auch wenn du danach stirbst. Der Pfeil zeigt auf die einfachen Teufelssaurier im Westen und Norden; ein {npc:6499} streift durch die Mitte des Kratersüdens, näher an {npc:9619}.",
		["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "Zurück zu {npc:9619} in der Südostecke des {zone:1449}.",
		["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer ({npc:3033}, {npc:4217} or Theridran in {zone:1453}) offers the same quest."] = "Wirke {spell:18960}. {npc:12042} steht in {area:2361}; dein Klassenlehrer ({npc:3033}, {npc:4217} oder Theridran in {zone:1453}) bietet dieselbe Quest an.",
		["Eight of each. The Gorishi Wasps and Stingers (level 51-52) in and around the {area:540}, the hive in the south-west of the crater, drop a sting about one kill in seven; the wasps share spawn points with the other bugs, so kill whatever stands near you to make room for more wasps (respawn five minutes). The bugs' {spell:8137} makes you take more physical damage for 30 minutes; Workers call for help when hurt. The Bloodpetal Sprouts grow all over the crater (around {area:541} and the western half): open them, about every other one gives a {item:22434}, back in three to five minutes."] = "Je acht. Die Gorishi Wasps und Stingers (Stufe 51-52) in und um {area:540}, den Bienenstock im Südwesten des Kraters, lassen etwa bei jedem siebten Kill einen Stachel fallen; die Wespen teilen sich Spawnpunkte mit den anderen Käfern, also töte alles in deiner Nähe, damit mehr Wespen nachspawnen (Respawn fünf Minuten). Die {spell:8137} der Käfer lässt dich 30 Minuten lang mehr körperlichen Schaden erleiden; Arbeiter rufen bei Verletzung um Hilfe. Die Bloodpetal Sprouts wachsen überall im Krater (um {area:541} und in der westlichen Hälfte): Öffne sie, etwa jeder zweite gibt {item:22434}, nach drei bis fünf Minuten sind sie wieder da.",
		["Experience in Un'Goro at 50 and two healing potions; the Classic item choice may be gone in Forever."] = "Erfahrung in Un'Goro bei Stufe 50 und zwei Heiltränke; die Classic-Gegenstandsauswahl gibt es in Forever womöglich nicht mehr.",
		["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "Flieg nach {area:976} und reite nach Westen zur langen Rampe hinab in den {zone:1449}: {npc:9619} lagert an ihrem Fuß, in der Südostecke des Kraters.",
		["Gorishi Stings and {item:22434}"] = "Gorishistachel und {item:22434}",
		["Stab a {npc:6498} with the {item:22432}"] = "Stich einen {npc:6498} mit {item:22432}",
		["The {area:1417}"] = "{area:1417}",
		["{npc:6498}: stab it with the {item:22432}"] = "{npc:6498}: Stich ihn mit {item:22432}",
		["{npc:9619}: the old item choice may be gone, count on the experience"] = "{npc:9619}: Die alte Gegenstandsauswahl gibt es womöglich nicht mehr, rechne mit der Erfahrung",
} end)()
t.guides["forever/class/druid/cat-form"] = (function() return {
		["Back to {npc:11802}"] = "Zurück zu {npc:11802}",
		["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}, um bei {npc:11802} in {area:2361} zu landen (niemand auf Zephras Isle nimmt die Himmelsgeborenen-Quest an), und nimm dann den Flug von {npc:11798} nach {area:1638}. {npc:11802} steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11800}'s flight to {area:702}: she stands in the middle of {area:2361} and flies druids there, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}, um bei {npc:11802} in {area:2361} zu landen (niemand auf Zephras Isle nimmt die Himmelsgeborenen-Quest an), und nimm dann den Flug von {npc:11800} nach {area:702}: Sie steht in der Mitte von {area:2361} und fliegt Druiden dorthin, keine Flugroute nötig. {npc:11802} steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}. {npc:11802} steht oben in seinem Gebäude in {area:2361}: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Take the portal up to {npc:4217}, upstairs in the {area:1658}: he teaches you {spell:768}."] = "Nimm das Portal nach oben zu {npc:4217}, oben in der {area:1658}: Er bringt dir {spell:768} bei.",
		["The relics of the Barrow Dens"] = "Die Relikte der Grabhügel",
		["The {area:2363}"] = "Die {area:2363}",
		["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "Deine Tarn- und Nahkampfgestalt: In Forever gibt diese Questreihe {spell:768} auf Stufe 20, nicht der Lehrer.",
		["{npc:3033} on {area:1639} teaches you {spell:768}."] = "{npc:3033} auf {area:1639} bringt dir {spell:768} bei.",
		["{npc:3033} stands in the druids' hut on {area:1639}. No {spell:1066} yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the {spell:1066} guide) is in the same {area:493}."] = "{npc:3033} steht in der Druidenhütte auf {area:1639}. Noch keine {spell:1066}? Nimm bei ihm auch „Eine wertvolle Lektion“ an: Sie geht ebenfalls an {npc:11802}, und ihre „Prüfung des Sees“ (der Guide für {spell:1066}) liegt im selben {area:493}.",
		["{npc:4217} stands in the {area:1658}. Skyborne far from {zone:1457}: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {spell:1066} yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the {spell:1066} guide) is in the same {area:493}."] = "{npc:4217} steht in der {area:1658}. Himmelsgeborene weit weg von {zone:1457}: Wirke {spell:18960} und nimm den Flug von {npc:11800} aus der Mitte von {area:2361} (sie fliegt Druiden nach {area:702}, keine Flugroute nötig), dann das Portal nach oben. Noch keine {spell:1066}? Nimm bei ihm auch „Eine wertvolle Lektion“ an: Sie geht ebenfalls an {npc:11802}, und ihre „Prüfung des Sees“ (der Guide für {spell:1066}) liegt im selben {area:493}.",
		["{quest:98342} (Tauren) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98342} (Tauren) wartet auf dem Hügel über der Brücke im Süden von {area:493}; der {npc:272054} (Himmelsgeborene) steht auf einer Anhöhe hinter den Zwillingsbrücken, südwestlich von {area:2361}: Klettere zu ihm hinauf. Die Relikte liegen in {area:2363} östlich des Sees: Verlasse deine Gestalt und klicke die Statue am Eingang der Höhle an, um kurz getarnt zu sein (fünf Minuten), und geh dann tief in die Höhle und über die Brücke. Wütende Geister bewachen die Relikte und greifen alles an, was sie sehen: Bleib in der Tarnung der Statue und bewege dich weiter. Jedes Relikt ist eine kleine Kugel neben einer Katzenstatue in einer Nische: Fang und Claw haben je einen Platz, Silent Shadow zwei, und dort campen die Spieler. Ein Relikt wird als unbenutzbar angezeigt, während ein anderer Spieler es plündert: Warte kurz und versuche es erneut. Tarnung weg? Geh zurück zur Statue am Eingang, um eine neue zu bekommen.",
		["{quest:98394} (Night Elves) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98394} (Nachtelfen) wartet auf dem Hügel über der Brücke im Süden von {area:493}; der {npc:272054} (Himmelsgeborene) steht auf einer Anhöhe hinter den Zwillingsbrücken, südwestlich von {area:2361}: Klettere zu ihm hinauf. Die Relikte liegen in {area:2363} östlich des Sees: Verlasse deine Gestalt und klicke die Statue am Eingang der Höhle an, um kurz getarnt zu sein (fünf Minuten), und geh dann tief in die Höhle und über die Brücke. Wütende Geister bewachen die Relikte und greifen alles an, was sie sehen: Bleib in der Tarnung der Statue und bewege dich weiter. Jedes Relikt ist eine kleine Kugel neben einer Katzenstatue in einer Nische: Fang und Claw haben je einen Platz, Silent Shadow zwei, und dort campen die Spieler. Ein Relikt wird als unbenutzbar angezeigt, während ein anderer Spieler es plündert: Warte kurz und versuche es erneut. Tarnung weg? Geh zurück zur Statue am Eingang, um eine neue zu bekommen.",
} end)()
t.guides["forever/class/druid/cure-poison"] = (function() return {
		["Back in {area:442}, at the north end of the village."] = "Zurück in {area:442}, am Nordende des Dorfes.",
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960} und besuche {npc:11802}, nimm dann den Flug von {npc:11798} nach {area:1638}. {npc:11802} steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed) and the portal up to {zone:1457}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960} und besuche {npc:11802}, nimm dann den Flug von {npc:11800} aus der Mitte von {area:2361} (sie fliegt Druiden nach {area:702}, keine Flugroute nötig) und das Portal nach oben nach {zone:1457}. {npc:11802} steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the Crossroads from there."] = "Wirke {spell:18960}: {npc:11802} steht oben im Gebäude neben dir. Er gibt dir {item:15842}. {npc:11798} fliegt Druiden nach {area:1638}; flieg von dort weiter nach Crossroads.",
		["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15844}. Then fly to {area:442} (learn the {zone:1450} flight path at Sindrayl first if you have not)."] = "Wirke {spell:18960}: {npc:11802} steht oben im Gebäude neben dir. Er gibt dir {item:15844}. Flieg dann nach {area:442} (lerne vorher die Flugroute {zone:1450} bei Sindrayl, falls du sie noch nicht hast).",
		["Every {npc:3234} (level 14-15) drops a horn, but they are few and wander: search the far north near the {area:382} and the oases, above all the {area:388} south-east of the Crossroads. They charge from range and stomp. Herbalists find {item:2449} all over the northern {zone:1413}."] = "Jeder {npc:3234} (Stufe 14-15) lässt ein Horn fallen, aber sie sind selten und wandern umher: Such im hohen Norden nahe {area:382} und bei den Oasen, vor allem an der {area:388} südöstlich der Crossroads. Sie greifen aus der Entfernung an und trampeln. Kräuterkundler finden {item:2449} überall im Norden von {zone:1413}.",
		["From the Crossroads head north to {area:384} and climb to the bubbling {object:19464} on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the {item:15842}: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run."] = "Geh von Crossroads nach Norden zu {area:384} und klettere zu dem sprudelnden {object:19464} auf dem Gipfel. Kultisten der Burning Blade lagern darum: Pull sie einzeln oder zu zweit. Stell dich ins Wasser und benutze {item:15842}: Drei Toxikologen der Burning Blade (Stufe 13-14, Flüche und Hexenmeisterzauber) erscheinen und greifen an. Du musst sie nicht töten: Sobald die Probenflasche voll ist, lauf weg.",
		["He hands you the {item:15826}: ten doses, one per gazelle."] = "Er gibt dir {item:15826}: zehn Dosen, eine pro Gazelle.",
		["Head north-east from {area:442} to {area:445}. Stand at the cave mouth at the top of the waterfall, not in the river below, and use the {item:15844} (not the {item:12350} of another quest). Naga line the climb, a caster waits on the far bank, and filling the sampler calls two more (a Wave Rider and a Toxicologist, level 15): clear the way first and be ready to fight."] = "Geh von {area:442} nach Nordosten zu {area:445}. Stell dich an den Höhleneingang oben am Wasserfall, nicht in den Fluss darunter, und benutze {item:15844} (nicht {item:12350} einer anderen Quest). Naga säumen den Aufstieg, ein Zauberwirker wartet am anderen Ufer, und das Füllen der Probenflasche ruft zwei weitere (einen Wave Rider und einen Toxicologist, Stufe 15): Räum zuerst den Weg frei und sei kampfbereit.",
		["She hands you the {item:15826}: ten doses, one per deer. Destroy any leftover {item:15851}."] = "Sie gibt dir {item:15826}: zehn Dosen, eine pro Hirsch. Zerstöre übrig gebliebenen {item:15851}.",
		["Sickly Gazelles"] = "Kränkliche Gazellen",
		["The Lunar Fungal Blooms are tiny white-spotted mushrooms on the floors and walls of the small moonkin caves in the hills just east and south-east of {area:442}; each gives one or two fungus, and each cave holds only a few, so go from cave to cave (they regrow in three minutes). The moonkin there are irritable. No {skill:182} needed for the blooms. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it ({npc:1313} or {npc:1302} in {zone:1453}, or the Auction House)."] = "Die Lunar Fungal Blooms sind winzige weiß gefleckte Pilze auf dem Boden und an den Wänden der kleinen Moonkin-Höhlen in den Hügeln östlich und südöstlich von {area:442}; jede gibt ein oder zwei Pilze, und jede Höhle hat nur wenige, also geh von Höhle zu Höhle (sie wachsen nach drei Minuten nach). Die Moonkin dort sind reizbar. Für die Blooms brauchst du kein {skill:182}. {item:2449} braucht {skill:182}: Kräuterkundler pflücken sie überall in {zone:1439}, alle anderen kaufen sie ({npc:1313} oder {npc:1302} in {zone:1453}, oder im Auktionshaus).",
		["Use the {item:15826} on Sickly Gazelles"] = "Benutze {item:15826} an Sickly Gazelles",
		["Use the {item:15826} on living Sickly Gazelles (level 3): they graze on both sides of the road north of the Crossroads up to the {zone:1440} border, north-west of the Crossroads and west of {area:392}. Druid trick: root a gazelle with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from {npc:3448} for a fresh salve."] = "Benutze {item:15826} an lebenden Sickly Gazelles (Stufe 3): Sie grasen auf beiden Seiten der Straße nördlich der Crossroads bis zur Grenze zu {zone:1440}, nordwestlich der Crossroads und westlich von {area:392}. Druidentrick: Wurzle eine Gazelle mit {spell:339}, trag die Salbe auf, bevor die Wurzeln ticken, und der Wurzel-Kill zählt ein zweites Mal, sodass fünf Gazellen reichen können. Eine Dosis verloren? Brich die Quest ab und nimm sie bei {npc:3448} noch einmal an, um eine frische Salbe zu bekommen.",
		["Use the {item:15826} on living {npc:12298} (level 5, a green cloud over them): they roam {zone:1439} from the {area:456} to the {zone:1440} border, many around the Blackwood furbolg camp north-east of {area:442}. Druid trick: root a deer with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time. Lost a dose on a deer that did not count? Abandon the quest and take it again from {npc:3702} for a fresh salve."] = "Benutze {item:15826} an lebenden {npc:12298} (Stufe 5, eine grüne Wolke über ihnen): Sie streifen durch {zone:1439} vom {area:456} bis zur Grenze zu {zone:1440}, viele rund um das Blackwood-Furbolglager nordöstlich von {area:442}. Druidentrick: Wurzle einen Hirsch mit {spell:339}, trag die Salbe auf, bevor die Wurzeln ticken, und der Wurzel-Kill zählt ein zweites Mal. Eine Dosis an einem Hirsch verloren, der nicht gezählt hat? Brich die Quest ab und nimm sie bei {npc:3702} noch einmal an, um eine frische Salbe zu bekommen.",
		["Use the {item:15826} on {npc:12298}"] = "Benutze {item:15826} an {npc:12298}",
		["{item:15842}, standing in the pool"] = "{item:15842}, im Teich stehend",
		["{item:15844}, at the cave mouth"] = "{item:15844}, am Höhleneingang",
		["{item:15851} and {item:2449}"] = "{item:15851} und {item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449} und Kodohörner",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449}; Kräuterkundige pflücken es in den Ebenen",
		["{npc:3033} on {area:1639} teaches you {spell:8946}."] = "{npc:3033} auf {area:1639} bringt dir {spell:8946} bei.",
		["{npc:3033} stands in the druids' hut on {area:1639}; {npc:262560}, the Skyborne druid trainer where the airship from Zephras Isle lands in northern {zone:1412}, gives the same quest. No {skill:182}? {npc:3490} at the Crossroads sells {item:2449} later, or buy five on the Auction House now."] = "{npc:3033} steht in der Druidenhütte auf {area:1639}; {npc:262560}, der Druidenlehrer der Himmelsgeborenen, wo das Luftschiff von Zephras Isle im Norden von {zone:1412} landet, gibt dieselbe Quest. Kein {skill:182}? {npc:3490} in Crossroads verkauft später {item:2449}, oder kauf jetzt fünf im Auktionshaus.",
		["{npc:3033}, or {npc:262560} in northern {zone:1412}"] = "{npc:3033}, oder {npc:262560} im Norden von {zone:1412}",
		["{npc:3448} stands in the Crossroads. No {skill:182}? {npc:3490}, a few steps away by the wind rider master, sells {item:2449} for 80 copper each, three at a time until he restocks."] = "{npc:3448} steht in Crossroads. Kein {skill:182}? {npc:3490}, ein paar Schritte entfernt beim Windreitermeister, verkauft {item:2449} für 80 Kupfer das Stück, je drei, bis er wieder Nachschub hat.",
		["{npc:4217} stands upstairs in the druids' building of the {area:1658}. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217} steht oben im Druidengebäude der {area:1658}. Kein {skill:182}? Kauf zuerst fünf {item:2449} im Auktionshaus: Du brauchst sie später.",
		["{npc:4217} stands upstairs in the druids' building of the {area:1658}; {npc:270459} by the Skyborne Portal does not give this quest. Cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217} steht oben im Druidengebäude der {area:1658}; {npc:270459} am Portal der Himmelsgeborenen gibt diese Quest nicht. Wirke {spell:18960} und nimm den Flug von {npc:11800} aus der Mitte von {area:2361} (sie fliegt Druiden nach {area:702}, keine Flugroute nötig), dann das Portal nach oben. Kein {skill:182}? Kauf zuerst fünf {item:2449} im Auktionshaus: Du brauchst sie später.",
		["{npc:4217}, upstairs in the {area:1658}, teaches you {spell:8946}."] = "{npc:4217}, oben in der {area:1658}, bringt dir {spell:8946} bei.",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "{spell:8946} wird in Forever nicht mehr gelehrt: Diese Questreihe bringt es dir bei, mit einem Medizinbeutel unterwegs.",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "Zurück zu den Uralten",
		["Before the demons"] = "Vor den Dämonen",
		["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, stands in southern {zone:1447}, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around {area:2245}, the cave south of {area:2255} in {zone:1452}, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver."] = "Hastats Köcher braucht {item:18704}. {npc:6109}, ein Weltboss für einen Schlachtzug, steht im Süden von {zone:1447}, kehrt nur alle zwei bis vier Tage zurück und lässt ihn bei fast jedem Kill fallen. Die Cobalt-Drachkin-Elite in und um {area:2245}, die Höhle südlich von {area:2255} in {zone:1452}, lassen ihn etwa bei jedem 200. Kill fallen; Manaclaw dort etwas öfter. Überspring den Rest dieses Guides, wenn du den Köcher nicht willst.",
		["Learn {spell:19878} and get demon-slaying potions"] = "Lerne {spell:19878} und besorge Dämonentöten-Tränke",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and talking to Vartrus once more then gave {item:18715}, at no extra cost."] = "In Forever nicht bestätigt. In Classic entstand Rhok'delar, wenn du {item:18707} mit {item:18724} in deinen Taschen benutzt hast, und ein weiteres Gespräch mit Vartrus gab dir dann {item:18715}, ohne Mehrkosten.",
		["Onyxia"] = "Onyxia",
		["Onyxia is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. She drops one {item:18705} in about two kills of five, lootable without the quest, so only one hunter per kill gets it: settle who first."] = "Onyxia ist der Schlachtzugsboss für 40 Spieler in {area:2159}, einer Höhle im {area:511} im Süden von {zone:1445}; sie kehrt einmal pro Woche zurück. Sie lässt in etwa zwei von fünf Kills {item:18705} fallen, plünderbar auch ohne die Quest, sodass nur ein Jäger pro Kill ihn bekommt: Klärt vorher, wer zuerst dran ist.",
		["Rhok'delar and Lok'delar"] = "Rhok'delar und Lok'delar",
		["The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring a {item:9224} ({skill:171} or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. {spell:19878}, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head."] = "Die vier Dämonen sind Elite der Stufe 60, als freundliche Reisende getarnt; sprich einen an und sag, dass du weißt, was er ist, dann verwandelt er sich in seine Dämonengestalt. Kämpfe jeden allein: kein Begleiter (entlasse ihn), keine Heilung, kein Buff und kein Angriff eines anderen Spielers, sobald der Kampf beginnt, sonst nennt dich der Dämon einen Feigling und verschwindet, und es dauert 3 Stunden, bis er zurückkehrt (auch nach seinem Tod). Buffs und Tränke, die du vor dem Pull nimmst, sind in Ordnung, und ein Freund darf danebenstehen, um umherstreifende Monster oder gegnerische Spieler zu töten, solange er nie den Dämon oder dich berührt. Bring {item:9224} mit ({skill:171} oder das Auktionshaus), Große Manatränke für die langen Kites und eine Nahkampfwaffe mit der Verzauberung „Dämonentöten“, wenn du kannst. {spell:19878}, von deinem Lehrer, zeigt die getarnten Dämonen auf der Minikarte an. Stell in einer Gruppe die Beuteverteilung auf „Jeder gegen jeden“, damit du den Kopf plündern kannst.",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "Die epische Bogen-Questreihe der Jäger: In Classic wurden aus Stab und Sehne Rhok'delar und Lok'delar (in Forever unbestätigt).",
		["The {item:18703}"] = "{item:18703}",
		["Vartrus, Stoma and {npc:14526} are petrified trees on a small island in a ring-shaped lake in {area:1767}, north {zone:1448}. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to {area:1998}; Horde: fly to {area:1997}. Vartrus gives {quest:7636}, Stoma A Proper String, Hastat the quiver; each can be handed in on its own."] = "Vartrus, Stoma und {npc:14526} sind versteinerte Bäume auf einer kleinen Insel in einem ringförmigen See in {area:1767}, nördlich von {zone:1448}. Ihre Geister erscheinen nur, wenn jemand mit dem Blatt den kleinen Hügel der Insel bis zu seinem Ostrand hinaufsteigt. Allianz: Flieg nach {area:1998}; Horde: Flieg nach {area:1997}. Vartrus gibt {quest:7636}, Stoma A Proper String, Hastat den Köcher; jede kann einzeln abgegeben werden.",
		["from the {item:18703}"] = "von {item:18703}",
		["{area:2717} is a 40-player raid inside {area:254}. When {npc:12018} yields, the {object:179703} appears; it holds the {item:18703} about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest."] = "{area:2717} ist ein Schlachtzug für 40 Spieler in {area:254}. Wenn {npc:12018} nachgibt, erscheint {object:179703}; sie enthält {item:18703} etwa in der Hälfte der Fälle, eines pro Kill, es kann also mehrere Wochen Schlachtzüge dauern. Klicke das Blatt mit der rechten Maustaste an, um die Quest zu starten.",
		["{item:18704}, from {npc:6109}"] = "{item:18704}, von {npc:6109}",
		["{item:18705}, from Onyxia"] = "{item:18705}, von Onyxia",
		["{item:18707}, by Vartrus"] = "{item:18707}, bei Vartrus dem Uralten",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: Lok'delar in Classic",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: der Köcher, zuletzt in diesem Guide",
		["{npc:14527}, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use {spell:19878}. Talk to her and she becomes {npc:14533}, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her {spell:421} hits hard, so drain her mana with {spell:3034} (a 15-second cooldown on Forever) and keep her busy; her {spell:23205} cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free."] = "{npc:14527}, eine Trollin mit einem Wolf, geht einen langen Weg, der am See im Westen von Un'Goro beginnt und bis in den Süden des Kraters reichen kann; nutze {spell:19878}. Sprich sie an, und sie wird zu {npc:14533}, ihr Wolf Precious zu einem Teufelspirscher. Die schwerste der vier: Leg Precious eine Eiskältefalle und zieh Simone weit von ihm weg, oder kite Precious weg und töte ihn zuerst, lass Simone zurücksetzen und komm allein für sie zurück. Ihr {spell:421} trifft hart, also entzieh ihr mit {spell:3034} (auf Forever 15 Sekunden Cooldown) das Mana und halte sie beschäftigt; ihr {spell:23205} senkt deine Fernkampf-Angriffskraft, also erledige sie im Nahkampf. Plündere ihren Kopf, bevor Precious sich befreit.",
		["{npc:14529}, a human, wanders the western {zone:1428} south of {area:254}. Talk to him and he becomes {npc:14534}, the easiest of the four. Keep {spell:3043} on him the whole fight: while it lasts he barely hurts you. When he goes into {spell:23257}, remove it with {spell:19801} and never stand in melee while it is up; between frenzies you can fight him in melee with {spell:2974} and {spell:2973}. He cannot leave the {zone:1428}, so kite him around the trees if needed."] = "{npc:14529}, ein Mensch, wandert durch den Westen von {zone:1428} südlich von {area:254}. Sprich ihn an, und er wird zu {npc:14534}, dem leichtesten der vier. Halte {spell:3043} den ganzen Kampf über auf ihm: Solange er wirkt, tut er dir kaum weh. Wenn er in {spell:23257} geht, entferne ihn mit {spell:19801} und steh nie im Nahkampf, solange er aktiv ist; zwischen den Raserei-Phasen kannst du ihn mit {spell:2974} und {spell:2973} im Nahkampf bekämpfen. Er kann {zone:1428} nicht verlassen, also kite ihn bei Bedarf um die Bäume.",
		["{npc:14531}, a tauren, walks a loop in the rocks of northern {zone:1452}, north of {area:2255}. Talk to him and he becomes {npc:14535}. Within 30 yards of him {spell:23298} hits hard: keep your distance and kite him the whole fight, {spell:5118} on, south down the road. {spell:1978} on him adds {spell:23299}, extra Nature damage, so keep it ticking while you run; his {spell:23257} can be removed with {spell:19801}, but distance matters more. It is a long fight: bring mana potions and plan your kiting path."] = "{npc:14531}, ein Tauren, geht eine Runde in den Felsen im Norden von {zone:1452}, nördlich von {area:2255}. Sprich ihn an, und er wird zu {npc:14535}. Im Umkreis von 30 Metern um ihn trifft {spell:23298} hart: Halte Abstand und kite ihn den ganzen Kampf über, {spell:5118} an, die Straße nach Süden. {spell:1978} auf ihm fügt {spell:23299} hinzu, zusätzlichen Naturschaden, also halte ihn am Ticken, während du läufst; seine {spell:23257} lässt sich mit {spell:19801} entfernen, aber der Abstand ist wichtiger. Es ist ein langer Kampf: Bring Manatränke mit und plane deinen Kite-Weg.",
		["{npc:14536}, a gnome, walks around the gates of {area:3428} in the far south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. He enrages with {spell:23272} as he turns: drop a {spell:13809}, {spell:5384}, and he resets without the enrage. {spell:2974} roots him for a long time; while rooted he fears you and sends beetles ({npc:14761}): kill them fast with traps and {spell:2643} before they wear you down."] = "{npc:14536}, ein Gnom, läuft um die Tore von {area:3428} im äußersten Südwesten von {zone:1451}. Sprich ihn an, und er wird zu {npc:14530}. Bei der Verwandlung wird er mit {spell:23272} wütend: Wirf eine {spell:13809}, {spell:5384}, und er setzt ohne die Wut zurück. {spell:2974} wurzelt ihn lange fest; solange er festgewurzelt ist, versetzt er dich in Furcht und schickt Käfer ({npc:14761}): Töte sie schnell mit Fallen und {spell:2643}, bevor sie dich zermürben.",
} end)()
t.guides["forever/class/hunter/taming-the-beast-alliance"] = (function() return {
		["At 10 go to {npc:1231}, the hunter trainer at the smithy in {area:131}. The Hunter's Path from {npc:5116} in {zone:1455}, {npc:11807} north-west of {area:131} or {npc:5515} in {zone:1453} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Geh mit Stufe 10 zu {npc:1231}, dem Jägerlehrer bei der Schmiede in {area:131}. Auch der Weg des Jägers von {npc:5116} in {zone:1455}, {npc:11807} nordwestlich von {area:131} oder {npc:5515} in {zone:1453} führt hierher, für ein wenig Erfahrung; es ist nur ein Hinweis. Mit Stufe 10 stattdessen in Elwynn? Die Questreihe von {npc:251507} in {area:87} bringt dasselbe bei.",
		["At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same."] = "Geh mit Stufe 10 zu {npc:251507}, der Jägerlehrerin, die mit den anderen Lehrern beim Lion's Pride Inn in {area:87} steht; {npc:258930}, der Begleiterlehrer, ist neben ihr. Himmelsgeborene: Das ist für alle, die {zone:2521} ohne Zähmung verlassen haben; es bringt dasselbe bei.",
		["At 10 go to {npc:3601}, the hunter trainer in {area:186}. The Hunter's Path from {npc:3596} at {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} or {npc:1231} in {area:131} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Geh mit Stufe 10 zu {npc:3601}, dem Jägerlehrer in {area:186}. Auch der Weg des Jägers von {npc:3596} bei {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} oder {npc:1231} in {area:131} führt hierher, für ein wenig Erfahrung; es ist nur ein Hinweis. Mit Stufe 10 stattdessen in Elwynn? Die Questreihe von {npc:251507} in {area:87} bringt dasselbe bei.",
		["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "Mit Stufe 10 schickt dich {npc:254084}, eine Jägerlehrerin auf {zone:2521}, womöglich mit {quest:94007} weiter nach {area:16638}. Es ist nur ein Hinweis: Überspring ihn, wenn du schon in {area:16638} bist.",
		["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}."] = "Entlasse zuerst den Eber (Rechtsklick auf das Begleiterportrait, {spell:2641}): Ein freigelassener Übungsbegleiter kann sich gegen dich wenden. Gray Forest Wolves (Stufe 7-8) laufen in den Wäldern östlich von {area:87}, östlich von {area:18}.",
		["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of {area:131}, more north-west and west of it; the smaller Juvenile Snow Leopards do not count."] = "Entlasse zuerst den Eber (Rechtsklick auf das Begleiterportrait, {spell:2641}): Ein freigelassener Übungsbegleiter kann sich gegen dich wenden. Schneeleoparden (Stufe 7-8) streifen über die Hänge südöstlich von {area:131}, mehr noch nordwestlich und westlich davon; die kleineren Juvenile Snow Leopards zählen nicht.",
		["Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of {area:186}."] = "Entlasse die Katze. Strigid Screechers (Stufe 7-8), Eulen, sitzen in den Wäldern südlich, südwestlich und westlich von {area:186}.",
		["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "Entlasse zuerst den Crawler (Rechtsklick auf das Begleiterportrait, {spell:2641}). Ornery Galestriders grasen in {area:16626}, den Feldern ein Stück westlich und südwestlich von {area:16638}.",
		["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "Entlasse den Galestrider. Vuldren Alphas jagen im selben {area:16626}, ein Stück weiter südlich.",
		["Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around {area:131}, many south-east of it and more north-west toward {area:77}; their {spell:3130} hits hard, so start at full health."] = "Entlasse den Leoparden. Eisklauenbären (Stufe 7-8) streifen durch die Hügel rund um {area:131}, viele südöstlich davon und mehr nordwestlich Richtung {area:77}; ihr {spell:3130} trifft hart, also fang mit voller Gesundheit an.",
		["Dismiss the spider first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of {area:259}, south of {area:186}; the plain Nightsabers by the village do not count."] = "Entlasse zuerst die Spinne (Rechtsklick auf das Begleiterportrait, {spell:2641}): Ein freigelassener Übungsbegleiter kann sich gegen dich wenden. Nightsaber Stalkers (Stufe 7-8) liegen am Hang südlich von {area:259}, südlich von {area:186}; die einfachen Nachtsäbler beim Dorf zählen nicht.",
		["Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town."] = "Entlasse den Wolf. Young Forest Bears (Stufe 8-9) streifen durch die Wälder direkt südlich von {area:87}, mehr noch südwestlich und südöstlich der Stadt.",
		["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "Zufriedenheit: das Gesicht im Begleiterfenster. Ein unzufriedener Begleiter richtet drei Viertel seines Schadens an, ein zufriedener ein Viertel mehr. Die Zufriedenheit sinkt langsam, schneller, wenn der Begleiter stirbt; ein zu lange unzufriedener Begleiter kann weglaufen.",
		["Large Crag Boars (level 6-7) root around the fields west, south and north-west of {area:131} and respawn every 3 minutes. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, being out of range or anyone else's help breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:1231}. The boars use {spell:6268} from 25 yards, so start with the rod, not {spell:75}. Keep each rod: it goes back to {npc:1231}."] = "Large Crag Boars (Stufe 6-7) wühlen auf den Feldern westlich, südlich und nordwestlich von {area:131} und respawnen alle 3 Minuten. So funktioniert der Stab: Wähle ein lebendes Tier als Ziel, benutze {item:15908} und steh während des gesamten Kanalisierens still, während es dich schlägt. Bewegen, Zurückschlagen, außer Reichweite sein oder fremde Hilfe unterbricht es und kostet eine der wenigen Ladungen des Stabs; wenn sie aufgebraucht sind, zerstöre den Stab, brich die Quest ab und nimm sie bei {npc:1231} noch einmal an. Die Eber nutzen {spell:6268} aus 25 Metern, also fang mit dem Stab an, nicht mit {spell:75}. Behalte jeden Stab: Er geht zurück an {npc:1231}.",
		["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "Die Loyalität wächst mit der Zeit und mit Kills. Jeder Loyalitätsrang erhöht die Trainingspunkte, die du in {spell:5149} ausgibst (Begleiterstufe mal Loyalitätsrang minus eins).",
		["Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}."] = "In der Nähe von {area:131}: Schneeleoparden (Katzen, Stufe 7-8) streifen überall durch {zone:1426}, Scarred Crag Boars (9-10) durch den Osten Richtung {zone:1432}; mit 10-11 streifen Bergeber durch den Westen von {zone:1432}.",
		["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "In der Nähe von {area:16638}: Vuldren Alphas (Stufe 10), das Tier deiner letzten Übungszähmung, jagen in {area:16626}; Shriekling Matriarchs (Raptoren, Stufe 9) nisten direkt westlich von {area:16638}; Shadowgale Urseras (Bären, 10-11) streifen durch den Norden von {zone:2521}.",
		["Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}."] = "In der Nähe von {area:186}: Elder Nightsabers (Katzen, Stufe 8-9) und Feral Nightsabers (Katzen, 10-11) streifen durch die Wälder im Nordwesten von {zone:1438}.",
		["Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}."] = "In der Nähe von {area:87} gibt es keine Katzen: Prowlers (Wölfe, Stufe 9-10) streifen durch das östliche Elwynn, Longsnouts (Eber, 10-11) durch den äußersten Südwesten an der Grenze zu {zone:1436}; mit 12-13 grasen Young Goretusks (Eber) auf den Feldern im Norden von {zone:1436}.",
		["Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}."] = "Begleiterlehrer verkaufen Ränge von {spell:1853} und Widerstände. Allianz: {npc:258930} in {area:87}, {npc:2879} bei den Jägerlehrern im {object:28027} von {zone:1453}, {npc:2878} in {area:131}, {npc:10090} in {object:32390} von {zone:1455}, Keldas in {area:186}, Silvaria in der Cenarion-Enklave von {zone:1457}, {npc:254411} in {area:16638}.",
		["Rockhide Boars (level 7-8) graze in three herds south and south-east of {area:87}, toward the {area:64}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use {spell:6268}, so start with the rod, not {spell:75}. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through {area:87} from here."] = "Rockhide Boars (Stufe 7-8) grasen in drei Herden südlich und südöstlich von {area:87}, Richtung {area:64}. So funktioniert der Stab: Wähle ein lebendes Tier als Ziel, benutze {item:15908} und steh während des gesamten Kanalisierens still, während es dich schlägt. Bewegen, Zurückschlagen, eine Heilung von jemand anderem oder fremde Treffer auf das Tier unterbrechen es und kosten eine der wenigen Ladungen des Stabs; wenn sie aufgebraucht sind, zerstöre den Stab, brich die Quest ab und nimm sie noch einmal an. Die Eber nutzen {spell:6268}, also fang mit dem Stab an, nicht mit {spell:75}. Einen Eber zu töten zählt nicht. Behalte jeden Stab: Er geht zurück an Josephine. Ein Zwerg oder Nachtelf, der Josephines Stab statt den seines Heimatlehrers genommen hat, wird von hier aus durch {area:87} geführt.",
		["Take the road west from {area:186} to {zone:1457}. {npc:4146} stands inside the {area:1658} with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her."] = "Nimm die Straße von {area:186} nach Westen bis {zone:1457}. {npc:4146} steht in der {area:1658} bei den Jägerlehrern; Silvaria, die Begleiterlehrerin, ist die Rampe hinauf neben ihr.",
		["Tame a beast of your level to keep"] = "Zähme ein Tier deiner Stufe, das du behältst",
		["Tame {npc:1922}"] = "Zähme {npc:1922}",
		["Tame {npc:250874}"] = "Zähme {npc:250874}",
		["Tame {npc:251707}"] = "Zähme {npc:251707}",
		["Tame {npc:254588}"] = "Zähme {npc:254588}",
		["Tame {npc:524}"] = "Zähme {npc:524}",
		["Tame {npc:822}"] = "Zähme {npc:822}",
		["Use the {item:15908} on a living alpha"] = "Benutze {item:15908} an einem lebenden Alpha",
		["Use the {item:15908} on a living bear"] = "Benutze {item:15908} an einem lebenden Bären",
		["Use the {item:15908} on a living boar"] = "Benutze {item:15908} an einem lebenden Eber",
		["Use the {item:15908} on a living crawler"] = "Benutze {item:15908} an einem lebenden Crawler",
		["Use the {item:15908} on a living galestrider"] = "Benutze {item:15908} an einem lebenden Galestrider",
		["Use the {item:15908} on a living leopard"] = "Benutze {item:15908} an einem lebenden Leoparden",
		["Use the {item:15908} on a living owl"] = "Benutze {item:15908} an einer lebenden Eule",
		["Use the {item:15908} on a living spider"] = "Benutze {item:15908} an einer lebenden Spinne",
		["Use the {item:15908} on a living stalker"] = "Benutze {item:15908} an einem lebenden Stalker",
		["Use the {item:15908} on a living wolf"] = "Benutze {item:15908} an einem lebenden Wolf",
		["Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of {area:186}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their {spell:1265843} roots you but does not break the channel if you keep still. Keep each rod: it goes back to {npc:3601}."] = "Webwood Lurkers (Stufe 5-6) schleichen durch die Wälder nordöstlich, südwestlich und östlich von {area:186}. So funktioniert der Stab: Wähle ein lebendes Tier als Ziel, benutze {item:15908} und steh während des gesamten Kanalisierens still, während es dich schlägt; Bewegen, Angreifen oder fremde Hilfe unterbricht es und kostet eine der wenigen Ladungen des Stabs (keine Ladungen mehr: zerstöre den Stab, brich die Quest ab, nimm sie noch einmal an). Ihr {spell:1265843} wurzelt dich fest, unterbricht das Kanalisieren aber nicht, wenn du stillstehst. Behalte jeden Stab: Er geht zurück an {npc:3601}.",
		["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to {npc:252389}."] = "Windsong Crawlers leben nur am Wasser: Die nächsten huschen am Ufer südwestlich von {area:16638} entlang, zwischen den Krabben. So funktioniert der Stab: Wähle einen lebenden Crawler als Ziel, benutze {item:15908} und steh während des gesamten Kanalisierens still, während er dich schlägt; Bewegen, Zurückschlagen oder fremde Hilfe unterbricht es und kostet eine der wenigen Ladungen des Stabs. Ihn zu töten zählt nicht. Behalte jeden Stab: Er geht zurück an {npc:252389}.",
		["Your first pet"] = "Dein erster Begleiter",
		["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "Dein eigener Begleiter mit Stufe 10: Drei Übungszähmungen mit {item:15908} bringen dir {spell:1515} bei, dann {spell:5149}.",
		["{npc:10090} in {zone:1455}"] = "{npc:10090} in {zone:1455}",
		["{npc:10090}, the pet trainer, stands in the {object:32390} in {zone:1455}'s {object:32359}, by the hunter trainers."] = "{npc:10090}, die Begleiterlehrerin, steht in {object:32390} in {object:32359} von {zone:1455}, bei den Jägerlehrern.",
		["{npc:1231} in {area:131}"] = "{npc:1231} in {area:131}",
		["{npc:1231}: the first {item:15908}"] = "{npc:1231}: der erste {item:15908}",
		["{npc:251507} in {area:87}"] = "{npc:251507} in {area:87}",
		["{npc:251507}: the first {item:15908}"] = "{npc:251507}: der erste {item:15908}",
		["{npc:252389} in {area:16638}"] = "{npc:252389} in {area:16638}",
		["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389} steht bei den Lehrern am Westtor von {area:16638}, {npc:254411} neben ihr.",
		["{npc:252389}: the first {item:15908}"] = "{npc:252389}: der erste {item:15908}",
		["{npc:254411}, beside her: {spell:5149}"] = "{npc:254411}, neben ihr: {spell:5149}",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, neben ihr: {spell:5149}",
		["{npc:3601} in {area:186}"] = "{npc:3601} in {area:186}",
		["{npc:3601}: the first {item:15908}"] = "{npc:3601}: der erste {item:15908}",
		["{npc:4146} in {zone:1457}"] = "{npc:4146} in {zone:1457}",
		["{quest:6063} (Alliance)"] = "{quest:6063} (Allianz)",
		["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515} funktioniert wie der Stab: ein Tier deiner Stufe oder niedriger, ein Kanalisieren, bei dem du dich nicht bewegen darfst, und das Tier schlägt dich die ganze Zeit. Ein Begleiter behält die Stufe, auf der du ihn gezähmt hast, und steigt mit dir auf; er kann nie über deiner Stufe liegen, also zähme einen nahe an deiner. Jede Familie hat auf Forever ihre eigene Fähigkeit (zum Beispiel den Sturmangriff eines Ebers). Zum Leveln schlägt eine Katze am härtesten zu (Klaue und {spell:17253}), und ein Eber hält mehr aus.",
		["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in {area:87}, Jaeana in {zone:1457} and the innkeepers on {zone:2521} sell meat; the innkeepers of {area:131} and {area:186} sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584}: Öffne dein Zauberbuch, wirke {spell:1584} und klicke auf ein Futter, das die Familie deines Begleiters frisst (der Tooltip des Begleiters listet sie auf: Katzen fressen Fleisch und Fisch, Eber fast alles). Rohes Fleisch, das du von Tieren plünderst, zählt. Zum Kaufen: Der Fleischer Toddrick in {area:87}, Jaeana in {zone:1457} und die Gastwirte auf {zone:2521} verkaufen Fleisch; die Gastwirte von {area:131} und {area:186} verkaufen Brot. Futter nahe der Stufe des Begleiters macht ihn am glücklichsten; deutlich niedrigeres gibt etwa die Hälfte. Im Kampf kannst du nicht füttern.",
		["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} on {zone:2521}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149} (Zauberbuch, Reiter Allgemein) bringt deinem aktuellen Begleiter die Fähigkeiten bei, die du kennst. Um eine neue Fähigkeit oder einen neuen Rang zu lernen: Lass deinen Begleiter bei einem Stallmeister (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} auf {zone:2521}), zähme ein Tier, das sie beherrscht (im Begleiter-Zauberbuch-Reiter siehst du, was es kann), benutze die Fähigkeit in Kämpfen, bis das Spiel meldet, dass du sie gelernt hast, hol dann deinen eigenen Begleiter zurück und bring sie ihm mit {spell:5149} bei. Ein Begleiter hat höchstens vier aktive Fähigkeiten.",
		["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "{spell:883}, {spell:2641} und {spell:982} sind jetzt in deinem Zauberbuch; {spell:136} bekommst du mit Stufe 12 von deinem Lehrer. Ein toter Begleiter braucht {spell:982}; einer, der mehr als etwa 100 Meter entfernt ist, wird entlassen und kommt mit {spell:883} zurück.",
} end)()
t.guides["forever/class/hunter/taming-the-beast-horde"] = (function() return {
		["Adult Plainstriders (level 6-7) walk the plains south-west and north-west of {area:222}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). A plainstrider flees at 25% health, so do not damage it first. Keep each rod: it goes back to Yaw."] = "Adult Plainstriders (Stufe 6-7) laufen über die Ebenen südwestlich und nordwestlich von {area:222}. So funktioniert der Stab: Wähle ein lebendes Tier als Ziel, benutze {item:15908} und steh während des gesamten Kanalisierens still, während es dich schlägt; Bewegen, Zurückschlagen oder fremde Hilfe unterbricht es und kostet eine der wenigen Ladungen des Stabs (keine Ladungen mehr: zerstöre den Stab, brich die Quest ab, nimm sie noch einmal an). Ein Plainstrider flieht bei 25% Gesundheit, also beschädige ihn vorher nicht. Behalte jeden Stab: Er geht zurück an Yaw.",
		["At 10 go to {npc:3065}, who stands at the north edge of {area:222}. The Hunter's Path from {npc:3038} in {zone:1456}, {npc:3407} in {zone:1454} or {npc:3171} in {area:362} also leads here, for a little experience; it is only a pointer."] = "Geh mit Stufe 10 zu {npc:3065}, der am Nordrand von {area:222} steht. Auch der Weg des Jägers von {npc:3038} in {zone:1456}, {npc:3407} in {zone:1454} oder {npc:3171} in {area:362} führt hierher, für ein wenig Erfahrung; es ist nur ein Hinweis.",
		["At 10 go to {npc:3171}, the hunter trainer inside the barracks in {area:362}. If {npc:3407} in {zone:1454}, {npc:11814} in {area:367} or {npc:3038} in {zone:1456} hands you The Hunter's Path, take it and hand it to {npc:3171} for a little experience; it is only a pointer, and you can take the first rod without it."] = "Geh mit Stufe 10 zu {npc:3171}, dem Jägerlehrer in der Kaserne in {area:362}. Wenn dir {npc:3407} in {zone:1454}, {npc:11814} in {area:367} oder {npc:3038} in {zone:1456} den Weg des Jägers gibt, nimm ihn an und gib ihn für ein wenig Erfahrung bei {npc:3171} ab; es ist nur ein Hinweis, und den ersten Stab bekommst du auch ohne ihn.",
		["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "Mit Stufe 10 schickt dich {npc:254084}, eine Jägerlehrerin auf {zone:2521}, womöglich mit {quest:94007} weiter nach {area:16638}. Es ist nur ein Hinweis: Überspring ihn, wenn du schon in {area:16638} bist.",
		["Dire Mottled Boars (level 6-7) roam just north and west of {area:362}. How the rod works: target a living beast, use the {item:15908} from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:3171}. The boars charge from 20 yards, so start with the rod, not {spell:75}. The tamed boar becomes your pet for practice. Keep each rod: it goes back to {npc:3171}."] = "Dire Mottled Boars (Stufe 6-7) streifen direkt nördlich und westlich von {area:362} umher. So funktioniert der Stab: Wähle ein lebendes Tier als Ziel, benutze {item:15908} in dessen Reichweite und steh während des gesamten Kanalisierens still, während das Tier dich schlägt. Bewegen, Zurückschlagen, eine Heilung von jemand anderem oder fremde Treffer auf das Tier unterbrechen es und kosten eine der wenigen Ladungen des Stabs; wenn sie aufgebraucht sind, zerstöre den Stab, brich die Quest ab und nimm sie bei {npc:3171} noch einmal an. Die Eber stürmen aus 20 Metern los, also fang mit dem Stab an, nicht mit {spell:75}. Der gezähmte Eber wird zur Übung dein Begleiter. Behalte jeden Stab: Er geht zurück an {npc:3171}.",
		["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "Entlasse zuerst den Crawler (Rechtsklick auf das Begleiterportrait, {spell:2641}). Ornery Galestriders grasen in {area:16626}, den Feldern ein Stück westlich und südwestlich von {area:16638}.",
		["Dismiss the crawler. Armored Scorpids (level 7-8) crawl the dry plains west and south-west of {area:362}, some just south of the road west out of town; {spell:1494} shows them. Their hits can break the channel: start at full health and keep still."] = "Entlasse den Crawler. Armored Scorpids (Stufe 7-8) kriechen über die trockenen Ebenen westlich und südwestlich von {area:362}, einige direkt südlich der Straße, die westlich aus der Stadt führt; {spell:1494} zeigt sie an. Ihre Treffer können das Kanalisieren unterbrechen: Fang mit voller Gesundheit an und steh still.",
		["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "Entlasse den Galestrider. Vuldren Alphas jagen im selben {area:16626}, ein Stück weiter südlich.",
		["Dismiss the plainstrider first (right-click the pet portrait, {spell:2641}): a released practice pet may attack you. Prairie Stalkers (level 7-8) roam the grass north of {area:222}."] = "Entlasse zuerst den Plainstrider (Rechtsklick auf das Begleiterportrait, {spell:2641}): Ein freigelassener Übungsbegleiter kann dich angreifen. Prairie Stalkers (Stufe 7-8) streifen durch das Gras nördlich von {area:222}.",
		["Dismiss the stalker. Swoops (level 7-9) glide over the plains north-west and north-east of Bloodhoof; the Taloned Swoops do not count. A {npc:2970}'s knockdown breaks the channel, but it lands only once per channel: start the rod just after it has used it."] = "Entlasse den Stalker. Swoops (Stufe 7-9) gleiten über die Ebenen nordwestlich und nordöstlich von Bloodhoof; die Taloned Swoops zählen nicht. Der Niederschlag eines {npc:2970} unterbricht das Kanalisieren, trifft aber nur einmal pro Kanalisierung: Starte den Stab direkt, nachdem er ihn eingesetzt hat.",
		["First dismiss the boar (right-click your pet's portrait, {spell:2641}): a released practice pet can turn on you. Surf Crawlers (level 7-8) walk the beaches around {area:367} and the {area:368}; the small Pygmy Surf Crawlers do not count. A crawler runs for help at 15% health, so do not hurt it."] = "Entlasse zuerst den Eber (Rechtsklick auf das Portrait deines Begleiters, {spell:2641}): Ein freigelassener Übungsbegleiter kann sich gegen dich wenden. Surf Crawlers (Stufe 7-8) laufen an den Stränden um {area:367} und die {area:368}; die kleinen Pygmy Surf Crawlers zählen nicht. Ein Crawler holt bei 15% Gesundheit Hilfe, also verletze ihn nicht.",
		["Follow the road north to {zone:1454}'s gate. {npc:3352} stands with the hunter trainers in the {object:172958}, up the ramp at the city's east side; {npc:10088}, the pet trainer, is a few steps north of him."] = "Folge der Straße nach Norden bis zum Tor von {zone:1454}. {npc:3352} steht bei den Jägerlehrern im {object:172958}, die Rampe hinauf auf der Ostseite der Stadt; {npc:10088}, der Begleiterlehrer, ist ein paar Schritte nördlich von ihm.",
		["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "Zufriedenheit: das Gesicht im Begleiterfenster. Ein unzufriedener Begleiter richtet drei Viertel seines Schadens an, ein zufriedener ein Viertel mehr. Die Zufriedenheit sinkt langsam, schneller, wenn der Begleiter stirbt; ein zu lange unzufriedener Begleiter kann weglaufen.",
		["Head north to {zone:1456} and take a lift up. {npc:3039} stands with the hunter trainers on {area:1641}; {npc:10086}, the pet trainer, is nearby."] = "Geh nach Norden bis {zone:1456} und nimm einen Aufzug nach oben. {npc:3039} steht bei den Jägerlehrern auf {area:1641}; {npc:10086}, der Begleiterlehrer, ist in der Nähe.",
		["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "Die Loyalität wächst mit der Zeit und mit Kills. Jeder Loyalitätsrang erhöht die Trainingspunkte, die du in {spell:5149} ausgibst (Begleiterstufe mal Loyalitätsrang minus eins).",
		["Near Bloodhoof: Flatland Prowlers (cats, level 9) and Prairie Wolf Alphas (wolves, 9-10) roam the plains of northern {zone:1412}; at 11-12, Savannah Huntresses (cats) prowl around the Crossroads in the {zone:1413}."] = "In der Nähe von Bloodhoof: Flatland Prowlers (Katzen, Stufe 9) und Prairie Wolf Alphas (Wölfe, 9-10) streifen durch die Ebenen im Norden von {zone:1412}; mit 11-12 streifen Savannah Huntresses (Katzen) um die Crossroads im {zone:1413}.",
		["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "In der Nähe von {area:16638}: Vuldren Alphas (Stufe 10), das Tier deiner letzten Übungszähmung, jagen in {area:16626}; Shriekling Matriarchs (Raptoren, Stufe 9) nisten direkt westlich von {area:16638}; Shadowgale Urseras (Bären, 10-11) streifen durch den Norden von {zone:2521}.",
		["Near {area:362}: Durotar Tigers (cats, level 7-8) roam the south of {zone:1411}, from {area:367} down the coast; Venomtail Scorpids (9-10) the north-west toward {zone:1454}; at 11-12, Savannah Huntresses (cats) prowl the plains around the Crossroads in the {zone:1413}."] = "In der Nähe von {area:362}: Durotar Tigers (Katzen, Stufe 7-8) streifen durch den Süden von {zone:1411}, von {area:367} die Küste hinunter; Venomtail Scorpids (9-10) durch den Nordwesten Richtung {zone:1454}; mit 11-12 streifen Savannah Huntresses (Katzen) über die Ebenen um die Crossroads im {zone:1413}.",
		["Pet trainers sell {spell:1853} ranks and resistances. Horde: Harruk in {area:362}, {npc:3688} at Bloodhoof, {npc:10088} in {zone:1454}'s {object:172958}, {npc:10086} on {zone:1456}'s {area:1641}, {npc:254411} in {area:16638}, later Grokor in {area:75} and Zudd at {object:3202}."] = "Begleiterlehrer verkaufen Ränge von {spell:1853} und Widerstände. Horde: Harruk in {area:362}, {npc:3688} in Bloodhoof, {npc:10088} im {object:172958} von {zone:1454}, {npc:10086} auf {area:1641} in {zone:1456}, {npc:254411} in {area:16638}, später Grokor in {area:75} und Zudd in {object:3202}.",
		["Tame a beast of your level to keep"] = "Zähme ein Tier deiner Stufe, das du behältst",
		["Tame {npc:250874}"] = "Zähme {npc:250874}",
		["Tame {npc:251707}"] = "Zähme {npc:251707}",
		["Tame {npc:254588}"] = "Zähme {npc:254588}",
		["Use the {item:15908} on a living alpha"] = "Benutze {item:15908} an einem lebenden Alpha",
		["Use the {item:15908} on a living boar"] = "Benutze {item:15908} an einem lebenden Eber",
		["Use the {item:15908} on a living crawler"] = "Benutze {item:15908} an einem lebenden Crawler",
		["Use the {item:15908} on a living galestrider"] = "Benutze {item:15908} an einem lebenden Galestrider",
		["Use the {item:15908} on a living plainstrider"] = "Benutze {item:15908} an einem lebenden Plainstrider",
		["Use the {item:15908} on a living scorpid"] = "Benutze {item:15908} an einem lebenden Skorpiden",
		["Use the {item:15908} on a living stalker"] = "Benutze {item:15908} an einem lebenden Stalker",
		["Use the {item:15908} on a living {npc:2970}"] = "Benutze {item:15908} an einem lebenden {npc:2970}",
		["Use the {item:15908} on a living {npc:3107}"] = "Benutze {item:15908} an einem lebenden {npc:3107}",
		["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs a charge. Killing one does not count."] = "Windsong Crawlers leben nur am Wasser: Die nächsten huschen am Ufer südwestlich von {area:16638} entlang, zwischen den Krabben. So funktioniert der Stab: Wähle einen lebenden Crawler als Ziel, benutze {item:15908} und steh während des gesamten Kanalisierens still, während er dich schlägt; Bewegen, Zurückschlagen oder fremde Hilfe unterbricht es und kostet eine Ladung. Ihn zu töten zählt nicht.",
		["Your first pet"] = "Dein erster Begleiter",
		["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "Dein eigener Begleiter mit Stufe 10: Drei Übungszähmungen mit {item:15908} bringen dir {spell:1515} bei, dann {spell:5149}.",
		["{npc:252389} in {area:16638}"] = "{npc:252389} in {area:16638}",
		["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389} steht bei den Lehrern am Westtor von {area:16638}, {npc:254411} neben ihr.",
		["{npc:252389}: the first {item:15908}"] = "{npc:252389}: der erste {item:15908}",
		["{npc:254411}, beside her: {spell:5149}"] = "{npc:254411}, neben ihr: {spell:5149}",
		["{npc:3039} in {zone:1456}"] = "{npc:3039} in {zone:1456}",
		["{npc:3065} at Bloodhoof"] = "{npc:3065} in Bloodhoof",
		["{npc:3065}: the first {item:15908}"] = "{npc:3065}: der erste {item:15908}",
		["{npc:3171} in {area:362}"] = "{npc:3171} in {area:362}",
		["{npc:3171}: the first {item:15908}"] = "{npc:3171}: der erste {item:15908}",
		["{npc:3352} in {zone:1454}"] = "{npc:3352} in {zone:1454}",
		["{quest:6061} (Horde)"] = "{quest:6061} (Horde)",
		["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515} funktioniert wie der Stab: ein Tier deiner Stufe oder niedriger, ein Kanalisieren, bei dem du dich nicht bewegen darfst, und das Tier schlägt dich die ganze Zeit. Ein Begleiter behält die Stufe, auf der du ihn gezähmt hast, und steigt mit dir auf; er kann nie über deiner Stufe liegen, also zähme einen nahe an deiner. Jede Familie hat auf Forever ihre eigene Fähigkeit (zum Beispiel den Sturmangriff eines Ebers). Zum Leveln schlägt eine Katze am härtesten zu (Klaue und {spell:17253}), und ein Eber hält mehr aus.",
		["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Grimtak the butcher and {npc:6928} in {area:362} sell meat, {npc:3025} in {zone:1456} and the innkeepers on {zone:2521} too; Bloodhoof's innkeeper and bakers sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584}: Öffne dein Zauberbuch, wirke {spell:1584} und klicke auf ein Futter, das die Familie deines Begleiters frisst (der Tooltip des Begleiters listet sie auf: Katzen fressen Fleisch und Fisch, Eber fast alles). Rohes Fleisch, das du von Tieren plünderst, zählt. Zum Kaufen: Der Fleischer Grimtak und {npc:6928} in {area:362} verkaufen Fleisch, ebenso {npc:3025} in {zone:1456} und die Gastwirte auf {zone:2521}; der Gastwirt und die Bäcker von Bloodhoof verkaufen Brot. Futter nahe der Stufe des Begleiters macht ihn am glücklichsten; deutlich niedrigeres gibt etwa die Hälfte. Im Kampf kannst du nicht füttern.",
		["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master ({npc:9987} in {area:362}, Seikwa at Bloodhoof, {npc:265756} on {zone:2521}, {npc:9988} in {zone:1454}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149} (Zauberbuch, Reiter Allgemein) bringt deinem aktuellen Begleiter die Fähigkeiten bei, die du kennst. Um eine neue Fähigkeit oder einen neuen Rang zu lernen: Lass deinen Begleiter bei einem Stallmeister ({npc:9987} in {area:362}, Seikwa in Bloodhoof, {npc:265756} auf {zone:2521}, {npc:9988} in {zone:1454}), zähme ein Tier, das sie beherrscht (im Begleiter-Zauberbuch-Reiter siehst du, was es kann), benutze die Fähigkeit in Kämpfen, bis das Spiel meldet, dass du sie gelernt hast, hol dann deinen eigenen Begleiter zurück und bring sie ihm mit {spell:5149} bei. Ein Begleiter hat höchstens vier aktive Fähigkeiten.",
		["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "{spell:883}, {spell:2641} und {spell:982} sind jetzt in deinem Zauberbuch; {spell:136} bekommst du mit Stufe 12 von deinem Lehrer. Ein toter Begleiter braucht {spell:982}; einer, der mehr als etwa 100 Meter entfernt ist, wird entlassen und kommt mit {spell:883} zurück.",
} end)()
t.guides["forever/class/hunter/the-hunters-charm"] = (function() return {
		["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "Mit 50 bietet sie jeder Jägerlehrer der Allianz an: {npc:5516} im {object:28027} von {zone:1453}, {npc:5116} in der {object:32390} von {zone:1455} oder Dorion in der Enklave des Cenarius von {zone:1457}.",
		["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "Mit 50 bietet sie jeder Jägerlehrer der Horde an: {npc:3352} im {object:172958} von {zone:1454} oder {npc:3039} auf der {area:1641} in {zone:1456}.",
		["Experience"] = "Erfahrung",
		["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "Erfahrung mit Stufe 50 durch {zone:1447} und den {area:1417}; die Gegenstandsauswahl aus Classic gibt es auf Forever womöglich nicht mehr.",
		["In Classic Ogtinc let you choose the {item:19991}, the {item:19992} or the {item:20083} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "In Classic ließ dich Ogtinc hier {item:19991}, {item:19992} oder {item:20083} wählen. Die Änderungshinweise von Forever sagen, dass die Auswahl entfällt, obwohl die Questseite noch drei unbenannte Belohnungen auflistet: Sieh dir das Belohnungsfenster an, bevor du abgibst.",
		["Morphaz in the {area:1417}"] = "Morphaz im {area:1417}",
		["Morphaz is an elite green drake (level 52) inside the {area:1417}, a five-player dungeon: needs a group of five. The temple stands in the {area:74} in eastern {zone:1435}: climb its outer steps, dive into the flooded hall and follow the stairs down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} or {area:42} and ride on. He is not there when you arrive: first kill the six troll guardians on the platforms around the upper ring, which opens the way down to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe (pull them one at a time); when both are dead, Morphaz and Hazzas appear together and cannot be split. Clear the dragonkin around the pit first, because they call for help. Morphaz uses {spell:12533} and {spell:11019}. The tooth always drops. Warriors in the group may want the same run for the voodoo feathers of the balcony trolls."] = "Morphaz ist ein grüner Elite-Drache (Stufe 52) im {area:1417}, einem Dungeon für fünf Spieler: Du brauchst eine Gruppe aus fünf. Der Tempel steht in {area:74} im Osten von {zone:1435}: Steig die äußeren Stufen hinauf, tauch in die geflutete Halle und folge den Treppen nach unten zum Eingang. Horde: Flieg nach {area:75}; Allianz: Flieg nach {area:1438} oder {area:42} und reite weiter. Er ist bei deiner Ankunft nicht da: Töte zuerst die sechs Trollwächter auf den Plattformen um den oberen Ring, was den Weg hinab zu {npc:5710} in der Opfergrube öffnet. Jammal'ans Tod bringt zwei Drachen hervor, Weaver und Dreamscythe (pull sie einzeln); sind beide tot, erscheinen Morphaz und Hazzas zusammen und lassen sich nicht trennen. Räum zuerst die Drachkin um die Grube, denn sie rufen um Hilfe. Morphaz nutzt {spell:12533} und {spell:11019}. Der Zahn fällt immer. Krieger in der Gruppe wollen vielleicht denselben Lauf für die Voodoo-Federn der Balkon-Trolle.",
		["You need six {item:20087}. Wavethrashers (three-headed sea beasts) live along {zone:1447}'s coasts, mostly underwater: the Young Wavethrashers (level 51-52) of the north-east shore drop a scale about one kill in three, the Wavethrashers (52-53) of the east coast by the {area:1229} about as often (a few walk the beach there), the Great Wavethrashers (53-54) of the south-east shore about one in seven. {spell:1494} does not show them; fight them where you can breathe, and bring water breathing if you can. Elite sharks swim the deeper water."] = "Du brauchst sechs {item:20087}. Wavethrashers (dreiköpfige Seebestien) leben an den Küsten von {zone:1447}, meist unter Wasser: Die Young Wavethrashers (Stufe 51-52) an der Nordostküste lassen etwa bei jedem dritten Kill eine Schuppe fallen, die Wavethrashers (52-53) der Ostküste beim {area:1229} etwa genauso oft (ein paar laufen dort am Strand), die Great Wavethrashers (53-54) der Südostküste etwa bei jedem siebten. {spell:1494} zeigt sie nicht an; bekämpfe sie dort, wo du atmen kannst, und bring Wasseratmung mit, wenn du kannst. Im tieferen Wasser schwimmen Hai-Elite.",
		["You need two Perfect Courser Antlers. Mosshoof Coursers (level 52-53, deer) graze all over {zone:1447} and drop one about one kill in twelve, so expect two dozen kills. Good herds: north of the {area:1220} in the north, and the hills north-east and south-east of {area:1237}; the {area:1234} area also has elite giants and dragonkin. They Enrage at 30% health. Coursers share spawn points with the Thunderhead hippogryphs: if none are around, kill the hippogryphs and coursers may spawn instead. Respawn is about five and a half minutes."] = "Du brauchst zwei Perfect Courser Antlers. Mosshoof Coursers (Stufe 52-53, Hirsche) grasen überall in {zone:1447} und lassen etwa bei jedem zwölften Kill eines fallen, rechne also mit zwei Dutzend Kills. Gute Herden: nördlich von {area:1220} im Norden und in den Hügeln nordöstlich und südöstlich von {area:1237}; im Gebiet {area:1234} gibt es außerdem Riesen- und Drachkin-Elite. Sie werden bei 30% Gesundheit wütend. Coursers teilen sich Spawnpunkte mit den Thunderhead-Hippogreifen: Sind keine da, töte die Hippogreife, dann können stattdessen Coursers spawnen. Der Respawn dauert etwa fünfeinhalb Minuten.",
		["{item:20017}, from Mosshoof Coursers"] = "{item:20017}, von Mosshoof Coursers",
		["{item:20019}, inside the {area:1417}"] = "{item:20019}, im {area:1417}",
		["{npc:8405} lives on a raised spot on the cliffs at the north-east rim of the {area:1221}, west-central {zone:1447}. Keep to the high ridges around the ruins: the pit below does not lead up to him. Alliance: fly to {area:3137}; Horde: fly to {area:1237}, a short ride west of him."] = "{npc:8405} lebt auf einer erhöhten Stelle an den Klippen am Nordostrand der {area:1221}, im Westen von {zone:1447}. Bleib auf den hohen Graten um die Ruinen: Die Grube darunter führt nicht zu ihm hinauf. Allianz: Flieg nach {area:3137}; Horde: Flieg nach {area:1237}, ein kurzes Stück westlich von ihm.",
		["{quest:8151} (Alliance)"] = "{quest:8151} (Allianz)",
		["{quest:8151} (Horde)"] = "{quest:8151} (Horde)",
} end)()
t.guides["forever/class/mage/arcane-refreshment"] = (function() return {
		["Back to Lydros"] = "Zurück zu Lydros",
		["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing, or through the North wing's courtyard doors with a {item:18249} (it drops from the imp Pusillin in the East wing; a {item:18594} also opens them; Blink no longer gets past). Other mages in your group can take it too: share it."] = "Flieg nach Feathermoon (Allianz) oder {area:1099} (Horde) und reite nach {area:2577} in der Mitte von {zone:1444}. {npc:14368} wartet im Athenaeum, der Bibliothek, die du durch den Westflügel erreichst, oder durch die Hofflügeltüren des Nordflügels mit {item:18249} (er fällt vom Imp Pusillin im Ostflügel; auch {item:18594} öffnet sie; Blinzeln kommt nicht mehr vorbei). Andere Magier in deiner Gruppe können sie ebenfalls annehmen: Teilt sie.",
		["Hydrospawn"] = "Hydrobrut",
		["Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. {area:1758} hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets."] = "Hydrospawn, ein Wasserelementar-Elite der Stufe 57, lebt im Warpwood Quarter (Dire Maul Ost): Jage den Imp Pusillin, bis er sich zum Kampf stellt, räum den Satyrraum und nimm dann die Spiralrampe hinunter zum Becken. Eine Gruppe aus fünf. Frost wirkt bei ihm nicht, also wechseln Frostmagier zu Feuer oder Arkan. {area:1758} trifft alle im Umkreis von 10 Metern, also bleiben Fernkämpfer zurück; bei einem Viertel Gesundheit ruft er Hydrolings. Die Essenz fällt immer; er kommt erst wieder, wenn die Instanz zurückgesetzt wird.",
		["Shen'dralar reputation"] = "Ruf bei den Shen'dralar",
		["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{spell:10140} der Stufe 60, aus einer Bibliothek in {area:2577}: Getränke für dich und deine Gruppe.",
		["{item:18299}: Hydrospawn"] = "{item:18299}: Hydrobrut",
		["{npc:14368}: {spell:10140}, and 200 Shen'dralar reputation"] = "{npc:14368}: {spell:10140} und 200 Ruf bei den Shen'dralar",
} end)()
t.guides["forever/class/mage/astral-knot-garment"] = (function() return {
		["A robe or a blouse for Alliance mages in their late 20s."] = "Eine Robe oder eine Bluse für Allianz-Magier in ihren späten Zwanzigern.",
		["Back to Andromath"] = "Zurück zu Andromath",
		["Carrion Recluses"] = "Aaskrabbler",
		["Head east through {zone:1429} into Redridge, or fly to {area:69}. The {area:96} stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' {spell:2691} interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it."] = "Geh nach Osten durch {zone:1429} nach Redridge oder flieg nach {area:69}. Der {area:96} steht allein im Osten des Gebiets. Steig bis ganz nach oben (nicht ins Stockwerk darunter): Die Abhandlung ist das Buch, das aus dem Regal ragt, wo die Treppe hochkommt. Zwei Gnollhunde und ein Gnollzauberer bewachen das Regal; der {spell:2691} der Hunde unterbricht den Klick, also bekämpfe sie auf der Treppe außer Sichtweite. Morganth (Elite der Stufe 26) steht quer im obersten Stockwerk: Du brauchst ihn nicht, halte dich am linken Rand der Rampe, damit er stehen bleibt. Das Buch ist zwei Sekunden, nachdem es jemand genommen hat, wieder da. Wenn du stirbst, kann dein Geist hinauflaufen und daneben wieder zum Leben erwachen.",
		["The {area:96}"] = "{area:96}",
		["You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:5694} waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. ({npc:5497} may also offer you {npc:5694}, the pointer quest; it is only a pointer and you can skip it.)"] = "Du brauchst keinen Brief: Steig mit Stufe 26 das Wizard's Sanctum hinauf, den violetten Turm im {object:2101} von {zone:1453}. {npc:5694} wartet auf dem Spiralgang, kurz hinter der Tür des Portalraums nahe dem oberen Ende, und hat die Quest für dich. ({npc:5497} bietet dir vielleicht auch {npc:5694} an, die Hinweisquest; sie ist nur ein Hinweis, du kannst sie überspringen.)",
		["{area:492} in western {zone:1431}: the six Carrion Recluses (level 25-26, green, {spell:3609}) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. {npc:522}, a level 35 elite skeleton, walks the cemetery: watch for him."] = "{area:492} im Westen von {zone:1431}: Die sechs Carrion Recluses (Stufe 25-26, grün, {spell:3609}) laufen über die Gräber, die zentrale Statue und das Flussufer, und jede lässt eine Seide fallen; sie kommen nach 5 Minuten wieder. Die Black Widow Hatchlings (24-25) an den Hängen östlich des Friedhofs lassen sie etwa bei jedem sechsten Kill fallen, mische sie also beim Warten dazu. {npc:522}, ein Skelett-Elite der Stufe 35, läuft über den Friedhof: Halte nach ihm Ausschau.",
		["{npc:1309} works at {object:23296} in the {object:2101}. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit."] = "{npc:1309} arbeitet bei {object:23296} im {object:2101}. Die Robe gibt Intelligenz, Ausdauer und Willenskraft; die Bluse mehr Intelligenz und Ausdauer, aber keine Willenskraft.",
		["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144} unterrichtet Magier in {object:32362} in {zone:1455}. Nimm danach {area:2257} von {object:171524} nach {zone:1453}.",
		["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}; the portal near the top of the spiral ramp takes you to her."] = "{npc:5497} steht oben im Wizard's Sanctum, dem violetten Turm des {object:2101}; das Portal nahe dem oberen Ende der Spiralrampe bringt dich zu ihr.",
		["{npc:5694} (Skyborne)"] = "{npc:5694} (Himmelsgeborene)",
		["{quest:1939} waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers."] = "{quest:1939} wartet auf dem Spiralgang des Wizard's Sanctum, kurz hinter der Tür des Portalraums, wenn du von den Lehrern nach unten gehst.",
} end)()
t.guides["forever/class/mage/atiesh"] = (function() return {
		["Back to {npc:15192}"] = "Zurück zu {npc:15192}",
		["Back to {npc:15192} at the {area:2300}."] = "Zurück zu {npc:15192} bei den {area:2300}.",
		["Forty Splinters of Atiesh drop in Naxxramas, the 40-player raid in the necropolis over the {area:2277} in {zone:1423}: each of its twelve bosses before Sapphiron and {npc:15990}, and the Four Horsemen's chest, drops one about a third of the time, and the raid shares them out. It takes many weeks of clears. Keep every splinter in one stack."] = "Vierzig Splitter von Atiesh fallen in Naxxramas, dem Schlachtzug für 40 Spieler in der Nekropole über {area:2277} in {zone:1423}: Jeder seiner zwölf Bosse vor Saphiron und {npc:15990} sowie die Truhe der Vier Reiter lässt in etwa einem Drittel der Fälle einen fallen, und der Schlachtzug verteilt sie untereinander. Es dauert viele Wochen an Clears. Halte alle Splitter in einem Stapel.",
		["Right-click the {quest:9250} to start the quest, then take it to {npc:15192}, the bronze dragon in elf form who stands outside the {area:2300} in eastern {zone:1446}. Fly to {area:976} and ride east."] = "Klicke {quest:9250} mit der rechten Maustaste an, um die Quest zu starten, und bring sie dann zu {npc:15192}, dem Bronzedrachen in Elfengestalt, der vor den {area:2300} im Osten von {zone:1446} steht. Flieg nach {area:976} und reite nach Osten.",
		["Splinters of Atiesh"] = "Splitter von Atiesh",
		["Take the befouled staff to {area:2279}, the dungeon at the north end of {zone:1423}, through the main gate. On {object:175433} find the patch of {object:181206} with a small white flame on it, stand on it and use the staff: {npc:16387}, Hand of Sargeras (level 63 boss) steps out. Bring a strong group: his {spell:17466} hurts everyone and cannot be dispelled (shadow resistance helps), his {spell:28342} curse must be removed at once, and a warrior's Disarm makes him drop his sword, which a melee player can pick up and use against him. He stays up to two and a half hours, so you can regroup."] = "Bring den besudelten Stab nach {area:2279}, dem Dungeon am Nordende von {zone:1423}, durch das Haupttor. Finde auf {object:175433} die Stelle mit {object:181206}, auf der eine kleine weiße Flamme brennt, stell dich darauf und benutze den Stab: {npc:16387}, Hand von Sargeras (Boss der Stufe 63) tritt hervor. Bring eine starke Gruppe mit: Seine {spell:17466} schadet allen und lässt sich nicht bannen (Schattenwiderstand hilft), sein Fluch {spell:28342} muss sofort entfernt werden, und die Entwaffnung eines Kriegers lässt ihn sein Schwert fallen, das ein Nahkämpfer aufheben und gegen ihn einsetzen kann. Er bleibt bis zu zweieinhalb Stunden, ihr könnt euch also neu sammeln.",
		["The Greatstaff"] = "Der Großstab",
		["The Staff Head and the Base"] = "Der Stabkopf und die Basis",
		["The legendary staff of the Guardian: forty splinters from Naxxramas, two raid bosses and a demon in {area:2279}."] = "Der legendäre Stab des Wächters: vierzig Splitter aus Naxxramas, zwei Schlachtzugsbosse und ein Dämon in {area:2279}.",
		["Two more raid bosses, a full 40-player raid each, both pieces always drop: the {item:22733} from {npc:15990} on his throne at the top of Naxxramas, the {item:22734} from {npc:15727} at the bottom of the {area:16076}, behind the {area:3478} in southern {zone:1451}. Each boss comes back once a week."] = "Zwei weitere Schlachtzugsbosse, je ein voller Schlachtzug für 40 Spieler, beide Teile fallen immer: {item:22733} von {npc:15990} auf seinem Thron oben in Naxxramas, {item:22734} von {npc:15727} ganz unten im {area:16076}, hinter den {area:3478} im Süden von {zone:1451}. Jeder Boss kehrt einmal pro Woche zurück.",
		["the befouled staff, on the {object:181206} inside {area:2279}"] = "der besudelte Stab, auf der {object:181206} in {area:2279}",
		["your class's {npc:16387} quest; he hands you the befouled staff"] = "die {npc:16387}-Quest deiner Klasse; er gibt dir den besudelten Stab",
		["{item:22733}: {npc:15990}, Naxxramas"] = "{item:22733}: {npc:15990}, Naxxramas",
		["{item:22734}: {npc:15727}, {area:16076}, past the {object:176146}"] = "{item:22734}: {npc:15727}, {area:16076}, hinter dem {object:176146}",
		["{npc:16387}, Hand of Sargeras"] = "{npc:16387}, Hand von Sargeras",
		["{spell:28324}: forty splinters become the {quest:9250}"] = "{spell:28324}: Vierzig Splitter werden zu {quest:9250}",
} end)()
t.guides["forever/class/mage/celestial-orb"] = (function() return {
		["An off-hand orb or a staff for the late 30s, your pick."] = "Eine Schildhand-Kugel oder ein Stab für die späten 30er, nach deiner Wahl.",
		["At 40 the mage trainers who send you to {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}) also have {quest:2861}, a quest any class can do. {npc:6546} then wants the {quest:2846} from {npc:7795}, a level 46 elite naga in {area:978}, the troll dungeon in north-western {zone:1446}: a group of five, level 44-54. The reward window shows the {item:9527} and the {item:9531}."] = "Mit Stufe 40 haben die Magierlehrer, die dich zu {npc:6546} schicken ({npc:5497}, Bink, {npc:4568}, {npc:5885}), auch {quest:2861}, eine Quest, die jede Klasse machen kann. {npc:6546} will dann {quest:2846} von {npc:7795}, einer Naga-Elite der Stufe 46 in {area:978}, dem Troll-Dungeon im Nordwesten von {zone:1446}: eine Gruppe aus fünf, Stufe 44-54. Im Belohnungsfenster siehst du {item:9527} und {item:9531}.",
		["Back at {npc:6546}'s. Hand in the orb now; {quest:1955} waits for level 38. Kill the critters around the cottage first: they join the fight. Accepting {quest:1955} starts a 3 minute timer, and {npc:6546} calls the {npc:6549} out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again."] = "Zurück bei {npc:6546}. Gib die Kugel jetzt ab; {quest:1955} wartet auf Stufe 38. Töte zuerst die Kleintiere rund um das Häuschen: Sie schließen sich dem Kampf an. Das Annehmen von {quest:1955} startet einen 3-Minuten-Timer, und {npc:6546} ruft den {npc:6549} in ihrem Garten herbei: eine Elite der Stufe 40, die viele Zauber widersteht, wurzelt und verlangsamt. Sich zu gruppieren wird empfohlen: Ein Magier mit 40 braucht womöglich Hilfe oder Tränke, mit etwa 45 ist er allein machbar. Du kannst ihn vom Steg aus aus der Ferne pullen. Der Timer läuft nach seinem Tod weiter, gib die Quest also sofort ab. Läuft die Zeit ab, brich die Quest ab und nimm sie noch einmal an; sie ruft den Dämon erneut.",
		["Back to {npc:6546}. Accepting {quest:1957} opens a rift beside her cottage and starts a 10 minute timer: twelve {quest:1957} (level 40, Shock and {spell:403}) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out."] = "Zurück zu {npc:6546}. Das Annehmen von {quest:1957} öffnet einen Riss neben ihrem Häuschen und startet einen 10-Minuten-Timer: Zwölf {quest:1957} (Stufe 40, Schock und {spell:403}) kommen heraus, etwa vier auf einmal. Einen anzugreifen zieht die anderen nicht mit. Wenn du am Rand des Feldes stehst, lockst du sie alle an; der Baum südwestlich davon ist außerhalb ihrer Reichweite, aber in der Reichweite deiner Zauber. Töte zwölf und gib ab, bevor der Timer abläuft.",
		["The Burning Blade Summoners (level 38-39, not elite) work the {area:602} in southern {zone:1443}, east of {area:2408}, and every one carries an {item:7291}. They cast {spell:686} from 40 yards, keep an imp at their side and run for help at low health; Nether Maidens patrol the pillared ruin beside them, so pull with care. Horde mages: one more summoner stands alone in western {zone:1412}, south-west of {zone:1456}."] = "Die Burning Blade Summoners (Stufe 38-39, keine Elite) arbeiten im {area:602} im Süden von {zone:1443}, östlich von {area:2408}, und jeder trägt eine {item:7291}. Sie wirken {spell:686} aus 40 Metern, haben einen Imp an ihrer Seite und holen bei niedriger Gesundheit Hilfe; Nether Maidens patrouillieren in der Säulenruine neben ihnen, also zieh mit Vorsicht. Horde-Magier: Ein weiterer Summoner steht allein im Westen von {zone:1412}, südwestlich von {zone:1456}.",
		["{area:1517} is a dungeon in the northern {zone:1418}: a group of five, from level 40 here. Go in by the rear entrance, a cave in {area:1898} south-east of the main entrance (elite dragons fly nearby): the {npc:7023} (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an {npc:7209}, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back."] = "{area:1517} ist ein Dungeon im Norden von {zone:1418}: eine Gruppe aus fünf, hier ab Stufe 40. Geh durch den Hintereingang, eine Höhle in {area:1898} südöstlich des Haupteingangs (in der Nähe fliegen Elite-Drachen): Der {npc:7023} (Elite der Stufe 42) steht direkt hinter der ersten Tür. Bei 80, 60, 40 und 20 Prozent löst er einen {npc:7209} ab, ebenfalls eine Elite; solange ein Splitter lebt, reflektieren beide gezielte Zauber, also nutze Flächenzauber und deinen Zauberstab gegen sie. Ein Solo-Trick: Tritt jedes Mal, wenn ein Splitter erscheint, durch die nahe Gebietsgrenze nach draußen; der Sentinel heilt sich, schrumpft aber weiter. Er lässt die Energiequelle immer fallen und braucht 2 Stunden, um zurückzukehren.",
		["{area:978}, the troll dungeon in north-western {zone:1446}, needs a group of five; the guide waits for level 44. {npc:7795} is one of the bosses by the sacred pool, and the tiara always drops."] = "{area:978}, der Troll-Dungeon im Nordwesten von {zone:1446}, braucht eine Gruppe aus fünf; der Guide wartet auf Stufe 44. {npc:7795} ist einer der Bosse beim heiligen Teich, und die Tiara fällt immer.",
		["{item:7515} and Stave"] = "{item:7515} und Stab",
		["{npc:5497} at the top of the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you back to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497} oben im Wizard's Sanctum, im {object:2101} von {zone:1453}, schickt dich zurück zu {npc:6546}; Bink in {zone:1455} gibt dieselbe Quest.",
		["{npc:5885}, one of {zone:1454}'s mage trainers in {object:173161}, sends you back to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, einer der Magierlehrer von {zone:1454} in {object:173161}, schickt dich zurück zu {npc:6546}; {npc:4568} in {zone:1458} und {npc:3048} in {zone:1456} geben dieselbe Quest.",
		["{npc:6546}'s cottage is deep in the marsh west of Theramore, just north of the {area:508}; come in from the west road, the elites roam its east side."] = "Das Häuschen von {npc:6546} liegt tief im Sumpf westlich von Theramore, direkt nördlich der {area:508}; komm von der Weststraße, die Elite streift über die Ostseite.",
		["{npc:6549} (elite, 40)"] = "{npc:6549} (Elite, 40)",
		["{quest:1958}: the {item:7515} (off-hand) or the {item:9517}"] = "{quest:1958}: {item:7515} (Nebenhand) oder {item:9517}",
		["{quest:2846} in {area:978}"] = "{quest:2846} in {area:978}",
		["{quest:2861} (optional)"] = "{quest:2861} (optional)",
} end)()
t.guides["forever/class/mage/destroy-morphaz"] = (function() return {
		["Back to {npc:8395} and up to the tower."] = "Zurück zu {npc:8395} und hinauf zum Turm.",
		["Back to {npc:8395}, who teleports you up to the tower."] = "Zurück zu {npc:8395}, der dich hinauf zum Turm teleportiert.",
		["Back to {zone:1447}, {npc:8395} and the tower. Look at the reward window before you hand in: Classic offered the {item:20037}, the {item:20036} or the {item:20035}, and Forever's notes say the choice may be gone."] = "Zurück nach {zone:1447}, zu {npc:8395} und dem Turm. Sieh dir das Belohnungsfenster an, bevor du abgibst: Classic bot {item:20037}, {item:20036} oder {item:20035}, und die Hinweise von Forever sagen, dass die Auswahl entfallen könnte.",
		["Experience"] = "Erfahrung",
		["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "Erfahrung mit Stufe 50 durch {zone:1447} und den {area:1417}; die Gegenstandsauswahl aus Classic gibt es auf Forever womöglich nicht mehr.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to {npc:8379} at the top of the tower; an attendant at the top sends you back down, as often as you like."] = "Flieg nach {area:3137} (Allianz) oder {area:1237} (Horde). {npc:8395} lagert unterhalb des Turms seines Meisters, ein kurzes Stück östlich von {area:1237}: Geh von der Gabelung der Hauptstraße von {zone:1447} bei den {area:1221} direkt nach Norden zu den Klippen. Steig von deinem Reittier ab, bevor er dich nach oben teleportiert, sonst nimmt dich der Teleport womöglich nicht mit. Ein Pfad ohne Feinde führt hinauf zu {npc:8379} an der Spitze des Turms; ein Diener oben schickt dich so oft du willst wieder hinunter.",
		["Morphaz"] = "Morphaz",
		["The Spitelash Sirens (level 50-52) walk the ruins and beaches around the {area:1221} and the bay east of {area:1237}, often three together, and a few stand inside the {area:1223}; each drops a coral about one time in four. The Spitelash Screamers look almost the same but never drop it. Killing the other naga there makes more Sirens appear in their spots. {npc:7864} ghosts wander the ruins: watch your back."] = "Die Spitelash Sirens (Stufe 50-52) laufen durch die Ruinen und Strände um die {area:1221} und die Bucht östlich von {area:1237}, oft zu dritt, und ein paar stehen im {area:1223}; jede lässt etwa bei jedem vierten Kill eine Koralle fallen. Die Spitelash Screamers sehen fast gleich aus, lassen sie aber nie fallen. Wenn du die anderen Naga dort tötest, erscheinen an ihrer Stelle mehr Sirens. {npc:7864}-Geister wandern durch die Ruinen: Gib auf deinen Rücken acht.",
		["The blood elves hold the {area:1220} on the hills of north-eastern {zone:1447}. Blood Elf Surveyors (51-52, {spell:8349} up close) and Reclaimers (52-53, {spell:133}, and they heal and {spell:139} each other) each drop the dust about one time in four; they spot you from far off, so pull at the edges. They come back after 5 1/2 minutes."] = "Die Blutelfen halten das {area:1220} auf den Hügeln im Nordosten von {zone:1447}. Blood Elf Surveyors (51-52, {spell:8349} aus der Nähe) und Reclaimers (52-53, {spell:133}, und sie heilen sich gegenseitig und wirken {spell:139}) lassen den Staub jeweils etwa bei jedem vierten Kill fallen; sie entdecken dich von weitem, also pull an den Rändern. Sie kommen nach 5 1/2 Minuten wieder.",
		["The {item:20085}"] = "Der {item:20085}",
		["{area:1477}, the {area:1417}, lies in the {area:74}: climb the steps into the sunken building, swim down through it and follow the passage down to the portal. A group of five, level 50-54. Morphaz is not waiting when you arrive. First kill the six troll guardians (elites of 50-52) on the platforms around the upper ring; that opens the way down (the left-hand ramp from the entrance) to {npc:5710} and {npc:5711} in the Pit of Sacrifice. Once Jammal'an dies, two green drakes, Weaver and Dreamscythe, come out and patrol the pit: pull them one at a time. When both are dead, Morphaz (level 52 elite, {spell:12533} and {spell:11019}) and Hazzas appear together and cannot be split, so fight both. The shard always drops. Hunters, Priests and Rogues of 50 need Morphaz too: a group of them shares one clear."] = "{area:1477}, der {area:1417}, liegt in {area:74}: Steig die Stufen in das versunkene Gebäude hinauf, schwimm durch es nach unten und folge dem Gang nach unten zum Portal. Eine Gruppe aus fünf, Stufe 50-54. Morphaz wartet bei deiner Ankunft nicht. Töte zuerst die sechs Trollwächter (Elite, Stufe 50-52) auf den Plattformen um den oberen Ring; das öffnet den Weg nach unten (die linke Rampe vom Eingang) zu {npc:5710} und {npc:5711} in der Opfergrube. Sobald Jammal'an stirbt, kommen zwei grüne Drachen, Weaver und Dreamscythe, heraus und patrouillieren in der Grube: pull sie einzeln. Sind beide tot, erscheinen Morphaz (Elite der Stufe 52, {spell:12533} und {spell:11019}) und Hazzas zusammen und lassen sich nicht trennen, also bekämpfe beide. Der Splitter fällt immer. Jäger, Priester und Schurken der Stufe 50 brauchen Morphaz ebenfalls: Eine Gruppe von ihnen teilt sich einen Clear.",
		["{item:20085}: Morphaz"] = "{item:20085}: Morphaz",
		["{npc:331}, the Master Mage, stands in the Wizard's Sanctum in {zone:1453}'s {object:2101}; Dink in {zone:1455} gives the same quest."] = "{npc:331}, der Meistermagier, steht im Magiersanktum im Gebiet {object:2101} in {zone:1453}; Dink in {zone:1455} gibt dieselbe Quest.",
		["{npc:7311}, one of {zone:1454}'s mage trainers in {object:173161}, gives it; so do {npc:4567} in the {zone:1458} and {npc:3047} in {zone:1456}."] = "{npc:7311}, einer der Magierlehrer von {zone:1454} in {object:173161}, gibt sie; ebenso {npc:4567} in {zone:1458} und {npc:3047} in {zone:1456}.",
		["{npc:8379} again"] = "Wieder zu {npc:8379}",
		["{npc:8379}, in the tower"] = "{npc:8379}, im Turm",
} end)()
t.guides["forever/class/mage/ju-ju-heaps"] = (function() return {
		["A staff or an off-hand orb at 10: Orcs and Trolls on the {area:368}, the Undead at a Tirisfal farm."] = "Ein Stab oder ein Orb für die Nebenhand mit Stufe 10: Orcs und Trolle auf den {area:368}, die Untoten auf einer Farm in Tirisfal.",
		["At 10 {npc:2128}, the {area:159} mage trainer upstairs in the {area:2119}, sends you to {npc:4568} in the {zone:1458}. Taking it shuts out {quest:1884}; if {quest:1883} (from {zone:1454} or {zone:1456}) is in your log, abandon it first or {npc:2128} cannot give you this one. (A Troll who took this one in {area:159} follows the Balnir steps; an Undead who took {quest:1884} in Sen'jin, the {area:368} steps.)"] = "Mit Stufe 10 schickt dich {npc:2128}, der Magierlehrer von {area:159} oben im {area:2119}, zu {npc:4568} in {zone:1458}. Sie anzunehmen schließt {quest:1884} aus; ist {quest:1883} (aus {zone:1454} oder {zone:1456}) in deinem Questlog, brich sie zuerst ab, sonst kann {npc:2128} dir diese nicht geben. (Ein Troll, der diese in {area:159} angenommen hat, folgt den Schritten von Balnir; ein Untoter, der {quest:1884} in Sen'jin angenommen hat, den Schritten der {area:368}.)",
		["Back to Anastasia"] = "Zurück zu Anastasia",
		["Back to Un'thuwa"] = "Zurück zu Un'Thuwa",
		["Ley or {item:9514} or Orb (Horde)"] = "Ley oder {item:9514} oder Orb (Horde)",
		["The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "Der Orb ist eine Nebenhand für eine Einhandwaffe; der Stab ist eine Zweihandwaffe.",
		["The {quest:1884}"] = "{quest:1884}",
		["Un'thuwa"] = "Un'Thuwa",
		["Un'thuwa, the troll mage trainer, stands in {area:367} on the {zone:1411} coast south of {area:362}. Orcs coming from {zone:1454} can take {quest:1883} from {npc:7311} in the {object:172961} first; it is only a pointer and Un'thuwa gives {quest:1884} without it. Taking it shuts out the {zone:1458}'s {area:165}."] = "Un'thuwa, der Trollmagierlehrer, steht in {area:367} an der Küste von {zone:1411} südlich von {area:362}. Orcs, die aus {zone:1454} kommen, können zuerst {quest:1883} von {npc:7311} im {object:172961} annehmen; sie ist nur ein Hinweis, und Un'thuwa gibt {quest:1884} auch ohne sie. Sie anzunehmen schließt {area:165} in {zone:1458} aus.",
		["Un'thuwa: {item:7508} or {item:9513}"] = "Un'thuwa: {item:7508} oder {item:9513}",
		["Wade across the shallows south-east of Sen'jin to the main Echo Isle, where Zalazane (level 10) holds his camp with Hexed and Voodoo Trolls (level 8). The heaps you can click are the skull piles inside the raised huts around his camp, one hut holding two, more in the huts to the north; the skulls lying on the ground outside cannot be clicked. Destroy four. There are seven and each comes back 30 seconds after it is destroyed."] = "Wate durch die Untiefen südöstlich von Sen'jin zur großen Echo-Insel, wo Zalazane (Stufe 10) sein Lager mit Hexed und Voodoo Trolls (Stufe 8) hat. Die Haufen, die du anklicken kannst, sind die Schädelhaufen in den erhöhten Hütten um sein Lager, eine Hütte mit zwei, weitere in den Hütten im Norden; die Schädel, die draußen auf dem Boden liegen, lassen sich nicht anklicken. Zerstöre vier. Es gibt sieben, und jeder kommt 30 Sekunden nach der Zerstörung wieder.",
		["Walk south from {area:159} to the {area:153} and take the lift down into the {zone:1458}. Anastasia stands in the {object:36082}, the north-east ring of the city."] = "Geh von {area:159} nach Süden zu den {area:153} und nimm den Aufzug hinunter in {zone:1458}. Anastasia steht im {object:36082}, dem nordöstlichen Ring der Stadt.",
		["{npc:4568}: {item:7507} or {item:9514}"] = "{npc:4568}: {item:7507} oder {item:9514}",
		["{object:102986}, four of them"] = "{object:102986}, vier davon",
		["{quest:1882} lies south-east of {area:159}, south of the road east to the {area:152}. The snapdragons grow in the farm's garden and look more like bushes than flowers; any of them will do and you need no {skill:182}. They come back within seconds."] = "{quest:1882} liegt südöstlich von {area:159}, südlich der Straße nach Osten zum {area:152}. Die Löwenmäulchen wachsen im Garten der Farm und sehen eher wie Büsche als wie Blumen aus; jedes genügt, und du brauchst kein {skill:182}. Sie sind innerhalb von Sekunden wieder da.",
} end)()
t.guides["forever/class/mage/mages-wand"] = (function() return {
		["\"Plucky\" Johnson"] = "Eisenherz Johnson",
		["A wand of your school for the 30s: frost, arcane or fire."] = "Ein Zauberstab deiner Schule für Stufe 30+: Frost, Arkan oder Feuer.",
		["Back to {npc:6546}. With both quests handed in she starts the ritual: wait a few seconds, then talk to her again and pick your wand: Icefury (frost), Nether Force (arcane) or Ragefire (fire)."] = "Zurück zu {npc:6546}. Wenn du beide Quests abgegeben hast, beginnt sie das Ritual: Warte ein paar Sekunden, sprich sie dann noch einmal an und wähle deinen Zauberstab: Icefury (Frost), Nether Force (Arkan) oder Ragefire (Feuer).",
		["The Witherbark trolls (level 30-36) hold the villages in south-eastern Arathi and south of {area:321}; every kind of them drops a {item:7273} about two times in five: you need ten. Then go to the {area:336} (the outer one, not the Inner circle). Three elementals (level 33-39) stand around its middle stone: pull them one at a time and clear them first. Stand at the middle stone and use a totem stick; about ten seconds later the {item:7272} forms on the stone: click it. If you die before you pick it up, the bramble and the sticks are lost and you need ten more."] = "Die Witherbark-Trolle (Stufe 30-36) halten die Dörfer im Südosten von Arathi und südlich von {area:321}; jede ihrer Arten lässt in etwa zwei von fünf Fällen einen {item:7273} fallen: Du brauchst zehn. Geh dann zum {area:336} (dem äußeren, nicht dem inneren Kreis). Drei Elementare (Stufe 33-39) stehen um den mittleren Stein: Pull sie einzeln und räum sie zuerst. Stell dich an den mittleren Stein und benutze einen Totemstab; etwa zehn Sekunden später bildet sich {item:7272} auf dem Stein: Klick ihn an. Wenn du stirbst, bevor du ihn aufgehoben hast, sind die Brombeere und die Stäbe verloren, und du brauchst zehn weitere.",
		["Tirth sold the book to the Scarlet Crusade. The {area:796} stands in north-eastern {zone:1420}; take the Library wing with a group of five. The book is in the last long hallway, the one that ends in {npc:6487}'s round room: on the left-hand shelf as you face his room, next to the {item:5535}. Take the thick, highlighted blue book sticking out of the shelf; a magnifying-glass cursor means a book you can only read."] = "Tirth hat das Buch an den Scharlachroten Kreuzzug verkauft. Das {area:796} liegt im Nordosten von {zone:1420}; nimm den Bibliotheksflügel mit einer Gruppe aus fünf. Das Buch liegt im letzten langen Gang, dem, der in {npc:6487}s rundem Raum endet: im linken Regal, wenn du zu seinem Raum blickst, neben {item:5535}. Nimm das dicke, hervorgehobene blaue Buch, das aus dem Regal ragt; ein Lupen-Cursor zeigt ein Buch an, das du nur lesen kannst.",
		["Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken pecking around the foot of the race track's lookout tower; at night type /target plucky. Target him and type /beckon (not /chicken or /wave): he turns human for a moment. Talk to him and ask for the phrase. Do not attack him. If he is gone, he is back within 5 minutes."] = "Tirths Lehrling ist „Plucky“ Johnson, ein kleines graues Huhn, das am Fuß des Aussichtsturms der Rennstrecke herumpickt; nachts tippe /target plucky. Wähle ihn als Ziel und tippe /beckon (nicht /chicken oder /wave): Er verwandelt sich kurz in einen Menschen. Sprich ihn an und frag nach dem Satz. Greife ihn nicht an. Ist er weg, ist er innerhalb von 5 Minuten wieder da.",
		["Witherbark trolls and the {item:7272}"] = "Witherbark-Trolle und {item:7272}",
		["at the middle stone of the {area:336}"] = "am mittleren Stein des {area:336}",
		["{npc:5497} at the top of the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497} oben im Wizard's Sanctum, im {object:2101} von {zone:1453}, schickt dich zu {npc:6546}; Bink in {zone:1455} gibt dieselbe Quest.",
		["{npc:5885}, one of {zone:1454}'s mage trainers in {object:173161}, sends you to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, einer der Magierlehrer von {zone:1454} in {object:173161}, schickt dich zu {npc:6546}; {npc:4568} in {zone:1458} und {npc:3048} in {zone:1456} geben dieselbe Quest.",
		["{npc:6546} also wants one {item:1529}, a green gem. Miners sometimes find one in ore veins; the Auction House sells it; the Torn Fin Coastrunners on the coast south-west of {area:271} drop one about every fifth kill. Do not sell it to a vendor by mistake."] = "{npc:6546} will außerdem einen {item:1529}, einen grünen Edelstein. Bergleute finden manchmal einen in Erzadern; das Auktionshaus verkauft ihn; die Torn Fin Coastrunners an der Küste südwestlich von {area:271} lassen etwa bei jedem fünften Kill einen fallen. Verkauf ihn nicht versehentlich an einen Händler.",
		["{npc:6546}'s ritual"] = "Das Ritual von {npc:6546}",
		["{npc:6546}, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the {area:508}. Level 38-41 elites roam the east side of her farm, and swimming in passes level 42 Muckshells: come in from the west along the road from the {zone:1413}. Her cottage is no refuge: mobs follow you inside. Take both her quests."] = "{npc:6546}, eine Einsiedlerin, lebt in einem Häuschen tief im Sumpf westlich von Theramore, direkt nördlich der {area:508}. Elite der Stufe 38-41 streift durch die Ostseite ihrer Farm, und wer hineinschwimmt, kommt an Muckshells der Stufe 42 vorbei: Komm von Westen auf der Straße aus {zone:1413}. Ihr Häuschen ist kein Zufluchtsort: Mobs folgen dir hinein. Nimm beide ihrer Quests an.",
		["{npc:6548} spends his days at the race track in the {area:439}, south-east {zone:1441}."] = "{npc:6548} verbringt seine Tage an der Rennstrecke im Gebiet {area:439}, im Südosten von {zone:1441}.",
		["{quest:1951}: Scarlet Monastery Library"] = "{quest:1951}: Das Scharlachrote Kloster, Bibliothek",
} end)()
t.guides["forever/class/mage/manaweave-robe"] = (function() return {
		["A robe at 15 for Alliance mages, from {zone:1453} and {zone:1432}."] = "Eine Robe mit Stufe 15 für Allianzmagier, aus {zone:1453} und {zone:1432}.",
		["Any humanoid drops {item:2589}, and the Tunnel Rats in the {area:149} drop it while you gather the gems; the Auction House in the {object:2096} sells it. You hand in ten."] = "Jeder Humanoide lässt {item:2589} fallen, und die Tunnel Rats in der {area:149} lassen es fallen, während du die Edelsteine sammelst; das Auktionshaus im {object:2096} verkauft es. Du gibst zehn ab.",
		["Back to {npc:5497}"] = "Zurück zu {npc:5497}",
		["Back to {zone:1453} by the tram. {npc:1309} works at {object:23296} in the {object:2101}."] = "Mit der Bahn zurück nach {zone:1453}. {npc:1309} arbeitet bei {object:23296} in {object:2101}.",
		["Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The {area:149} is at the north end of the loch, north of {area:144}; Tunnel Rat kobolds hold it. The gems come only from the tall stacked {object:271} (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest."] = "Nimm die {area:2257} nach {zone:1455}, dann die Straße nach Osten durch den Südtor-Tunnel nach {zone:1432}. Die {area:149} liegt am Nordende des Sees, nördlich von {area:144}; Tunnel-Rat-Kobolde halten sie. Die Edelsteine kommen nur aus den hohen gestapelten {object:271} (der Cursor zeigt ein Zahnrad über ihnen; einzelne Kisten enthalten nichts): Jede Kiste gibt einen, es gibt vierzehn, und sie kommen nach 3 bis 5 Minuten wieder. Für sechs musst du womöglich bis in die Endkammer. Dieselben Kisten dienen der Zwergenquest Filthy Paws.",
		["The {area:149}"] = "{area:149}",
		["{item:7247}, on the stunned {npc:6492}"] = "{item:7247}, am betäubten {npc:6492}",
		["{npc:328} is the {area:87} mage trainer, upstairs in the Lion's Pride Inn."] = "{npc:328} ist der Magierlehrer von {area:87}, oben im Lion's Pride Inn.",
		["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}: climb the spiral ramp and take the portal near the top. The {item:7247} and the {item:7308} lie on the table behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:5497} steht oben im Wizard's Sanctum, dem violetten Turm des {object:2101}: Steig die Spiralrampe hinauf und nimm das Portal nahe dem oberen Ende. {item:7247} und {item:7308} liegen auf dem Tisch hinter ihr (beide kommen 5 Minuten nach dem Mitnehmen wieder). Du gibst beide am Ende ab, also behalte sie.",
		["{npc:6492}, down to the stun"] = "{npc:6492}, bis zur Betäubung",
		["{npc:7312} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:7312} unterrichtet Magier in {object:32362} in {zone:1455}. Nimm danach {area:2257} von {object:171524} nach {zone:1453}.",
		["{object:2169} is the tavern in the {object:2101}. Read the {item:7308} inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of {spell:122} fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the {item:7247} on it while it is stunned, then click the {item:7292} it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds."] = "{object:2169} ist die Taverne im {object:2101}. Lies darin {item:7308}, damit die unsichtbaren Rift Spawns (Stufe 16-17) sichtbar werden: Im Keller bringt es einen hervor, auf dem Balkon oder in der Küche zwei, im Hauptraum oder an der Tür drei, lies ihn also unten. Sie schlagen hart zu und brechen schnell aus {spell:122} aus. Prügle einen nieder: Er stirbt nicht, sondern sitzt betäubt mit einer Spirale über dem Kopf da; benutze {item:7247} an ihm, solange er betäubt ist, und klick dann {item:7292} an, den er auf dem Boden hinterlässt (ein Klick, bevor er erscheint, verschwendet eine Ladung). Du brauchst drei, und die Beschwörung wirkt nur alle 5 Minuten (Ausloggen setzt sie nicht zurück), plane also drei Runden ein.",
} end)()
t.guides["forever/class/mage/nether-lace-garment"] = (function() return {
		["A robe or a tunic for Horde mages in their late 20s."] = "Eine Robe oder eine Tunika für Horde-Magier in ihren späten Zwanzigern.",
		["Back to {npc:5885}"] = "Zurück zu {npc:5885}",
		["Fly to {area:431} and swim north up the river past the big lake to its far northern end, where the zone text reads {area:429}; satyrs hold the ruins around it and a few river beasts are in the way. Swim right in under the highest waterfall until you touch the rock wall, then use the flask (you can stay in the water). The waterfalls on the western Falfarren fork do not work."] = "Flieg nach {area:431} und schwimm den Fluss nach Norden hinauf, am großen See vorbei bis zu seinem nördlichen Ende, wo der Gebietstext {area:429} anzeigt; Satyrn halten die Ruinen darum, und ein paar Flusstiere sind im Weg. Schwimm direkt unter den höchsten Wasserfall, bis du die Felswand berührst, und benutze dann die Flasche (du kannst im Wasser bleiben). Die Wasserfälle an der westlichen Falfarren-Gabelung funktionieren nicht.",
		["Take the zeppelin to {zone:1454} (or use {spell:3567}, which lands you on the upper floor of {object:173161}). {npc:5885} stands with the mage trainers on the lower floor of {object:173161} in the {object:172961}. She hands you {item:7269}."] = "Nimm den Zeppelin nach {zone:1454} (oder nutze {spell:3567}, das dich im oberen Stockwerk von {object:173161} absetzt). {npc:5885} steht bei den Magierlehrern im unteren Stockwerk von {object:173161} im {object:172961}. Sie gibt dir {item:7269}.",
		["The {object:174797}"] = "Der {object:174797}",
		["The {quest:1945}"] = "Die {quest:1945}",
		["The {quest:1945}, dryads of level 24-25, roam around the {area:426} in central {zone:1440}; every one drops a hair and they come back after 5 minutes. They often resist fire (and some frost and shadow): arcane spells land best. Each runs for help at low health. Keep clear of the guards by the white tower of the retreat, who hit hard."] = "Die {quest:1945}, Dryaden der Stufe 24-25, streifen um das {area:426} in der Mitte von {zone:1440}; jede lässt ein Haar fallen, und sie kommen nach 5 Minuten wieder. Sie widerstehen oft Feuer (und manche Frost und Schatten): Arkane Zauber treffen am besten. Jede holt bei niedriger Gesundheit Hilfe. Halte Abstand zu den Wachen am weißen Turm des Rückzugsorts, sie schlagen hart zu.",
		["{item:7269}, under the falls"] = "{item:7269}, unter den Fällen",
		["{npc:3484}, a troll tailor, works at the Crossroads. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit."] = "{npc:3484}, ein Trollschneider, arbeitet in Crossroads. Die Robe gibt Intelligenz, Ausdauer und Willenskraft; die Tunika mehr Intelligenz und Ausdauer, aber keine Willenskraft.",
		["{npc:4568} stands in the {zone:1458}'s {object:36082}. Orcs and Trolls use {spell:3563} or take the zeppelin from {zone:1454} to {zone:1420} for her."] = "{npc:4568} steht im {object:36082} von {zone:1458}. Orcs und Trolle nutzen {spell:3563} oder nehmen den Zeppelin von {zone:1454} nach {zone:1420} zu ihr.",
} end)()
t.guides["forever/class/mage/polymorph-pig"] = (function() return {
		["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "Ein neues Aussehen für {spell:118}: Das Ziel wird in ein Schwein statt in ein Schaf verwandelt.",
		["Back to the {area:1221}, full of Spitelash naga. Cast your sheep {spell:118} (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with {spell:122} and {spell:1449}. Fifty clones are needed, so it takes a while; not in a raid group."] = "Zurück zu den {area:1221}, voller Spitelash-Naga. Wirke dein Schaf {spell:118} (das Schildkröten-Schaf bringt nichts) auf eine Naga und warte ein paar Sekunden: Sie teilt sich in zwei bis sechs Polymorph Clones mit etwa 150 Gesundheit, die schnell davonlaufen. Stell dich neben das Schaf und triff sie in dem Moment, in dem sie erscheinen, mit {spell:122} und {spell:1449}. Es sind fünfzig Klone nötig, es dauert also eine Weile; nicht in einer Schlachtzugsgruppe.",
		["Back to {npc:8395} and up to the tower."] = "Zurück zu {npc:8395} und hinauf zum Turm.",
		["Back to {npc:8395} and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags."] = "Zurück zu {npc:8395} und hinauf zum Turm. Xylem gibt dir mit der nächsten Quest die Muschel zurück: Behalte sie in deinen Taschen.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower."] = "Flieg nach {area:3137} (Allianz) oder {area:1237} (Horde). {npc:8395} lagert unterhalb des Turms von {npc:8379}, ein kurzes Stück östlich von {area:1237}: Geh von der Gabelung der Hauptstraße von {zone:1447} bei den {area:1221} direkt nach Norden zu den Klippen. Steig ab, und er teleportiert dich nach oben; ein Pfad führt zum Erzmagier an der Spitze des Turms.",
		["Polymorph Clones"] = "Verwandelte Kopien",
		["Xylem's tower"] = "Xylems Turm",
		["{npc:8379}: {spell:118} (pig)"] = "{npc:8379}: {spell:118} (Schwein)",
		["{npc:8408} (level 55, not elite, Strike and {spell:99}) hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He always drops the {item:23250} and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine."] = "{npc:8408} (Stufe 55, keine Elite, Schlag und {spell:99}) versteckt sich hinter seinen Spitelash-Wachen im {area:1223}, dem größten Gebäude in der Mitte der {area:1221}. Er lässt {item:23250} immer fallen und ist 5 1/2 Minuten nach einem Kill wieder da. Verlasse vorher jede Schlachtzugsgruppe: Ein Schlachtzug bekommt keinen Fortschritt, eine Gruppe ist in Ordnung.",
} end)()
t.guides["forever/class/mage/spellfire-robes"] = (function() return {
		["A robe at 15 for Horde mages, from the {zone:1458} and {zone:1421}."] = "Eine Robe mit 15 für Magier der Horde, aus {zone:1458} und dem {zone:1421}.",
		["Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the {item:7308}: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the {item:7247} on it, then click the {item:7292} once it appears on the floor (clicking too early wastes a charge). Three are needed."] = "Algernons Alchemieladen ist im Apothecarium. Stell dich auf die Stufen oder die Brücke vor dem Laden und lies {item:7308}: Bis zu vier unsichtbare Rift Spawns (Stufe 16-17) erscheinen und greifen sofort an, und die Stadtwachen helfen nicht. Triff einen mit einem Einzelzielzauber und zieh dich über die Brücke zurück: Die anderen geben auf und lösen sich auf, der getroffene folgt dir. Prügle ihn auf der Ladenhälfte der Brücke nieder (hinter der Mitte wirkt die Truhe nicht auf ihn), bis er nicht mehr kämpft und betäubt unter einer Spirale sitzt, benutze {item:7247} an ihm und klick dann {item:7292} an, sobald er auf dem Boden erscheint (zu früh klicken verschwendet eine Ladung). Drei sind nötig.",
		["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop in the {object:36082}. Hand the gems and cloth to {npc:4576} and let the three of them talk for a moment; then {npc:4576} offers {quest:1962}: take it and hand it straight back to him for the robe."] = "Zurück nach {zone:1458}. {npc:4576}, {npc:11048} und {npc:11049} führen den Schneiderladen im {object:36082}. Gib die Edelsteine und den Stoff an {npc:4576} ab und lass die drei einen Moment reden; dann bietet {npc:4576} {quest:1962} an: Nimm sie an und gib sie direkt wieder bei ihm ab, um die Robe zu bekommen.",
		["Back to {npc:4568}"] = "Zurück zu {npc:4568}",
		["Leave the {zone:1458} and follow the road south through {zone:1421}. Every {area:279} human drops a {item:7293} four times in five, and {item:2589} too: the easiest are the Dalaran Apprentices (level 13-14, {spell:116}) on the hills south-east of the {area:228}, either side of the road south; deeper in, the walled town of {area:233} in south-east Silverpine has Watchers (18-19, {spell:134} and {spell:2120}) and Wizards (19-20, {spell:122}) that come back every 4 1/2 minutes and run for help at low health, so pull at the edge. Ten {item:2589} also come from any humanoid or the Undercity Auction House."] = "Verlasse {zone:1458} und folge der Straße nach Süden durch {zone:1421}. Jeder Mensch von {area:279} lässt in vier von fünf Fällen {item:7293} fallen, und auch {item:2589}: Am leichtesten sind die Dalaran Apprentices (Stufe 13-14, {spell:116}) auf den Hügeln südöstlich von {area:228}, auf beiden Seiten der Straße nach Süden; weiter drinnen hat die ummauerte Stadt {area:233} im Südosten von Silverpine Watchers (18-19, {spell:134} und {spell:2120}) und Wizards (19-20, {spell:122}), die alle 4 1/2 Minuten wiederkommen und bei niedriger Gesundheit Hilfe holen, also pull am Rand. Zehn {item:2589} kommen auch von jedem Humanoiden oder aus dem Auktionshaus von Undercity.",
		["The alchemist shop"] = "Der Alchemieladen",
		["{item:7247}, on the stunned {npc:6492}"] = "{item:7247}, am betäubten {npc:6492}",
		["{npc:2128} is the {area:159} mage trainer, upstairs in the {area:2119}: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:2128} ist der Magierlehrer von {area:159}, oben im {area:2119}: Nimm die Treppe drinnen, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["{npc:4568} stands in the {object:36082}. The {item:7247} and the {item:7308} lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:4568} steht im {object:36082}. {item:7247} und {item:7308} liegen auf dem Sims hinter ihr (beide kommen 5 Minuten nach dem Mitnehmen wieder). Du gibst beide am Ende ab, also behalte sie.",
		["{npc:6492}, down to the stun"] = "{npc:6492}, bis zur Betäubung",
		["{npc:7311} is one of {zone:1454}'s mage trainers, in {object:173161} in the {object:172961}. Then take the zeppelin to {zone:1420} from the tower outside {zone:1454}'s main gate."] = "{npc:7311} ist einer der Magierlehrer von {zone:1454}, in {object:173161} im {object:172961}. Nimm dann den Zeppelin nach {zone:1420} vom Turm vor dem Haupttor von {zone:1454}.",
} end)()
t.guides["forever/class/mage/staff-or-orb-alliance"] = (function() return {
		["A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand."] = "Ein Stab oder ein Orb für die Nebenhand mit Stufe 10 vom Magierlehrer deiner Heimatstadt; Himmelsgeborene bekommen zusätzlich einen Zauberstab.",
		["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {quest:1860}, the {area:87} trainer's errand; {npc:5144}'s Gizmonitor and {npc:5497}'s {quest:1861} shut out each other, so you get one staff or orb. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "Mit Stufe 10 schickt dich {npc:1228}, der Magierlehrer von {area:131} in der {area:2102}, zu {npc:5144} in {zone:1455}. Sie anzunehmen schließt {quest:1860} aus, den Botengang des Lehrers von {area:87}; Gizmonitor von {npc:5144} und {quest:1861} von {npc:5497} schließen sich gegenseitig aus, du bekommst also einen Stab oder Orb. (Ein Gnom, der stattdessen die Quest von {npc:328} in {area:87} angenommen hat, folgt den Schritten von {quest:1861}; ein Mensch, der diese angenommen hat, den Gizmonitor-Schritten.)",
		["At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town."] = "Mit Stufe 10 schickt dich {npc:252373}, der Magierlehrer von {area:16638}, zu {npc:256507}, dem Stabhändler wenige Schritte entfernt in derselben Stadt.",
		["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {quest:1879}, the {area:131} trainer's errand; {quest:1861} and {npc:5144}'s Gizmonitor shut out each other, so you get one staff or orb."] = "Mit Stufe 10 schickt dich {npc:328}, der Magierlehrer von {area:87}, oben im Lion's Pride Inn, zu {npc:5497} in {zone:1453}. Sie anzunehmen schließt {quest:1879} aus, den Botengang des Lehrers von {area:131}; {quest:1861} und Gizmonitor von {npc:5144} schließen sich gegenseitig aus, du bekommst also einen Stab oder Orb.",
		["Back to {npc:256507}"] = "Zurück zu {npc:256507}",
		["Back to {npc:5144}"] = "Zurück zu {npc:5144}",
		["Back to {npc:5497}"] = "Zurück zu {npc:5497}",
		["Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "Geh zurück hinauf im Wizard's Sanctum und durch das Portal. Der Orb ist eine Nebenhand für eine Einhandwaffe; der Stab ist eine Zweihandwaffe.",
		["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "Folge der Straße nach Norden nach {zone:1453} und nach Westen zum {object:2101}. {npc:5497} steht oben im Wizard's Sanctum, dem hohen violetten Turm: Steig die Spiralrampe hinauf und tritt nahe dem oberen Ende ins Portal, das dich neben sie setzt. Sie gibt dir {item:7207}. Himmelsgeborene Magier nehmen {quest:1861} bei ihr an, wenn sie zum ersten Mal {zone:1453} erreichen, mit etwa Stufe 15.",
		["Head west along the road to {area:133}. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone."] = "Geh die Straße nach Westen zu {area:133}. Direkt nördlich des Eingangs stehen zwei Hütten; die Werkzeugkiste ist in der höheren, östlichen, der Hütte mit dem Aufzug: eine kleine graue Kiste im Erdgeschoss, halb unter dem Tisch neben dem Aufzug. Leper Gnomes (Stufe 8) bewachen die Hütten: pull sie einzeln. Es gibt nur eine Werkzeugkiste, und sie braucht 15 Minuten, um wiederzukommen, nachdem jemand sie geöffnet hat; warte also in der Nähe, wenn sie weg ist.",
		["Leave {zone:1453} by the main gate and head south-west to the waterfall that feeds {quest:1861}. Wade in under the falling water to the rock behind it and use {item:7207} there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water."] = "Verlasse {zone:1453} durch das Haupttor und geh nach Südwesten zum Wasserfall, der {quest:1861} speist. Wate unter das herabstürzende Wasser bis zum Fels dahinter und benutze dort {item:7207} (5 Sekunden Zauberzeit); überall sonst scheitert es. Defias-Zauberwirker der Stufe 10 stehen auf den Felsen zu beiden Seiten der Fälle und schießen aus der Ferne: Pull sie einzeln oder füll die Flasche aus dem Wasser.",
		["Ley or {item:9514} or Orb (Alliance)"] = "Ley oder {item:9514} oder Orb (Allianz)",
		["The Windstone Formations"] = "Die Windsteinformationen",
		["The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of {area:16636}. It does not sparkle, so look at the ground by the stones; there are two spots for it."] = "Der Ast liegt am Boden zwischen den Windstone Formations, dem Windschrein auf der Anhöhe westlich von Fillions Lager, südlich von {area:16636}. Er funkelt nicht, such also den Boden bei den Steinen ab; es gibt zwei Stellen dafür.",
		["The {quest:1861} waterfall"] = "Der Wasserfall von {quest:1861}",
		["{item:7207}, under the falls"] = "{item:7207}, unter den Fällen",
		["{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb."] = "Die Quest von {npc:256507} steht auch menschlichen und gnomischen Magiern offen, wenn du je {area:16638} auf {zone:2521}, der Heimat der Himmelsgeborenen, besuchst: {npc:252373}, der Magierlehrer der Stadt, schickt dich zu {npc:256507} nebenan, der einen {item:262668} vom Boden bei den Windstone Formations südlich von {area:16636} will, für {item:263430}. Sie schließt den Stab oder den Orb nicht aus.",
		["{npc:256507}'s wand (optional)"] = "Zauberstab von {npc:256507} (optional)",
		["{npc:5144} teaches mages in the {object:32362}, at the back of {zone:1455} past the {object:32386}."] = "{npc:5144} bildet Magier im {object:32362} aus, hinten in {zone:1455} hinter der {object:32386}.",
		["{npc:5144}: {item:7507} or {item:9514}"] = "{npc:5144}: {item:7507} oder {item:9514}",
		["{npc:5497}: {item:7508} or {item:9513}"] = "{npc:5497}: {item:7508} oder {item:9513}",
		["{quest:1861} (the next steps) waits for you with {npc:5497} in {zone:1453}, at about 15."] = "{quest:1861} (die nächsten Schritte) wartet mit etwa Stufe 15 bei {npc:5497} in {zone:1453} auf dich.",
} end)()
t.guides["forever/class/mage/teleports-alliance"] = (function() return {
		["At 20 go to the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:2485}, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches {spell:3561} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor; {npc:1308} sells them at the foot of the tower), so carry a few."] = "Geh mit Stufe 20 zum Wizard's Sanctum, dem violetten Turm im {object:2101} von {zone:1453}. {npc:2485}, die Portallehrerin, steht ganz oben: Steig die Spiralrampe hinauf und nimm das Portal nahe dem oberen Ende. Sie bringt dir {spell:3561} für 20 Silber bei. Jeder Teleport verbraucht eine {item:17031} (10 Silber bei jedem Reagenzienhändler; {npc:1308} verkauft sie am Fuß des Turms), nimm also ein paar mit.",
		["At 30. Take the boat from {area:17203} to {area:442} in {zone:1439}, then the boat to {area:702} and the pink portal up into {zone:1457}. {npc:4165}, the portal trainer, teaches {spell:3565} for 80 silver."] = "Mit Stufe 30. Nimm das Boot von {area:17203} nach {area:442} in {zone:1439}, dann das Boot nach {area:702} und das rosa Portal nach oben in {zone:1457}. {npc:4165}, die Portallehrerin, bringt dir {spell:3565} für 80 Silber bei.",
		["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:2485} has {spell:10059} at the top of the Wizard's Sanctum; then the tram to {npc:2489} in {zone:1455}'s {object:32362} for {spell:11416}."] = "Mit Stufe 40 bringen dir die Portallehrer die Portale bei: ein Tor, durch das deine ganze Gruppe treten kann, für je 1 Gold 50 Silber. Jedes Portal verbraucht eine {item:17032} (20 Silber bei jedem Reagenzienhändler). {npc:2485} hat {spell:10059} oben im Wizard's Sanctum; nimm dann die Tiefenbahn zu {npc:2489} im {object:32362} von {zone:1455} für {spell:11416}.",
		["At 50 {npc:4165} in {zone:1457} teaches the last one, {spell:11419}, for 3 gold 20 silver. Use your {spell:3565} to get there."] = "Mit Stufe 50 bringt dir {npc:4165} in {zone:1457} das letzte bei, {spell:11419}, für 3 Gold 20 Silber. Nutze dein {spell:3565}, um hinzukommen.",
		["Portals to {zone:1453} and {zone:1455}"] = "Portale nach {zone:1453} und {zone:1455}",
		["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}. {npc:2489}, the portal trainer, stands with the mage trainers in the {object:32362} at the back of the city: {spell:3562}, 20 silver."] = "Nimm die {area:2257} vom {object:28027} von {zone:1453} nach {zone:1455}. {npc:2489}, der Portallehrer, steht bei den Magierlehrern im {object:32362} hinten in der Stadt: {spell:3562}, 20 Silber.",
		["Teleports and Portals (Alliance)"] = "Teleports und Portale (Allianz)",
		["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "Deine Stadtteleports mit 20 und 30 und die Gruppenportale mit 40 und 50, jeweils vom Portallehrer der Stadt.",
		["{item:17031}, 10s each"] = "{item:17031}, je 10s",
		["{item:17032}, 20s each"] = "{item:17032}, je 20s",
} end)()
t.guides["forever/class/mage/teleports-horde"] = (function() return {
		["At 20 go to {object:173161} in {zone:1454}'s {object:172961}, where the mage trainers live. {npc:5958}, the portal trainer, stands on the upper floor and teaches {spell:3567} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor), so carry a few."] = "Geh mit Stufe 20 zu {object:173161} im {object:172961} von {zone:1454}, wo die Magierlehrer leben. {npc:5958}, der Portallehrer, steht im oberen Stockwerk und bringt dir {spell:3567} für 20 Silber bei. Jeder Teleport verbraucht eine {item:17031} (10 Silber bei jedem Reagenzienhändler), nimm also ein paar mit.",
		["At 30. {zone:1456} is in {zone:1412}: fly there from {zone:1454} or the Crossroads. {npc:5957}, the portal trainer, stands with the mage trainers in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart. She teaches {spell:3566} for 80 silver."] = "Mit Stufe 30. {zone:1456} liegt in {zone:1412}: Flieg von {zone:1454} oder der Crossroads dorthin. {npc:5957}, die Portallehrerin, steht bei den Magierlehrern in den {area:2197}, der Höhle unter {area:1640}: Geh drinnen nach unten, der Pfeil kann die Stockwerke nicht unterscheiden. Sie bringt dir {spell:3566} für 80 Silber bei.",
		["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:5958} in {object:173161} has {spell:11417}; teleport to the {zone:1458} for {npc:2492}'s {spell:11418}."] = "Mit Stufe 40 bringen dir die Portallehrer die Portale bei: ein Tor, durch das deine ganze Gruppe treten kann, für je 1 Gold 50 Silber. Jedes Portal verbraucht eine {item:17032} (20 Silber bei jedem Reagenzienhändler). {npc:5958} in {object:173161} hat {spell:11417}; teleportiere dich nach {zone:1458} für {spell:11418} von {npc:2492}.",
		["At 50 {npc:5957}, down in the {area:2197} under {area:1640} in {zone:1456}, teaches the last one, {spell:11420}, for 3 gold 20 silver. Use your {spell:3566} to get there."] = "Mit Stufe 50 bringt dir {npc:5957}, unten in den {area:2197} unter {area:1640} in {zone:1456}, das letzte bei, {spell:11420}, für 3 Gold 20 Silber. Nutze dein {spell:3566}, um hinzukommen.",
		["Portals to {zone:1454} and the {zone:1458}"] = "Portale nach {zone:1454} und {zone:1458}",
		["Take the zeppelin from the tower outside {zone:1454}'s gate to {zone:1420} and walk into the {zone:1458}. {npc:2492}, the portal trainer, stands in the {object:36082} with the mage trainers: {spell:3563}, 20 silver. {npc:4575} beside him sells the runes."] = "Nimm den Zeppelin vom Turm vor dem Tor von {zone:1454} nach {zone:1420} und geh in {zone:1458} hinein. {npc:2492}, der Portallehrer, steht im {object:36082} bei den Magierlehrern: {spell:3563}, 20 Silber. {npc:4575} neben ihm verkauft die Runen.",
		["Teleports and Portals (Horde)"] = "Teleports und Portale (Horde)",
		["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "Deine Stadtteleports mit 20 und 30 und die Gruppenportale mit 40 und 50, jeweils vom Portallehrer der Stadt.",
		["{item:17031}, 10s each"] = "{item:17031}, je 10s",
		["{item:17032}, 20s each"] = "{item:17032}, je 20s",
} end)()
t.guides["forever/class/paladin/cloak-of-the-divine-storm"] = (function() return {
		["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "Zurück zu {npc:3663} in {area:413} im Westen von {zone:1440}, quer durch das ganze Gebiet.",
		["Back to {npc:5495}"] = "Zurück zu {npc:5495}",
		["Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the Strange Orb at the top: it gives you the Althalaxx Orb; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it."] = "Steig zur Spitze des {area:444} im Norden von {zone:1439}. Die Dark Strand Fanatics darum sind leicht (Stufe 16-17), aber vier Dark Strand Voidcallers (Stufe 28-29) stehen im Turm auf dem Weg zum Orb: Jeder ruft einen Leerwandler und wirkt {spell:686} aus der Ferne. Bring mit 22-25 einen oder zwei Freunde mit, pull sie einzeln und tritt hinter eine Wand, damit sie zu dir kommen müssen. Plündere das Strange Orb oben: Es gibt dir den Althalaxx Orb; klick ihn mit der rechten Maustaste an, um die Quest zu starten. Behalte den Orb in deinen Taschen bis zum {object:409311}: Drei spätere Quests brauchen ihn.",
		["Motes of Mannoroth"] = "Partikel von Mannoroth",
		["Starts now at 22 at the {area:444}; its mobs are 28-30, so go nearer 30 or with a friend. Alliance only for now."] = "Beginnt jetzt mit 22 am {area:444}; die Mobs dort sind 28-30, geh also eher mit 30 oder mit einem Freund. Vorerst nur Allianz.",
		["Strange Orb atop the {area:444}: right-click the Althalaxx Orb it gives"] = "Strange Orb oben auf {area:444}: Rechtsklick auf die Kugel von Althalaxx, die sie gibt",
		["The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the {item:209778}; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of {area:69} drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is {npc:334} (26): stay in the north-west."] = "Die Blackrock Summoners, Champions und Trackers (Stufe 22-25, keine Elite) lagern im Nordwesten von Redridge und lassen {item:209778} fallen; du brauchst 14. Zwei Elite-Blackrock Shadowcasters (22-23) stehen am Höhleneingang am Ostende des Lagers: Umgeh sie. Die Blackrock-Lager östlich von {area:69} lassen das Salz ebenfalls fallen, aber ihre Shadowcasters, Sentries und Hunters sind Elite (Stufe 21-24), ebenso {npc:334} (26): Bleib im Nordwesten.",
		["The Strange Orb"] = "Die Strange Orb",
		["The {object:409311}"] = "Der {object:409311}",
		["The {object:409311} stands at the east end of {area:435}. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the {object:409315} beside it starts the last quest."] = "Der {object:409311} steht am Ostende von {area:435}. Gib die Motes am Speer ab, während der Althalaxx Orb in deinen Taschen ist: Der Orb zerbricht, und der {object:409315} daneben startet die letzte Quest.",
		["from the {object:409315}"] = "von der {object:409315}",
		["{area:435} is in south-east {zone:1440}, east of {area:431} (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast {spell:686} and {spell:348}, Infernals keep a fire shield up. They respawn in five minutes."] = "{area:435} liegt im Südosten von {zone:1440}, östlich von {area:431} (ein Horde-Lager: geh drumherum). Die Mannoroc Lashers, Searing Infernals, Felguards und Legion Hounds (Stufe 29-30, keine Elite) lassen die Motes of Mannoroth fallen; du brauchst 12. Unter etwa 27 sind sie allein schwer: Komm mit einem zweiten Spieler oder später. Felguards werfen dich um, Lashers wirken {spell:686} und {spell:348}, Infernals halten einen Feuerschild aufrecht. Sie respawnen nach fünf Minuten.",
		["{npc:3663} stands at {area:413} in western {zone:1440}, south of the {zone:1439} road. He sends you to {zone:1453} with the orb."] = "{npc:3663} steht in {area:413} im Westen von {zone:1440}, südlich der Straße von {zone:1439}. Er schickt dich mit dem Orb nach {zone:1453}.",
		["{npc:5492} stands in the Cathedral of Light; she sends you to a warlock for a second opinion."] = "{npc:5492} steht in der Kathedrale des Lichts; sie schickt dich für eine zweite Meinung zu einem Hexenmeister.",
		["{npc:5495}, the warlock trainer, is in the {object:2101}'s warlock sanctum, down in the {object:2164}'s cellar. She wants 14 {item:209778} to read the orb."] = "{npc:5495}, die Hexenmeisterlehrerin, ist im Hexenmeister-Heiligtum des {object:2101}, unten im Keller von {object:2164}. Sie will 14 {item:209778}, um den Orb zu lesen.",
} end)()
t.guides["forever/class/paladin/holy-mightstone"] = (function() return {
		["A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever."] = "Ein Einmalstein, der dich 10 Minuten lang viel stärker gegen Untote macht; die alte Gegenstandsauswahl gibt es auf Forever womöglich nicht mehr.",
		["At 50 {npc:5149}, the paladin trainer in the {object:32362}, sends you to {area:3197} in the {zone:1422}. {npc:928} in {zone:1453} gives the same quest."] = "Mit Stufe 50 schickt dich {npc:5149}, der Paladinlehrer im {object:32362}, zum {area:3197} in den {zone:1422}. {npc:928} in {zone:1453} gibt dieselbe Quest.",
		["At 50 {npc:928}, the paladin trainer in the Cathedral of Light, sends you to {area:3197} in the {zone:1422}. {npc:5149} in {zone:1455} gives the same quest."] = "Mit Stufe 50 schickt dich {npc:928}, der Paladinlehrer in der Kathedrale des Lichts, zum {area:3197} in den {zone:1422}. {npc:5149} in {zone:1455} gibt dieselbe Quest.",
		["Back to Ashlam in {area:3197}: he forges the {item:20620}. Look at the reward window before you hand in: Classic also offered the {item:20505}, the {item:20504} or the {item:20512}, and Forever's notes say that choice may be gone. Use the stone before a fight against undead ({area:2279}, {area:2057}): it lasts ten minutes and is gone after one use."] = "Zurück zu Ashlam im {area:3197}: Er schmiedet {item:20620}. Sieh dir das Belohnungsfenster an, bevor du abgibst: Classic bot außerdem {item:20505}, {item:20504} oder {item:20512}, und die Hinweise von Forever sagen, dass diese Auswahl entfallen könnte. Benutze den Stein vor einem Kampf gegen Untote ({area:2279}, {area:2057}): Er hält zehn Minuten und ist nach einem Einsatz weg.",
		["Back to {area:3197}. Ashlam needs the voodoo of the {area:1417}'s trolls for the stone."] = "Zurück zum {area:3197}. Ashlam braucht das Voodoo der Trolle des {area:1417} für den Stein.",
		["Kill the Scourge of the {zone:1422} with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a {item:12840} about two kills in five. {area:197}, just east of {area:3197} around {area:196}, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast {spell:120} and {spell:1449} up close, Dark Summoners run for help at low health."] = "Töte die Geißel der {zone:1422} mit angelegter Kommission: Skelette, Ghule und Kultisten (Stufe 50-58) lassen in etwa zwei von fünf Fällen {item:12840} fallen. {area:197}, direkt östlich von {area:3197} um {area:196}, ist die nächste Farmstelle. Meide die Flesh Golems, die über die Felder patrouillieren; Skeletal Guardians wirken {spell:120} und {spell:1449} aus der Nähe, Dark Summoners holen bei niedriger Gesundheit Hilfe.",
		["Minion's Scourgestones"] = "Geißelsteine des Dieners",
		["The Scourge drop no Scourgestones unless you wear an {quest:5401}. {npc:10840} gives you one through her quest, {quest:5401}, which you hand in straight away (if you already have one from {area:2268}, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones."] = "Die Geißel lässt keine Geißelsteine fallen, wenn du keine {quest:5401} trägst. {npc:10840} gibt dir eine durch ihre Quest, {quest:5401}, die du sofort abgibst (hast du schon eine aus {area:2268}, trag diese). Leg sie in einen Schmuckplatz an: Sie erscheint als Buff, der nie ausläuft. Behalte sie an, bis du 20 Steine hast.",
		["The {area:1417}"] = "{area:1417}",
		["The {quest:5401}"] = "{quest:5401}",
		["the {quest:5401} trinket: equip it"] = "das {quest:5401}-Schmuckstück: anlegen",
		["{area:1477}, the {area:1417}, lies in the {area:74} in eastern {zone:1435}: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first."] = "{area:1477}, der {area:1417}, liegt in {area:74} im Osten von {zone:1435}: Geh die Treppen der Ruine hinauf, tauch in die geflutete Halle und folge den Treppen nach unten zum Portal. Es ist ein Dungeon für eine Gruppe aus fünf mit etwa Stufe 50-55. Sechs Troll-Zwischenbosse (Elite, Stufe 51-52) stehen auf den Balkonen um den großen runden Raum des Tempels, jeder hinter einem Rudel Elite auf seinem Seitenpfad. Jeder lässt jedes Mal seine Feder fallen: Gasher und {npc:5716} (Bernstein), Hukku und Mijan (Blau), Zolo und Loro (Grün); du brauchst alle sechs. Hukku ruft Wächter und wirft Schattenblitzsalven, Mijan heilt: Töte sie zuerst.",
		["{area:3197} is the Alliance camp at the south end of the {zone:1422}, north of the Alterac foothills. {npc:10838} commands it; {npc:10840} stands in the same camp."] = "{area:3197} ist das Allianzlager am Südende der {zone:1422}, nördlich der Ausläufer von Alterac. {npc:10838} befehligt es; {npc:10840} steht im selben Lager.",
		["{item:12840} x20"] = "{item:12840} x20",
		["{item:20606} x2: Gasher, {npc:5716}"] = "{item:20606} x2: Gasher, {npc:5716}",
		["{item:20607} x2: Hukku, Mijan"] = "{item:20607} x2: Hukku, Mijan",
		["{item:20608} x2: Zolo, Loro"] = "{item:20608} x2: Zolo, Loro",
		["{npc:1854} keeps watch at {area:196} on {area:197}, east of the camp. He turns your 20 stones into one {item:20612}: keep it."] = "{npc:1854} hält Wache bei {area:196} auf {area:197}, östlich des Lagers. Er macht aus deinen 20 Steinen einen {item:20612}: Behalte ihn.",
} end)()
t.guides["forever/class/paladin/lumina-windsinger"] = (function() return {
		["At 18 {npc:246378}, inside {area:16602} on the bluffs north-west of the {area:156}, sends you south to the {area:228} in {zone:1421}."] = "Mit Stufe 18 schickt dich {npc:246378} in {area:16602} auf den Klippen nordwestlich des {area:156} nach Süden zum {area:228} in {zone:1421}.",
		["At 20 {npc:259620} asks for a blade that can kill {quest:95140}. Talk to {npc:248840} beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third."] = "Mit Stufe 20 bittet {npc:259620} um eine Klinge, die {quest:95140} töten kann. Sprich mit {npc:248840} neben ihr für seine Weapon Notes, die die Teile auflisten, und behalte sie: Er will sie mit den Teilen zurück. Drei Teile in beliebiger Reihenfolge: zwei aus Dungeons (je eine Gruppe aus fünf) und ein Edelstein von Naga-Elite vor einem dritten.",
		["Back to the {area:228}"] = "Zurück zum {area:228}",
		["Back to {npc:248840} in the {area:228}'s lower part: he hands you the {item:268484}, a two-handed sword."] = "Zurück zu {npc:248840} im unteren Teil von {area:228}: Er überreicht dir {item:268484}, ein Zweihandschwert.",
		["Back to {npc:259620} in the {area:228} with the {item:268484} (the quest asks for it): she takes it and blesses it with the magic of her people into {item:267369}."] = "Zurück zu {npc:259620} in {area:228} mit {item:268484} (die Quest verlangt es): Sie nimmt es entgegen und segnet es mit der Magie ihres Volkes zu {item:267369}.",
		["Back to {npc:259649} at Zoram'gar: he cleanses the gem. Keep the {item:272448} for {npc:248840}."] = "Zurück zu {npc:259649} in Zoram'gar: Er reinigt den Kor Gem. Behalte den {item:272448} für {npc:248840}.",
		["Bring the lumber, the ingot and the gem to {npc:248840} in the {area:228}. He gives you a {item:268192} for a smith in {area:272}: keep it in your bags."] = "Bring das Holz, den Barren und den Kor Gem zu {npc:248840} in {area:228}. Er gibt dir {item:268192} für einen Schmied in {area:272}: Behalte es in deinen Taschen.",
		["Equip the {item:268484}. {quest:95140}, the great worgen, roams the woods south of the {area:228} toward the gates of {area:17065}. He is elite (level 25): the guide waits for level 22 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke."] = "Rüste {item:268484} aus. {quest:95140}, der große Worgen, streift durch die Wälder südlich von {area:228} in Richtung der Tore von {area:17065}. Er ist Elite (Stufe 25): Der Guide wartet zuerst auf Stufe 22, und sich zu gruppieren ist empfehlenswert; Spieler haben ihn ab Stufe 22 getötet, einer brauchte einen zweiten, ein anderer hat ihn solo auf Stufe 25 geschafft. Ein violetter Schild schützt ihn, bis dein erster Schlag mit der Klinge trifft: Eine Meldung verrät dir, dass er zerbrochen ist.",
		["Free {npc:248755}"] = "Befreie {npc:248755}",
		["Goblin Woodcarvers, inside"] = "Goblin-Holzschnitzer, drinnen",
		["Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: {npc:248755} walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the {area:228}. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage."] = "Gib zuerst den Schlüssel ab: Beginnst du die Eskorte davor, bekommt die Schlüsselquest keinen Fortschritt. Öffne dann den Käfig: {npc:248755} geht durch die Festung und ihren Hof, während die Gnolle angreifen, läuft dann zum Dock und findet allein ihren Weg zurück zum {area:228}. Bleib dicht bei ihr und halte sie am Leben; stirbt sie, nimm die Quest noch einmal an, wenn sie wieder in ihrem Käfig ist.",
		["The Forsaken paladin's two-handed sword: rescue {quest:91862}, gather three parts, slay {quest:95140}."] = "Das Zweihandschwert des verlassenen Paladins: Rette {quest:91862}, sammle drei Teile, erschlage {quest:95140}.",
		["The blade is a two-handed sword, and you need the skill to hit a level 25 elite with it. {npc:11870}, the weapon master in the {zone:1458}'s {object:36070}, teaches {spell:202} for a small fee; then swing it on easy mobs until the skill is near its cap (five points per level)."] = "Die Klinge ist ein Zweihandschwert, und du brauchst die Fertigkeit, um damit einen Elite der Stufe 25 zu treffen. {npc:11870}, der Waffenmeister im {object:36070} von {zone:1458}, bringt dir {spell:202} gegen eine kleine Gebühr bei; übe dann mit dem Schwert an leichten Mobs, bis die Fertigkeit fast am Maximum ist (fünf Punkte pro Stufe).",
		["The naga stand in the flooded ruins and passages around the {area:2797} entrance, just north of Zoram'gar: you do not need to enter the instance (its first naga drop the gem too). Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24) drop the {item:6995}, one in two. All are elite: grouping up is encouraged. Players solo them one at a time, with difficulty; a group of three makes it easy. They heal themselves, run for help at low health, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "Die Naga stehen in den überfluteten Ruinen und Gängen rund um den Eingang von {area:2797}, nördlich von Zoram'gar: Du musst die Instanz nicht betreten (auch ihre ersten Naga lassen den Kor Gem fallen). Tide Priestesses (Stufe 20-21), Oracles (21-22) und Sea Witches (23-24) lassen den {item:6995} fallen, jede zweite. Alle sind Elite: Sich zu gruppieren ist empfehlenswert. Solo schaffst du sie nur einzeln und mit Mühe; mit einer Gruppe aus drei Spielern ist es leicht. Sie heilen sich selbst, rufen bei wenig Leben um Hilfe, und die Sea Witches wirken aus der Nähe {spell:122}. Manche Spieler berichten, dass in einer Schlachtzugsgruppe nichts fällt.",
		["The pyre on {area:172}"] = "Der Scheiterhaufen auf der {area:172}",
		["The {item:267361}"] = "{item:267361}",
		["The {item:272448}"] = "Der {item:272448}",
		["The {item:6995}"] = "{item:6995}",
		["Watch {npc:3539} forge the blade"] = "Sieh {npc:3539} beim Schmieden der Klinge zu",
		["from the {object:566037}"] = "von den {object:566037}",
		["{area:1581} lies under {area:20} in {zone:1436}, Alliance land: a group of five at about 17-24. From the {zone:1458} take the zeppelin to {object:3202} in {zone:1434} and go north through {zone:1431} into {zone:1436}. The way in is the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time."] = "{area:1581} liegt unter {area:20} in {zone:1436}, Allianzgebiet: eine Gruppe aus fünf mit etwa Stufe 17-24. Nimm von {zone:1458} den Zeppelin nach {object:3202} in {zone:1434} und geh nach Norden durch {zone:1431} nach {zone:1436}. Der Weg hinein ist die Mine von {area:20}. Die Goblin Woodcarvers (Elite, Stufe 18-19) in Sneeds Mastraum lassen das Holz jedes Mal fallen.",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, in der Mine von {area:20}",
		["{area:172} lies in the lake north-east of the {area:228}. The gnolls' pyre, with the {object:566037}, is on its shore: click the remains to hand in, and click them again for the next quest. The body is a tauren's, not the elf's."] = "{area:172} liegt im See nordöstlich des {area:228}. Der Scheiterhaufen der Gnolle mit {object:566037} steht an seinem Ufer: Klick die Überreste an, um abzugeben, und klick sie noch einmal für die nächste Quest an. Der Leichnam gehört einem Tauren, nicht der Elfe.",
		["{area:236} is the dungeon in south Silverpine, for a group of five in the low to mid 20s. The ingot sits on the table next to {npc:4275} at the very end. A friend's cleared instance works: walk in and run to the table."] = "{area:236} ist der Dungeon im Süden von Silverpine, für eine Gruppe aus fünf in den niedrigen bis mittleren Zwanzigern. Der Barren liegt auf dem Tisch neben {npc:4275} ganz am Ende. Die bereits geräumte Instanz eines Freundes geht: Lauf hinein und renn zum Tisch.",
		["{item:267361}, on Arugal's table"] = "{item:267361}, auf Arugals Tisch",
		["{item:267412}, from the Rot Hide gnolls"] = "{item:267412}, von den Gnollen der Moderfelle",
		["{item:267454}: talk to {npc:248840}"] = "{item:267454}: sprich mit {npc:248840}",
		["{item:268484} and {item:267369} (Forsaken)"] = "{item:268484} und {item:267369} (Verlassene)",
		["{npc:248840} stands in the lower part of the {area:228}, below the surface; {npc:259611} keeps watch near the town's entrance."] = "{npc:248840} steht im unteren Teil des {area:228}, unter der Oberfläche; {npc:259611} hält Wache nahe dem Eingang der Stadt.",
		["{npc:259620} waits beside {npc:248840} in the {area:228} (a different {npc:259620} from the one you escorted). For {quest:95034}, click through every line of her story."] = "{npc:259620} wartet neben {npc:248840} im {area:228} (ein anderer {npc:259620} als der, den du eskortiert hast). Klick für {quest:95034} jede Zeile ihrer Geschichte durch.",
		["{npc:259620}, the {area:228}"] = "{npc:259620}, das {area:228}",
		["{npc:259620}: hear her story to the end"] = "{npc:259620}: hör ihre Geschichte bis zum Ende",
		["{npc:259649} waits at {area:2897} on {zone:1440}'s west coast: take the zeppelin from {object:3202} (or the {zone:1458}) to {zone:1454}, then go north through the {zone:1413} into {zone:1440} and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take {npc:259649}'s quest before you hunt the naga: the Kor Gem only drops while you have it."] = "{npc:259649} wartet in {area:2897} an der Westküste von {zone:1440}: Nimm den Zeppelin von {object:3202} (oder aus {zone:1458}) nach {zone:1454}, geh dann nördlich durch {zone:1413} nach {zone:1440} und folge der Straße nach Westen. Andruk, der Windreitermeister des Außenpostens, erspart dir den Weg beim nächsten Mal. Nimm die Quest von {npc:259649} an, bevor du die Naga jagst: Der Kor Gem fällt nur, solange du sie hast.",
		["{npc:3539} gives you {quest:95125}"] = "{npc:3539} gibt dir {quest:95125}",
		["{npc:3539}, the weaponsmith, stands just south of {area:272} in {zone:1424}. Accepting {quest:95125} starts the forging: step back and wait near him until he is done."] = "{npc:3539}, der Waffenschmied, steht südlich von {area:272} in {zone:1424}. Mit dem Annehmen von {quest:95125} beginnt das Schmieden: Tritt zurück und warte in seiner Nähe, bis er fertig ist.",
		["{quest:91862} is caged in the basement of {area:235}, at the north end of the isle. The Rot Hide gnolls (level 18-19) fill the keep: they pull in big groups across floors and players report very fast respawns, so clear a path and keep moving. Any of them can carry the {item:267412} (often the first kill); the rare {npc:1944} (22) and Snarlmane (23) can too. If her cage is empty, another player is escorting her: wait for her to come back."] = "{quest:91862} ist im Keller von {area:235} am Nordende der Insel in einen Käfig gesperrt. Die Rot Hide-Gnolle (Stufe 18-19) füllen die Festung: Sie kommen in großen Gruppen über Stockwerke hinweg, und Spieler berichten von sehr schnellen Respawns, also räum einen Weg frei und bleib in Bewegung. Jeder von ihnen kann {item:267412} tragen (oft der erste Kill); die Rares {npc:1944} (22) und Snarlmane (23) auch. Ist ihr Käfig leer, eskortiert sie ein anderer Spieler: Warte, bis sie zurückkommt.",
		["{quest:95140}, with the {item:268484} equipped"] = "{quest:95140}, mit ausgerüstetem {item:268484}",
} end)()
t.guides["forever/class/paladin/tome-of-divinity"] = (function() return {
		["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "Mit 12 schickt dich {npc:5149}, der Paladinlehrer in {object:32362} von {zone:1455}, die Treppe hinauf zu {npc:6179}. Der Botengang ist optional und bringt ein wenig EP: {npc:1232} in {area:131} und {npc:928} in {zone:1453} geben dieselbe Quest (wenn du eine annimmst, schließen sich die anderen), und {npc:6179} beginnt die Questreihe auch ohne sie.",
		["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "Mit 12 schickt dich {npc:927}, der Paladinlehrer in {area:87}, zu {npc:6171} in die Kathedrale des Lichts in {zone:1453}. Der Botengang ist optional und bringt ein wenig EP: {npc:5149} in {zone:1455} gibt dieselbe Quest (wenn du die eine annimmst, schließt sich die andere), und {npc:6171} beginnt die Questreihe auch ohne sie.",
		["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "Zurück zur Kathedrale des Lichts: {npc:6173} nimmt das Schriftstück, {npc:6171} bringt dir {spell:7328} bei.",
		["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "Zurück zur Kathedrale. {npc:6171} gibt dir {item:6866}; {npc:6173} liegt verwundet am Altar derselben Halle. Behalte das Symbol: Du brauchst es bei {npc:6172}. Wenn du es verlierst, gibt dir {npc:6171} ein neues (das {item:6866}).",
		["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "Zurück nach oben in den {object:32386}: {npc:6178} nimmt das Schriftstück, {npc:6179} bringt dir {spell:7328} bei.",
		["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "Wieder nach oben in den {object:32386}. {npc:6179} gibt dir {item:6866}; ihr Mann {npc:6178} ruht auf demselben Stockwerk. Behalte das Symbol: Du brauchst es bei {npc:6177}. Wenn du es verlierst, gibt dir {npc:6179} ein neues (das {item:6866}).",
		["Right-click the {item:6775}"] = "Klicke {item:6775} mit der rechten Maustaste an",
		["Right-click the {item:6916}"] = "Klicke {item:6916} mit der rechten Maustaste an",
		["The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the {item:6847}. They run for help at low health: finish them or step back. They respawn in three minutes."] = "Die Dark Iron Spies (Stufe 9-11, zwölf an der Zahl) schleichen um das kleine Haus unterhalb des Sees, südlich von Narm; du siehst sie von seinem Hügel aus. Etwa jeder zweite Kill lässt {item:6847} fallen. Sie rufen bei wenig Leben um Hilfe: Erledige sie oder tritt zurück. Sie respawnen nach drei Minuten.",
		["The Defias Rogue Wizards around the big stone tablet east of {npc:6172} carry the {item:6846}: about one kill in two drops it, but some players need many kills. They respawn in three minutes."] = "Die Defias Rogue Wizards bei der großen Steintafel östlich von {npc:6172} tragen {item:6846}: Etwa jeder zweite Kill lässt es fallen, aber manche Spieler brauchen viele Kills. Sie respawnen nach drei Minuten.",
		["The summons (Dwarf)"] = "Die Vorladung (Zwerg)",
		["The summons (Human)"] = "Die Vorladung (Mensch)",
		["The {item:6846}"] = "{item:6846}",
		["The {item:6847}"] = "{item:6847}",
		["The {item:6866}"] = "{item:6866}",
		["{item:2589} x10"] = "{item:2589} x10",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: Abtrünnige Hexer der Defias",
		["{item:6847}: Dark Iron Spies"] = "{item:6847}: Spione der Dunkeleisenzwerge",
		["{item:6866} on {npc:6172}'s body"] = "{item:6866} auf den Leichnam von {npc:6172}",
		["{item:6866} on {npc:6177}'s body"] = "{item:6866} auf den Leichnam von {npc:6177}",
		["{npc:6171} stands inside the Cathedral of Light. He hands you the {item:6775}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6171} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6171} steht in der Kathedrale des Lichts. Er gibt dir {item:6775}: Klicke es in deinen Taschen mit der rechten Maustaste an, um die nächste Quest zu beginnen. Wenn im Buch steht, dass die Quest schon erledigt ist, zerstöre es und bitte {npc:6171} um ein neues Exemplar. Bring für den nächsten Schritt 10 {item:2589} mit, falls du welches hast.",
		["{npc:6171}, Cathedral of Light"] = "{npc:6171}, Kathedrale des Lichts",
		["{npc:6172} lies dead on {area:56}, the island in {area:86} in eastern Elwynn, on top of one of the mounds around the stone circle. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes. The Defias Rogue Wizards on the island (level 9-10) cast {spell:116} from far off: they stand apart, so pull one at a time."] = "{npc:6172} liegt tot auf {area:56}, der Insel in {area:86} im östlichen Elwynn, oben auf einem der Hügel rund um den Steinkreis. Wähle seinen Leichnam als Ziel und belebe ihn mit {item:6866} wieder, sprich dann mit ihm. Wenn ihn gerade ein anderer Paladin wiederbelebt hat, ist sein Leichnam nach etwa drei Minuten wieder da. Die Defias Rogue Wizards auf der Insel (Stufe 9-10) wirken {spell:116} aus großer Entfernung: Sie stehen verstreut, also zieh einen nach dem anderen.",
		["{npc:6174} stands at a corner in the middle of the {object:2096}, outside a general goods store. She wants 10 {item:2589}: humanoids drop it (Riverpaw gnolls in {zone:1436} about every other kill, Defias and kobolds a little less), or buy it at the Auction House a few steps away in the {object:2096}."] = "{npc:6174} steht an einer Ecke mitten im {object:2096}, vor einem Gemischtwarenladen. Sie will 10 {item:2589}: Humanoide lassen es fallen (Riverpaw-Gnolle in {zone:1436} etwa bei jedem zweiten Kill, Defias und Kobolde etwas seltener), oder kaufe es im Auktionshaus, ein paar Schritte entfernt im {object:2096}.",
		["{npc:6175} walks the outer ring of the Commons, past the front gate, the bank and the Auction House. He wants 10 {item:2589}: humanoids drop it ({npc:1245} in {area:131} every time, Dark Iron Ambushers about two kills in five), or buy it at the Auction House on his ring."] = "{npc:6175} geht auf dem äußeren Ring der Commons entlang, am Haupttor, der Bank und dem Auktionshaus vorbei. Er will 10 {item:2589}: Humanoide lassen es fallen ({npc:1245} in {area:131} jedes Mal, Dark Iron Ambushers in etwa zwei von fünf Kills), oder kaufe es im Auktionshaus auf seinem Ring.",
		["{npc:6177} lies dead in {zone:1426}, not {zone:1432}: east past {area:131}, north-east of Ironband's compound, on the smallest of three little hills between {area:212} and the {object:147516} camp. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes."] = "{npc:6177} liegt tot in {zone:1426}, nicht in {zone:1432}: östlich an {area:131} vorbei, nordöstlich von Ironbands Anlage, auf dem kleinsten von drei Hügeln zwischen {area:212} und dem Lager von {object:147516}. Wähle seinen Leichnam als Ziel und belebe ihn mit {item:6866} wieder, sprich dann mit ihm. Wenn ihn gerade ein anderer Paladin wiederbelebt hat, ist sein Leichnam nach etwa drei Minuten wieder da.",
		["{npc:6179} stands upstairs in the {object:32386}, in the {object:32362}: take the ramp at the back of the hall. She hands you the {item:6916}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6179} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6179} steht oben im {object:32386}, in {object:32362}: Nimm die Rampe am Ende der Halle. Sie gibt dir {item:6916}: Klicke es in deinen Taschen mit der rechten Maustaste an, um die nächste Quest zu beginnen. Wenn im Buch steht, dass die Quest schon erledigt ist, zerstöre es und bitte {npc:6179} um ein neues Exemplar. Bring für den nächsten Schritt 10 {item:2589} mit, falls du welches hast.",
		["{npc:6179}, upstairs in the {object:32386}"] = "{npc:6179}, oben im {object:32386}",
		["{spell:7328} (Alliance)"] = "{spell:7328} (Allianz)",
		["{spell:7328} at 12, the paladin's resurrection: an easy chain through your capital and its home zone."] = "{spell:7328} mit 12, die Wiederbelebung des Paladins: eine einfache Questreihe durch deine Hauptstadt und ihr Heimatgebiet.",
} end)()
t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["At 4 {npc:244808} sends you after a {npc:246143} who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy)."] = "Mit 4 schickt dich {npc:244808} hinter einem {npc:246143} her, der in die Hügel westlich der Kirche geflohen ist, südlich der Fledermaushöhle. Sprich sie an, um Hilfe anzubieten: Sie greift dich an, und du musst sie erledigen (Stufe 3, leicht).",
		["At 8 {npc:246152} in {area:159} sends you to the order's keep on the west coast. {quest:91317} in {area:16881} and the crypt under it hit hard at 8-9: come at 10 or later."] = "Mit 8 schickt dich {npc:246152} in {area:159} zur Festung des Ordens an der Westküste. {quest:91317} in {area:16881} und die Gruft darunter schlagen mit 8-9 hart zu: Komm mit 10 oder später.",
		["Back to the keep"] = "Zurück zur Feste",
		["Back to {area:16602}, across the whole glades: Billmuth downstairs takes the plans, then {npc:246378}, back upstairs in the keep, teaches you {spell:7328}."] = "Zurück nach {area:16602}, quer durch die ganzen Lichtungen: Billmuth unten nimmt die Pläne, dann bringt dir {npc:246378}, wieder oben in der Festung, {spell:7328} bei.",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep. If you lose the symbol, {npc:246378} gives you another."] = "Zurück nach {area:16602}. {npc:246378} gibt dir {item:6866}; {npc:257655} wartet unten in der Festung. Wenn du das Symbol verlierst, gibt dir {npc:246378} ein neues.",
		["Faintly Glowing Bones x6"] = "Faintly Glowing Bones x6",
		["Follow the road east out of {area:154} to {area:159}. {npc:246152}, the paladin trainer, stands in town; she trains you from here on."] = "Folge der Straße östlich aus {area:154} hinaus nach {area:159}. {npc:246152}, die Paladinlehrerin, steht in der Stadt; von hier an bildet sie dich aus.",
		["Heal 5 {npc:259377} with {spell:635}"] = "Heile 5 {npc:259377} mit {spell:635}",
		["Lumber Piles, in the cellar: the way down is here"] = "Lumber Piles, im Keller: Hier geht es nach unten",
		["Talk to the {npc:246143}, then defeat her"] = "Sprich mit {npc:246143} und besiege sie dann",
		["Tarnished Drudges x8"] = "Tarnished Drudges x8",
		["Tarnished Zealots x6"] = "Tarnished Zealots x6",
		["The Scarlet Zealots (level 8-9), Friars (9-10) and Tarnished around {area:812} carry the attack plans. They run for help at low health and respawn in five minutes."] = "Die Scarlet Zealots (Stufe 8-9), Friars (9-10) und Tarnished um {area:812} tragen die Angriffspläne. Sie rufen bei wenig Leben um Hilfe und respawnen nach fünf Minuten.",
		["The Scarlet attack plans"] = "Die Angriffspläne des Scharlachroten Kreuzzugs",
		["The Shadowvale Lurchers and Mystics (level 8-10) in the crypt drop the Faintly Glowing Bones: about one in two from Lurchers, more from one kind of Mystic, less from the other."] = "Die Shadowvale Lurchers und Mystics (Stufe 8-10) in der Gruft lassen die Faintly Glowing Bones fallen: etwa jeder zweite Lurcher, mehr von einer Art Mystic, weniger von der anderen.",
		["The Vile Fin murlocs (level 9-11) lurk on the bluffs along the road east of the keep and in the camps around the lake to the south-west, on the way down to {area:16881}."] = "Die Vile Fin Murlocs (Stufe 9-11) lauern auf den Klippen an der Straße östlich der Festung und in den Lagern rund um den See im Südwesten, auf dem Weg hinunter nach {area:16881}.",
		["The cellar is under the village, not on the surface: the way down is inside a burned-out house, where the arrow points. Twelve Lumber Piles (stacked beams) lie in the cellar, each good for one {item:246213}. {npc:260396}, an elite (level 11-13), sits at the far end: leave it alone."] = "Der Keller liegt unter dem Dorf, nicht an der Oberfläche: Der Weg nach unten führt durch ein ausgebranntes Haus, dorthin zeigt der Pfeil. Im Keller liegen zwölf Lumber Piles (gestapelte Balken), jeder gut für ein {item:246213}. {npc:260396}, ein Elite (Stufe 11-13), sitzt am hinteren Ende: Lass ihn in Ruhe.",
		["The crypt under {area:16881}"] = "Die Gruft unter {area:16881}",
		["The {item:286269}, a green crystal, lies on the floor in the left-hand part of the crypt."] = "{item:286269}, ein grüner Kristall, liegt im linken Teil der Gruft auf dem Boden.",
		["The {item:6866}"] = "{item:6866}",
		["Tyr's Watch and {spell:7328} (Forsaken)"] = "Tyr's Watch und {spell:7328} (Verlassene)",
		["Vile Fin Attackers x8"] = "Vile Fin Attackers x8",
		["Vile Fin Seers x8"] = "Vile Fin Seers x8",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "Geh von {area:159} nach Süden zu {area:153} und hinab nach {zone:1458}. {npc:10181} hält in {object:36126} Hof; {npc:257648} bettelt in {object:36078}.",
		["{area:16602} stands on the bluffs north-west of the {area:156} (the road west starts near 29,46). {npc:246349} waits at the gate. {npc:246389}, the keep's trainer, and {npc:259190}, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after {quest:96896} from Leonid at the keep, the end of {npc:267009}'s chain that starts south-east of {area:159}; take their quests when you see them."] = "{area:16602} liegt auf den Klippen nordwestlich von {area:156} (die Straße nach Westen beginnt bei etwa 29,46). {npc:246349} wartet am Tor. {npc:246389}, die Lehrerin der Festung, und {npc:259190}, ihr Stallmeister, stehen am Waldrand direkt südlich von ihm. Sie haben erst ab Stufe 10 Arbeit für dich, und zwar nach {quest:96896} von Leonid in der Festung, dem Ende der Questreihe von {npc:267009}, die südöstlich von {area:159} beginnt; nimm ihre Quests an, wenn du sie siehst.",
		["{area:812} is at the far east end of the glades, a long walk. Falgan lies dead among the Scarlet Crusaders there: target his body and use the {item:6866}, then talk to him at once, as he does not stay alive long. If he is already up (another player), just talk to him; if he died again, raise him again."] = "{area:812} liegt am äußersten Ostende der Lichtungen, ein langer Marsch. Falgan liegt tot unter den Scarlet Crusaders dort: Wähle seinen Leichnam als Ziel und benutze {item:6866}, sprich dann sofort mit ihm, denn er bleibt nicht lange am Leben. Wenn er schon wieder steht (ein anderer Spieler), sprich einfach mit ihm; wenn er wieder gestorben ist, belebe ihn erneut wieder.",
		["{item:2589} x10"] = "{item:2589} x10",
		["{npc:1569} gives you a {item:282423} after {quest:364}: read it, then bring it to {npc:244808} by the church. He asks you to heal five {npc:259377} lying around {area:154}. {spell:635} hurts a Forsaken paladin a little each time: watch your health."] = "{npc:1569} gibt dir nach {quest:364} {item:282423}: Lies es und bringe es dann zu {npc:244808} bei der Kirche. Er bittet dich, fünf {npc:259377} zu heilen, die um {area:154} herum liegen. {spell:635} schadet einem Verlassenen-Paladin jedes Mal ein wenig: Achte auf dein Leben.",
		["{npc:246349} gives you a weapon, then sends you round the keep to speak with four of its people: {npc:246389} just south of the gate, {npc:246394}, the lookout, who walks the road south-east of the keep, then {npc:246393} and {npc:246378} inside the keep. Pick the conversation option with each."] = "{npc:246349} gibt dir eine Waffe und schickt dich dann um die Festung, damit du mit vier ihrer Leute sprichst: {npc:246389} südlich des Tores, {npc:246394}, der Späher, der die Straße südöstlich der Festung abgeht, dann {npc:246393} und {npc:246378} in der Festung. Wähle bei jedem die Gesprächsoption.",
		["{npc:246349}: {item:246164} or {item:246165}"] = "{npc:246349}: {item:246164} oder {item:246165}",
		["{npc:246378} hands you {npc:259431}'s head for Sylvanas: keep it in your bags, it is what you hand in."] = "{npc:246378} gibt dir den Kopf von {npc:259431} für Sylvanas: Behalte ihn in deinen Taschen, er ist es, was du abgibst.",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it. {quest:91317} need level 9."] = "{npc:246378} führt den Orden aus dem Inneren der Festung; {npc:246393} steht neben ihr. {quest:91317} brauchen Stufe 9.",
		["{npc:246378} offers the first Lesson in Divinity at level 12. Bring 10 {item:2589} if you have it: the {zone:1458} asks for it next."] = "{npc:246378} bietet die erste Lesson of Divinity ab Stufe 12 an. Bring 10 {item:2589} mit, falls du welches hast: {zone:1458} verlangt es als Nächstes.",
		["{npc:246378}, back upstairs: {spell:7328}"] = "{npc:246378}, wieder oben: {spell:7328}",
		["{npc:246389} and {npc:259190} wait at the forest's edge south of the gate."] = "{npc:246389} und {npc:259190} warten am Waldrand südlich des Tores.",
		["{npc:246389}'s bones"] = "Die Knochen von {npc:246389}",
		["{npc:257648} needs 10 {item:2589}. Humanoids drop it: the Scarlet Zealots and Friars of the glades about three kills in ten. The Undercity Auction House sells it too."] = "{npc:257648} braucht 10 {item:2589}. Humanoide lassen es fallen: die Scarlet Zealots und Friars der Lichtungen in etwa drei von zehn Kills. Das Auktionshaus von Undercity verkauft es auch.",
		["{npc:257655}, downstairs"] = "{npc:257655}, unten",
		["{npc:259190} waits at the forest's edge south of the gate, a few steps west of {npc:246389}."] = "{npc:259190} wartet am Waldrand südlich des Tores, ein paar Schritte westlich von {npc:246389}.",
		["{npc:259190}'s crystal"] = "Der Kristall von {npc:259190}",
		["{quest:91317} (level 8-9) hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. Commander {npc:259431} (level 10) stands on the upper floor of a house, with Drudges below him: clear the ground floor first."] = "{quest:91317} (Stufe 8-9) halten das zerstörte Dorf {area:16881} im {area:16616} südwestlich der Festung. Kommandant {npc:259431} (Stufe 10) steht im Obergeschoss eines Hauses, unter ihm Drudges: Räume zuerst das Erdgeschoss.",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328}, um gefallene Verbündete wiederzubeleben, dazu eine Waffe und ein Schild für einen neuen verlassenen Paladin.",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "Mit 20 gibt dir {npc:6179}, oben im {object:32386} in {object:32362}, {item:6776}. Klicke es mit der rechten Maustaste an: Es schickt dich zu {npc:6171} in die Kathedrale des Lichts in {zone:1453}. Nimm {area:2257} von {zone:1455} nach {zone:1453}.",
		["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "Zurück zur Kathedrale des Lichts: {npc:6171} gibt dir den Schild {item:9607} und bringt dir {spell:5502} bei.",
		["Back to {npc:3649} in {area:442}: he purifies the gem."] = "Zurück zu {npc:3649} in {area:442}: Er reinigt den Edelstein.",
		["Back to {npc:6241}"] = "Zurück zu {npc:6241}",
		["Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil."] = "Bring die vier Teile zu {npc:6181} vor {zone:1455}. Nimm seine letzte Quest an und warte bei ihm, während er die Keule an seinem Amboss schmiedet.",
		["Goblin Woodcarvers, inside"] = "Goblin-Holzschnitzer, drinnen",
		["Protect {npc:6182}: three waves"] = "Beschütze {npc:6182}: drei Wellen",
		["Right-click the {item:6776}"] = "Klicke {item:6776} mit der rechten Maustaste an",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield and {spell:5502} on the way."] = "Der seltene Zweihandstreitkolben des Allianz-Paladins für die 20er, mit einem Schild und {spell:5502} auf dem Weg.",
		["The Blackfathom naga in the flooded passages around the {area:2797} entrance, on {zone:1440}'s north-west coast, drop the {item:6995}: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "Die Blackfathom Naga in den überfluteten Gängen rund um den Eingang von {area:2797} an der Nordwestküste von {zone:1440} lassen den {item:6995} fallen: Tide Priestesses (Stufe 20-21), Oracles (21-22) und Sea Witches (23-24), jede zweite. Du musst die Instanz nicht betreten. Alle sind Elite: Sich zu gruppieren ist empfehlenswert; Solo schaffst du sie nur einzeln und mit Mühe. Sie heilen sich selbst, rufen bei wenig Leben um Hilfe, bei manchen stehen Satyrn, und die Sea Witches wirken aus der Nähe {spell:122}. Manche Spieler berichten, dass in einer Schlachtzugsgruppe nichts fällt.",
		["The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east {zone:1432}, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one."] = "Die Erzkiste steht im Freien mitten im Lager der Mo'grosh-Oger im Nordosten von {zone:1432}, neben einem großen Baum und einem kaputten Wagen, zwischen den Höhlen. Im Lager sind etwa fünfzehn Mo'grosh-Oger, Elite (Stufe 18-19), die dich umwerfen und nach fünf Minuten zurückkommen: Sich zu gruppieren ist empfehlenswert; mit 20-22 braucht man eine Gruppe von etwa drei Spielern. Die Kiste ist zwei Sekunden nach jedem Plündern wieder da, sodass jeder Paladin in der Gruppe eine bekommt.",
		["The {item:6995}"] = "{item:6995}",
		["The {item:7083}"] = "{item:7083}",
		["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581} ist ein Dungeon für fünf Spieler unter {area:20}; das Instanzportal liegt am Ende der Mine von {area:20}. Die Goblin Woodcarvers (Elite, Stufe 18-19) im Mastraum bei Sneed lassen das Holz jedes Mal fallen.",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, in der Mine von {area:20}",
		["{area:236} is a dungeon for a group of five in the low to mid 20s, in southern {zone:1421}, Horde land: a long trip for the Alliance, through the {zone:1437}, Arathi and {area:287}. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it."] = "{area:236} ist ein Dungeon für eine Gruppe aus fünf Spielern in den unteren bis mittleren 20ern, im Süden von {zone:1421}, Horde-Gebiet: eine lange Reise für die Allianz, durch {zone:1437}, Arathi und {area:287}. Der Hammer liegt auf einer Kiste gegenüber den Pferden in den Ställen, früh im Dungeon, am Ende des Hofs vor der Rampe nach oben; er ist fünf Minuten nach dem Aufnehmen wieder da.",
		["{npc:3649} is in {area:442}. Take his quest before you hunt naga: the Kor Gem never drops without it."] = "{npc:3649} ist in {area:442}. Nimm seine Quest an, bevor du Naga jagst: Der Kor Gem fällt ohne sie nie.",
		["{npc:6171} stands in the Cathedral of Light. Humans get the {item:6776} from him. Right-click the book to start its quest and hand it straight back to him."] = "{npc:6171} steht in der Kathedrale des Lichts. Menschen bekommen {item:6776} von ihm. Klicke das Buch mit der rechten Maustaste an, um seine Quest zu beginnen, und gib sie gleich bei ihm ab.",
		["{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes."] = "{npc:6181} arbeitet vor den Toren von {zone:1455}, nicht darin. Er gibt dir {item:6996}: vier Teile, in beliebiger Reihenfolge. Behalte die Notizen.",
		["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}, south of {area:20}: take the path that runs south beside the {area:1581}' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or {npc:6182} die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24."] = "Das Bauernhaus von {npc:6182} steht an der Südwestküste von {zone:1436}, südlich von {area:20}: Nimm den Pfad, der südlich neben dem hinteren Ausgang von {area:1581} verläuft. Wenn du ihre Quest annimmst, geht sie von ihrem Obstgarten zum Haus, und drei Wellen Defias Raiders (Stufe 17-18) greifen an: drei, dann vier, dann fünf. Kämpfe nah bei ihr, damit sie nicht überrannt wird, und heile sie, wenn sie fällt. Zwischen den Wellen hast du Zeit zum Essen und Trinken, und sie wird voll geheilt. Wenn du oder {npc:6182} stirbt, schlägt die Quest fehl: Brich sie ab und nimm sie erneut bei ihr an (sie ist fünf Minuten nach ihrem Tod zurück). Allein finden Spieler sie vor etwa Stufe 24 schwer.",
		["{npc:6241} is downstairs in the house of {area:144} that has a tailoring merchant outside. His quest only opens once you hold Jordan's."] = "{npc:6241} ist unten in dem Haus in {area:144}, vor dem ein Schneiderhändler steht. Seine Quest wird erst frei, wenn du Jordans Notizen hast.",
		["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "{npc:6241} verarbeitet das Erz zu {item:6993}, dem Teil, das Jordan will.",
		["{object:91138}, inside"] = "{object:91138}, drinnen",
		["{object:92420} crate"] = "Kiste: {object:92420}",
} end)()
t.guides["forever/class/priest/benediction"] = (function() return {
		["Equip {item:18646}, then find {npc:14494}, a ghost on the hillside in the north-west of the {zone:1423}, west of {area:2279}'s gate (if she does not show, take the Eye off and put it back on). {quest:7621} is only talk; {quest:7622} starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or {item:13931}, and a stack of {item:8956} or {item:13180} for the skeletons."] = "Rüste {item:18646} aus und finde dann {npc:14494}, einen Geist am Hang im Nordwesten der {zone:1423}, westlich vom Tor von {area:2279} (wenn sie nicht erscheint, nimm das Auge ab und leg es wieder an). {quest:7621} ist nur Gerede; {quest:7622} beginnt in dem Moment, in dem du sie annimmst, also bereite dich vorher vor: volles Mana, Major Mana Potions, Demonic oder Dark Runes, Mana-Nahrung oder {item:13931} und einen Stapel {item:8956} oder {item:13180} für die Skelette.",
		["Save 50 peasants before 15 die (the {object:179694} by the path counts the dead). They walk from the cave towards {npc:14494} in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first ({spell:552}), keep {spell:139} on the hurt ones, {spell:2061} the nearly dead, and kill skeletons as they spawn: one {spell:15237} of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and {npc:14494} is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back."] = "Rette 50 Bauern, bevor 15 sterben (der {object:179694} am Pfad zählt die Toten). Sie laufen in Wellen von der Höhle zu {npc:14494}, fangen Krankheiten auf und ziehen Skelette und Skelettbogenschützen an. Heile zuerst die violett leuchtenden Krankheiten ({spell:552}), halte {spell:139} auf den Verletzten, wirke {spell:2061} auf die Beinahe-Toten und töte Skelette, sobald sie erscheinen: Ein {spell:15237} von Rang 3 oder höher tötet sie, Öl braucht zwei Ticks, während sie dich schlagen. Schütze dich zu Beginn jeder Welle mit einem Schild; freundliche Namensplaketten machen die verletzten Bauern leicht erkennbar. Freunde dürfen dich vor dem Annehmen buffen und Bauern heilen oder von Krankheiten befreien, aber sie dürfen dich nicht heilen oder buffen, kein Skelett angreifen und kein Pet mitbringen, sobald es losgeht, sonst erscheint ein Dämon und tötet alle. Scheiterst du, ist {npc:14494} eine Weile weg (Spieler berichten von 15 Minuten bis zu zwei Stunden); sprich sie wieder an, wenn sie zurück ist.",
		["The epic priest staff: the {spell:23101} from {area:2717}, {npc:14494}'s peasant rescue, then the Eye of Shadow."] = "Der epische Priesterstab: {spell:23101} aus {area:2717}, die Rettung der Bauern durch {npc:14494}, dann das Auge der Schatten.",
		["The splinter needs {item:18665} as well. {npc:12397}, a world boss in the {zone:1419} (a raid), always drops it; Manahounds and Doomguard Commanders there drop it rarely (about 3% and 2%), the Hederine of Winterspring hardly ever. It can be traded: check the Auction House first."] = "Der Splitter braucht außerdem {item:18665}. {npc:12397}, ein Weltboss im {zone:1419} (ein Schlachtzug), lässt es immer fallen; Manahounds und Doomguard Commanders dort lassen es selten fallen (etwa 3 % und 2 %), die Hederine in Winterspring fast nie. Es ist handelbar: Schau zuerst im Auktionshaus.",
		["Use the {item:18659} with both Eyes in your bags: {item:18608}"] = "Benutze {item:18659}, wenn beide Augen in deinen Taschen sind: {item:18608}",
		["With the {item:18659}, {item:18646} and {item:18665} in your bags, use the splinter wherever you are: it becomes {item:18608}. Use {item:18608} to turn it into Anathema, the shadow staff, and back (a 30-minute cooldown)."] = "Wenn {item:18659}, {item:18646} und {item:18665} in deinen Taschen sind, benutze den Splitter, wo du gerade bist: Er wird zu {item:18608}. Benutze {item:18608}, um ihn in Anathema, den Schattenstab, zu verwandeln und wieder zurück (30 Minuten Abklingzeit).",
		["{item:18608} and Anathema"] = "{item:18608} und Bannfluch",
		["{item:18646} comes from the {object:179703}, the chest that appears when {npc:12018} yields in {area:2717}, a 40-player raid (it is in the cache about half the time). {area:2717}'s portal is at the bottom of {area:1584}; once you have done Attunement to the Core (a {item:18412} from beside that portal), {npc:14387} inside {area:254} ports you straight in. Nothing in this chain starts without the Eye: {npc:14494} is invisible until you equip it."] = "{item:18646} stammt aus {object:179703}, der Truhe, die erscheint, wenn {npc:12018} in {area:2717}, einem Schlachtzug für 40 Spieler, nachgibt (sie ist etwa zur Hälfte der Zeit darin). Das Portal von {area:2717} liegt am Ende von {area:1584}; sobald du Attunement to the Core abgeschlossen hast (ein {item:18412} neben diesem Portal), bringt dich {npc:14387} in {area:254} direkt hinein. Ohne das Auge beginnt in dieser Questreihe nichts: {npc:14494} ist unsichtbar, bis du es ausrüstest.",
		["{item:18646}: {area:2717}, through {area:254}"] = "{item:18646}: {area:2717}, durch {area:254}",
		["{npc:14387}: the way into {area:2717} once attuned"] = "{npc:14387}: der Weg nach {area:2717}, sobald du eingestimmt bist",
} end)()
t.guides["forever/class/priest/blood-of-morphaz"] = (function() return {
		["17,060 XP and 1g55s at 50: {zone:1447}, then Morphaz in the {area:1417} (group of 5). The item choice may be gone."] = "17.060 EP und 1g55s mit 50: {zone:1447}, dann Morphaz im {area:1417} (Gruppe aus 5). Die Gegenstandswahl könnte entfallen sein.",
		["17,060 experience and 1 gold 55 silver"] = "17.060 Erfahrung und 1 Gold 55 Silber",
		["At 50 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) offers {quest:8254}. Before you leave a city, buy an {item:7972} at the Auction House (a few silver): the third quest asks for one and it drops rarely."] = "Mit 50 bietet dir in {zone:1455} {npc:11406} im {object:32386} ({object:32362}) {quest:8254} an. Kaufe, bevor du eine Stadt verlässt, einen {item:7972} im Auktionshaus (ein paar Silber): Die dritte Quest verlangt einen, und er fällt selten.",
		["At 50, {npc:5489} at the altar of {zone:1453}'s Cathedral of Light offers {quest:8254} ({npc:11406} in {zone:1455} has it too). Before you leave, buy an {item:7972} at the Auction House in the {object:2096} (a few silver): the third quest asks for one and it drops rarely."] = "Mit 50 bietet dir {npc:5489} am Altar der Kathedrale des Lichts in {zone:1453} {quest:8254} an ({npc:11406} in {zone:1455} hat sie auch). Kaufe, bevor du gehst, einen {item:7972} im Auktionshaus im {object:2096} (ein paar Silber): Die dritte Quest verlangt einen, und er fällt selten.",
		["At 50, {npc:6018} in {zone:1454}'s {object:172961} offers {quest:8254}. Before you leave, buy an {item:7972} at the Auction House (a few silver): the third quest asks for one and it drops rarely."] = "Mit 50 bietet dir {npc:6018} im {object:172961} von {zone:1454} {quest:8254} an. Kaufe, bevor du gehst, einen {item:7972} im Auktionshaus (ein paar Silber): Die dritte Quest verlangt einen, und er fällt selten.",
		["Carrying an {item:7972} already? It counts at once. Otherwise any undead may drop one, rarely: the {npc:7864} (level 48) in the {area:1221} below {npc:8405}'s cliff drop it about one kill in ten, the highborne ghosts on {zone:1447}'s border with {zone:1440} (level 45-46) a little less, the Anguished and {npc:7523} in {zone:1452} (54-55) about one in eight. The Auction House is usually quicker."] = "Hast du schon einen {item:7972}? Er zählt sofort. Sonst lässt ihn jeder Untote selten fallen: die {npc:7864} (Stufe 48) in {area:1221} unter der Klippe von {npc:8405} etwa bei jedem zehnten Kill, die Geister der Hochgeborenen an der Grenze von {zone:1447} zu {zone:1440} (Stufe 45-46) etwas seltener, die Anguished und {npc:7523} in {zone:1452} (54-55) etwa bei jedem achten. Das Auktionshaus ist meist schneller.",
		["Morphaz in the {area:1417}"] = "Morphaz im {area:1417}",
		["Morphaz is a level 52 elite green dragon inside the {area:1417}, a five-player dungeon: bring a group of five (a level 60 group clears it with ease). Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. The temple stands in the middle of the {area:74}: climb the steps on its south side, swim down through the flooded hall and take the stairs to the portal. Inside, Morphaz only appears late: kill the six troll minibosses on the upper balconies, then {npc:5710} below them; that wakes the drakes Weaver and Dreamscythe in the Pit of Sacrifice, and killing both brings Morphaz and Hazzas. The pair patrols together and cannot be split: pull them into a hallway and have the tank face them away from the group (breath and a knockback). Loot him in a party, not a raid group: the blood always drops."] = "Morphaz ist ein grüner Elite-Drache der Stufe 52 im {area:1417}, einem Dungeon für fünf Spieler: Bring eine Gruppe aus fünf mit (eine Gruppe der Stufe 60 räumt ihn mühelos). Horde: Flieg nach {area:75}; Allianz: Flieg nach {area:1438} im {zone:1419} und reite nach Norden. Der Tempel steht mitten im {area:74}: Steig die Stufen an seiner Südseite hinauf, schwimm durch die überflutete Halle nach unten und nimm die Treppe zum Portal. Drinnen erscheint Morphaz erst spät: Töte die sechs Troll-Minibosse auf den oberen Balkonen, dann {npc:5710} darunter; das weckt die Drachen Weaver und Dreamscythe in der Pit of Sacrifice, und wenn du beide tötest, erscheinen Morphaz und Hazzas. Das Paar patrouilliert zusammen und lässt sich nicht trennen: Zieh sie in einen Gang und lass den Tank sie von der Gruppe weg ausrichten (Atem und Rückstoß). Plündere ihn in einer Gruppe, nicht in einem Schlachtzug: Das Blut fällt immer.",
		["Mosshoof Coursers (level 52-53, not elite) graze all over {zone:1447}, thickest north-east of {npc:8405} and south of the mountains; about one in three drops a {item:20027}, so plan on a dozen kills for four. They enrage at 30% health: finish them fast. Killing them costs no Cenarion Circle reputation. Keep any {item:7972} you loot."] = "Mosshoof Coursers (Stufe 52-53, nicht Elite) grasen überall in {zone:1447}, am dichtesten nordöstlich von {npc:8405} und südlich der Berge; etwa jeder dritte lässt eine {item:20027} fallen, rechne also mit einem Dutzend Kills für vier. Sie toben bei 30 % Leben: Erledige sie schnell. Sie zu töten kostet keinen Ruf beim Zirkel des Cenarius. Behalte jeden {item:7972}, den du erbeutest.",
		["{npc:10922} is at the {area:2479} in southern {zone:1448}. Horde: fly to {area:1997} and ride south-east; Alliance: fly to {area:415} in {zone:1440} and ride north into {zone:1448}. She takes the blood for experience and gold. Look at the reward window before you hand in: Classic let you pick {item:19990}, {item:20006} or Woestave, and Forever's notes say that choice may be gone."] = "{npc:10922} ist im {area:2479} im Süden von {zone:1448}. Horde: Flieg nach {area:1997} und reite nach Südosten; Allianz: Flieg nach {area:415} in {zone:1440} und reite nach Norden in {zone:1448}. Sie nimmt das Blut gegen Erfahrung und Gold. Sieh dir das Belohnungsfenster an, bevor du abgibst: In Classic konntest du {item:19990}, {item:20006} oder Woestave wählen, und Forevers Hinweise besagen, dass diese Wahl entfallen sein könnte.",
		["{npc:8405}, a furbolg, lives on the clifftop north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}. Ride east and leave the road at the fork before the ruins, then follow the northern cliff edge east to him: the naga ruins and the beach below are walled in by cliffs with no way up."] = "{npc:8405}, ein Furbolg, lebt auf der Klippe nordöstlich von {area:1221}. Allianz: Flieg nach {area:3137}; Horde: Flieg nach {area:1237}. Reite nach Osten und verlasse die Straße an der Gabelung vor den Ruinen, folge dann dem nördlichen Klippenrand nach Osten bis zu ihm: Die Naga-Ruinen und der Strand darunter sind von Klippen umschlossen, ohne Weg nach oben.",
		["{quest:8257}: the {area:1417} entrance"] = "{quest:8257}: Eingang zum {area:1417}",
} end)()
t.guides["forever/class/priest/confounding-flash-and-contingency-plan"] = (function() return {
