t.guides["forever/class/priest/priest-robes-alliance"] = (function() return {
		["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Ein kostenloses ungewöhnliches Gewand mit 5: Heile und stärke eine verwundete Wache in der Nähe deiner ersten Stadt.",
		["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Mit 5 schickt dich {npc:3595}, die Priesterlehrerin auf der zweiten Ebene von {area:256}, dem großen Baum in {area:188}, zu {npc:3600} in {area:186}. Lerne bei ihr {spell:613} (Rang 2), solange du hier bist: Der Rang ist ab Stufe 4 für 1 Silber erhältlich, und die nächste Quest braucht genau diesen Rang.",
		["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Mit 5 schickt dich {npc:375}, die Priesterlehrerin in {area:24}, zu {npc:377} in {area:87}. Lerne bei Anetta {spell:613} (Rang 2), solange du hier bist: Der Rang ist ab Stufe 4 für 1 Silber erhältlich, und die nächste Quest braucht genau diesen Rang.",
		["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Mit 5 schickt dich {npc:837}, der Priesterlehrer in {area:77} in {area:132}, zu {npc:1226} in {area:131}. Lerne bei ihm {spell:613} (Rang 2), solange du hier bist: Der Rang ist ab Stufe 4 für 1 Silber erhältlich, und die nächste Quest braucht genau diesen Rang.",
		["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "Zurück am Nordrand von {area:186}: {npc:3600} gibt dir {item:16604}.",
		["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "Zurück in der {area:2102}: {npc:1226} gibt dir {item:16605}.",
		["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "Zurück nach oben im Lion's Pride Inn: Josetta gibt dir {item:16605}.",
		["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "Folge der Straße nach Süden aus {area:9} nach {area:87}. {npc:377} ist oben im Lion's Pride Inn.",
		["Heal and fortify {npc:12423}"] = "Heile und stärke {npc:12423}",
		["Heal and fortify {npc:12427}"] = "Heile und stärke {npc:12427}",
		["Heal and fortify {npc:12429}"] = "Heile und stärke {npc:12429}",
		["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "Verlasse {area:188} über die Rampe und folge der Straße nach Südwesten nach {area:186}. {npc:3600} ist im Gebäude am Nordrand des Dorfes.",
		["Priest Robes at 5 (Alliance)"] = "Priestergewänder mit 5 (Allianz)",
		["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "Nimm den Tunnel nach Nordosten aus {area:132} und folge der Straße nach Osten nach {area:131}. {npc:1226} ist in der {area:2102}.",
		["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423} kniet an einem Baum am Seeufer östlich von {area:87}, abseits der Straße: Geh am Ufer entlang, die Minikarte zeigt ihn von der Straße aus nicht. Wirke zuerst {spell:613} (Rang 2) auf ihn, dann {spell:1243}. Rang 1 von {spell:613} zählt nicht; zieh Rang 2 aus dem Zauberbuch auf deine Leiste (oder wirke beide aus dem Zauberbuch, falls ein Aktionsleisten-Addon stört). Er geht weg, sobald beide wirken, und ist nach etwa 3 Minuten zurück.",
		["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427} kniet auf einem Kamm zwischen zwei niedrigen Mauern, südlich von {area:131}, gegenüber dem Lehrer für Jägerbegleiter auf der anderen Straßenseite: Wenn die Straße bergab zu führen beginnt, bist du an ihm vorbei. Wirke zuerst {spell:613} (Rang 2) auf ihn, dann {spell:1243}; er spricht nach jedem Zauber. Rang 1 von {spell:613} zählt nicht.",
		["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429} kniet auf den Felsen am Rand von {area:259}, etwa 100 Yards südlich von {area:186}, ohne Questzeichen über sich. Wirke zuerst {spell:613} (Rang 2) auf sie, dann {spell:1243}; sie rennt in Richtung See davon, sobald beide wirken, und ist nach etwa 5 Minuten zurück. Rang 1 von {spell:613} zählt nicht.",
		["{spell:613} (Rank 2), if Anetta did not teach it yet"] = "{spell:613} (Rang 2), falls Anetta ihn dir noch nicht beigebracht hat",
		["{spell:613} (Rank 2), if {npc:3595} did not teach it yet"] = "{spell:613} (Rang 2), falls {npc:3595} ihn dir noch nicht beigebracht hat",
		["{spell:613} (Rank 2), if {npc:837} did not teach it yet"] = "{spell:613} (Rang 2), falls {npc:837} ihn dir noch nicht beigebracht hat",
} end)()
t.guides["forever/class/priest/priest-robes-horde"] = (function() return {
		["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Ein kostenloses ungewöhnliches Gewand mit 5: Heile und stärke eine verwundete Wache in der Nähe deiner ersten Stadt.",
		["At 5, {npc:2123}, the priest trainer in the chapel of {area:154}, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Mit 5 schickt dich {npc:2123}, der Priesterlehrer in der Kapelle von {area:154}, zu {npc:2129} in {area:159}. Lerne bei ihm {spell:613} (Rang 2), solange du hier bist: Der Rang ist ab Stufe 4 für 1 Silber erhältlich, und die nächste Quest braucht genau diesen Rang.",
		["At 5, {npc:3707}, the priest trainer in the Den in the middle of the {area:363}, sends you to {npc:3706} in {area:362}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Mit 5 schickt dich {npc:3707}, der Priesterlehrer in der Höhle mitten im {area:363}, zu {npc:3706} in {area:362}. Lerne bei ihm {spell:613} (Rang 2), solange du hier bist: Der Rang ist ab Stufe 4 für 1 Silber erhältlich, und die nächste Quest braucht genau diesen Rang.",
		["Back in the {area:362} barracks: {npc:3706} gives you the {item:16606}."] = "Zurück in der Kaserne von {area:362}: {npc:3706} gibt dir {item:16606}.",
		["Back upstairs in the {area:159} inn: Beryl gives you the {item:16607}."] = "Zurück oben im Gasthaus von {area:159}: Beryl gibt dir {item:16607}.",
		["Follow the road east out of {area:154} to {area:159}. {npc:2129} is upstairs in the inn, {area:2119}."] = "Folge der Straße nach Osten aus {area:154} nach {area:159}. {npc:2129} ist oben im Gasthaus, {area:2119}.",
		["Follow the road out of the {area:363} north-east to {area:362}. {npc:3706} is inside the barracks, the first building on the right as you come into town."] = "Folge der Straße aus dem {area:363} nach Nordosten nach {area:362}. {npc:3706} ist in der Kaserne, dem ersten Gebäude rechts, wenn du in die Stadt kommst.",
		["Heal and fortify {npc:12428}"] = "Heile und stärke {npc:12428}",
		["Heal and fortify {npc:12430}"] = "Heile und stärke {npc:12430}",
		["Priest Robes at 5 (Horde)"] = "Priestergewänder mit 5 (Horde)",
		["{npc:12428} kneels, half-dead, beside the north gate of {area:159}'s graveyard, a short walk north of the inn. Cast {spell:613} (Rank 2) on him first, then {spell:1243}: Fortitude first does not count, nor does Rank 1 of {spell:613}. If an addon gets in the way, cast both from the spellbook."] = "{npc:12428} kniet halbtot neben dem Nordtor des Friedhofs von {area:159}, ein kurzes Stück nördlich des Gasthauses. Wirke zuerst {spell:613} (Rang 2) auf ihn, dann {spell:1243}: Zuerst Seelenstärke zählt nicht, ebenso wenig Rang 1 von {spell:613}. Wenn ein Addon stört, wirke beide aus dem Zauberbuch.",
		["{npc:12430} kneels behind a group of rocks just off the road, a short walk south of {area:362}. Cast {spell:613} (Rank 2) on her first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes."] = "{npc:12430} kniet hinter einer Felsgruppe direkt an der Straße, ein kurzes Stück südlich von {area:362}. Wirke zuerst {spell:613} (Rang 2) auf sie, dann {spell:1243}. Rang 1 von {spell:613} zählt nicht; zieh Rang 2 aus dem Zauberbuch auf deine Leiste. Sie geht weg, sobald beide wirken, und ist nach etwa 5 Minuten zurück.",
		["{spell:613} (Rank 2), if Duesten did not teach it yet"] = "{spell:613} (Rang 2), falls Duesten ihn dir noch nicht beigebracht hat",
		["{spell:613} (Rank 2), if {npc:3707} did not teach it yet"] = "{spell:613} (Rang 2), falls {npc:3707} ihn dir noch nicht beigebracht hat",
} end)()
t.guides["forever/class/priest/starshards-and-elunes-grace"] = (function() return {
		["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Mit 10 gibt dir in {zone:1426} {npc:1226}, der Priesterlehrer in der {area:2102} in {area:131}, {quest:5628}, einen Brief für {npc:11401} in {zone:1457}.",
		["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Mit 10 gibt dir in {zone:1429} {npc:377}, oben im Lion's Pride Inn in {area:87}, {quest:5628}, einen Brief für {npc:11401} in {zone:1457}.",
		["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Mit 10 gibt dir in {zone:1453} {npc:5489} am Altar der Kathedrale des Lichts {quest:5628}, einen Brief für {npc:11401} in {zone:1457}. {npc:11397} im Park hat denselben Brief.",
		["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Mit 10 gibt dir in {zone:1455} {npc:5142} im {object:32386} ({object:32362}) {quest:5628}, einen Brief für {npc:11401} in {zone:1457}.",
		["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "Geh mit 10 zu {npc:11401} auf dem oberen Balkon des Tempels des Mondes am Südende von {zone:1457}: Nimm die Rampe von der Tempelhalle nach oben; sie steht neben {npc:7999}. {quest:5627} wird gegeben und sofort zurückgenommen und bringt dir {spell:10797} bei. Kein Brief nötig. Forever hat {spell:10797} deutlich stärker gemacht, bei 30 Sekunden Abklingzeit.",
		["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "Mit 10 gibt dir {npc:3600}, die Priesterlehrerin im Gebäude am Nordrand von {area:186}, {quest:5628}, einen Brief für {npc:11401} in {zone:1457}. {area:186} liegt an der Straße nach Westen zu {zone:1457}.",
		["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Mit 20 gibt dir in {zone:1453} {npc:376} am Altar der Kathedrale des Lichts einen Brief {spell:2651} für {npc:11401} in {zone:1457}. {npc:11397} im Park hat denselben Brief.",
		["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "Mit 20 gibt dir in {zone:1455} {npc:11406} im {object:32386} ({object:32362}) einen Brief {spell:2651} für {npc:11401} in {zone:1457}.",
		["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "Mit 20 bringt dir {npc:11401} auf dem oberen Balkon des Tempels des Mondes, neben {npc:7999}, {quest:5672} mit einer Quest bei, die sie dir gibt und sofort zurücknimmt. In Forever halbiert {quest:5672} 15 Sekunden lang die Chance, dass Nah- und Fernkampfangriffe dich treffen, oder bis drei Angriffe danebengehen.",
		["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Gib Laurenas Brief bei {npc:11401} ab, auf dem oberen Balkon des Tempels des Mondes in {zone:1457}, neben {npc:7999}: das Boot von {area:17203} (oder {area:150}) nach {area:442}, das Boot weiter nach {area:702}, dann das Portal hinauf nach {zone:1457}.",
		["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Gib Naras Brief bei {npc:11401} ab, auf dem oberen Balkon des Tempels des Mondes in {zone:1457}, neben {npc:7999}: das Boot von {area:17203} (oder {area:150}) nach {area:442}, das Boot weiter nach {area:702}, dann das Portal hinauf nach {zone:1457}.",
		["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Gib Rohans Brief bei {npc:11401} ab, auf dem oberen Balkon des Tempels des Mondes in {zone:1457}, neben {npc:7999}: das Boot von {area:17203} (oder {area:150}) nach {area:442}, das Boot weiter nach {area:702}, dann das Portal hinauf nach {zone:1457}.",
		["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "Nimm die Straße nach Westen von {area:186} nach {zone:1457} und geh hinauf auf den oberen Balkon des Tempels des Mondes, neben {npc:7999}: {npc:11401} nimmt {quest:5629} entgegen und bringt dir {spell:10797} bei.",
		["The Night Elf priest spells: {spell:10797} at 10, {spell:2651} at 20. Free, no objectives."] = "Die Priesterzauber der Nachtelfen: {spell:10797} mit 10, {spell:2651} mit 20. Kostenlos, keine Ziele.",
		["{npc:11406}: take his {spell:2651} letter"] = "{npc:11406}: Nimm seinen Brief {spell:2651} an",
