t.guides["forever/class/priest/touch-of-weakness-and-dark-sacrifice"] = (function() return {
		["At 10 in {zone:1411}, {npc:3706}, the priest trainer inside the barracks of {area:362}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Mit 10 gibt dir in {zone:1411} {npc:3706}, der Priesterlehrer in der Kaserne von {area:362}, einen Brief {spell:2652} für {npc:4606} in der {zone:1458}.",
		["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Mit 10 gibt dir in {zone:1412} {npc:11407}, südwestlich von {area:222}, einen Brief {spell:2652} für {npc:4606} in der {zone:1458}.",
		["At 10 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}. The zeppelin to {zone:1420} leaves from the tower outside {zone:1454}'s front gate."] = "Mit 10 gibt dir in {zone:1454} {npc:6018} im {object:172961} einen Brief {spell:2652} für {npc:4606} in der {zone:1458}. Der Zeppelin nach {zone:1420} startet am Turm vor dem Haupttor von {zone:1454}.",
		["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Mit 10 gibt dir in {zone:1456} {npc:3044}, der Priesterlehrer in der Höhle unter {area:1640}, einen Brief {spell:2652} für {npc:4606} in der {zone:1458}.",
		["At 10, go to {npc:4606}, the priest trainer in the {zone:1458}'s {object:36070}: she gives {quest:5658} and takes it back at once. No letter needed. From {area:159}, follow the road south to the ruined city of Lordaeron; the {zone:1458}'s lifts are at the back of the throne room. {quest:5658} strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes."] = "Geh mit 10 zu {npc:4606}, der Priesterlehrerin im {object:36070} der {zone:1458}: Sie gibt dir {quest:5658} und nimmt sie sofort zurück. Kein Brief nötig. Von {area:159} aus folgst du der Straße nach Süden zur zerstörten Stadt Lordaeron; die Aufzüge der {zone:1458} liegen hinten im Thronsaal. {quest:5658} trifft den nächsten Nahkampfangreifer mit Schattenschaden und senkt seine Nahkampf-Angriffskraft für 2 Minuten.",
		["At 20 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "Mit 20 gibt dir in {zone:1454} {npc:6018} im {object:172961} einen Brief {quest:5644} für {npc:4606} in der {zone:1458}.",
		["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "Mit 20 gibt dir in {zone:1456} {npc:3044} in der Höhle unter {area:1640} einen Brief {quest:5644} für {npc:4606} in der {zone:1458}.",
		["At 20, {npc:4606} in the {object:36070} teaches {quest:5644} with a quest she gives and takes back at once (its text still speaks of {spell:2944}, which every priest now learns from the trainer)."] = "Mit 20 bringt dir {npc:4606} im {object:36070} {quest:5644} mit einer Quest bei, die sie dir gibt und sofort zurücknimmt (ihr Text spricht noch von {spell:2944}, das jetzt jeder Priester beim Lehrer lernt).",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}, a short walk from the {zone:1458}."] = "Gib den Brief bei {npc:4606} im {object:36070} der {zone:1458} ab: Der Zeppelin vom Turm vor {zone:1454} landet in {zone:1420}, ein kurzes Stück von der {zone:1458} entfernt.",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}."] = "Gib den Brief bei {npc:4606} im {object:36070} der {zone:1458} ab: Der Zeppelin vom Turm vor {zone:1454} landet in {zone:1420}.",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: travel to {zone:1454} and take the zeppelin to {zone:1420}."] = "Gib den Brief bei {npc:4606} im {object:36070} der {zone:1458} ab: Reise nach {zone:1454} und nimm den Zeppelin nach {zone:1420}.",
		["The Undead priest spells: {spell:2652} at 10, {quest:5644} (new in Forever) at 20. Free, no objectives."] = "Die Priesterzauber der Untoten: {spell:2652} mit 10, {quest:5644} (neu in Forever) mit 20. Kostenlos, keine Ziele.",
		["{npc:11407}: take the {spell:2652} letter"] = "{npc:11407}: Nimm den Brief {spell:2652} an",
		["{npc:3044}: take his {quest:5644} letter"] = "{npc:3044}: Nimm seinen Brief {quest:5644} an",
		["{npc:3044}: take his {spell:2652} letter"] = "{npc:3044}: Nimm seinen Brief {spell:2652} an",
		["{npc:3706}: take his {spell:2652} letter"] = "{npc:3706}: Nimm seinen Brief {spell:2652} an",
		["{npc:6018}: take his {quest:5644} letter"] = "{npc:6018}: Nimm seinen Brief {quest:5644} an",
		["{npc:6018}: take his {spell:2652} letter"] = "{npc:6018}: Nimm seinen Brief {spell:2652} an",
		["{quest:5644}: {npc:3044}'s letter"] = "{quest:5644}: der Brief von {npc:3044}",
		["{quest:5646}: {npc:6018}'s letter"] = "{quest:5646}: der Brief von {npc:6018}",
		["{quest:5660}: {npc:3706}'s letter"] = "{quest:5660}: der Brief von {npc:3706}",
		["{quest:5661}: {npc:11407}'s letter"] = "{quest:5661}: der Brief von {npc:11407}",
		["{quest:5662}: {npc:6018}'s letter"] = "{quest:5662}: der Brief von {npc:6018}",
		["{quest:5663}: {npc:3044}'s letter"] = "{quest:5663}: der Brief von {npc:3044}",
		["{spell:2652} and {quest:5644}"] = "{spell:2652} und {quest:5644}",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-alliance"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Ein Dolch auf Stufe 10 aus den Schurkenquests deiner Heimatstadt.",
		["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "Auf Stufe 10 schickt dich {npc:1234}, der Schurkenlehrer in der {area:2102} in {area:131}, zu {npc:5165} in {zone:1455}.",
		["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "Mit 10 gibt dir {npc:3599}, der Schurkenlehrer im Gasthaus von {area:186}, eine Rose für {npc:4163} in {zone:1457}. Wenn du die Rose verlierst, brich die Quest ab und nimm sie erneut an.",
		["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "Mit 10 gibt dir {npc:917}, der Schurkenlehrer oben im Lion's Pride Inn in {area:87}, ein Paket für {npc:332} in {zone:1453}. Lerne {spell:921}, falls du es noch nicht kannst: Diese Questreihe braucht es.",
		["Back to Mathias Shaw"] = "Zurück zu Mathias Shaw",
		["Back to {npc:4163}"] = "Zurück zu {npc:4163}",
		["Back to {npc:5165}"] = "Zurück zu {npc:5165}",
		["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "Geh nach Norden nach {zone:1453}. Shaw steht oben im SI:7-Gebäude in {object:2100} (die Quest sagt Kaserne; gemeint ist SI:7).",
		["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "Geh nach Westen nach {area:133}. Neben der Straße zu seinem Eingang steht ein hölzerner Wendelturm: {npc:6886} wartet getarnt auf der obersten Plattform, neben einem {npc:1211} der Stufe 10, sodass du ihn erst aus der Nähe siehst.",
		["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "Geh nach Westen nach {zone:1457}. {npc:4163} ist unter der Erde in der {area:1658}: Der Weg nach unten ist die Öffnung am Fuß des gespaltenen Baums links vom Baum des Erzdruiden, in der Nähe des Nachtsäbler-Lehrers. Ihre Kartenmarkierung erscheint über der Erde.",
		["Pick Pocket Sethir the Ancient for {item:7737}"] = "Bestiehl Sethir the Ancient und erhalte {item:7737}",
		["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "Der {npc:6846} (Stufe 10, ein Goblin) arbeitet im Dockhaus bei {area:797}, am Fluss am südlichen Rand von Elwynn, südlich von {area:87}. Schleiche dich hinein und wende {spell:921} von hinten an ihm an: Der Zeitplan fällt nie von seiner Leiche. Beginne nicht mit {spell:2070} oder einem Kampf: Er ruft drei Wellen Leibwächter. Halte dich von den Kaminen im Haus fern; sie brennen dich aus der Tarnung. Er ist 2 bis 5 Minuten nach einem Tod zurück.",
		["{item:7298} (Alliance)"] = "{item:7298} (Allianz)",
		["{npc:332}, SI:7"] = "{npc:332}, SI:7",
		["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165} ist im {object:32383}, dem Schurkenviertel im Norden von {zone:1455}: Geh in das Gebäude mit einem zwielichtigen Händler davor und die Treppe hinunter.",
		["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909} (Satyr der Stufe 12) lebt draußen auf einem großen Ast nördlich von {area:264}: Geh durch die V-förmige Lücke in der Wand nördlich der Lichtung und hinaus auf den Ast. Stiehl ihm das Tagebuch per Taschendiebstahl; ihn zu töten bringt es nicht, und ein Kampf ruft drei Minions of Sethir herbei. Er läuft zwischen dem Hauptast und einem Seitenast hin und her: Warte getarnt am äußersten Ende des Hauptasts und bestiehl ihn von hinten, wenn er zurückkommt. Dann verschwinde mit {spell:2983}. Er ist 8 1/2 Minuten nach einem Tod zurück.",
		["{spell:921} the {npc:6846} for the {item:7675}"] = "{spell:921} beim {npc:6846} für {item:7675}",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-horde"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Ein Dolch mit Stufe 10 aus den Schurkenquests deiner Heimatstadt.",
		["At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "Mit 10 schickt dich {npc:2130}, die Schurkenlehrerin oben in der {area:2119} in {area:159}, zu {quest:1885} in der {zone:1458}.",
		["At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}. It is only a pointer: an Orc already in {zone:1454} can skip it and take {quest:1963} from {quest:1859} straight away."] = "Mit 10 schickt dich {npc:3170}, der Schurkenlehrer in {area:362}, zu {quest:1859} in {zone:1454}. Es ist nur ein Hinweis: Ein Orc, der schon in {zone:1454} ist, kann ihn überspringen und {quest:1963} direkt von {quest:1859} annehmen.",
		["Back to {npc:6446}"] = "Zurück zu {npc:6446}",
		["Back to {npc:6467}"] = "Zurück zu {npc:6467}",
		["Pick Pocket Gamon for {item:7208}"] = "Bestiehl Gamon und erhalte {item:7208}",
		["The {object:36073}"] = "{object:36073}",
		["{item:7209}, once you have the key"] = "{item:7209}, sobald du den Schlüssel hast",
		["{item:7295}, from the satchel"] = "{item:7295}, aus der Tasche",
		["{item:7298} (Horde)"] = "{item:7298} (Horde)",
		["{npc:6446}'s reward"] = "Belohnung von {npc:6446}",
		["{npc:6467} and {npc:2425}"] = "{npc:6467} und {npc:2425}",
		["{npc:6467} sends the ledger on to {npc:2425}, the big demon in the middle of the Hall of the Dark Lady in the {object:36126}, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from {npc:6522}'s bookshelf."] = "{npc:6467} schickt das Hauptbuch weiter an {npc:2425}, den großen Dämon mitten in der Hall of the Dark Lady im {object:36126}, vorbei an seinen Elite-Wachen; der Weg hinein ist der Gang vom Apothekarium aus. Wenn du das Hauptbuch verlierst, nimm ein anderes aus dem Regal von {npc:6522}.",
		["{npc:6494} (level 13, not elite) is a troll pirate on the {area:391} south of {area:392}: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again."] = "{npc:6494} (Stufe 13, nicht Elite) ist ein Troll-Pirat an der {area:391} südlich von {area:392}: Er läuft auf dem eingezäunten Hügelpfad zwischen dem unteren Piratenlager am gestrandeten Schiff und dem oberen Lager an einem großen Baum. Kämpfe am Fuß des Hügels gegen ihn, abseits der Lager. Er lässt seine Tasche immer fallen und ist 4 1/2 Minuten nach einem Tod zurück; eine Tasche pro Kill, zwei Schurken brauchen also zwei Kills. Gib die Tasche ungeöffnet ab: Wird ihr Schloss jetzt geknackt, wird sie zerstört, und du musst ihn erneut töten.",
		["{npc:6497} (level 13) walks the road between the {area:228} and the {zone:1458}, north of the {area:228}. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death."] = "{npc:6497} (Stufe 13) geht auf der Straße zwischen {area:228} und der {zone:1458} entlang, nördlich von {area:228}. Er sieht aus wie ein freundlicher Reisender ohne Questzeichen. Sprich ihn an und wähle beide seiner Antworten: Er wird feindselig. Töte ihn für den Brief (er fällt immer). Kämpfe abseits von Wachen, die den Kill übernehmen können, ohne dass Beute übrig bleibt; nur ein Schurke pro Kill erhält den Brief. Er ist 5 Minuten nach einem Tod zurück.",
		["{npc:6522} is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him."] = "{npc:6522} ist im Apothekarium, in dessen größtem Raum, wo zwei riesige Wachen eine kleine Brücke bewachen. Sein Hauptbuch liegt im Regal im Hinterzimmer hinter ihm, nicht in dem Regal an der Wand neben ihm.",
		["{quest:1859} hands the satchel back: now open it. {npc:6466} (level 12) kneels by the innkeeper in the inn in the {object:172982}; stealth up and pick his pocket for {item:7208} (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on {item:7209} in your bags. If you have trained {spell:1804}, you can pick the satchel's lock instead."] = "{quest:1859} gibt die Tasche zurück: Öffne sie jetzt. {npc:6466} (Stufe 12) kniet beim Gastwirt im Gasthaus im {object:172982}; schleiche dich heran und bestiehl ihn für {item:7208} (töte ihn nicht: Der Schlüssel fällt fast nie). Spieler töten ihn oft, du musst also bis zu 5 Minuten auf ihn warten. Benutze den Schlüssel dann an {item:7209} in deinen Taschen. Wenn du {spell:1804} gelernt hast, kannst du stattdessen das Schloss der Tasche knacken.",
		["{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10."] = "{quest:1859} steht in {object:172960}, der Schlucht unter {object:172982}. Trolle: Nehmt mit 10 {quest:1963} bei ihm an.",
		["{quest:1885} stands in the {object:36073}."] = "{quest:1885} steht in {object:36073}.",
} end)()
t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "Mit 16 schickt dich {npc:1234} in der {area:2102} in {area:131} zu {npc:5165} im {object:32383} von {zone:1455}.",
		["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "Mit 16 schickt dich {npc:3599} im Gasthaus von {area:186} zu {quest:2259} in {zone:1457}.",
		["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "Mit 16 schickt dich {npc:917}, der Schurkenlehrer oben im Lion's Pride Inn in {area:87}, zu {npc:6946} in {zone:1453}. Wenn du sie annimmst, sind die Hinweisquests der anderen Städte versperrt.",
		["Back to {npc:6966}"] = "Zurück zu {npc:6966}",
		["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "Geh nach Osten durch {zone:1429} nach Redridge oder flieg nach {area:69}. {npc:6966} steht auf einer Kiste an einem der Docks von {area:69}, südlich der Stadt; er gibt dir mit dem Auftrag {item:5060} ({npc:3090} in {area:69} verkauft mehr). {spell:1804} funktioniert nicht ohne das Werkzeug in deinen Taschen.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "Dein erster Schlossknacker-Auftrag mit Stufe 16: die Kassette von {npc:6966} bei {quest:2282}, für {quest:2300}.",
		["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214} steht in der {area:1658}. Dann das Boot von {area:702} nach {area:442} und das Boot von {area:442} nach {area:17203}.",
		["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165} ist im Haus mit dem zwielichtigen Händler davor, im {object:32383}, die Treppe hinunter. Flieg dann oder nimm {area:2257} nach {zone:1453}.",
		["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946} steht oben im Gebäude {quest:2300} in {object:2100}, hinter den Schurkenlehrern. Bevor du gehst: Wenn du {spell:1804} nicht kannst, bringt es dir {npc:13283} im Gebäude {quest:2300} bei; Schlossknacken ist die Prüfung der nächsten Quest.",
		["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282} steht östlich von {area:69}, abseits der Straße; in der Nähe streifen Schwarzfels-Orcs umher. Drinnen kommen die Practice Lockboxes fast sofort wieder: Knacke sie, bis sich {object:121264} für dich öffnet (etwa 25 Schlossknacken). Dein Schlossknacken-Limit steigt um 5 pro Stufe, ein niedriger Charakter kann also stocken. Manche Kisten sind mit Fallen versehen (zum Beispiel eine Frostfalle); die Fertigkeit steigt trotzdem. In Forever streifen Spinnen der Stufe 20 bei den Kisten umher: Räume sie zuerst oder bring einen Freund mit. Die Schließkiste enthält immer die Marke und ist zwei Sekunden nach der Benutzung wieder da. Übe weiter, solange es noch Fertigkeit bringt: Die nächste Klassenquest braucht etwa 75.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "Auf Stufe 16 schickt dich {npc:3170}, der Schurkenlehrer in {area:362}, zu {npc:3401} in {zone:1454}.",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "Auf Stufe 16 schickt dich {npc:6467} im {object:36073} zu {npc:3401} in {zone:1454}. Nimm bei ihm auch {quest:1998} an; sie wird am Ende dieses Guides in {zone:1421} erledigt.",
		["Back to {npc:6467}"] = "Zurück zu {npc:6467}",
		["Back to {npc:7161}"] = "Zurück zu {npc:7161}",
		["Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags)."] = "Flieg oder geh nach {area:392} an der Küste von {zone:1413}. {npc:7161} steht in einem kleinen Schuppen nahe der Bank, den Hügel links hinauf vor den Docks. Sein Gizmotronic Apparatus neben ihm gibt aus, was der Auftrag braucht: Nimm einen {item:7970} und {item:5060} ({spell:1804} funktioniert nicht ohne das Werkzeug in deinen Taschen).",
		["Follow the coast south from {area:392} to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of {object:123462}: it is empty, but opening it calls a giant level 50 {npc:7168} into the next room. Stay stealthed, put the {item:7970} on your action bar, target {npc:7168} and use it: the parrot shrinks to level 18. Kill it for the {item:7968}."] = "Folge der Küste südlich von {area:392} bis zum ersten gestrandeten Piratenschiff, der Tide Razor, und klettere am Bug an Bord. Auf dem Mitteldeck kommen die Buccaneer's Strongboxes schnell wieder: Knacke sie, bis dein Schlossknacken bei etwa 30 liegt (einige sind mit einer Frostnova versehen oder verwandeln dich in eine Ratte; Knacken geht auch als Ratte). Knacke weiter, solange sie noch Fertigkeit bringen: Der Giftauftrag mit 20 endet an einer Schließkiste, die etwa 75 braucht, und diese Kisten sind die nächste Übungsmöglichkeit. Geh dann hinunter in den untersten Laderaum und knacke das Schloss von {object:123462}: Sie ist leer, aber ihr Öffnen ruft einen riesigen {npc:7168} der Stufe 50 in den nächsten Raum. Bleib getarnt, lege {item:7970} auf deine Aktionsleiste, wähle {npc:7168} als Ziel und benutze ihn: Der Papagei schrumpft auf Stufe 18. Töte ihn für {item:7968}.",
		["If you have no {item:5060} left, ask {npc:6566}, the outfitter in the {object:36073}."] = "Wenn du kein {item:5060} mehr hast, frag {npc:6566}, die Ausrüsterin im {object:36073}.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and head south into Silverpine. {quest:1998} (level 16) stands alone on the old ferry dock on {area:1338}, north-east of the {area:228}. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death."] = "Nimm den Zeppelin von {zone:1454} zur {zone:1458} und geh nach Süden nach Silberwald. {quest:1998} (Stufe 16) steht allein auf dem alten Fähranleger am {area:1338}, nordöstlich von {area:228}. Sein Uppercut wirft dich zurück, kämpfe also nicht am Rand des Anlegers gegen ihn. Er lässt seinen Kopf immer fallen und ist 4 1/2 Minuten nach einem Tod zurück.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Zehn {item:7676}, das Energiegetränk der Schurken, aus den Schlossknack-Aufträgen der Horde auf Stufe 16.",
		["The Kirin Tor keep their reports in walled {area:233}, in south-east Silverpine. Facing the town hall, take the building on the right: the {object:103815} is in a corner room upstairs (any Lockpicking opens it; the {item:5060} must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time."] = "Der Kirin Tor bewahrt seine Berichte im ummauerten {area:233} im Südosten von Silberwald auf. Wenn du dem Rathaus gegenüberstehst, nimm das Gebäude rechts: {object:103815} steht oben in einem Eckzimmer (jedes Schlossknacken öffnet sie; {item:5060} muss in deinen Taschen sein). Drei Zauberwirker der Stufe 19-20 bewachen dieses Stockwerk und sehen durch Tarnung; einer läuft in den Raum mit der Truhe hinein und wieder heraus: Pass den Zeitpunkt ab oder kämpfe einzeln gegen sie.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test."] = "Untote nehmen den Zeppelin von den Türmen vor der {zone:1458} nach {zone:1411}. {npc:3401} und {quest:2379} stehen im {object:172960}, der Schlucht unter dem {object:172982}. Lerne jetzt {spell:1804} bei {npc:3401} (oder einem anderen Schurkenlehrer), falls du es nicht kannst: Dieser Auftrag ist eine Schlossknacken-Prüfung.",
		["{item:7968}: {npc:7168}, after the {item:7970}"] = "{item:7968}: {npc:7168}, nach dem {item:7970}",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} und {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: zehn {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay with the Doc targeted"] = "/lay mit dem Doc als Ziel",
		["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: the Auction House in the {object:2096}; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "Alle vier sind in {zone:1453}. {item:3421}: Bernard oder der Blumenladen von {npc:1303} am Kanal beim {object:2096}. Eine {item:3372}: viele Gemischtwaren- und Alchemiehändler ({npc:1257}, {npc:1325} und andere). Eine {item:4371}: das Auktionshaus im {object:2096}; die Ingenieurbedarfshändler haben nur eine und sind fast immer ausverkauft, und ein Ingenieur kann eine herstellen. Die {item:8431} liegt auf dem Boden neben dem linken Ende der Theke in {object:2177}, dem Schneiderladen an den Kanälen; du kannst sie nur mit dieser Quest aufheben. Wenn du die Heilung auslässt, beseitigt auch ein {item:6452} ({skill:129}) oder {spell:526} eines Druiden das {spell:9810}.",
		["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "Mit 20 schickt dich {npc:332}, oben im SI:7-Gebäude in {object:2100}, zu {npc:7024} in {zone:1436}. Mit dieser Questreihe lernst du in Forever Gifte, überspringe sie also nicht.",
		["Back to {npc:7207}"] = "Zurück zu {npc:7207}",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever bringt dir Gifte über diese Questreihe bei, nicht über den Lehrer; das Rezept {item:7676} gehört dazu.",
		["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol."] = "Hol zuerst den Schlüssel. Die {npc:7051} (Stufe 23, nicht Elite) beginnt am Turmeingang und läuft eine Runde außen herum; sie ist die mit den stacheligen Haaren, die gelbe Funken hinter sich herzieht. Schleiche dich heran und wende {spell:921} von hinten an: Sie hat den Schlüssel immer. Sie schlägt hart zu: Wenn die Tarnung bricht, verschwinde mit {spell:2983}. Achte auf das Paar Defias Drones, das ebenfalls patrouilliert.",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {spell:8681} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Geh nach Norden durch Elwynn nach {zone:1453}; Mathias Shaw ist oben im SI:7. Er bringt dir Gifte bei und gibt dir das Rezept {item:7676}. Gifte werden hergestellt, nicht gekauft: Jede Charge {spell:8681} braucht {item:2928} und {item:3371}, die {npc:1325} und {npc:1326} in {object:2100} neben dem SI:7 verkaufen. Kaufe von jedem einen Stapel, öffne Gifte in deinem Zauberbuch, um sie herzustellen, und benutze dann ein Gift auf deiner Waffe.",
		["Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like."] = "Kearnen versteckt sich getarnt an der Westseite eines großen Baums mit zwei kleinen Bäumen davor, nördlich des Defias-Turms von {npc:7053} im äußersten Osten von {zone:1436}, an der Grenze zu {zone:1431}. Lies {item:8046} für den Grundriss des Turms, wenn du magst.",
		["Klaven's journal"] = "Klavens Tagebuch",
		["Poisons (Alliance)"] = "Gifte (Allianz)",
		["Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "Schleiche den Turm hinauf. Defias Tower Patrollers (23) und Sentries (24) bewachen die Stockwerke; ein Hinterhalt mit einem Dolch tötet sie sofort, wenn du sie lieber ausschalten willst. {npc:7053}, ein Elite der Stufe 26, wartet im obersten Stockwerk: Setz ihn mit Kopfnuss außer Gefecht oder bring einen Freund mit. Die {object:123214} neben seinem Schreibtisch braucht Schlossknacken von etwa 70-75 (übe vorher an den Kisten bei {area:97} in Redridge). Ein Trick: Springe, während die Sentries weg sind, vom Stuhl auf die Lampe und auf das Bücherregal über der Truhe, tritt aus der Tarnung und öffne die Truhe von dort. Das Öffnen vergiftet dich mit {spell:9810}, was deine Tarnung eine Weile beendet und die Drohne dich sehen lässt; deshalb kommt der Schlüssel zuerst. Dann nichts wie raus.",
		["The cure's ingredients"] = "Die Zutaten für das Heilmittel",
		["The {item:7923}"] = "{item:7923}",
		["{item:4371}: the Auction House"] = "{item:4371}: das Auktionshaus",
		["{item:7908}: the {object:123214}, top floor"] = "{item:7908}: {object:123214}, oberstes Stockwerk",
		["{npc:332}: Poisons"] = "{npc:332}: Gifte",
		["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "{quest:2607} hängt noch an dir. {npc:7207} arbeitet im Keller des SI:7-Gebäudes: Die Treppe nach unten liegt unter der Treppe zum Obergeschoss, hinter {npc:1325}. Wähle ihn als Ziel und tippe /lay (nichts danach), um untersucht zu werden, und warte dann. Wenn er nichts tut, brich die Quest ab, nimm sie erneut an und warte, bis er dich bittet, dich hinzulegen.",
		["{spell:921} the {npc:7051} for the {item:7923}"] = "{spell:921} bei der {npc:7051} für {item:7923}",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/salutieren: {npc:3401}",
		["Back to {npc:3401}"] = "Zurück zu {npc:3401}",
		["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each."] = "Flieg zurück nach {zone:1454} ({area:392} oder nach Crossroads; am Turm zu sterben und den Rückweg des Geistheilers nach Crossroads zu nehmen ist schneller). Behalte danach {item:8072}. Kaufe, bevor du {area:263} verlässt, {item:2928} und Leere Phiolen bei Rekkul: Sobald Hinott dir Gifte beibringt, braucht jede Charge {spell:8681} von jedem eins.",
		["Fly to the Crossroads and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}."] = "Flieg zum Kreuzweg und geh nach Norden zum Turm der Venture Co. über dem {area:382}. Fizzule steht unter einem Baum östlich des Turms, außerhalb, und ist feindselig, bis du ein Signal gibst. Wähle ihn aus etwa 50 Yards als Ziel und feuere zweimal die {item:8051} ab, geh dann vor ihn und tippe /salute. In jeder anderen Reihenfolge greift er an. Hast du die {item:8051} verloren? Brich ab und nimm die Quest erneut bei {npc:3401} an.",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever bringt dir Gifte über diese Questreihe bei, nicht über den Lehrer; das Rezept {item:7676} gehört dazu.",
		["Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "Drinnen, Stockwerk für Stockwerk (alles kommt nach 4 1/2 Minuten wieder): Die Mutated Venture Co. Drones (Stufe 25) im Erdgeschoss sterben durch einen Hinterhalt mit einem Dolch; die Patrollers im zweiten Stockwerk verlieren durch ein {spell:1943} mit einem Punkt die Hälfte ihres Lebens, die Lookouts im offenen dritten Stockwerk durch ein {spell:2098} mit einem Punkt. {npc:7288} wartet im obersten Stockwerk: ein Elite der Stufe 23, 10 Minuten nach einem Kill zurück. Beginne mit Hinterhalt (etwa die Hälfte seines Lebens), dann {spell:1776}, {spell:5277}, ein Heiltrank und {item:7676}; mit einem Freund ist es leicht. Ein Kopf pro Kill. Knacke dann neben ihm {object:129127} für den Vorrat: Sie vergiftet dich mit {spell:9810}, was Tarnung und Beweglichkeit schwächt, bis {npc:2391} es heilt.",
		["Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back."] = "Behalte {item:8066} in deinen Taschen und benutze sie jedes Mal bei ihm, wenn du in seine Nähe kommst, sonst wird er feindselig. {npc:7287} (Stufe 22) läuft am Turm vorbei: Drück dich an die Wand, schleiche dich hinter ihn und wende {spell:921} für den Schlüssel an. Ihn zu töten bringt den Schlüssel nicht; wenn seine Taschen leer sind, töte ihn und warte 4 1/2 Minuten, bis er zurück ist.",
		["Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor"] = "Schlossknacken etwa 75: Knacke die Buccaneer's Strongboxes auf der Tide Razor",
		["Lockpicking practice"] = "Schlossknacken üben",
		["Pick Pocket Foreman Silixiz for {item:8072}"] = "Bestiehl Foreman Silixiz und erhalte {item:8072}",
		["Poisons (Horde)"] = "Gifte (Horde)",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon."] = "Nimm den Zeppelin von {zone:1454} zur {zone:1458} und folge der Straße nach Süden durch {zone:1421} nach {area:287}, bis {area:272}. {npc:2391} arbeitet im Gebäude neben der Flugroute, neben {npc:2216}, einem Wagen vor der Tür. Wenn du die Probe von Zanzils Gebräu verloren hast, brich ab und nimm die Quest erneut bei {npc:3401} an. Bleib etwa eine Minute bei ihm, während er das Heilmittel braut; wenn es nie fertig wird, brich ab und nimm die Quest erneut bei ihm an. Öffne dann Gifte in deinem Zauberbuch, um aus Rekkuls Staub und Phiolen {spell:8681} herzustellen, und benutze es auf deiner Waffe.",
		["The Venture Co. tower"] = "Der Turm der Venture Co.",
		["Tide Razor"] = "Tide Razor",
		["Wait for the cure"] = "Warte auf das Heilmittel",
		["{item:8051}, twice, at Fizzule"] = "{item:8051}, zweimal, auf Fizzule",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (Elite)",
		["{item:8095}: clears the {spell:9810}"] = "{item:8095}: entfernt {spell:9810}",
		["{npc:2391}: Poisons"] = "{npc:2391}: Gifte",
		["{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya."] = "{npc:3401} steht im {object:172960}, der Schlucht unter dem {object:172982}. Nimm die Quest an und warte: Er spricht drei Zeilen und salutiert dir. Wähle ihn nach seiner dritten Zeile als Ziel und tippe /salute. Wenn es nicht zählt, brich die Quest ab und nimm sie erneut an. Der Turmauftrag danach dreht sich um Hinterhalt, der einen Dolch braucht: Wenn du keinen hast, verkauft Kareth, der Klingenhändler im {object:172960}, eine Jambiya.",
		["{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level."] = "{object:129127} am Ende des Turmauftrags braucht Schlossknacken von etwa 70-75. Lerne {spell:1804} bei Gest oder {npc:3401} im {object:172960}, falls du es nicht kannst, trage {item:5060} bei dir und knacke die Buccaneer's Strongboxes auf dem Mitteldeck der Tide Razor, dem gestrandeten Piratenschiff südlich von {area:392}: Sie kommen schnell wieder. Dein Limit steigt um 5 pro Stufe.",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: Behalte {item:8051}",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 any capital's rogue trainer ({npc:332} or {npc:918} in {zone:1453}, Gest or Ormok in {zone:1454}, and the others) has an {item:17126} from {npc:13936} for you: ask for it in their talk window. Open it: the quest gives you the {item:17125} for {npc:6707}. Learn {spell:1846} from your trainer first if you have not; the way in is a test of it."] = "Mit 24 hat der Schurkenlehrer jeder Hauptstadt ({npc:332} oder {npc:918} in {zone:1453}, Gest oder Ormok in {zone:1454} und die anderen) einen {item:17126} von {npc:13936} für dich: Frag in ihrem Gesprächsfenster danach. Öffne ihn: Die Quest gibt dir {item:17125} für {npc:6707}. Lerne vorher {spell:1846} bei deinem Lehrer, falls noch nicht geschehen; der Weg hinein ist eine Prüfung darin.",
		["Back to {npc:13085}"] = "Zurück zu {npc:13085}",
		["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "Zurück zu {npc:13085}; der Bericht schickt dich den Erbstücken der Perenolde nach. Zwei Türme stehen zwischen den {area:281}, mitten im {zone:1416}, von Ogern gehalten: Der Schild liegt im nördlichen Turm, das Schwert im südlichen, den Elite-Oger umringen und aus der Ferne beobachten. Bleib getarnt; drinnen bewacht nichts die Erbstücke.",
		["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "Falconcrests Männer machen die Übergabe am Südende von {area:1057}, der alten Mauer zwischen Arathi und {area:287}. Töte die beiden, die die Kiste bewachen, und nimm {item:275882}. Behalte {item:275706}: {npc:13085} will sie mit der Lieferung zurück.",
		["Horde fly to {area:272}, Alliance to {area:271}. The trail to the manor is hard to see: it starts behind the plateau north of {area:275}, east of {area:272}, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast {spell:1846} near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies {area:3486}: {npc:6707} is upstairs inside. Do not attack anyone at the manor: it costs {npc:13936} reputation."] = "Die Horde fliegt nach {area:272}, die Allianz nach {area:271}. Der Pfad zum Anwesen ist schwer zu erkennen: Er beginnt hinter dem Plateau nördlich von {area:275}, östlich von {area:272}, führt in die Hügel und knickt zweimal ab zu einem kleinen Tunnel. Im Tunnel steht eine Truhe: Öffne sie nicht. Wirke {spell:1846} in ihrer Nähe und geh dicht heran; das ist der Rite of Cunning (er kommt nach 5 Minuten wieder). Das Öffnen der Truhe ruft Milton, einen Elite-Schurken der Stufe 32. Hinter dem Tunnel liegt {area:3486}: {npc:6707} ist oben im Inneren. Greife im Anwesen niemanden an: Das kostet Ruf bei {npc:13936}.",
		["In your mid 30s {npc:13085} has two more jobs; take both. Barton leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row."] = "In deinen mittleren 30ern hat {npc:13085} zwei weitere Aufträge; nimm beide an. Barton führt einen Spähtrupp des Syndikats in {area:280} an, im Osten des {zone:1416}, in einem der Häuser, mit getarnten Syndikatsleuten um sich. Bestiehl ihn für den Bericht und töte ihn nicht: Er lässt ihn nicht fallen. Wenn du eine niedrigere Stufe hast als er, sieht er durch Tarnung; Meister der Täuschung hilft, oder lenke ihn ab, verschwinde und komm von hinten. {spell:921} kann mehrmals hintereinander fehlschlagen.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and {npc:13085}'s jobs against the Syndicate."] = "Öffnet {area:3486}, das versteckte Schurkenhaus in den Hügeln von Alterac, und die Aufträge von {npc:13085} gegen das Syndikat.",
		["Pick Pocket Barton for {item:275482}"] = "Bestiehl Barton und erhalte {item:275482}",
		["Pick Pocket Syndicate members for {quest:6701}"] = "Bestiehl Mitglieder des Syndikats für {quest:6701}",
		["Rite of Cunning: {spell:1846} beside the tunnel chest"] = "Rite of Cunning: {spell:1846} neben der Truhe im Tunnel",
		["She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the {item:275709}. If it is already open, wait for it to come back."] = "Sie redet nicht ohne etwas zum Verhandeln. Ihr Versteck liegt oben in einem Haus nahe der Festung: Nimm {item:275709}. Wenn es schon geöffnet ist, warte, bis es wieder da ist.",
		["Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the {item:275706} ({quest:96784} hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with {quest:96785}. {npc:266847} is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge."] = "Die Syndicate Prowlers und Conjurors in Stromgarde sind Elite (Stufe 35-36): Ein Schurke der Stufe 36 kann an ihnen vorbeischlüpfen, aber allein gegen einen zu kämpfen ist schwer, bleib also versteckt oder bring einen Freund mit. Zieh {item:275706} an ({quest:96784} gibt sie dir an der Truhe), um als einer von ihnen durchzugehen; Tarnung oder verdächtiges Verhalten können sie brechen. Wenn dir die Truhe keine Uniform gegeben hat, gibt dir Anastasia mit {quest:96785} eine. {npc:266847} ist nicht in der Festung: Sie steht auf einem Vorsprung an der Außenseite der Burgmauer. Spring vom Dach des Hauses neben dem Vorsprung hinüber.",
		["The {item:17126}"] = "Der {item:17126}",
		["{area:324} in western Arathi is a Syndicate stronghold; to get in you need a uniform. {area:313}, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the {object:656157} there and take the uniform; that ends {quest:96783}."] = "{area:324} im westlichen Arathi ist eine Festung des Syndikats; um hineinzukommen, brauchst du eine Uniform. {area:313}, im nordwestlichen Arathi, wird von Syndicate Highwaymen, Pathstalkers und Mercenaries (Stufe 30-32) gehalten: Finde dort {object:656157} und nimm die Uniform; damit endet {quest:96783}.",
		["{item:275635}, in the southern tower"] = "{item:275635}, im südlichen Turm",
		["{item:275636}, in the northern tower"] = "{item:275636}, im nördlichen Turm",
		["{item:275709}: Anastasia's Stash"] = "{item:275709}: Anastasias Versteck",
		["{npc:13085}: 70 silver, 300 {npc:13936} reputation"] = "{npc:13085}: 70 Silber, 300 Ruf bei {npc:13936}",
		["{npc:13936} reputation"] = "Ruf bei {npc:13936}",
		["{npc:266216} is inside {area:275}, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says {npc:13085}. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry {quest:6701} for the guards' repeatable reputation quest."] = "{npc:266216} ist in {area:275}, der Festung des Syndikats südlich des Anwesens; er kann an fünfzehn verschiedenen Stellen in der Festung stehen, such also. Schnell und leise, sagt {npc:13085}. Bestiehl auf dem Weg die Syndicate Rogues, Shadow Mages und Watchmen der Stufe 20-21: Sie tragen {quest:6701} für die wiederholbare Rufquest der Wachen.",
		["{npc:6766}: one emblem each time, 100 reputation"] = "{npc:6766}: ein Emblem pro Abgabe, 100 Ruf",
		["{quest:96784}: the {item:275706}"] = "{quest:96784}: {item:275706}",
} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern {zone:1447} carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. {spell:921} them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with {area:1769}, mark them At War in your reputation panel first. They cast {spell:403} and {spell:6535}, heal each other and run at low health."] = "Die Allianz fliegt nach {area:3137}, die Horde nach {area:1237}. Nur die Timbermaw Shamans der Stufe 50-51 in den Furbolg-Hügeln im Norden von {zone:1447} tragen die Tasche (die Furbolgs der Stufe 47-49 weiter südlich nicht): Etwa jeder dreißigste Kill lässt sie fallen. Bestiehl sie stattdessen mit {spell:921}, dann verlierst du keinen Ruf bei den Timbermaw; wenn du bei {area:1769} Unfreundlich oder besser bist, setze sie vorher in deinem Rufpanel auf Im Krieg. Sie wirken {spell:403} und {spell:6535}, heilen sich gegenseitig und laufen bei wenig Leben weg.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "Auf Stufe 50 hat {npc:3328} in der {object:172960} sie; ebenso {npc:4583} im {object:36073} von {zone:1458}.",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} in {zone:1455}."] = "Mit 50 hat {npc:918} in {object:2100} von {zone:1453} sie; ebenso Syurna in {zone:1457} und {npc:5165} in {zone:1455}.",
		["Back to Xylem"] = "Zurück zu Xylem",
		["Look at the reward window before you hand in: Classic offered the {item:19982}, the {item:19984} or the {item:20255}, and Forever's notes say the choice may be gone."] = "Sieh dir das Belohnungsfenster an, bevor du abgibst: Classic bot {item:19982}, {item:19984} oder {item:20255}, und Forevers Hinweise besagen, dass die Wahl entfallen sein könnte.",
		["Lord Ravenholdt"] = "Lord Ravenholdt",
		["Morphaz in the {area:1417}"] = "Morphaz im {area:1417}",
		["Morphaz, a level 52 elite green drake, lives deep in the {area:1417}: a group of five, level 50-54. The temple stands in the {area:74}; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their {spell:12533} is nature damage: nature protection potions help; poisons and {spell:2094} do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all."] = "Morphaz, ein grüner Elite-Drache der Stufe 52, lebt tief im {area:1417}: eine Gruppe aus fünf, Stufe 50-54. Der Tempel steht im {area:74}; klettere in das versunkene Gebäude, schwimm hindurch nach unten und folge dem Gang zum Portal. Horde: Flieg nach {area:75}; Allianz: Flieg nach {area:1438} und reite weiter. Er ist bei deiner Ankunft nicht da: Töte zuerst die sechs Troll-Wächter (Elite, 50-52) auf den Plattformen rund um den oberen Ring, was den Weg nach unten öffnet (die linke Rampe vom Eingang) zu {npc:5710} in der Pit of Sacrifice. Jammal'ans Tod bringt zwei Drachen hervor, Weaver und Dreamscythe; wenn beide tot sind, erscheinen Morphaz und Hazzas zusammen und kämpfen als Paar. Ihr {spell:12533} ist Naturschaden: Naturschutztränke helfen; Gifte und {spell:2094} wirken bei ihnen nicht. Der Schlüssel fällt immer. Jäger, Priester und Magier der Stufe 50 brauchen Morphaz ebenfalls: Ein Durchgang dient allen.",
		["Ravenholdt reputation"] = "Ruf bei Ravenholdt",
		["Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever."] = "Ruf bei Rabenholdt und Erfahrung mit 50; die Gegenstandswahl aus Classic könnte in Forever entfallen sein.",
		["The Forest Oozes (level 52-53, {spell:6907} up close) drop a fragment four times in five: the biggest group, seven of them, is in the {area:2497} hills of north-eastern {zone:1447}, four more south-east of {area:1237}. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear."] = "Die Forest Oozes (Stufe 52-53, aus der Nähe {spell:6907}) lassen in vier von fünf Fällen einen Splitter fallen: Die größte Gruppe, sieben von ihnen, ist in den Hügeln von {area:2497} im Nordosten von {zone:1447}, vier weitere südöstlich von {area:1237}. Bestiehl sie vor dem Kill für einen oder zwei zusätzliche Splitter. Das Töten der Mistwing Ravagers und Hippogreife, die dieselben Plätze teilen, lässt mehr Oozes erscheinen.",
		["{area:3486} hides in the hills east of {area:272}. Horde fly to {area:272}, Alliance to {area:271}. The trail starts behind the plateau north of {area:275}, climbs into the hills and runs through a small tunnel into the {zone:1416}; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you."] = "{area:3486} versteckt sich in den Hügeln östlich von {area:272}. Die Horde fliegt nach {area:272}, die Allianz nach {area:271}. Der Pfad beginnt hinter dem Plateau nördlich von {area:275}, führt in die Hügel und durch einen kleinen Tunnel in das {zone:1416}; Lord Jorach ist im Anwesen. Greife im Anwesen niemanden an: Verlorener Ruf bei Rabenholdt führt dazu, dass er sich weigert, mit dir zu sprechen.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022}: Morphaz, im Tempel",
		["{npc:8395}, camped below the cliffs just east of {area:1237}, teleports you up (dismount first); a trail leads to Xylem's tower."] = "{npc:8395}, der unter den Klippen östlich von {area:1237} lagert, teleportiert dich nach oben (steig vorher ab); ein Pfad führt zu Xylems Turm.",
		["{quest:8233} (Alliance)"] = "{quest:8233} (Allianz)",
		["{quest:8233} (Horde)"] = "{quest:8233} (Horde)",
} end)()
t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "Zurück zum toten Briefkasten",
		["C's dead drop"] = "Der tote Briefkasten von C",
		["C's next job comes by letter: once you are level 30 and have done the horn job, visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "Der nächste Auftrag von C kommt per Brief: Sobald du Stufe 30 hast und den Horn-Auftrag erledigt hast, besuche eine beliebige Hauptstadt, und der Brief von C landet im Briefkasten; erst dann bietet ihn {object:410369} nahe {area:204} an, im südlichen Silberwald direkt südlich von {area:236}. Die Questdaten nennen eine Mindeststufe von 25, aber Spieler erhalten den Brief und den Auftrag mit 30.",
		["Place the eye in the {object:410369} near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared."] = "Lege das Auge in {object:410369} bei Pyrewood. Sieh bei deinem nächsten geplanten Stadtbesuch im Briefkasten einer Hauptstadt nach dem Zahlungsbrief von C und kehre dann für die Belohnungsquest hierher zurück. Die Zahlung ist vielleicht nicht sofort da; wiederhole die Infiltration nicht nur, weil die Belohnung noch nicht erschienen ist.",
		["Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings."] = "Solo-Route: Friedhofsschlüssel, Brief in der Bibliothek, Bänke und Truhe auf dem Friedhof, dann der Reliquienschrein in der Bibliothek für das Auge. Lies den Brief vor dem Bänke-Rätsel; prüfe die Verkleidung bei jedem Flügelwechsel.",
		["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {spell:427592} from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "Das Kloster steht im äußersten Nordosten von {zone:1420}. Geh allein hinein, außerhalb jeder Gruppe. Nimm vor dem Betreten {spell:427592} aus dem Vorratsspind in den Ställen hinter dem Kloster und zieh sie an; Tarnung und verdächtige Handlungen entfernen sie, leg sie also nach jedem Flügelwechsel wieder an. Wende im Friedhof, in der Chamber of Atonement (dem ersten großen Raum), {spell:921} auf einen {npc:4293} oder Scarlet Crier an, für {item:210963}. Öffne damit in der Bibliothek die Personal Letterbox im Athenaeum und lies die Confidential Message. Sie schickt dich zurück, um dich im Friedhof auf beide Bänke zwischen den zwei Statuen zu setzen. Achte auf die Meldungen des Mechanismus und nimm dann {item:210968} aus der Steintruhe: Ein Elite steht bei der Truhe mit einer Patrouille dahinter, aber neben dem nördlichen Mausoleum kannst du die Kamera drehen, bis die Kiste sichtbar ist, und sie durch die Wand anklicken (eine Interaktionstaste funktioniert auch). Ein Elite-Geist läuft nahe dem Mausoleum; das zerbrochene Stück an seinem Rand hält dich aus seinem Weg. Kehre dann zur Bibliothek zurück, für den verschlossenen Reliquienschrein und das Auge. Vermeide es, dich durch die Instanz zu kämpfen.",
		["The {area:796}"] = "{area:796}",
		["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "Die {item:277246}, die Bezahlung von C für einen Soloauftrag im Gebiet {area:796}.",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "Zurück zum toten Briefkasten",
		["C's dead drop"] = "Cs toter Briefkasten",
		["Go in alone and use the {item:210186} at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring {item:5140} and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the {item:210213}, then the brother in the room reached by turning right at the top of the stairs for the {item:210212} (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach."] = "Geh allein hinein und benutze {item:210186} am Hoftor. Spieler berichten auch, dass ein befreiter Gefangener die Hoftür für dich öffnet: Wenn du stirbst, während er sie öffnet, bleib tot, bis sie offen ist; sie bleibt offen, sobald du freigelassen wirst. Wenn du Verschwinden kennst, bring {item:5140} mit und prüfe vor dem Betreten die Abklingzeit; halte es für einen misslungenen Anlauf bereit. Bestiehl die Schwester im Speisesaal für {item:210213}, dann den Bruder in dem Raum, den du erreichst, wenn du oben an der Treppe rechts abbiegst, für {item:210212} (ein Schurke der Stufe 20 ohne Verschwinden braucht vielleicht Ränge in Meister der Täuschung, um den zweiten ungesehen zu erreichen). Füge sie an einem sicheren Ort zusammen: Das bricht die Tarnung. Mach vorher einen Taschenplatz frei: Wenn du die Truhe mit vollen Taschen öffnest, kann der Schlüssel verbraucht werden, ohne dass du das Horn bekommst. Kehre zu den Ställen im Hof zurück und benutze den kombinierten Schlüssel an der Truhe, um das Horn zu erhalten. Halte dich von den Elites in der Nähe fern; die Mindeststufe der Quest garantiert keinen sicheren Zugang.",
		["Place the horn in the {object:410369} near Pyrewood. The payment may not appear immediately: check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for the reward quest. Do not repeat the dungeon just because the payment is not yet offered."] = "Lege das Horn in {object:410369} bei Pyrewood. Die Zahlung wird vielleicht nicht sofort angeboten: Sieh bei deinem nächsten geplanten Stadtbesuch im Briefkasten einer Hauptstadt nach dem Folgebrief von C und kehre dann für die Belohnungsquest zu dieser Truhe zurück. Wiederhole den Dungeon nicht nur, weil die Zahlung noch nicht angeboten wird.",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "{item:277210}, Cs Bezahlung für einen Soloauftrag in {area:236}.",
		["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "{object:410369} ist eine Truhe in einem Haus direkt vor {area:204} im südlichen Silberwald, südlich von {area:236}. Öffne sie und lies Cs Notiz: Der Auftrag muss allein erledigt werden, außerhalb jeder Gruppe.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, in {area:236}",
		["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon, a short way north-east of {area:460}. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and {spell:921} it; killing them does not give it."] = "{npc:4086}, ein Goblin, der beiden Fraktionen freundlich gesinnt ist, steht bei der Venture Co. im {area:461}, im Osten des Steinkrallengebirges, ein kurzes Stück nordöstlich von {area:460}. Die Horde fliegt nach {area:460}, die Allianz nach {area:467}. Er will {item:210187}, bevor er Sprengstoff herausgibt: Die Venture Co. Loggers (Stufe 18), die um ihn herum arbeiten, tragen sie in den Taschen. Schleiche dich hinter einen und wende {spell:921} an; sie zu töten bringt sie nicht.",
		["{spell:921} a {npc:3989} for a {item:210187}"] = "{spell:921} bei einem {npc:3989} für {item:210187}",
} end)()
t.guides["forever/class/shaman/call-of-air-alliance"] = (function() return {
		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "Mit 30 schickt dich {npc:258098}, der Schamanenlehrer in {zone:1455}, zu {npc:259023} in {zone:1417}. Deine Lufttotems der Stufe 30 (Erdungstotem, {spell:10596}) brauchen {item:5178}, das er dir gibt.",
		["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Fünf Twisted Air Totems. Die Maraudine-Zentauren (Stufe 36-40) nördlich und nordöstlich von {area:2408} im Westen von {zone:1443} tragen sie; die Scouts lassen bei fast jedem zweiten Kill eines fallen. Wranglers werfen Netz und Entwaffnen, Windchasers heilen, Stormers werfen {spell:9654}: Zieh einen nach dem anderen. Respawn etwa fünf Minuten.",
		["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Fünf Twisted Earth Totems. Die Lost Ones (Murlocs, Stufe 34-39) nördlich und nordöstlich von {area:75} im {zone:1435} tragen sie; die meisten rufen bei Verletzung um Hilfe.",
		["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Fünf Twisted Fire Totems. Die Stonevault-Troggs (Skullthumpers, Bonesnappers und Shamans, Stufe 37-41) südlich von {area:338} in den {zone:1418} tragen sie; die Shamans lassen Fire Nova Totems und einen {npc:3560} fallen, die Bonesnappers rufen bei Verletzung um Hilfe. Respawn etwa fünf Minuten.",
		["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Fünf Twisted Water Totems. Die Mirefin-Murlocs (Stufe 35-38) nordöstlich von {area:496} im Norden von {zone:1445} tragen sie.",
		["The steam pools"] = "Die Dampfbecken",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "Das {item:5178}, mit dem du Lufttotems aufstellst, dann eine Waffe deiner Wahl auf Stufe 40.",
		["Twisted Air Totems"] = "Verdrehte Lufttotems",
		["Twisted Earth Totems"] = "Verdrehte Erdtotems",
		["Twisted Fire Totems"] = "Verdrehte Feuertotems",
		["Twisted Water Totems"] = "Verdrehte Wassertotems",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} ist ein Dungeon für fünf Spieler am südlichen Rand von {zone:1413} (der Pfeil zeigt auf seinen Eingang); {npc:4421} (Elite der Stufe 33) ist sein letzter Boss. Sie wirkt {spell:8292}, {spell:139} auf ihre Verbündeten und Purity; {item:274463} fällt nur bei ihr.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, vom {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, von {npc:4421}",
		["{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east."] = "{npc:259023} lagert in den Hügeln westlich von {area:321}, der Horde-Stadt im Nordosten von Arathi: Hüte dich vor ihren Wachen. Flieg nach {area:320} und geh nach Nordosten.",
		["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:259023} gibt dir {item:268582}. {zone:1441} ist weit: das Boot nach Theramore und die Straße nach Westen, oder flieg nach {area:489} an der Grenze zu {zone:1444} und geh nach Osten in die Schlucht. Stelle {item:268582} an den Dampfbecken nordwestlich von {area:484} auf, um die verderbten Elementare und dann {npc:216474} herbeizurufen; Razormane-Quilboar mischen sich in den Kampf ein, während das Ritual läuft. Eine Gruppenquest: Bring mindestens einen oder zwei Freunde mit. {item:212792} fällt etwa bei jedem zweiten Kill, und jedes Gruppenmitglied kann es plündern.",
		["{npc:259023}: your {item:5178}"] = "{npc:259023}: dein {item:5178}",
		["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "{npc:6176} lagert in den Ruinen im Osten des {zone:1416}: Folge von {area:272} aus dem Fluss östlich der Stadt nach Norden in die Hügel. Wähle deine Waffe: {item:280607}, {item:280605} oder {item:280604}.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: {item:280696} und deine Waffe",
		["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789} und die Waffen des Sturms (Allianz)",
} end)()
t.guides["forever/class/shaman/call-of-air-horde"] = (function() return {
		["At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem."] = "Mit 30 bekommen Himmelsgeborene-Schamanen ihre eigene {quest:96136}. {npc:259119} wartet dort, wo das Luftschiff von Zephras Isle landet, im Norden von {zone:1412} bei {zone:1456}. Deine Lufttotems der Stufe 30 brauchen das Lufttotem, das Prate Cloudseer gibt. Wenn sie nichts für dich hat, geh hinauf zu {npc:5906} in {zone:1456} (nächster Schritt): Die {quest:96136} der Lehrer steht Himmelsgeborenen offen und gibt dasselbe Totem.",
		["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives."] = "Mit 30 schickt dich {npc:5892} im {object:172957} zu {npc:5905} in {zone:1441}. Deine Lufttotems der Stufe 30 (Erdungstotem, {spell:10596}) brauchen {item:5178}, das sie dir gibt.",
		["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1531} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "Mit 30 schickt dich {npc:5906}, ein Schamanenlehrer auf {area:1640} in {zone:1456}, zu {npc:5905} in {zone:1441}. Deine Lufttotems der Stufe 30 (Erdungstotem, {spell:10596}) brauchen das Lufttotem, das Prate gibt. Trägst du schon {quest:1531} von {npc:5892} aus {zone:1454} bei dir? Sie geht auch an {npc:5905}: Überspringe {npc:5906}.",
		["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Fünf Twisted Air Totems. Die Maraudine-Zentauren (Stufe 36-40) nördlich und nordöstlich von {area:2408} im Westen von {zone:1443} tragen sie; die Scouts lassen bei fast jedem zweiten Kill eines fallen. Wranglers werfen Netz und Entwaffnen, Windchasers heilen, Stormers werfen {spell:9654}: Zieh einen nach dem anderen. Respawn etwa fünf Minuten.",
		["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Fünf Twisted Earth Totems. Die Lost Ones (Murlocs, Stufe 34-39) nördlich und nordöstlich von {area:75} im {zone:1435} tragen sie; die meisten rufen bei Verletzung um Hilfe.",
		["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Fünf Twisted Fire Totems. Die Stonevault-Troggs (Skullthumpers, Bonesnappers und Shamans, Stufe 37-41) südlich von {area:338} in den {zone:1418} tragen sie; die Shamans lassen Fire Nova Totems und einen {npc:3560} fallen, die Bonesnappers rufen bei Verletzung um Hilfe. Respawn etwa fünf Minuten.",
		["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Fünf Twisted Water Totems. Die Mirefin-Murlocs (Stufe 35-38) nordöstlich von {area:496} im Norden von {zone:1445} tragen sie.",
		["Fly to {area:484}. {npc:5905} stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running."] = "Flieg nach {area:484}. {npc:5905} steht auf einem Felsvorsprung über einem Höhleneingang in der Canyonwand nordöstlich des Postens, nicht in der Höhle: Klettere den Hang daneben hinauf. Sie gibt dir außerdem eine Stunde schnellere Angriffe und schnelleres Laufen.",
		["The steam pools"] = "Die Dampfbecken",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "{item:5178}, mit dem du Lufttotems aufstellen kannst, dann mit 40 eine Waffe deiner Wahl.",
		["Twisted Air Totems"] = "Verdrehte Lufttotems",
		["Twisted Earth Totems"] = "Verdrehte Erdtotems",
		["Twisted Fire Totems"] = "Verdrehte Feuertotems",
		["Twisted Water Totems"] = "Verdrehte Wassertotems",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} ist ein Dungeon für fünf Spieler am südlichen Rand von {zone:1413} (der Pfeil zeigt auf seinen Eingang); {npc:4421} (Elite der Stufe 33) ist sein letzter Boss. Sie wirkt {spell:8292}, {spell:139} auf ihre Verbündeten und Purity; {item:274463} fällt nur bei ihr.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, von {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, von {npc:4421}",
		["{npc:4722} stands at {area:484}."] = "{npc:4722} steht in {area:484}.",
		["{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:5905} gibt dir {item:268582}. Stelle {item:268582} an den Dampfbecken nordwestlich von {area:484} auf, um die verderbten Elementare und dann {npc:216474} herbeizurufen; Razormane-Quilboar mischen sich in den Kampf ein, während das Ritual läuft. Eine Gruppenquest: Bring mindestens einen oder zwei Freunde mit. {item:212792} fällt etwa bei jedem zweiten Kill, und jedes Gruppenmitglied kann es plündern.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: dein {item:5178}",
		["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it."] = "{npc:6176} lagert in den Ruinen im Osten des {zone:1416}: Folge von {area:272} aus dem Fluss östlich der Stadt nach Norden in die Hügel. Wähle deine Waffe: {item:280607}, {item:280605} oder {item:280604}; der Schild {item:280696} gehört dazu.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: {item:280696} und deine Waffe",
		["{quest:1531} and the Tempest's Weapons (Horde)"] = "{quest:1531} und die Waffen des Sturms (Horde)",
} end)()
t.guides["forever/class/shaman/call-of-earth-alliance"] = (function() return {
		["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "Zurück zu Teo in {area:77}. Er gibt dir {item:6635}: Trink es noch nicht.",
		["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Bring {item:6656} zurück zu Teo in {area:77}. Behalte {item:5175} dauerhaft in deinen Taschen: Jedes Erdtotem braucht es.",
		["Iceclaw Bear Pendants"] = "Iceclaw Bear Pendants",
		["Lost the {quest:94472}?"] = "{quest:94472} verloren?",
		["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "Nur wenn {quest:94472} nicht mehr in deinen Taschen ist (abseits des Steins getrunken oder verkauft): Teo gibt dir ein neues.",
		["Teo's {quest:94373} needs the {quest:98581} handed in first: {npc:658}, where you entered {area:132}, gives it to Dwarf shamans after his {quest:179}. Bring it up the road to {npc:257446} inside {area:77}."] = "Teos {quest:94373} verlangt, dass du zuerst {quest:98581} abgibst: {npc:658}, dort, wo du {area:132} betreten hast, gibt sie Zwergen-Schamanen nach seiner {quest:179}. Bring sie die Straße hinauf zu {npc:257446} in {area:77}.",
		["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "Die Frostmane Troll Whelps (Stufe 3-4) halten die verschneiten Hänge westlich und südwestlich von {area:77}, und die Frostmane Novices (Stufe 3-4, sie werfen aus der Ferne Frostblitze) lagern südlich davon. Beide tragen die Anhänger; sie respawnen nach etwa drei Minuten.",
		["The Spirit Stone"] = "Der Geisterstein",
		["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "Der Geisterstein steht auf einem verschneiten Kamm nordwestlich von {area:77}. Der Pfad ist leicht zu übersehen: Er führt vom Talboden den Hügel hinauf; am kleinen Lager nahe der Spitze biegst du links ab, und der Stein kommt in Sicht. Stell dich neben ihn, trink {item:6635} und sprich mit {npc:5891}, bevor sie verblasst.",
		["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Dein {item:5175}: Ohne es kann kein Erdtotem gewirkt werden. {spell:8071} kommt mit Stufe 4 dazu.",
		["it hands you the {item:6656}: keep it"] = "sie gibt dir {item:6656}: Behalte ihn",
		["the level 4 shaman spells"] = "die Schamanenzauber der Stufe 4",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, neben dem Geisterstein",
		["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446} bildet Schamanen in {area:77} aus, der Halle am Südende von {area:132}. Die Quest wird mit Stufe 4 frei. Hast du sie nie angenommen und bist jetzt 10 oder höher? {npc:258098} in {zone:1455} oder {npc:258113} in {area:131} gibt dir {quest:94373}, einen Hinweis zurück zu Teo: Nimm sie für die Erfahrung auf dem Weg mit.",
		["{npc:257446}: a new {quest:94472}"] = "{npc:257446}: ein neues {quest:94472}",
		["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446}: {spell:8071} und dein {item:5175}",
		["{quest:94373} (Alliance)"] = "{quest:94373} (Allianz)",
} end)()
t.guides["forever/class/shaman/call-of-earth-horde"] = (function() return {
		["Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it."] = "Jeder Al'Aketh-Kultist kann {item:251924} tragen: die Converts (Stufe 2-3) bei den Standsteinen direkt östlich des Dorfes oder die Brutes und Neophytes (Stufe 4) im Lager hinter {npc:252095}, südwestlich des Dorfes. Töte weiter, bis einer es fallen lässt.",
		["Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet."] = "Zurück zu Boro in {area:16635}. Er gibt dir {quest:1462}: Trink es noch nicht.",
		["Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet."] = "Zurück zur Seherin in {area:221}. Sie gibt dir {quest:1462}: Trink es noch nicht.",
		["Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet."] = "Zurück zu {npc:5887} vor dem Den. Sie gibt dir {quest:1462}: Trink es noch nicht.",
		["Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Bring {item:6656} zurück zu Boro. Behalte {item:5175} dauerhaft in deinen Taschen: Jedes Erdtotem braucht es.",
		["Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Bring {item:6656} zurück zur Seherin. Behalte {item:5175} dauerhaft in deinen Taschen: Jedes Erdtotem braucht es.",
		["Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it."] = "Bring {item:6656} zurück zu {npc:5887} vor dem Den. Behalte {item:5175}, das sie dir gibt, dauerhaft in deinen Taschen: Jedes Erdtotem braucht es.",
		["Felstalker Hooves"] = "Felstalker-Hufe",
		["Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes."] = "Felstalkers (Stufe 3-4) streifen über den Hang unterhalb von {area:365}, der Höhle im Norden des Tals, und direkt hinter ihrem Eingang zwischen den Vile Familiars. Fast jeder {npc:3102} lässt einen Huf fallen (vier von fünf Kills); sie respawnen nach etwas über drei Minuten.",
		["Lost the {quest:1462}?"] = "{quest:1462} verloren?",
		["Lost the {quest:1463}?"] = "{quest:1463} verloren?",
		["Only if the {quest:1462} is gone from your bags: the Seer gives you another."] = "Nur wenn {quest:1462} nicht mehr in deinen Taschen ist: Die Seherin gibt dir ein neues.",
		["Only if the {quest:1463} is gone from your bags (drunk away from the rock, or sold): {npc:5887} gives you another."] = "Nur wenn {quest:1463} nicht mehr in deinen Taschen ist (abseits des Felsens getrunken oder verkauft): {npc:5887} gibt dir ein neues.",
		["The Bristleback Shamans (level 3-4) stand among the quilboar huts of {area:358}, east of the camp, and throw the odd {spell:403}. Four kills in five drop a salve; they respawn in about four minutes."] = "Die Bristleback Shamans (Stufe 3-4) stehen zwischen den Quilboar-Hütten von {area:358}, östlich des Lagers, und werfen gelegentlich {spell:403}. Vier von fünf Kills lassen eine Salbe fallen; sie respawnen nach etwa vier Minuten.",
		["The {area:16988}"] = "{area:16988}",
		["The {area:16988} is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the {item:6635} beside the shrine and speak to the {npc:251166} before it fades."] = "{area:16988} ist der Schrein auf der Hügelkuppe nordöstlich von Boro: Der Pfad hinauf beginnt am Hügel direkt über der Lichtung, auf der die Fliegen waren. Trink {item:6635} neben dem Schrein und sprich mit {npc:251166}, bevor sie verblasst.",
		["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Dein {item:5175}: Ohne es kann kein Erdtotem gewirkt werden. {spell:8071} kommt mit Stufe 4 dazu.",
		["it hands you the {item:6656}: keep it"] = "sie gibt dir {item:6656}: Behalte ihn",
		["the level 4 shaman spells"] = "die Schamanenzauber der Stufe 4",
		["{area:637} is a small pillar on a low mound due east of {npc:2991}'s well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the {item:6635}, then speak to the {npc:5891} before it fades (drink again if it does)."] = "{area:637} ist ein kleiner Pfeiler auf einem niedrigen Hügel genau östlich des Brunnens von {npc:2991}, östlich des Lagers; er ist erst aus etwa fünfzehn Yards Entfernung zu sehen, und feindliche Eber grasen um ihn herum. Stell dich neben ihn und trink {item:6635}, sprich dann mit {npc:5891}, bevor sie verblasst (trink erneut, falls sie es tut).",
		["{area:639} sits on a ledge in the hills just south of the Den. The {area:638} up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the {item:6635}: the {npc:5891} appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path."] = "{area:639} liegt auf einem Vorsprung in den Hügeln direkt südlich des Den. Der {area:638} hinauf beginnt am Fuß der Hügel südwestlich des Den, zwischen zwei untätigen Peons; er führt nach Südwesten in die Hügel und biegt dann zurück nach Osten zum Felsen. Stell dich direkt neben den Stein und trink {item:6635}: {npc:5891} erscheint nur kurz, sprich also sofort mit ihr (geh fast unter sie, wenn sie nicht antwortet). Auf dem Rückweg kannst du den Vorsprung in Richtung Den hinunterspringen, statt den Pfad zu gehen.",
		["{item:6635}, beside the shrine"] = "{item:6635}, neben dem Schrein",
		["{item:6635}, beside {area:637}"] = "{item:6635}, neben {area:637}",
		["{item:6635}, beside {area:639}"] = "{item:6635}, neben {area:639}",
		["{npc:251374}, the shaman trainer, stands in {area:16635}. The quest opens at level 3."] = "{npc:251374}, der Schamanenlehrer, steht in {area:16635}. Die Quest wird mit Stufe 3 frei.",
		["{npc:251374}: {spell:8071} and your {item:5175}"] = "{npc:251374}: {spell:8071} und dein {item:5175}",
		["{npc:5887} stands just outside the Den, the cave in the middle of the {area:363}. The quest opens at level 4."] = "{npc:5887} steht direkt vor dem Den, der Höhle mitten im {area:363}. Die Quest wird mit Stufe 4 frei.",
		["{npc:5887}: a new {quest:1463}"] = "{npc:5887}: ein neues {quest:1463}",
		["{npc:5887}: {spell:8071} and your {item:5175}"] = "{npc:5887}: {spell:8071} und dein {item:5175}",
		["{npc:5888} stands in {area:221}. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4."] = "{npc:5888} steht in {area:221}. Über ihrem Kopf ist vielleicht kein Questzeichen: Sprich sie trotzdem an. Die Quest wird mit Stufe 4 frei.",
		["{npc:5888}: a new {quest:1462}"] = "{npc:5888}: ein neues {quest:1462}",
		["{npc:5888}: {spell:8071} and your {item:5175}"] = "{npc:5888}: {spell:8071} und dein {item:5175}",
		["{quest:1516} (Horde)"] = "{quest:1516} (Horde)",
} end)()
t.guides["forever/class/shaman/call-of-fire-alliance"] = (function() return {
		["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "Mit 10 schickt dich {npc:258113}, der Schamanenlehrer in {area:131}, oder {npc:258098}, der Schamanenlehrer in {zone:1455}, zu {npc:257597}.",
		["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Zurück durch den Tunnel am Südtor und den Pfad hinauf zur Höhle von {npc:257597}. Behalte {item:5176} dauerhaft in deinen Taschen: Jedes Feuertotem braucht ihn.",
		["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "Geh den Pfad wieder hinauf zu {npc:257808}. Er stellt aus dem Teer und dem Beutel den {item:6636} her: Bewahre ihn bei der Fackel auf.",
		["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "Klicke oben auf dem Schrein mit der Fackel in deinen Taschen auf {object:61934}, um die Glut abzulegen, und klicke dann noch einmal darauf für die nächste Quest: die entzündete {item:277329}.",
		["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Geh an {npc:257808} vorbei weiter zum Gipfel. Trink dort neben der Steinstatue den {item:6636}, um {npc:5893} (Stufe 12) zu sehen: Er wartet, bis du angreifst, wird aber stärker, je länger man ihn lässt, und ist immun gegen Feuer. Eröffne sofort mit {spell:8017} und {spell:8042}. Seine {item:6655} fällt jedes Mal.",
		["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "Folge der Straße nach Osten zum Tunnel Richtung {area:806}. Halte dich nach dem ersten Tunnel links an {npc:1959} und dem Turm vorbei: Ein schmaler Pfad, schwer zu sehen, aber auf der Minikarte angezeigt, windet sich den Berg hinauf zur Höhle von {npc:257597} über dem Hof. Er gibt dir {item:6653}: Behalte sie bis zum Ende der Questreihe.",
		["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "Von der Felskante von {npc:257597} aus kannst du vorsichtig den Berg hinunter nach {zone:1432} springen oder durch den Tunnel zurückgehen. {npc:257808} hütet den Schrein auf dem Gipfel direkt südlich von {area:144}: Ein versteckter Pfad an einer Felskante, markiert mit Steintotems, führt von der Straße nördlich des Gipfels hinauf.",
		["Lost the {quest:94473}?"] = "{quest:94473} verloren?",
		["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "Nur wenn {quest:94473} nicht mehr in deinen Taschen ist: {npc:257808} gibt dir einen neuen.",
		["The Shrine of Eternal Flame"] = "The Shrine of Eternal Flame",
		["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "Die Stonesplinter Seers (Stufe 13-14) halten sich bei den Troggs von {area:923} im Süden des Sees auf, außerdem in den Trogglagern nordöstlich von {area:144}. Sie werfen aus 40 Metern {spell:1245113} und rufen bei Verletzung um Hilfe: Pull sie einzeln. Respawn etwa fünf Minuten.",
		["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "Die Tunnel Rat Geomancers (Stufe 12-13) arbeiten nur in der {area:149} am Nordende des Sees, hinter {area:144}. Sie wirken {spell:2136} hinter einem {spell:134} und rufen bei niedriger Gesundheit um Hilfe.",
		["The {object:61934}"] = "{object:61934}",
		["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Dein {item:5176} für jedes Feuertotem, {spell:3599} damit und Forevers {item:263412}.",
		["{item:6636}, beside the statue"] = "{item:6636}, neben der Statue",
		["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {spell:3599}, dein {item:5176} und {item:263412}",
		["{npc:257808}: a new {quest:94473}"] = "{npc:257808}: ein neuer {quest:94473}",
		["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{npc:258113}, {area:131}; oder {npc:258098}, {zone:1455}",
		["{quest:94449} (Alliance)"] = "{quest:94449} (Allianz)",
} end)()
t.guides["forever/class/shaman/call-of-fire-horde"] = (function() return {
		["At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage."] = "Mit Stufe 10 gibt dir {npc:252382}, die Schamanenlehrerin neben {npc:251968} in {area:16638}, {item:6653} ({npc:254082} bietet dieselbe Quest an). Hast du die Insel schon verlassen? {quest:97243} schickt dich zu ihnen zurück: Nimm den Himmelsschneider von den Klippen südlich von {area:17045}, nördlich von {zone:1456}. Lerne jetzt {spell:8050} bei ihr: {npc:268605} später in der Questreihe nimmt nur Feuerschaden.",
		["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "Mit Stufe 10 schickt dich {npc:3066}, der Schamanenlehrer in {area:222}, zu {npc:5907} im {zone:1413}. Trägst du schon den Brief von {npc:5906} aus {zone:1456} bei dir? Der geht auch an {npc:5907}: Überspring Narm.",
		["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "Mit Stufe 10 schickt dich {npc:3173}, der Schamanenlehrer auf der Ostseite von {area:362}, zu {npc:5907} im {zone:1413}. Trägst du schon den Brief von {npc:5892} aus {zone:1454} bei dir? Der geht auch an {npc:5907}: Überspring {npc:3173}.",
		["Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top."] = "Zurück nach Osten über die Brücke, dann südlich am {zone:1411}-Ufer des Flusses entlang, bis die Berge auf das Wasser treffen. Der Pfad hinauf beginnt am Fuß des Berges neben einem kleinen dunklen Stein mit eingeritzten Symbolen, nahe dem Stacheleber-Lager; er ist schmal, und ein Ausrutscher kostet Fallschaden. {npc:5900} hütet oben den Schrein.",
		["Back to {npc:268592} at the Shrine of Flames."] = "Zurück zu {npc:268592} am Schrein der Flammen.",
		["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "Zurück zu {npc:268592}. Nimm die letzte Quest an und warte dann bei {npc:268762}, während er das Ritual durchführt; wenn die Feuergeister {object:148418} entzünden, halte die Fackel daran. Ab dann hast du sechs Minuten: Trag die Flamme auf direktem Weg zu {npc:268679} neben {npc:252382} in {area:16638}, ohne Umwege oder Kämpfe. Zeit abgelaufen? Brich die Quest ab und nimm sie bei {npc:268592} erneut an.",
		["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "Geh den Pfad wieder hinauf zu {npc:5900}. Er stellt aus dem Teer und dem Beutel {quest:1464} her und gibt sie dir zusammen mit der Fackel: Behalte beides.",
		["Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}."] = "Klicke auf dem Plateau mit der Fackel in deinen Taschen auf {object:61934}, um die Glut abzulegen, und klicke dann ein zweites Mal darauf: Die nächste Quest öffnet sich nicht von selbst. Du erhältst die entzündete {item:277329}.",
		["Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Den Pfad hinunter, zurück über die Brücke zu {npc:5907} an seinem Turm. Behalte {item:5176} dauerhaft in deinen Taschen: Jedes Feuertotem braucht ihn.",
		["Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time."] = "Trink den {item:6636} neben {object:63674}, dem großen grauen Stein knapp unterhalb des Gipfels, und steig dann zum Plateau hinauf. Von den Feuerelementaren dort kann nur das in der Mitte angegriffen werden: Es hat Stufe 12, ist immun gegen Feuer und wird stärker, je länger der Kampf dauert. Eröffne also sofort mit {spell:8017} und {spell:8042} und lass die anderen in Ruhe. Seine {item:6655} fällt jedes Mal.",
		["Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Behalte {item:5176} dauerhaft in deinen Taschen: Jedes Feuertotem braucht ihn.",
		["Lost the {quest:1464}?"] = "{quest:1464} verloren?",
		["Only if the {quest:1464} is gone from your bags: {npc:5900} gives you another."] = "Nur wenn {quest:1464} nicht mehr in deinen Taschen ist: {npc:5900} gibt dir eine neue.",
		["The Burning Blade Cultists (level 10-11, they call imps and cast {spell:348}) live deep in {area:371} north of {area:362}: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. {area:817} by {zone:1454} is the wrong cave."] = "Die Burning Blade Cultists (Stufe 10-11, sie rufen Wichtel und wirken {spell:348}) leben tief in {area:371} nördlich von {area:362}: Steig die Rampe direkt nordöstlich der Stadt hinauf und bleib auf dem hohen Gelände über den Schluchten. Die Orcs am Höhleneingang sind keine Kultisten; die Kultisten sind weiter drinnen, links. Drei von vier Kills lassen einen Beutel fallen. {area:817} bei {zone:1454} ist die falsche Höhle.",
		["The Razormane casters north-east of the Crossroads drop the {item:5026} three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time."] = "Die Razormane-Zauberwirker nordöstlich der Crossroads lassen {item:5026} in drei von vier Fällen fallen: Water Seekers und Thornweavers (Stufe 10-11), Geomancers (Stufe 12-13, sie werfen Feuerbälle und rufen bei Verletzung um Hilfe) und Mystics (Stufe 13-14, sie heilen sich bei niedriger Gesundheit selbst). Pull sie einzeln.",
		["The Shrine of Flames hides on the island's outer rim south-west of {area:16638}, just south-east of {area:16663}: {npc:268592} keeps it."] = "Der Schrein der Flammen versteckt sich am äußeren Rand der Insel südwestlich von {area:16638}, direkt südöstlich von {area:16663}: {npc:268592} hütet ihn.",
		["The {npc:5893}"] = "{npc:5893}",
		["The {object:148418}"] = "{object:148418}",
		["The {object:61934}"] = "{object:61934}",
		["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Dein {item:5176} für jedes Feuertotem, {spell:3599} damit und Forevers {item:263412}.",
		["the ritual, then the {npc:268679} in {area:16638}"] = "das Ritual, dann {npc:268679} in {area:16638}",
		["{item:6636}, beside the {object:63674}"] = "{item:6636}, neben {object:63674}",
		["{npc:252382}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {spell:3599}, dein {item:5176} und {item:263412}",
		["{npc:268602} (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past {area:16638}, just south of the {area:16629}, on the hill west of the falls north of the {area:17675}. Kill him and take his heart."] = "{npc:268602} (Stufe 10, ein abtrünniger Windformer mit nur einem Spawn) hält die Farm nordöstlich hinter {area:16638}, direkt südlich von {area:16629}, auf dem Hügel westlich der Fälle nördlich von {area:17675}. Töte ihn und nimm sein Herz.",
		["{npc:5900}: a new {quest:1464}"] = "{npc:5900}: eine neue {quest:1464}",
		["{npc:5907} hands you the {item:6653}: keep it until the end of the chain."] = "{npc:5907} gibt dir {item:6653}: Behalte sie bis zum Ende der Questreihe.",
		["{npc:5907} is not in the Crossroads: take the road north from the Crossroads and fork east towards {zone:1411}; past {area:1704} he paces by a tall tower east of the road (from {zone:1411}: over the Southfury bridge, past {area:379}). If you reach {zone:1440} you went too far."] = "{npc:5907} ist nicht in den Crossroads: Nimm die Straße nördlich der Crossroads und biege nach Osten Richtung {zone:1411} ab; hinter {area:1704} läuft er bei einem hohen Turm östlich der Straße umher (von {zone:1411} aus: über die Southfury-Brücke, vorbei an {area:379}). Wenn du {zone:1440} erreichst, bist du zu weit gegangen.",
		["{npc:5907}: {npc:3066}'s letter"] = "{npc:5907}: Brief von {npc:3066}",
		["{npc:5907}: {npc:3173}'s letter"] = "{npc:5907}: Brief von {npc:3173}",
		["{npc:5907}: {npc:5892}'s letter"] = "{npc:5907}: Brief von {npc:5892}",
		["{npc:5907}: {npc:5906}'s letter"] = "{npc:5907}: Brief von {npc:5906}",
		["{npc:5907}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {spell:3599}, dein {item:5176} und {item:263412}",
		["{object:660848} is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of {area:16638}, in the hills south of the Windsong Crawlers' lakes. Knock on it to call {npc:268605} (level 10). The spirit shrugs off most magic: only fire hurts it, so keep {spell:8050} on it. Take its wooden mask."] = "{object:660848} ist der verdrehte Baumstumpf auf der Hügelkuppe beim Shen'dar-Highlands-Ankerpylon, westlich von {area:16638}, in den Hügeln südlich der Seen der Windsong Crawlers. Klopf darauf, um {npc:268605} (Stufe 10) zu rufen. Der Geist wehrt die meiste Magie ab: Nur Feuer verletzt ihn, also halte {spell:8050} auf ihm. Nimm seine Holzmaske.",
		["{object:660848}: knock on the bark"] = "{object:660848}: klopf auf die Rinde",
		["{quest:1522} (Horde)"] = "{quest:1522} (Horde)",
} end)()
t.guides["forever/class/shaman/call-of-water-alliance"] = (function() return {
		["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "Mit Stufe 20 schickt dich {npc:258098}, der Schamanenlehrer in {object:32362} von {zone:1455}, zu {npc:258043} in {zone:1432}.",
		["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "Zurück zu {npc:258043} bei {area:146} mit {item:7810}. Er gibt dir {item:6637} und {item:7811}: Behalte beides für {zone:1436}.",
		["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Zurück zu {npc:258043} mit {item:7813}. Behalte {item:5177} dauerhaft in deinen Taschen: Jedes Wassertotem braucht ihn.",
		["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Fülle {item:265732} am Fuß der Wasserfälle unterhalb der Höhle von {npc:258203}, dort wo das Süßwasser auf das Brackwasser trifft. In der Nähe der Fälle streifen {object:147516}-Zwerge umher.",
		["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Flieg nach {area:108} und geh nach Süden zu {area:20}: {area:919} und {object:619896} liegen direkt nördlich davon. Trink {item:6637} am Schrein, um {npc:5894} (Stufe 22, {spell:8056} und {spell:122}; ein Spawn, drei Minuten nach einem Kill wieder da) zu sehen. Besiege ihn für seine Armschienen (fallen immer), und lege sie dann zusammen mit {item:7811} auf {object:619896} (das, nicht {npc:258043}, schließt die Quest ab). Klicke den Schrein noch einmal an: {npc:5895} erhebt sich daneben; sprich mit ihm, bevor du weggehst (ist er weg, brich ab und nimm die Quest am Schrein erneut an). Er gibt dir {item:7813}.",
		["Lost the {quest:94616}?"] = "{quest:94616} verloren?",
		["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "Nur wenn {quest:94616} nicht mehr in deinen Taschen ist: {npc:258043} gibt dir eine neue, bevor du nach {zone:1436} aufbrichst.",
		["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "Nimm das Boot von {area:150} nach {area:442} (es hält unterwegs in {area:271}), dann flieg oder geh nach Süden durch {zone:1439} nach {area:415} in {zone:1440}. Fülle {item:265772} im See um die Stadt, dann nimm das Boot zurück nach Menethil.",
		["The blue waterskin"] = "Der blaue Wasserschlauch",
		["The brown waterskin"] = "Der braune Wasserschlauch",
		["The red waterskin"] = "Der rote Wasserschlauch",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "Das {item:5177}, mit dem du Wassertotems aufstellen kannst, und dazu {spell:5394}.",
		["the {item:7810}, for {npc:258043}"] = "die {item:7810}, für {npc:258043}",
		["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71} ergießen sich aus {area:68} am Ostende des Rotkammgebirges (flieg von {zone:1455} nach {area:69}). Fülle {item:265747} an ihrem Fuß, wo sich die Murloc Nightcrawlers versammeln; zieh die Murlocs zuerst von der Stelle weg. Wenn der Schlauch verschwindet, ohne zu zählen, brich die Quest ab und nimm sie bei {npc:258203} erneut an, um einen neuen zu bekommen.",
		["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "Die Erdhütte von {npc:258043} steht am nordwestlichen Seeufer, unterhalb von {area:146}, nördlich von {area:144}.",
		["{npc:258043}: a new {quest:94616}"] = "{npc:258043}: eine neue {quest:94616}",
		["{npc:258043}: your {item:6637}"] = "{npc:258043}: dein {item:6637}",
		["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043}: {spell:5394} und dein {item:5177}",
		["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "Die Familie von {npc:258203} lebt in einer Höhle unter den südlichen Fällen der {zone:1437}, östlich von {area:836}: nicht in einer Stadt. Durch den Algaz-Tunnel nördlich von {zone:1432}, dann östlich von der Straße abbiegen.",
		["{npc:5895}, beside the shrine"] = "{npc:5895}, neben dem Schrein",
		["{quest:94494} (Alliance)"] = "{quest:94494} (Allianz)",
} end)()
t.guides["forever/class/shaman/call-of-water-horde"] = (function() return {
		["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}. (Swart in {area:362} gives the same letter: carry either.)"] = "Mit Stufe 20 schickt dich {npc:5892} im {object:172957} zu {npc:5901} im {zone:1413}. (Swart in {area:362} gibt denselben Brief: Nimm einen von beiden mit.)",
		["At 20 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5901} in the {zone:1413}. ({npc:3066} in {area:222} gives the same letter: carry either.)"] = "Mit Stufe 20 schickt dich {npc:5906}, ein Schamanenlehrer auf {area:1640} in {zone:1456}, zu {npc:5901} im {zone:1413}. ({npc:3066} in {area:222} gibt denselben Brief: Nimm einen von beiden mit.)",
		["Back to {npc:5899}. She gives you the {item:7810} for {npc:5901}."] = "Zurück zu {npc:5899}. Sie gibt dir {item:7810} für {npc:5901}.",
		["Back to {npc:5901} south of {area:392}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Zurück zu {npc:5901} südlich von {area:392}. Behalte {item:5177} dauerhaft in deinen Taschen: Jedes Wassertotem braucht ihn.",
		["Click the {object:113791} to place the bracers and the drops. A few seconds later the pure {npc:5895} rises on the stone in the middle of the pool: speak to it while the {spell:8202} lasts (drink again by the stone if it has worn off). It gives you the {item:7813} for {npc:5901}. Gone before you could speak to it? Back at {npc:5901} ask for {quest:63} (a fresh {quest:972} for {npc:7007}, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it."] = "Klicke auf {object:113791}, um die Armschienen und die Tropfen abzulegen. Einige Sekunden später erhebt sich auf dem Stein in der Mitte des Teichs der reine {npc:5895}: Sprich mit ihm, solange {spell:8202} wirkt (trink am Stein erneut, falls es nachgelassen hat). Er gibt dir {item:7813} für {npc:5901}. Weg, bevor du ihn ansprechen konntest? Frag bei {npc:5901} nach {quest:63} (eine frische {quest:972} für {npc:7007}, der direkt westlich des Schreins steht): Gib sie Tiev, bleib in der Nähe, während er den Geist zurückruft, und sprich dann mit ihm.",
		["Fly to the {area:228}. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the {item:6637} beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The {npc:5894} is level 22 and casts {spell:8056} and {spell:122}; if someone just killed it, it is back in about three minutes. Its bracers always drop."] = "Flieg zu {area:228}. Der Schrein liegt in einer Senke direkt südwestlich davon: Geh hinter die Gruft zu dem dicken Baum zwischen den zwei Hügeln, hüpf daran vorbei auf die Felsen und lass dich nach Westen den Hang hinunter zum Teich fallen (jeder Sprung kostet etwas Gesundheit). Trink {item:6637} neben dem hohen Menhir am Teich: Mehrere Wasserelementare erscheinen, und nur der verderbte nahe der Mitte kann angegriffen werden (Tab wählt ihn aus). {npc:5894} hat Stufe 22 und wirkt {spell:8056} und {spell:122}; wenn ihn gerade jemand getötet hat, ist er in etwa drei Minuten wieder da. Seine Armschienen fallen immer.",
		["Lost the {quest:972}?"] = "{quest:972} verloren?",
		["Only if the {quest:972} is gone from your bags: {npc:5901} gives you another."] = "Nur wenn {quest:972} nicht mehr in deinen Taschen ist: {npc:5901} gibt dir eine neue.",
		["The muddy pond below {npc:5899}'s hut. Step right into the puddle before you use the {item:7766} (too far away and it refuses). Filling it calls a hostile {npc:3456} (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards."] = "Der schlammige Teich unterhalb der Hütte von {npc:5899}. Stell dich direkt in die Pfütze, bevor du {item:7766} benutzt (zu weit weg, und er funktioniert nicht). Das Füllen ruft einen feindlichen {npc:3456} (Stufe 20): Töte ihn und achte auf den Stacheleber-Jäger am Teich, der danach vielleicht zu schießen beginnt.",
		["The right fountain stands in a ring of standing stones on the island of the small green lake south of {area:415}, west of Lake Mystral (not the island in Lake Mystral itself). From the {zone:1413} take the road north through the {area:1703} and on west. Water elementals and walking treants guard the lake and root you in place; an elite {npc:12836} roams {zone:1440} and can pass close by. Use the {item:7767} beside the fountain."] = "Der rechte Brunnen steht in einem Ring aus Menhiren auf der Insel des kleinen grünen Sees südlich von {area:415}, westlich des Lake Mystral (nicht die Insel im Lake Mystral selbst). Nimm vom {zone:1413} aus die Straße nach Norden durch {area:1703} und weiter nach Westen. Wasserelementare und wandelnde Treants bewachen den See und halten dich fest; ein Elite-{npc:12836} streift durch {zone:1440} und kann nah vorbeikommen. Benutze {item:7767} neben dem Brunnen.",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "{item:5177}, mit dem du Wassertotems aufstellen kannst, und dazu {spell:5394}.",
		["The {npc:5895}"] = "{npc:5895}",
		["The {object:107045}"] = "{object:107045}",
		["The {object:107045} stands in the middle of {area:272}, just outside the church. From the {zone:1413}: the zeppelin from {zone:1454} to {zone:1420}, then south past the {zone:1458} and through {zone:1421} (or fly once you have the {area:272} flight path). {area:287} is contested: Alliance players may attack. Stand beside the well and use the {item:7768}."] = "{object:107045} steht mitten in {area:272}, direkt vor der Kirche. Vom {zone:1413} aus: das Luftschiff von {zone:1454} nach {zone:1420}, dann südlich an {zone:1458} vorbei und durch {zone:1421} (oder flieg, sobald du die Flugroute von {area:272} hast). {area:287} ist umkämpft: Allianzspieler dürfen angreifen. Stell dich neben den Brunnen und benutze {item:7768}.",
		["The {object:107046}"] = "{object:107046}",
		["The {object:113791}"] = "{object:113791}",
		["the {item:7810}, for {npc:5901}"] = "{item:7810}, für {npc:5901}",
		["{item:6637}, beside the standing stone"] = "{item:6637}, neben dem Menhir",
		["{item:7766}, standing in the puddle"] = "{item:7766}, in der Pfütze stehend",
		["{item:7767}, beside the fountain"] = "{item:7767}, neben dem Brunnen",
		["{item:7768}, beside the well"] = "{item:7768}, neben dem Brunnen",
		["{npc:5899} lives in the southern {zone:1413}, south of {area:378}: her hut sits on a hilltop of {area:1701} with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way."] = "{npc:5899} lebt im südlichen {zone:1413}, südlich von {area:378}: Ihre Hütte steht auf einer Hügelkuppe von {area:1701} mit einer sich drehenden Windmühle daneben, und der Weg hinauf führt über den Grat beim einzelnen Baum. Rundherum ein Stacheleber-Lager; Sturmhäute, Donnerfalken und Hyänen streifen auf dem Weg durch die Ebenen.",
		["{npc:5901} hands you the {item:6637} and the {item:7811}: take everything she offers before you leave for Silverpine, or you will be back for more."] = "{npc:5901} gibt dir {item:6637} und {item:7811}: Nimm alles mit, was sie anbietet, bevor du nach Silberwald aufbrichst, sonst musst du noch einmal zurück.",
		["{npc:5901} is not in {area:392}: take the small coast road south from {area:392} past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far."] = "{npc:5901} ist nicht in {area:392}: Nimm die kleine Küstenstraße südlich von {area:392} an dem Piratenlager vorbei und über einen niedrigen Hügel; ihre Fischerhütte, vor der ein Hai aufgehängt ist, steht am Wasser vor dem Piratenschiff. Wenn du das Schiff erreichst, bist du zu weit gegangen.",
		["{npc:5901}: Narm's letter"] = "{npc:5901}: Brief von Narm",
		["{npc:5901}: Swart's letter"] = "{npc:5901}: Brief von Swart",
		["{npc:5901}: a new {quest:972}"] = "{npc:5901}: eine neue {quest:972}",
		["{npc:5901}: your {item:6637}"] = "{npc:5901}: dein {item:6637}",
		["{npc:5901}: {npc:5892}'s letter"] = "{npc:5901}: Brief von {npc:5892}",
		["{npc:5901}: {npc:5906}' letter"] = "{npc:5901}: Brief von {npc:5906}",
		["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901}: {spell:5394} und dein {item:5177}",
		["{quest:63} (Horde)"] = "{quest:63} (Horde)",
} end)()
t.guides["forever/class/shaman/darkreaver"] = (function() return {
		["200 Horde reputation"] = "200 Ruf bei der Horde",
		["A five-player dungeon event: {area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. In the {object:179746}'s basement, first clear every mob in the room, then use the {item:18746} at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then {npc:14516} (level 62 elite) appears: he Cleaves, casts {spell:686} and {spell:6958}, and Dominates a player's mind against the group. His head always drops."] = "Ein Dungeon-Event für fünf Spieler: {area:2057} liegt unter {area:2298}, der Inselstadt im Südosten von {zone:1422}. Räume im Keller von {object:179746} zuerst alle Mobs im Raum, dann benutze {item:18746} in dessen Mitte: Es folgen vier Wellen von Geistern, jede endet mit einem Aspekt-Mini-Boss (die erste Welle schwach und langsam, die übrigen Elite). Kämpfe in einer Ecke, damit nichts anderes dazukommt, und trink zwischen den Wellen: Es dauert lange. Dann erscheint {npc:14516} (Stufe 62, Elite): Er wirkt Spalten und {spell:686} und {spell:6958} und beherrscht den Geist eines Spielers gegen die Gruppe. Sein Kopf fällt immer.",
		["A {area:2057} fight at 60 for Horde reputation; the {item:20134} may be gone in Forever."] = "Ein {area:2057}-Kampf mit Stufe 60 für Ruf bei der Horde; {item:20134} könnte in Forever weg sein.",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds."] = "Mit Stufe 58 verlangt {npc:13417}, der Schamanenlehrer im {object:172957}, zwei seltene Diamanten; jeder Horde-Schamane geht zu ihm. Himmelsgeborene: Die Questseite von Forever führt diese Quest nur für Orcs, Tauren und Trolle auf: Frag nach, bevor du die Diamanten kaufst.",
		["Both diamonds are rare: the auction house is the quick way. Miners find the {item:12800} in about one Thorium vein in a hundred (the Small Thorium Veins north of {area:2418} in the {zone:1428} respawn every five minutes). The {item:18335} drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine)."] = "Beide Diamanten sind selten: Das Auktionshaus ist der schnelle Weg. Bergbauer finden {item:12800} bei etwa einer von hundert Thoriumadern (die Small Thorium Veins nördlich von {area:2418} in {zone:1428} respawnen alle fünf Minuten). {item:18335} fällt bei hochstufigen Elites mit etwa einem Prozent, am besten beim seltenen Elite Revanchion (etwa eins zu neun).",
		["Two diamonds"] = "Zwei Diamanten",
		["he hands you the {item:18746}"] = "er gibt dir {item:18746}",
		["{npc:13417}: 200 Horde reputation; the {item:20134} may be gone"] = "{npc:13417}: 200 Ruf bei der Horde; {item:20134} könnte weg sein",
		["{quest:7668} needs level 60."] = "{quest:7668} erfordert Stufe 60.",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys."] = "Ein Dungeon für fünf Spieler: Du brauchst eine Gruppe aus fünf, etwa Stufe 50-55. Flieg nach {area:75} und reite nach Osten. Der {area:1417} ({area:1477}) liegt mitten im {area:74}: Steig die Treppe an der Südseite der Ruine hinauf, tauch in die geflutete Halle, schwimm durch sie nach unten und folge den Treppen und Gängen hinab zum Portal. Zwei Federn jeder Farbe, eine von jedem von sechs Elite-Troll-Mini-Bossen (Stufe 51-52) auf den Balkonen um den großen runden Raum des Tempels, bei jedem Kill, und jeder Spieler mit der Quest plündert seine eigenen: Gasher und {npc:5716} die Bernsteinfarbene, Hukku und Mijan die Blaue, Zolo und Loro die Grüne. Mijan heilt die anderen ({spell:139}, ein {npc:3560}): Töte ihn zuerst; Hukku beschwört Wächter und wirft Schattenblitzsalven.",
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}."] = "Mit Stufe 50 verlangt {npc:13417}, der Schamanenlehrer im {object:172957}, die vier Elemente für {npc:6176}.",
		["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "Mit Stufe 50 verlangt {npc:3032}, ein Schamanenlehrer auf {area:1640} in {zone:1456}, die vier Elemente für {npc:6176}. Himmelsgeborene: Die Questseite von Forever führt {quest:8410} und {quest:8412} nur für Orcs, Tauren und Trolle auf; hat {npc:3032} nichts für dich, steht {quest:8411} von {npc:6176} selbst allen Horde-Völkern offen, aber {quest:8412} danach könnte dich trotzdem abweisen.",
		["Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal."] = "Je acht. Flieg oder reite nach {area:813} und weiter zum Westrand von {zone:1422}, nordwestlich von {area:3197}: Die Venom Mist Lurkers (Stufe 50-51, sie vergiften) lassen {item:20610} fallen und die Diseased Black Bears (Stufe 51-52, {spell:3427}) {item:20611}, jeweils bei einem von fünf Kills; die zwei Carrion Vultures dort lassen beides fallen. Die größeren Diseased Grizzlies und Plague Lurkers weiter östlich lassen sie fast nie fallen. Einige Bären und Lurkers streifen auch südöstlich von {area:159} in Tirisfal umher.",
		["Experience and gold"] = "Erfahrung und Gold",
		["Experience and gold at 50, ending in the {area:1417}; the Classic item choice may be gone in Forever."] = "Erfahrung und Gold mit Stufe 50, endet im {area:1417}; die Gegenstandswahl aus Classic könnte in Forever weg sein.",
		["One each of {item:7069}, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, {zone:1417} has the exiles near {area:320} (level 38-39, about one kill in eight to ten, respawn under seven minutes): Thundering Exiles south-east of it (air), Rumbling Exiles south-west (earth), Burning Exiles far to the north-west (fire), and the {npc:2794} far to the south-west (water, about one in seven). Water comes easier from the Patches of Elemental Water in {zone:1447} (two in five) or {npc:14269} by {area:69} in Redridge."] = "Je einmal {item:7069}, Feuer, Erde und Wasser; alle vier sind handelbar, das Auktionshaus ist also am schnellsten. Zum Farmen: {zone:1417} hat die Exiles bei {area:320} (Stufe 38-39, etwa ein Kill von acht bis zehn, Respawn unter sieben Minuten): Thundering Exiles südöstlich davon (Luft), Rumbling Exiles südwestlich (Erde), Burning Exiles weit im Nordwesten (Feuer) und {npc:2794} weit im Südwesten (Wasser, etwa eins von sieben). Wasser fällt leichter bei den Patches of Elemental Water in {zone:1447} (zwei von fünf) oder bei {npc:14269} neben {area:69} im Rotkammgebirge.",
		["Spider eye and bear claw"] = "Spinnenauge und Bärenklaue",
		["The four elements"] = "Die vier Elemente",
		["The {area:1417}"] = "{area:1417}",
		["{item:20606}: Gasher, {npc:5716}"] = "{item:20606}: Gasher, {npc:5716}",
		["{item:20607}: Hukku, Mijan"] = "{item:20607}: Hukku, Mijan",
		["{item:20608}: Zolo, Loro"] = "{item:20608}: Zolo, Loro",
		["{item:7067}: Rumbling Exiles"] = "{item:7067}: Rumpelnde Verbannte",
		["{item:7068}: Burning Exiles"] = "{item:7068}: Brennende Verbannte",
		["{item:7069}: Thundering Exiles"] = "{item:7069}: Donnernde Verbannte",
		["{item:7070}: the {npc:2794}, or {zone:1447}'s water patches"] = "{item:7070}: {npc:2794} oder die Wasserflecken in {zone:1447}",
		["{npc:6176} camps in the ruins of the east of {zone:1416}: from {area:272} follow the river east of town north into the hills."] = "{npc:6176} lagert in den Ruinen im Osten von {zone:1416}: Folge von {area:272} aus dem Fluss östlich der Stadt nach Norden in die Hügel.",
		["{npc:6176}: the old item choice may be gone, count on the experience"] = "{npc:6176}: die alte Gegenstandswahl könnte weg sein, rechne mit der Erfahrung",
		["{quest:8412} and {quest:8413}"] = "{quest:8412} und {quest:8413}",
} end)()
t.guides["forever/class/warlock/dread-mage-hat"] = (function() return {
		["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Ein Stoffhut in deinen späten Zwanzigern: Zardeths Auftrag für jeden Allianzspieler bringt Hexenmeistern diese Extra-Belohnung.",
		["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "Mit Stufe 25 will {npc:1435} im Keller von {object:2164} im {object:2101} (neben den Hexenmeisterlehrern) zwei Zutaten für ein Gebräu. Mach das, wenn dein Leveln dich nach {zone:1431} und in die {zone:1437} führt.",
		["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "Noch einmal zurück zu Zardeth: Er bietet Hexenmeistern eine Belohnung an, die sein Wichtel {npc:1733}, der neben ihm steht, aushändigt.",
		["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "Zurück zu Zardeth. Er braut {item:2788} und gibt es dir für {npc:1439} in der Halle der Bittsteller, der ersten Halle rechts im Inneren von {object:2117}.",
		["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "Die Wurzel wächst am Wasserrand im Teich unterhalb der kleinen Fälle östlich von {area:836}, neben der {object:147516}-Höhle unterhalb von {area:146}: eine hohe, stachelige Holzwurzel, nicht am Fuß des Damms selbst.",
		["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "{area:1098} liegt im Nordosten von {zone:1431}, nördlich von {area:42}. {object:321} ist eine kleine weiße Blume tief im Gras des umzäunten Gartens neben Stalvans Haus: schwer zu sehen, also fahr mit der Maus über den Garten. Fetid Corpses (Stufe 29) wandern über das Gelände und kommen schnell: Schick mit Stufe 25 deinen Leerwandler auf den nächsten, schnapp dir die Blume und verschwinde. {npc:315} (32) ist im Haus; lass ihn in Ruhe.",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s from {npc:6266}; its last parts wait for levels 35 and 37."] = "Eine seltene Stoffrobe für deine 30er von {npc:6266}; ihre letzten Teile warten auf Stufe 35 und 37.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Mit Stufe 31 schickt dich {npc:3326} im {object:172960} zu {npc:6266} in {area:392}. Kauf vorher {item:5770} und {item:3577} (nächste Schritte), um dir einen Weg zu sparen.",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}; the zeppelin from {zone:1420} flies to {zone:1411}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Mit Stufe 31 schickt dich {npc:4563} im {object:36082} zu {npc:6266} in {area:392}; das Luftschiff von {zone:1420} fliegt nach {zone:1411}. Kauf vorher {item:5770} und {item:3577} (nächste Schritte), um dir einen Weg zu sparen.",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Mit Stufe 31 schickt dich {npc:461} im {object:2164}, im {object:2101}, zu {npc:6266} in {area:392}. Kauf vorher {item:5770} und {item:3577} (nächste Schritte), um dir einen Weg zu sparen.",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Mit Stufe 31 schickt dich {npc:5172} in {zone:1455} zu {npc:6266} in {area:392}. Kauf vorher {item:5770} und {item:3577} (nächste Schritte), um dir einen Weg zu sparen.",
		["Back to {npc:2670} in {area:35}: he offers {quest:4785} as a quest you hand straight back to him. He may show no quest marker; talk to him anyway."] = "Zurück zu {npc:2670} in {area:35}: Er bietet {quest:4785} als Quest an, die du direkt wieder bei ihm abgibst. Vielleicht zeigt er kein Questzeichen; sprich ihn trotzdem an.",
		["Back to {npc:6266}"] = "Zurück zu {npc:6266}",
		["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "Zurück zu {npc:6266} mit dem Faden, der Kohle und einem {item:6265}. Warte dann neben ihr, während sie die Robe bearbeitet (greif sie nicht an: Das Questlog zählt es als Kill), und sprich sie noch einmal an.",
		["Hatefury satyrs"] = "Satyrn der Zornsäer",
		["Tailors sew the {item:5770} from a rare pattern; miners smelt Gold Bars from {item:2776}. Everyone else buys both at the Auction House. If you wear the robe, take it off: {npc:6266} keeps it."] = "Schneider nähen {item:5770} nach einem seltenen Muster; Bergbauer schmelzen Goldbarren aus {item:2776}. Alle anderen kaufen beides im Auktionshaus. Trägst du die Robe, zieh sie aus: {npc:6266} behält sie.",
		["The Burning Exiles (level 38-39), fire elementals at the {area:334} in western {zone:1417}, drop the coal about one time in three. The guide waits for level 37 first: below it they hit too hard to solo. They resist fire: {spell:686} and Corruption. The Cresting Charms from the Cresting Exiles near {area:321} finish one off once you have hurt it. Make a {item:6265} with {spell:1120} on the way."] = "Die Brennenden Verbannten (Stufe 38-39), Feuerelementare am {area:334} im westlichen {zone:1417}, lassen die Kohle etwa bei jedem dritten Kill fallen. Der Guide wartet zuerst auf Stufe 37: Darunter schlagen sie zu hart zu, um sie allein zu schaffen. Sie widerstehen Feuer: {spell:686} und Verderbnis. Die Schäumenden Glücksbringer der Schäumenden Verbannten bei {area:321} erledigen einen, sobald du ihn verletzt hast. Stelle unterwegs mit {spell:1120} einen {item:6265} her.",
		["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25."] = "Die Satyrn der Zornsäer (Stufe 31-32) halten {area:603} im äußersten Nordosten von {zone:1443}, hinter {area:608}: Zwei von fünf Kills ergeben ein Fläschchen, plane also etwa 25 ein.",
		["The Lesser Infernals (36-37) and Demon Portal Guardians (38) of {area:602}, in the south of {zone:1443}, drop the stone half the time. The guide waits for level 35 first: at 31 they are too strong to solo. They resist fire, so use {spell:686} and Corruption."] = "Die Geringen Höllenbestien (36-37) und Dämonenportalwächter (38) von {area:602} im Süden von {zone:1443} lassen den Stein zur Hälfte fallen. Der Guide wartet zuerst auf Stufe 35: Mit 31 sind sie zu stark, um sie allein zu schaffen. Sie widerstehen Feuer, nimm also {spell:686} und Verderbnis.",
		["The boat from {area:392} sails to {area:35}. {npc:2670} runs {object:59851} on an upper level of the town. Give him the {item:3577}; he will spin the thread later."] = "Das Boot von {area:392} fährt nach {area:35}. {npc:2670} betreibt {object:59851} auf einer oberen Ebene der Stadt. Gib ihm {item:3577}; den Faden spinnt er später.",
		["Vials of Hatefury Blood"] = "Phiolen mit Zornsäerblut",
		["Wait beside {npc:6266} while she finishes the robe"] = "Warte neben {npc:6266}, während sie die Robe fertigstellt",
		["You need no thread yet: {npc:6266} wants demon parts from {zone:1443} next."] = "Faden brauchst du noch nicht: {npc:6266} will als Nächstes Dämonenteile aus {zone:1443}.",
		["{item:3577}: the Auction House"] = "{item:3577}: das Auktionshaus",
		["{item:5770} and a {item:3577}"] = "{item:5770} und {item:3577}",
		["{item:5770}: the Auction House"] = "{item:5770}: das Auktionshaus",
		["{item:6265}: {spell:1120} on an Exile as it dies"] = "{item:6265}: {spell:1120} auf einen Exile, während er stirbt",
		["{npc:2670}: {quest:4785}, handed straight back"] = "{npc:2670}: {quest:4785}, sofort wieder abgegeben",
		["{npc:6266} again"] = "Wieder zu {npc:6266}",
		["{npc:6266} stands by {npc:6251}'s tower on the hill above {area:392}, behind the engineers' hut. She takes the robe, then sends the gold bar to {npc:2670} in {area:35}."] = "{npc:6266} steht beim Turm von {npc:6251} auf dem Hügel über {area:392}, hinter der Hütte der Ingenieure. Sie nimmt die Robe und schickt dich dann mit dem Goldbarren zu {npc:2670} in {area:35}.",
} end)()
t.guides["forever/class/warlock/felhunter-alliance"] = (function() return {
		["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "Mit 30 schickt dich {npc:6120} in {object:32383} zu {npc:6251} in {area:392}.",
		["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "Mit 30 schickt dich {npc:6122} im Keller von {object:2164} in {object:2101} zu {npc:6251} in {area:392}.",
		["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Zurück zu {npc:6251} in {area:392}. Sobald du annimmst, zeichnet er den Beschwörungskreis, und seine Akolythen kanalisieren einen größeren Kreis darüber: Warte im Turm, bis beide fertig sind. Benutze dann {quest:1804} auf dem Kreis. Der Teufelsjäger (Stufe 30, kein Elite) bringt zum Schweigen und frisst Mana und verschwindet nach zwei Minuten: Hab deinen Leerwandler draußen, eröffne sofort mit deinem Schaden über Zeit und lass den Leerwandler tanken. Wenn du stirbst oder er gewinnt, brich {quest:1795} ab und nimm sie bei {npc:6251} erneut an. Behalte den Foliant: {npc:6251} nimmt ihn zurück.",
		["Back to {npc:6294}"] = "Zurück zu {npc:6294}",
		["Felhunter (Alliance)"] = "Teufelsjäger (Allianz)",
		["Rods of Channeling"] = "Ruten des Kanalisierens",
		["Rods of Channeling, from the Dragonmaw casters"] = "Stäbe der Kanalisierung, von den Zauberwirkern der Dragonmaw",
		["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Die Dragonmaw halten {area:1036} in den Hügeln östlich der Straße von {area:150} nach {area:836}. Nur die Zauberwirker lassen die Stäbe fallen, bei vier von fünf Kills: die Bonewarders (Stufe 27, mit Skelett-Begleitern) und Shadowwarders (28). Ein steiler Pfad nördlich des zentralen Geistheilers führt am Großteil der Krieger vorbei ins Lager hinauf.",
		["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "Die Zentaurenhöhle öffnet sich in den Klippen nördlich von {area:484}, einer Hordestadt: Halt dich von den Wachen fern. Halte dich drinnen an jeder Gabelung rechts, überquere den Teich am kleinen Wasserfall und öffne die kleine dunkle Kiste an der Wand neben einer größeren Truhe: Die größere ist die falsche. Du kannst sie nur öffnen, solange du die Quest hast. Die Zentauren respawnen hinter dir, wenn du hinausgehst.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "Der Teufelsjäger, der Dämon gegen Zauberwirker, und {item:22244} für deine Splitter.",
		["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "Der Foliant ist ein kleines graublaues Buch, das im Sand eines Murloc-Lagers am Ufer südwestlich von {area:271} liegt, nahe am Wasser. Sechs oder sieben Murlocs bewachen es und weitere lauern unter Wasser: Sie kommen in Gruppen, also schick einen in Furcht und lass deinen Leerwandler die übrigen halten. Geh zum Wasser hinunter, um es anzuklicken; vom Hang aus blockieren die Kisten den Cursor.",
		["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392} ist ein neutraler Goblinhafen an der Küste des {zone:1413}: Das Boot von {area:35} legt dort an. {npc:6251} steht auf dem Hügel über der Stadt, hinter der Hütte der Ingenieure, bei seinem kleinen Turm; {npc:6266} und zwei Akolythen sind bei ihm. Er schickt dich zu {npc:6294} in {zone:1455}.",
		["{item:6931}, from the {quest:1802} on the sand"] = "{item:6931}, aus {quest:1802} im Sand",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, in {object:92423}",
		["{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6294} ist in der Bibliothek von {object:32356}. Er will zwei verlorene Teile von {quest:1758}: eines an der Küste von {area:287}, eines in {zone:1441}.",
		["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6294} setzt den Foliant zusammen und gibt dir {item:7006}: Behalte ihn, {npc:6251} nimmt ihn zusammen mit den Stäben.",
		["{quest:1804}, on the circle"] = "{quest:1804}, auf dem Kreis",
} end)()
t.guides["forever/class/warlock/felhunter-horde"] = (function() return {
		["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:2996}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "Mit Stufe 30 schickt dich {npc:5675} im {object:36082} zu {npc:6251} in {area:392}. Das Luftschiff von {zone:1420} fliegt nach {zone:1411}. Nimm nur eine {quest:2996}: Bietet {npc:6251} nichts an, wirf die doppelte aus deinem Log.",
		["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "Mit Stufe 30 schickt dich {npc:5875}, im Gebiet {object:172960} unter dem {object:172982}, zu {npc:6251} in {area:392}.",
		["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Zurück zu {npc:6251} in {area:392}. Sobald du annimmst, zeichnet er den Beschwörungskreis, und seine Akolythen kanalisieren einen größeren Kreis darüber: Warte im Turm, bis beide fertig sind. Benutze dann {quest:1804} auf dem Kreis. Der Teufelsjäger (Stufe 30, kein Elite) bringt zum Schweigen und frisst Mana und verschwindet nach zwei Minuten: Hab deinen Leerwandler draußen, eröffne sofort mit deinem Schaden über Zeit und lass den Leerwandler tanken. Wenn du stirbst oder er gewinnt, brich {quest:1795} ab und nimm sie bei {npc:6251} erneut an. Behalte den Foliant: {npc:6251} nimmt ihn zurück.",
		["Back to {npc:6293}"] = "Zurück zu {npc:6293}",
		["Felhunter (Horde)"] = "Teufelsjäger (Horde)",
		["Rods of Channeling"] = "Kanalisierungsruten",
		["Rods of Channeling, from the Dragonmaw casters"] = "Stäbe der Kanalisierung, von den Zauberwirkern der Dragonmaw",
		["The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Die Dragonmaw halten {area:1036} in den Hügeln östlich der Straße durch die {zone:1437}, südlich von {area:881}, das du von {zone:1417} aus überquerst. Nur die Zauberwirker lassen die Stäbe fallen, bei vier von fünf Kills: die Bonewarders (Stufe 27, mit Skelett-Begleitern) und Shadowwarders (28). Ein steiler Pfad nördlich des zentralen Geistheilers führt am Großteil der Krieger vorbei ins Lager hinauf.",
		["The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "Die Zentaurenhöhle öffnet sich in den Klippen nördlich von {area:484}. Halte dich drinnen an jeder Gabelung rechts, überquere den Teich am kleinen Wasserfall und öffne die kleine dunkle Kiste an der Wand neben einer größeren Truhe: Die größere ist die falsche. Du kannst sie nur öffnen, solange du die Quest hast. Die Zentauren respawnen hinter dir, wenn du hinausgehst.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "Der Teufelsjäger, der Dämon gegen Zauberwirker, und ein {item:22244} für deine Splitter.",
		["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "Der Foliant ist ein kleines graublaues Buch, das im Sand eines Murloc-Lagers am Ufer südwestlich von {area:271} liegt, nahe am Wasser. Sechs oder sieben Murlocs bewachen es und weitere lauern unter Wasser: Sie kommen in Gruppen, also schick einen in Furcht und lass deinen Leerwandler die übrigen halten. Geh zum Wasser hinunter, um es anzuklicken; vom Hang aus blockieren die Kisten den Cursor.",
		["{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}."] = "Der Flugpunkt von {area:392} ist ein kurzer Flug von dem von {zone:1454} entfernt. {npc:6251} steht auf dem Hügel über der Stadt, hinter der Hütte der Ingenieure, bei seinem kleinen Turm; {npc:6266} und zwei Akolythen sind bei ihm. Er schickt dich zu {npc:6293} in {zone:1458}.",
		["{item:6931}, from the {quest:1803} on the sand"] = "{item:6931}, aus {quest:1803} im Sand",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, in der {object:92423}",
		["{npc:6293} is in the {object:36082} of the {zone:1458}. He wants two lost pieces of the {quest:1801}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6293} ist im {object:36082} von {zone:1458}. Er will zwei verlorene Teile von {quest:1801}: eines an der Küste von {area:287}, eines in {zone:1441}.",
		["{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6293} setzt den Foliant zusammen und gibt dir {item:7006}: Behalte ihn, {npc:6251} nimmt ihn zusammen mit den Stäben.",
		["{quest:1804}, on the circle"] = "{quest:1804}, auf dem Kreis",
} end)()
t.guides["forever/class/warlock/imp-alliance"] = (function() return {
		["Feather Charms"] = "Feather Charms",
		["Imp (Alliance)"] = "Wichtel (Allianz)",
		["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "Das Defias-Zelt steht im Weinberg östlich der Abtei. Das Buch ist klein: Es liegt auf dem Boden direkt rechts der Zeltöffnung, neben einem blauen Krug. Drei Defias Thugs (Stufe 3-4) bewachen das Zelt; pull sie einzeln, oder geh ins Zelt hinein und klicke das Buch an, wo sie dich nicht erreichen. Das Buch respawnt drei Minuten, nachdem jemand es genommen hat.",
		["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "Die Frostmane Novices (Stufe 3-4) sitzen hinten in der Trollhöhle südlich von {area:77}, nahe Grek'nir the Cold am eisigen Teich: Nimm den linken Tunnel hinter dem Eingang. Vier von fünf Kills lassen einen Charm fallen, aber es spawnen nur zwei oder drei Novices, du musst also vielleicht ihren Respawn von drei Minuten abwarten. Sie werfen Frostblitze aus der Distanz; die Troll Whelps am Höhleneingang greifen jeden an, der vorbeikommt. Mit den Charms bringt dich dein Ruhestein direkt zurück: Der eines neuen Charakters ist auf {area:132} gesetzt.",
		["The {object:83763}"] = "{object:83763}",
		["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "Dein erster Dämon auf Stufe 1-4: der Wichtel, vom Hexenmeisterlehrer deines Startgebiets.",
		["Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole."] = "Dein erster Brief ({item:9576}, von {npc:197} nach Kobold Camp Cleanup) schickt dich zu {npc:459}, der Hexenmeisterlehrerin auf dem kleinen Friedhof neben {area:24}. Sie verlangt ein Buch, das die Defias gestohlen haben.",
		["Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms."] = "Dein erster Brief ({item:9577}, von {npc:658} nach Dwarven Outfitters) schickt dich zu {npc:460}, dem Hexenmeisterlehrer im Obergeschoss von {area:77}. Er verlangt drei Feather Charms.",
		["{item:6785}, from the {object:83763}"] = "{item:6785}, aus {object:83763}",
		["{npc:459} (Humans)"] = "{npc:459} (Menschen)",
		["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:459} bringt dir bei der Abgabe {spell:688} bei: Beschwöre ihn sofort, er kostet nichts und kämpft an deiner Seite.",
		["{npc:460} (Gnomes)"] = "{npc:460} (Gnome)",
		["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:460} bringt dir bei der Abgabe {spell:688} bei: Beschwöre ihn sofort, er kostet nichts und kämpft an deiner Seite.",
} end)()
t.guides["forever/class/warlock/imp-horde"] = (function() return {
		["Imp (Horde)"] = "Wichtel (Horde)",
		["Rattlecage Skulls"] = "Rattlecage Skulls",
		["The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of {area:154}, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes."] = "Die Rattlecage Skeletons (Stufe 2-3) stehen bei den alten Schmiedegebäuden direkt nördlich von {area:154}, oft direkt an den Wänden. Vier von fünf Kills lassen einen Schädel fallen, plane also etwa fünf ein; zwanzig davon spawnen dort, und jedes kommt nach fünf Minuten zurück.",
		["The {quest:1485} (level 3-4) swarm the {area:365}, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own {quest:1485} quest."] = "Die {quest:1485} (Stufe 3-4) wimmeln in {area:365}, der Höhle nördlich davon, drinnen und rund um den Eingang. Fast jeder Kill lässt einen Kopf fallen (80 %), etwa acht Kills reichen also; sie werfen kleine Feuerbälle, pull sie also einzeln. Sie respawnen nach etwas mehr als drei Minuten. Andere Klassen jagen dieselben Wichtel für ihre eigene Quest {quest:1485}.",
		["Vile Familiar Heads"] = "Vile Familiar Heads",
		["Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls."] = "Dein erster Dämon auf Stufe 1-4: der Wichtel, mit einer Startklinge oder einem Startstab für Orcs und Trolle.",
		["Your first letter ({item:9578}, from {npc:1569} after The Mindless Ones) points you to Maximillion, the warlock trainer in {area:154}. {npc:5667} waits inside the building beside him and asks for three Rattlecage Skulls."] = "Dein erster Brief ({item:9578}, von {npc:1569} nach The Mindless Ones) schickt dich zu Maximillion, dem Hexenmeisterlehrer in {area:154}. {npc:5667} wartet im Gebäude neben ihm und verlangt drei Rattlecage Skulls.",
		["Your first letter ({item:9579} for Orcs, {item:282346} for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. {npc:5765} stands just outside the Den in the {area:363} and asks for six Vile Familiar Heads."] = "Dein erster Brief ({item:9579} für Orcs, {item:282346} für Trolle, von Gornek nach Cutting Teeth) schickt dich zu Nartok, dem Hexenmeisterlehrer in der Höhle. {npc:5765} steht direkt vor der Höhle im {area:363} und verlangt sechs Vile Familiar Heads.",
		["{npc:5667} (Undead)"] = "{npc:5667} (Untote)",
		["{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you."] = "{npc:5667} bringt dir {spell:688} bei, wenn du die Schädel abgibst: Beschwöre ihn sofort, er kostet nichts und kämpft an deiner Seite.",
		["{npc:5765} (Orcs and Trolls)"] = "{npc:5765} (Orcs und Trolle)",
		["{npc:5765} teaches you {spell:688} when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with {npc:3145} a few steps away for a starter weapon."] = "{npc:5765} bringt dir {spell:688} bei, wenn du die Köpfe abgibst: Beschwöre ihn sofort, er kostet nichts und kämpft an deiner Seite. Sprich dann ein paar Schritte weiter mit {npc:3145} für eine Startwaffe.",
} end)()
t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Ein Stab, ein Schildhand-Gegenstand oder eine Robe für deine 50er; ein eigener Auftrag von {npc:14470}, kein Schritt der Schreckensross-Questreihe.",
		["Amber Voodoo Feathers: Gasher, {npc:5716}"] = "Amber Voodoo Feathers: Gasher, {npc:5716}",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Mit Stufe 50 schickt dich {npc:3326} im {object:172960} mit einem Stück {item:14256} zu {npc:14470} in {zone:1448}.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Mit Stufe 50 schickt dich {npc:4563} im {object:36082} mit einem Stück {item:14256} zu {npc:14470} in {zone:1448}.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Mit Stufe 50 schickt dich {npc:461} im {object:2164}, im {object:2101}, mit einem Stück {item:14256} zu {npc:14470} in {zone:1448}.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Mit Stufe 50 schickt dich {npc:5172} in {zone:1455} mit einem Stück {item:14256} zu {npc:14470} in {zone:1448}.",
		["Blue Voodoo Feathers: Hukku, Mijan"] = "Blue Voodoo Feathers: Hukku, Mijan",
		["Choose the {item:20536} (staff), the {item:20534} (off-hand) or the {item:20530}."] = "Wähle {item:20536} (Stab), {item:20534} (Nebenhand) oder {item:20530}.",
		["Green Voodoo Feathers: Zolo, Loro"] = "Green Voodoo Feathers: Zolo, Loro",
		["One {item:14256}: the Jadefire satyrs of {zone:1448} drop it about one kill in fourteen, and so do the Legashi satyrs and the Felguard Sentries you hunt for Niby's essences. Quicker: buy one at the Auction House. You need it for the trainer's {quest:8419} or for {npc:14470}'s own {quest:8420}, the same errand: whichever you hold."] = "Ein {item:14256}: Die Jadefire-Satyrn in {zone:1448} lassen es etwa bei jedem vierzehnten Kill fallen, ebenso die Legashi-Satyrn und die Felguard Sentries, die du für Nibys Essenzen jagst. Schneller: Kauf eines im Auktionshaus. Du brauchst es für {quest:8419} des Lehrers oder für {npc:14470}s eigene {quest:8420}, derselbe Auftrag: Nimm, was du hast.",
		["The Irontree treants (level 52) of {area:1767}, in northern {zone:1448} west of {area:1998}, drop {item:20613} one time in four; the big {npc:7149} (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around {npc:14470} and along the Bloodvenom drop the essence one time in five."] = "Die Irontree-Treants (Stufe 52) von {area:1767} im nördlichen {zone:1448} westlich von {area:1998} lassen {item:20613} bei jedem vierten Kill fallen; der große {npc:7149} (55) lässt oft drei auf einmal fallen, schlägt aber hart zu und betäubt. Die Tainted Oozes (51) um {npc:14470} und entlang der Bloodvenom lassen die Essenz bei jedem fünften Kill fallen.",
		["The {area:1417}"] = "{area:1417}",
		["The {area:1417} ({area:1477}, level 50-56, a group of five) stands in the middle of the {area:74}: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52."] = "Der {area:1417} ({area:1477}, Stufe 50-56, Gruppe aus fünf) liegt mitten im {area:74}: Tauch in den Tempel hinunter und nimm die Treppe zum Eingang. Die sechs Troll-Wächter (Stufe 51-52, Elite) stehen auf den Balkonen um die zentrale Grube, jeder mit Adds; jeder lässt seine Feder jedes Mal fallen: Gasher und {npc:5716} die Bernsteinfarbene, Hukku und Mijan die Blaue, Zolo und Loro die Grüne. Mit 52 nicht solo machbar.",
		["{item:20613} and Bloodvenom"] = "{item:20613} und Blutgift",
		["{npc:14470} again"] = "Wieder {npc:14470}",
		["{npc:14470} now wants six {item:20609} from the {area:1417}: a dungeon run."] = "{npc:14470} will nun sechs {item:20609} aus dem {area:1417}: ein Dungeon-Durchlauf.",
		["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's {quest:8419} with the cloth. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} wartet neben {npc:14469} auf einer Anhöhe direkt nordöstlich von {area:1997}: Wenn du von Süden über die Brücke von {area:1765} nach Norden kommst, stehen sie östlich abseits der Straße, hinter ein paar Schlämmen. Gib ihm {quest:8419} des Lehrers mit dem Stoff. Als Nächstes will er zehn {item:20613} und vier {item:20614}.",
		["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Take his own {quest:8420} and hand him the cloth at once. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} wartet neben {npc:14469} auf einer Anhöhe direkt nordöstlich von {area:1997}: Wenn du von Süden über die Brücke von {area:1765} nach Norden kommst, stehen sie östlich abseits der Straße, hinter ein paar Schlämmen. Nimm seine eigene {quest:8420} an und gib ihm sofort den Stoff. Als Nächstes will er zehn {item:20613} und vier {item:20614}.",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "Mit Stufe 20 schickt dich {npc:6120}, der Hexenmeisterlehrer in {object:32383} von {zone:1455}, zu {npc:6122} in {zone:1453}. Nimm die {area:2257}.",
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "Mit Stufe 20 schickt dich {npc:6122}, im Keller von {object:2164} im {object:2101}, zu {npc:6244} im {zone:1413}: eine lange Reise für die Allianz. Nimm das Boot von {area:150} nach Theramore und geh nach Westen durch {zone:1445}, oder das Boot von {area:35} nach {area:392}.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Auf Stufe 20: der Sukkubus und der Inkubus von Forever, sein männliches Gegenstück, jeweils mit einem Seelenbeutel für deine Splitter.",
		["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "Zurück zu {npc:6122} mit {quest:1738}. Er gibt dir {item:6913}: Nimm die Treppe hinter ihm hinab in die Krypta; ein Stück weit im untersten Gang führt links eine Seitentreppe zum Raum mit dem violetten Kreis. Stell dich darauf und benutze den Kern. Beschwöre zuerst deinen Leerwandler und halte den Sukkubus (Stufe 20, kein Elite) auf dem Kreis, sonst töten ihn vielleicht die Wachen und der Kill zählt nicht. Gewinnt er, benutze den Kern erneut; behalte ihn, {npc:6122} nimmt ihn zurück.",
		["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "Gib Gakin die Figur, benutze dann {item:190309} in der Mitte desselben Kreises und besiege den Inkubus, den sie ruft (Stufe 20, kein Elite; er kann dich bezaubern), während dein Leerwandler tankt. Behalte die Figur: {npc:6122} nimmt sie zurück.",
		["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "Ordil'Aran liegt im nordwestlichen {zone:1440}, nördlich von {area:415} an der Straße Richtung {zone:1439}. Etwa zwanzig Kultisten der Dark Strand halten die Ruinen um den großen Baum: Bleib an der Außenmauer und klicke {quest:1738} aus möglichst großer Entfernung an. Sie wird bei {npc:6122} abgegeben, nicht bei Takar.",
		["Succubus and Incubus (Alliance)"] = "Sukkubus und Inkubus (Allianz)",
		["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "Das Haus steht allein zwischen den Bäumen im nordwestlichen {zone:1440}, nordwestlich von Ordil'Aran und weit nördlich von {area:413}: Erledige es auf derselben Reise wie {quest:1738}. Nimm {item:190307} vom Tisch draußen, entzünde sie an einem Lagerfeuer (ein {object:29784} von dir selbst oder Talens Feuer bei {area:414}) und geh direkt zurück: {item:190308} brennt nach fünf Minuten aus, ein eigenes Feuer neben dem Haus ist also am schnellsten. Ohne sie hält dich die Gestalt im Haus auf. Die Figur ist im Obergeschoss.",
		["The {item:190309}"] = "{item:190309}",
		["the incubus"] = "der Inkubus",
		["the succubus"] = "der Sukkubus",
		["{item:190307}, on the table outside"] = "{item:190307}, auf dem Tisch draußen",
		["{item:190309}, upstairs"] = "{item:190309}, im Obergeschoss",
		["{item:6913}, on the circle in the crypt"] = "{item:6913}, auf dem Kreis in der Krypta",
		["{npc:185335}, at the circle in the crypt"] = "{npc:185335}, am Kreis in der Krypta",
		["{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both."] = "{npc:6244} lagert an einem Zelt mit Lagerfeuer direkt nordöstlich von {area:378}, an einer Wegkreuzung: Hordeland, komm also von Osten und halte dich von den Wachen von Taurajo fern. {npc:6247} neben ihm beginnt {item:6898}. Takar bietet beide Zweige an: Nimm beide.",
		["{quest:1717} (Gnomes)"] = "{quest:1717} (Gnome)",
		["{quest:1739}: succubus"] = "{quest:1739}: Sukkubus",
		["{quest:65603}: incubus"] = "{quest:65603}: Inkubus",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1472} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "Mit Stufe 20 schickt dich {npc:5875} im {object:172960} unter {object:172982} zu {npc:5909} ein paar Schritte weiter. Zwei Lehrer starten diese Dämonen, {npc:5875} hier und {npc:5675} in {zone:1458}, und du kannst nur einen nehmen; dieser Guide folgt der Quest {quest:1472}, die du genommen hast. {npc:5909} bietet beide Zweige von {zone:1454} an: Nimm beide.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Auf Stufe 20: der Sukkubus und der Inkubus von Forever, sein männliches Gegenstück, jeweils mit einem Seelenbeutel für deine Splitter.",
		["Back to {npc:5675} with Dalin's and {npc:5683}'s hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "Zurück zu {npc:5675} mit Dalins und {npc:5683}s Herzen. Er gibt dir {item:6286}: Geh zum Beschwörungskreis unter ihm hinunter, stell dich darauf und benutze sie. Beschwöre zuerst deinen Leerwandler und halte den Kampf auf dem Kreis, sonst töten ihn vielleicht die Wachen und der Kill zählt nicht. Gewinnt er, benutze die Herzen erneut; behalte sie, {npc:5675} nimmt sie zurück.",
		["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "Zurück zu {npc:5675} mit den Herzen der Liebenden, platziere dann {item:190181} auf demselben Kreis und besiege den Inkubus, den sie rufen (Stufe 20, kein Elite; er kann dich bezaubern). Behalte die Herzen: {npc:5675} nimmt sie zurück.",
		["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "Zurück zu {npc:5875} mit dem Anhänger. Er gibt dir {item:6626}: Bring ihn über {object:172960} zum Zelt von {npc:3216}, stell dich auf den violetten Kreis und benutze ihn. Beschwöre zuerst deinen Leerwandler und lass ihn tanken: Der Sukkubus (Stufe 20, kein Elite) bezaubert und peitscht; halte deinen Schaden über Zeit auf ihm. Gewinnt er, benutze den Anhänger erneut. Behalte den Anhänger: {npc:5875} nimmt ihn zurück.",
		["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "Zurück zu {npc:5875} mit dem Schal, benutze dann {item:190232} auf demselben Kreis in Neerus Zelt und besiege den Inkubus, den er ruft (Stufe 20, kein Elite), während dein Leerwandler tankt. Behalte den Schal: {npc:5875} nimmt ihn zurück.",
		["Silverpine hearts"] = "Herzen aus Silberwald",
		["Succubus and Incubus (Horde)"] = "Sukkubus und Inkubus (Horde)",
		["Take the road west from the Crossroads into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "Nimm die Straße von den Crossroads nach Westen in {zone:1442} und, kurz hinter der Grenze, den schwachen Pfad nach links (Süden) hinauf: {area:2539} ist von der Hauptstraße aus nicht erreichbar. {npc:4197} gibt dir ihren Trank für {npc:5911}.",
		["the incubus"] = "der Inkubus",
		["the succubus"] = "der Sukkubus",
		["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 24 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} liegt im südlichen {zone:1440}, südwestlich von {area:431}. Die Schattendickichtsteinrücker und Schattendickichtborkenreißer (Stufe 25-27) rund um den See lassen {item:190232} bei etwa jedem zwanzigsten Kill fallen, und der einzelne {npc:3931} (30) kann es auch fallen lassen: Plane eine gute Zahl an Kills ein, deshalb wartet der Guide zuerst auf Stufe 24 (Forever hat diese Quest auf Stufe 27 gesetzt); ist der Sukkubus bereits gebunden, kannst du sie dir für dein Leveln in {zone:1440} in deinen Zwanzigern aufheben. Sie respawnen in fünf Minuten.",
		["{item:6286}, on the circle below {npc:5675}"] = "{item:6286}, auf dem Kreis unter {npc:5675}",
		["{item:6626}, on the circle in Neeru's tent"] = "{item:6626}, auf dem Kreis in Neerus Zelt",
		["{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart."] = "{npc:185333} (Stufe 22) arbeitet als Schneiderin für die Magier von {area:279} in {area:233}, im östlichen Silberwald: Die Magier um sie herum sind feindlich. {npc:5682} (Stufe 20, kein Elite) patrouilliert nahe {area:230} im äußersten Süden. Beide sind allianzfreundliche Menschen: Sie anzugreifen kann dich für PvP markieren. Jeder lässt sein Herz fallen.",
		["{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP."] = "{npc:185334} (Stufe 22) arbeitet in {area:392}, an der Küste des {zone:1413}, an einer von zwei Stellen in der Stadt: Nimm das Luftschiff nach {zone:1411} und geh nach Süden, oder flieg von {zone:1454} aus. Er ist ein allianzfreundlicher Mensch: Ihn anzugreifen kann dich für PvP markieren.",
		["{npc:185335}, at the circle below {npc:5675}"] = "{npc:185335}, am Kreis unter {npc:5675}",
		["{npc:185335}, at the circle in Neeru's tent"] = "{npc:185335}, am Kreis in Neerus Zelt",
		["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363} führt {object:173018} an der Hauptstraße östlich von {object:172960}. Er bittet dich, seine Gefährtin Krilge in {zone:1440} zu suchen.",
		["{npc:3464} waits in front of the inn at the Crossroads. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464} wartet vor dem Gasthaus an den Crossroads. Er schickt dich weiter zu {npc:4197} in {area:2539}, in {zone:1442}.",
		["{npc:5683} (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "{npc:5683} (Stufe 22, kein Elite; in älteren Daten Comar) wandert im Norden der {zone:1437} direkt hinter {area:881}, rechts, wenn du von der Brücke kommst. Geh von {zone:1458} aus durch {area:287} und {zone:1417}, wo die Mobs Stufe 30 und höher haben. Sie anzugreifen markiert dich für PvP.",
		["{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads."] = "{npc:5910} lebt in einer Hütte auf den Klippen an der Westseite der Stadt, über {object:172982}: Steig den Windreiterturm hinauf, überquere oben die Brücke nach Westen und biege dahinter rechts ab. Sie schickt dich zu den Crossroads.",
		["{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "{npc:5911} steht bei {area:378}, südlich der Crossroads die Straße hinunter. Er schickt dich nach Norden zum Stacheleber-Lager, wo Dogran gefangen gehalten wird: das Lager mit zwei nebeneinander stehenden Hütten, nordwestlich eines Täuschungslagers, dessen Hütten getrennt stehen. Ein seltener Stacheleber der Stufe 22 (Elite) bewacht manchmal die Hütten: Schick deinen Leerwandler hinein, opfere ihn notfalls, und sprich mit Dogran. Er gibt dir einen Anhänger für {npc:5875}. Behalte ihn.",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "Die Version von {object:1661}, für Hexenmeister, die {quest:1472} von {npc:5675} statt der von {npc:5875} genommen haben. Mit Stufe 20 schickt dich {npc:5675} im {object:36082} zu {npc:5693} in der Nähe. {npc:5693} zeigt dir ein Bild jeder Beute und bietet beide Zweige an: Nimm beide.",
		["{quest:1474}: succubus ({zone:1458})"] = "{quest:1474}: Sukkubus ({zone:1458})",
		["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513}: Sukkubus ({zone:1454})",
		["{quest:65597}: incubus ({zone:1458})"] = "{quest:65597}: Inkubus ({zone:1458})",
		["{quest:65604}: incubus ({zone:1454})"] = "{quest:65604}: Inkubus ({zone:1454})",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Eine Kugel für die Nebenhand oder ein Stab für Ende 30, über den Weg des Teufelshunds oder der Höllenbestie, deine Wahl.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "Mit 35 schickt dich {npc:3326} in {object:172960} zu {npc:6266} in {area:392}.",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "Mit 35 schickt dich {npc:4563} in {object:36082} zu {npc:6266} in {area:392}. Der Zeppelin aus {zone:1420} fliegt nach {zone:1411}.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "Mit 35 schickt dich {npc:461} in {object:2164} in {object:2101} zu {npc:6266} in {area:392}.",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "Mit 35 schickt dich {npc:5172} in {zone:1455} zu {npc:6266} in {area:392}.",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "Zurück zu {npc:6266} im Turm über {area:392} mit der gereinigten Kugel. Auf dem Teufelshund-Pfad nimm ihre letzte Quest an und warte neben ihr, während sie {item:15108} fertigstellt (greif sie nicht an: Das Questlog zählt es als Kill), sprich sie dann noch einmal an und wähle die Nebenhand-Kugel oder den Stab.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "Zurück zu {npc:6266} im Turm über {area:392} zuerst mit dem Geist und dem Edelstein: Ihre Kugel entsteht daraus.",
		["Choose an acolyte"] = "Wähle einen Akolythen",
		["On the infernal path, accept her last quest and wait beside {npc:6266} while she completes the {item:15107}, then speak to her again and pick the off-hand orb or the staff."] = "Auf dem Höllenbestien-Pfad nimm ihre letzte Quest an und warte neben {npc:6266}, während sie {item:15107} fertigstellt, sprich sie dann noch einmal an und wähle die Nebenhand-Kugel oder den Stab.",
		["Orb of Orahil"] = "Kugel von Orahil",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "Such dir einen Akolythen aus: Du kannst nur eine ihrer Quests nehmen. Der Teufelshund-Pfad von {npc:6254} endet mit dem Orb oder {item:15106}, den Schattenversionen; der Höllenbestien-Pfad von {npc:6252} mit dem Orb oder {item:15105}, ziemlich dieselben Gegenstände auf der Feuerseite. Die meisten Hexenmeister setzen auf Schatten, vergleiche aber zuerst die vier in ihren Tooltips. Der Guide folgt dem, den du nimmst. Behalte den Rubin oder den Smaragd: Er wird zurückgegeben.",
		["The demon's spirit"] = "Der Geist des Dämons",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["Wait beside {npc:6266} while she makes the orb"] = "Warte neben {npc:6266}, während sie die Kugel herstellt",
		["{area:602} fills south-central {zone:1443}, east of {area:2408}. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the {item:7291} every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with {spell:1120}: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)."] = "{area:602} füllt das südliche Zentrum von {zone:1443}, östlich von {area:2408}. Die Burning Blade Summoners (Stufe 38-39, Hexenmeister mit Wichteln) tragen jedes Mal {item:7291} bei sich. Bring für den Geist deinen Dämon mit deinem Schaden über Zeit auf niedrige Gesundheit, kanalisiere dann den Rubin oder den Smaragd auf ihn und kanalisiere weiter, während er stirbt, wie bei {spell:1120}: Der Edelstein verursacht selbst keinen Schaden. Der Rubin wirkt auf die Teufelshunde des Zirkels: die zwei Mana Eaters (37-38) im Norden und die Mage Hunters (38) und Ley Hunters (39) weiter südlich. Der Smaragd wirkt auf die Lesser Infernals (36-37, sechzehn Stück, feuerresistent).",
		["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648}, von {npc:4678}, {npc:4681} oder {npc:4685}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, von einer {npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}, von den Beschwörern der Burning Blade",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}: Er gibt dir {item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}: Sie gibt dir {item:12647}",
		["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266} und ihre zwei Akolythen stehen im Turm von {npc:6251} auf dem Hügel über {area:392}.",
		["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 38. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546} lebt auf ihrer Farm mitten in {zone:1445}, südlich der Straße vom {zone:1413} und südwestlich von Theramore; ein Geistheiler steht daneben. Schlammwühler, ein Krokilisk der Stufe 45, patrouilliert an den Bächen direkt nordöstlich. Gib die Kugel jetzt ab; „Die Säuberung der Kugel von Orahil“ wartet auf Stufe 38. Bevor du sie annimmst, räum die Spinnen und Krokilisken rund um ihr Gehege. Mit dem Annehmen startet ein 3-Minuten-Timer: Sie geht zum Gehege und lässt {npc:6549} heraus. Er ist ein Elite (Stufe 40): Eine Gruppe wird empfohlen; ein Hexenmeister um Stufe 40 kann ihn mit Furcht oder {spell:710} und Schaden über Zeit solo schaffen, mit Stufe 38 nimm einen Freund mit. Der Timer läuft nach dem Kill weiter, gib also sofort ab. Läuft die Zeit ab, brich die Quest ab und nimm sie bei {npc:6546} erneut an.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "Eine seltene Nebenhand-Kugel oder ein Stab für deine Zwanziger, für Fragmente aus zwei Dungeons.",
		["Back to {npc:6247}"] = "Zurück zu {npc:6247}",
		["Choose the off-hand {item:6898} or the two-handed {item:15109}."] = "Wähle die Nebenhand {item:6898} oder den Zweihandstab {item:15109}.",
		["Soran'ruk Fragments, from the Twilight Acolytes inside"] = "Soran'ruk-Fragmente, von den Twilight Acolytes drinnen",
		["{area:236} (level 22-30, a group of five) stands on the hill south of the {area:228}. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop."] = "{area:236} (Stufe 22-30, Gruppe aus fünf) liegt auf dem Hügel südlich von {area:228}. Befreie den Gefangenen in den Zellen rechts vom Eingang, dann öffnet er dir den Weg in den Hof. Die Shadowfang Darksouls (Stufe 20-21, Elite) sind nicht im Hof: Sie laufen in den Hallen dahinter, die nach links gekrümmte Rampe hinauf und im Gebäude danach. Etwa zwölf stehen in einem Durchlauf, und eine von fünf lässt das Große Fragment fallen, töte also jede Darksoul und wiederhole den Durchlauf, falls es nicht fällt.",
		["{area:2797} (level 24-32, a group of five) opens in the ruins on the north-west coast of {zone:1440}, under the water at {area:414}. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around {npc:4832} and the altar before {npc:4829}; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest."] = "{area:2797} (Stufe 24-32, Gruppe aus fünf) öffnet sich in den Ruinen an der Nordwestküste von {zone:1440}, unter Wasser bei {area:414}. Die Twilight Acolytes (Stufe 24-25, Elite, Heiler) stehen in den letzten Hallen, um {npc:4832} und den Altar vor {npc:4829}; jeder lässt ein Fragment fallen, aber pro Durchlauf spawnen nur drei und sie kommen zwei Stunden nicht zurück, ein Durchlauf reicht also für einen Hexenmeister: Töte sie zuerst, bevor sie die anderen heilen.",
		["{item:6915}, from the Shadowfang Darksouls inside"] = "{item:6915}, von den Shadowfang Darksouls drinnen",
		["{npc:6247} camps beside {npc:6244}, at a tent just north-east of {area:378} in the southern {zone:1413}. Alliance warlocks reach him from {area:392} or Theramore; Horde ones head south from the Crossroads. He wants fragments from two dungeons: take the quest before your {area:2797} and {area:236} runs."] = "{npc:6247} lagert neben {npc:6244} an einem Zelt direkt nordöstlich von {area:378} im südlichen {zone:1413}. Allianz-Hexenmeister erreichen ihn von {area:392} oder Theramore aus; Horde-Hexenmeister gehen von den Crossroads nach Süden. Er will Fragmente aus zwei Dungeons: Nimm die Quest vor deinen Durchläufen von {area:2797} und {area:236}.",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Eine seltene Schildhand für Stufe 50+ von {npc:14469} und {npc:14470} in {zone:1448}, dem Lager, das auch Die Bitte eines Wichtels anbietet.",
		["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "Mit Stufe 50 warten {npc:14469} und sein Wichtel {npc:14470} auf einer Anhöhe im mittleren {zone:1448} direkt nordöstlich von {area:1997}: Wenn du von Süden über die Brücke von {area:1765} nach Norden kommst, stehen sie östlich abseits der Straße, hinter ein paar Schlämmen. {npc:14469} schickt dich zu {npc:14470} neben ihm, der drei Flawless Fel Essences von drei Orten will.",
		["Back to {npc:14469}"] = "Zurück zu {npc:14469}",
		["Back to {npc:14470}. He hands you the {item:18626}: keep it, it wakes the infernal {npc:14467}."] = "Zurück zu {npc:14470}. Er gibt dir {item:18626}: Behalte es, es erweckt die Höllenbestie {npc:14467}.",
		["The Felguard Sentries (level 54) walk around the {area:72} in the south of the {zone:1419}, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest."] = "Die Felguard Sentries (Stufe 54) laufen um {area:72} im Süden von {zone:1419}, jeweils mit einem Teufelsjäger. Lass die Servants of Razelikh der Stufe 57 in Ruhe: Ohne ihre eigene Quest lassen sie sich nicht töten.",
		["The Legashi satyrs (level 51-53) hold the Legash Encampment on {zone:1447}'s northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly."] = "Die Legashi-Satyrn (Stufe 51-53) halten das Legash Encampment an der Nordküste von {zone:1447}. Jede Sorte lässt die Essenz bei drei von vier Kills fallen; die Satyrn verbrennen Mana und die Hellcallers lassen Feuer regnen, pull sie also einzeln.",
		["{area:1763} lies just south of {area:1997}, west of the road. The guide waits for level 53 first: its Legionnaires are 55. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} liegt direkt südlich von {area:1997}, westlich der Straße. Der Guide wartet zuerst auf Stufe 53: Seine Legionäre sind 55. Von seinen zwei Höhlen ist {area:1770} die nördliche, weiter oben am Hügel; die andere hat keine Legionäre. Die Tunnel von {area:1770} verlaufen nach Norden unter die Hügel, und die Legionäre von Jaedenar (Stufe 55) stehen in den tieferen Hallen, von den ersten Rampen bis zur Kammer von {npc:9516}; sie führen gegen jeden im Nahkampf einen Aufwärtshaken aus. Drei von vier Kills ergeben die Essenz, aber es spawnen nur etwa elf: Kämpf dich hinein und warte notfalls einen Respawn von fünf Minuten ab. Die Kultisten von {area:1763} und {area:1770} sind alle feindlich.",
		["{item:18626}, at {object:179677}"] = "{item:18626}, bei {object:179677}",
		["{npc:14467}' remains lie in {area:1766}, the burnt crater north of {npc:14469}: follow the road north from his camp; the remains lie a little east of it. Use the {item:18626} beside them and wait for him to rise. {npc:14467} is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull {npc:14467} away from it. He always drops his core. Lost the {item:18626}? Abandon the quest and take it again from {npc:14470}."] = "Die Überreste von {npc:14467} liegen in {area:1766}, dem verbrannten Krater nördlich von {npc:14469}: Folge der Straße von seinem Lager nach Norden; die Überreste liegen ein Stück östlich davon. Benutze {item:18626} neben ihnen und warte, bis er sich erhebt. {npc:14467} ist ein Elite (Stufe 55): Eine Gruppe wird empfohlen; ein Hexenmeister ab Stufe 55 kann ihn mit Furcht und Schaden über Zeit oder mit Dämonen versklaven solo schaffen, aber Feuerzauber wirken nicht auf ihn und er schleudert dich zurück. Stirbst du, heilt er sich voll; er erhebt sich drei Minuten nach seinem Tod erneut. Eine Elite-Höllenbestie patrouilliert am Teich südlich der Überreste: Zieh {npc:14467} von ihr weg. Er lässt seinen Kern immer fallen. {item:18626} verloren? Brich die Quest ab und nimm sie bei {npc:14470} erneut an.",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "Ein seltener Schildhand-Gegenstand mit 60, {npc:14463}s Lohn dafür, dass du einen {npc:12396} in den {zone:1419} einfängst.",
		["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "Mit Stufe 60 wartet {npc:14463} im {area:73}, der dämonenerfüllten Senke im Westen von {zone:1419}. Die Scar ist voller hart zuschlagender Elites: Setz zuerst einen Seelenstein auf dich, halte dich dann beim Hineingehen an die rechte Wand oder reite beritten hindurch. {npc:14463} gibt dir zwei Aufträge auf einmal.",
		["Back to {npc:14463}"] = "Zurück zu {npc:14463} dem Klapprigen",
		["Hand both in to {npc:14463} and take the {item:18601}. Find a {npc:12396} (level 61, elite) standing alone in the {area:73}, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his {spell:45} can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the {item:18605}: click it. If the channel breaks, kill him or run, and try another."] = "Gib beide bei {npc:14463} ab und nimm {item:18601} an. Such einen {npc:12396} (Stufe 61, Elite), der allein im {area:73} steht, eröffne aus etwa 30 Metern mit deinem Leerwandler auf ihm und kanalisiere das Gefängnis etwa 20 Sekunden lang auf ihn: Er greift dich an, um sich zu befreien, und sein {spell:45} kann die Kanalisierung unterbrechen, opfere also notfalls den Leerwandler für dessen Schild. Eine Gruppe wird empfohlen: Ein zweiter Spieler zum Tanken macht es leicht. Ist die Kanalisierung beendet, wird er zu {item:18605}: Klicke ihn an. Bricht die Kanalisierung ab, töte ihn oder lauf weg und versuch einen anderen.",
		["The Hederine demons (level 57-60, elite) hold {area:2256} in the far south of {zone:1452}: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their {spell:7645}). A warlock can solo them one at a time with Fear or {spell:710} and damage over time, but slowly. Any of them can drop the Tears, four kills in five."] = "Die Hederine-Dämonen (Stufe 57-60, Elite) halten {area:2256} im äußersten Süden von {zone:1452}: Eine Gruppe wird empfohlen. Zwei Slayers bewachen die Schlucht hinter der Brücke; der westliche Tunnel führt zu weiteren Initiates, den leichtesten von ihnen (achte auf ihr {spell:7645}). Ein Hexenmeister kann sie einzeln mit Furcht oder {spell:710} und Schaden über Zeit solo schaffen, aber langsam. Jeder von ihnen kann die Tränen fallen lassen, bei vier von fünf Kills.",
		["The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, {area:2577}'s eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at {area:2518} needs the {item:18249}, which drops inside this wing; until someone has it, go in by {area:2577}'s main gate in central {zone:1444}."] = "Die Wildspawn-Satyrn (Stufe 55-57, Elite) füllen das Warpwood Quarter, den Ostflügel von {area:2577}: Bring eine Gruppe aus fünf mit. Vier von fünf lassen ein Blut fallen, aber sie kommen zwei Stunden nicht zurück und ein vollständiges Räumen reicht vielleicht nicht für fünfzehn; setz zurück und wiederhole den Durchlauf. Die Hintertür bei {area:2518} braucht {item:18249}, der in diesem Flügel fällt; bis jemand ihn hat, geh durch das Haupttor von {area:2577} im zentralen {zone:1444} hinein.",
		["{item:18601}, on a {npc:12396}"] = "{item:18601}, auf einen {npc:12396}",
		["{item:18603}, from the Wildspawn inside"] = "{item:18603}, von den Wildspawn drinnen",
		["{item:18605}, click it"] = "{item:18605}, anklicken",
} end)()
t.guides["forever/class/warlock/voidwalker-alliance"] = (function() return {
		["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "Mit Stufe 10 schickt dich {npc:6120}, der Hexenmeisterlehrer in {object:32383} von {zone:1455}, zu {npc:6122} in {zone:1453}. Nimm die {area:2257} ab {object:171524}. Bietet {npc:6120} sie nicht an, geh trotzdem zu {npc:6122}: Er gibt dir trotzdem die nächste Quest.",
		["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "Mit Stufe 10 schickt dich {npc:6121}, im Keller des Lion's Pride Inn in {area:87} (die Treppe nach unten ist im Hinterzimmer hinter dem Fleischertisch), zu {npc:6122} in {zone:1453}.",
		["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "Zurück zu {npc:6122}. Er gibt dir {item:6928}. Der Kreis ist schwer zu finden: Nimm die Treppe hinter {npc:6122} nach unten; ein Stück weit im untersten Gang führt links eine Seitentreppe in einen Raum mit einem leuchtenden violetten Kreis in der Mitte. Stell dich darauf und benutze das Halsband. Der Leerwandler (Stufe 10, kein Elite) wird unter 30 % Gesundheit gefährlich: {spell:14868}, Verderbnis und {spell:348} mit deinem Wichtel darauf, Furcht, wenn er nah kommt. Besiegt er dich, benutze das Halsband erneut. Behalte das Halsband: {npc:6122} nimmt es zurück.",
		["Voidwalker (Alliance)"] = "Leerwandler (Allianz)",
		["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "Dein Tank-Dämon auf Stufe 10: der Leerwandler, nach dem Halsband einer dunklen Zauberin und einem Kampf in der Krypta von {npc:6122}.",
		["{item:6928}, on the circle in the crypt"] = "{item:6928}, auf dem Kreis in der Krypta",
		["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}, Keller des Lion's Pride Inn",
		["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881} (Stufe 9) ist im Bauernhaus am {area:62}, im Südosten von Elwynn nahe der Straße nach Redridge. {npc:473} (Stufe 10) und ein Krieger stehen bei ihr und greifen in den Kampf ein; Morgan hebelt aus und geht auf deinen Wichtel los, halte ihn also in Furcht. Setz deinen Schaden über Zeit zuerst auf {npc:881}, schick die anderen in Furcht und plündere ihr Halsband, bevor du sie erledigst: Es bleibt deins, auch wenn du danach stirbst. Sie wirft aus der Distanz Feuerbälle und ist drei Minuten nach ihrem Tod wieder da. Hab die Quest, bevor du sie tötest, sonst fällt das Halsband nicht.",
		["{quest:1685} (Humans)"] = "{quest:1685} (Menschen)",
		["{quest:1715} (Gnomes)"] = "{quest:1715} (Gnome)",
		["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715} ist die Taverne im {object:2101}; {npc:6122} ist in ihrem Keller, die Treppe drinnen hinunter.",
} end)()
t.guides["forever/class/warlock/voidwalker-horde"] = (function() return {
		["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "Mit Stufe 10 schickt dich {npc:3294} zu {npc:5875}. Er steht draußen hinten an der Kaserne von {area:362}, dem großen Gebäude an der Ostseite der Stadt (nicht das Gasthaus), ein paar Schritte von {npc:3172}, dem Hexenmeisterlehrer. {npc:5875} steht bei den älteren Hexenmeistern in {object:172960}, der Höhle unter {object:172982} von {zone:1454}. Ein Orc oder Troll, der in {zone:1420} levelt, kann stattdessen die Version von {zone:1458} bei {npc:5724} in {area:159} nehmen (die Schritte zu {zone:1458} weiter unten): Du kannst nur eine der beiden machen.",
		["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "Mit Stufe 10 schickt dich {npc:5724}, im Obergeschoss von {area:2119} in {area:159}, zu {npc:5675}: die Version für die Untoten und für Orcs und Trolle, die stattdessen in {zone:1420} leveln und nicht {npc:5875} nehmen. {npc:5675} steht im {object:36082} von {zone:1458}, beim Temple of the Damned.",
		["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "Zurück zu {npc:5675}. Er gibt dir {item:6284}: Geh die Treppe von ihm aus hinunter zum Beschwörungskreis und benutze sie, während du darauf stehst. Bekämpfe den Leerwandler (Stufe 10, kein Elite) auf dem Kreis: Wenn er davonwandert, töten ihn vielleicht die Stadtwachen und der Kill zählt nicht. {spell:14868}, Verderbnis und {spell:348} mit deinem tankenden Wichtel erledigen ihn; unter 30 % schlägt er härter zu. Verlierst du, benutze die Runen erneut. Behalte die Runen: {npc:5675} nimmt sie zurück.",
		["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "Zurück zu {npc:5875}. Er gibt dir {item:7464}: Bring sie über {object:172960} zum Zelt von {npc:3216}, stell dich auf den violetten Kreis auf seinem Boden und benutze sie. Der Leerwandler (Stufe 10, kein Elite) schlägt bei 30 % Gesundheit hart zu und verschwindet nach drei Minuten, fang also sofort an: {spell:14868}, Verderbnis und {spell:348}, schick deinen Wichtel hinein und schick den Leerwandler in Furcht, wenn du eine Verschnaufpause brauchst. Besiegt er dich oder verschwindet er, sind die Glyphen nicht verbraucht: Benutze sie erneut auf dem Kreis. Behalte die Glyphen: {npc:5875} nimmt sie zurück.",
		["The Scarlet tower stands in the fields west of the {zone:1458}'s ruins (not the tower near {area:154}). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. {npc:1662} (level 9) and a {npc:1537} guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it."] = "Der Scharlachrote Turm steht in den Feldern westlich der Ruinen von {zone:1458} (nicht der Turm bei {area:154}). Das Grimoire liegt in der kleinen Truhe im Erdgeschoss, unter der Treppe; ignoriere die Truhe oben. {npc:1662} (Stufe 9) und ein {npc:1537} bewachen sie: Töte sie oder schick den Eiferer in Furcht, während du dich um Perrine kümmerst. Scarlet Missionaries und Zealots (Stufe 7-9) laufen in den Feldern um den Turm. Die Truhe ist drei Sekunden, nachdem jemand sie geöffnet hat, wieder da.",
		["Voidwalker (Horde)"] = "Leerwandler (Horde)",
		["Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle."] = "Dein Tank-Dämon auf Stufe 10: der Leerwandler, nach einem gestohlenen Buch und einem Kampf an einem Beschwörungskreis.",
		["{area:817} is the cave in the cliffs just east of {zone:1454}'s gate. Inside, take the right-hand ramp up and follow it to the top: the {object:58595} sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and {npc:3204}, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet."] = "{area:817} ist die Höhle in den Klippen direkt östlich des Tors von {zone:1454}. Nimm drinnen die rechte Rampe nach oben und folge ihr bis zum Ende: {object:58595} liegt auf dem oberen Felsvorsprung, der vom unteren Boden aus nicht erreichbar ist. Die Höhle ist voll von Burning Blade Apprentices und Fanatics (Stufe 9-11, viele mit Leerwandlern), die schnell respawnen, und {npc:3204}, ein Burning-Blade-Hexenmeister der Stufe 14, steht nahe dem Versteck. Alte Notizen nennen ihn Elite; die Daten von Forever führen ihn als normal. Mit 10 ist es allein schwer: Pull ein Pack nach dem anderen und schick den überzähligen in Furcht, warte bis Stufe 11 oder geh mit einem Freund. Im Versteck liegt immer die Tafel.",
		["{item:6284}, on the circle below {npc:5675}"] = "{item:6284}, auf dem Kreis unter {npc:5675}",
		["{item:6285}, in {object:37098}"] = "{item:6285}, in {object:37098}",
		["{item:6535}, in the {object:58595}"] = "{item:6535}, in {object:58595}",
		["{item:7464}, on the circle in Neeru's tent"] = "{item:7464}, auf dem Kreis in Neerus Zelt",
		["{npc:5724}, upstairs in the {area:159} inn"] = "{npc:5724}, im Obergeschoss des Gasthauses von {area:159}",
		["{quest:1506} (Orcs and Trolls)"] = "{quest:1506} (Orcs und Trolle)",
} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "Mit 20 schickt dich {npc:3041}, der Kriegerlehrer von {zone:1456}, zu {npc:6394} in {area:378}.",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "Mit 20 schickt dich {npc:3354} im {object:172958} zu {npc:6394} in {area:378}.",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "Mit 20 schickt dich {npc:4595}, ein Kriegerlehrer in {zone:1458}, zu {npc:6394} in {area:378}.",
		["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "Zurück zu {npc:5878} auf {area:1699}. {quest:1848} ist das erste Teil; danach schickt er dich zu drei Handwerkern, einer pro Teil: Nimm alle drei.",
		["Fly to {area:378}. {npc:6394} stands in the hut with the leatherworking and tailoring trainers."] = "Flieg nach {area:378}. {npc:6394} steht in der Hütte mit den Lehrern für Lederverarbeitung und Schneiderei.",
		["Hillsbrad Miners"] = "Minenarbeiter von Hillsbrad",
		["Iron Bars"] = "Eisenbarren",
		["Iron Bars: {npc:8673}"] = "Eisenbarren: {npc:8673}",
		["Roogug in {area:1717}"] = "Roogug in {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 26 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug ist ein Elite-Stacheleber (Stufe 28) in {area:1717}, dem Dungeon am Südende des {zone:1413}; ein Dungeon für fünf Spieler: Du brauchst eine Gruppe aus fünf, seine Wachen kommen mit ihm. Der Guide wartet zuerst auf Stufe 26. Nimm drinnen an der ersten Gabelung den linken Weg, überquere die Rankenbrücke über den Schweinepferchen, geh am Raum mit dem großen Kessel vorbei: Er wartet im Raum rechts. Er wirkt {spell:403} und ruft Erdrumpler. Das Fläschchen fällt immer.",
		["Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way."] = "Beginnt jetzt mit Stufe 20 bei deinem Lehrer; vier Rüstungsteile mit Stufe 30 (Brustpanzer, Helm, Handschuhe, Beinschienen), unterwegs ein Schild.",
		["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "Nimm das Luftschiff von {zone:1454} nach {zone:1420}; {npc:6411} arbeitet im {object:36078} von {zone:1458}. Sie will 8 Sturdy Dragonmaw Shinbones.",
		["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "Die Dragonmaw-Orcs (Stufe 26-30) lagern mitten in der {zone:1437}; geh von {area:321} in Arathi nach Süden über {area:881} ({area:150} gehört der Allianz). Mit {quest:1846} von {npc:6411} im Questlog lässt jeder Raider, Swamprunner, Centurion, Shadowwarder und Bonewarder {item:7131} fallen (ohne die Quest lassen sie nichts fallen): Rechtsklick zum Testen, und etwa eines von vier erweist sich als stabil, der Rest zerbricht, rechne also mit 30 oder mehr Kills für 8. Du kannst auch in Bewegung oder im Kampf testen. Die Orcs rufen bei 15 % um Hilfe; Raiders werfen Netze, Centurions setzen Schildhiebe ein, Shadowwarders wirken {spell:686}, Bonewarders erwecken Skelette.",
		["The satyrs of {area:430}, north-east of {area:431} ({area:429}, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A {area:429} satyr at 15% health may cast {spell:6925} and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%."] = "Die Satyrn von {area:430}, nordöstlich von {area:431} ({area:429}, Stufe 28-30), und die Felmusk-Satyrn nordwestlich des Postens (25-27) lassen bei vier von fünf Kills einen Huf fallen. Ein Satyr von {area:429} mit 15 % Gesundheit wirkt vielleicht {spell:6925} und heilt sich voll: Erledige ihn schnell oder betäube ihn. Hellcallers werfen aus 40 Metern Feuerbälle; Felmusk-Satyrn stinken im Nahkampf und rufen bei 15 % um Hilfe.",
		["The {npc:6167} (level 28, not elite, larger than the young ones around her) roams the south edge of the {area:465} in south-west Stonetalon, near the road to {zone:1443}. She is the only one: she returns 5 minutes after dying and drops the {item:6840} four kills in five. She spits {spell:3396} from 30 yards."] = "Die {npc:6167} (Stufe 28, kein Elite, größer als die Jungen um sie herum) streift am Südrand von {area:465} im Südwesten von Stonetalon, nahe der Straße nach {zone:1443}. Es gibt nur diese eine: Sie kommt 5 Minuten nach ihrem Tod zurück und lässt {item:6840} bei vier von fünf Kills fallen. Sie spuckt aus 30 Metern {spell:3396}.",
		["You have 30 minutes, and each {item:7119} rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the {area:390} south of {area:378}; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. {item:7120}, a shield, is the reward."] = "Du hast 30 Minuten, und jedes {item:7119} verrottet 15 Minuten, nachdem du es geplündert hast, nimm die Quest also nur an, wenn du bereit bist (Ausloggen hält die Uhr nicht an). Die Silithid Mounds sind über das {area:390} südlich von {area:378} verstreut; jeder Silithid lässt eine Antenne fallen. Creepers (Stufe 20-21) und Grubs sind am leichtesten: Swarmers (21-22) rufen kleine Schwärme und Creepers legen Eier, aus denen Adds schlüpfen. Im östlichen Teil des Feldes gibt es viele Creepers. Die Belohnung ist {item:7120}, ein Schild.",
		["You need 10 Iron Bars. Miners smelt them from {item:2772} (one ore a bar, {spell:3307} at {skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "Du brauchst 10 Eisenbarren. Bergbauer schmelzen sie aus {item:2772} (ein Erz pro Barren, {spell:3307} bei {skill:186} 125); alle anderen kaufen sie im Auktionshaus in {zone:1454}.",
		["You need 10 {item:7127}. The guide waits for level 25 first. The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "Du brauchst 10 {item:7127}. Der Guide wartet zuerst auf Stufe 25. Die Minenarbeiter von Hillsbrad (Stufe 26-27) arbeiten in der Mine in den Hügeln westlich von {area:271} und lassen den Azurit bei vier von fünf Kills fallen; sie kämpfen in {spell:71}, zerreißen deine Rüstung und rufen bei 30 % Gesundheit um Hilfe. Flieg nach {area:272} und geh nach Südwesten.",
		["You need 15 Smoky Iron Ingots. The {area:2160} lies at the east end of {area:461}, east of {area:460}; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast {spell:116}."] = "Du brauchst 15 Smoky Iron Ingots. {area:2160} liegt am Ostende von {area:461}, östlich von {area:460}; jeder Windshear-Kobold (Stufe 19-23) lässt bei vier von fünf Kills einen Barren fallen. Stonecutters, Geomancers und Overlords rufen bei niedriger Gesundheit um Hilfe; Geomancers wirken {spell:116}.",
		["from the Dragonmaw orcs: right-click to test it"] = "von den Dragonmaw-Orcs: Rechtsklick zum Testen",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, von {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}, von Roogug",
		["{item:7119}, from the silithid"] = "{item:7119}, von den Silithiden",
		["{item:7126}, from the Windshear kobolds"] = "{item:7126}, von den Windshear-Kobolden",
		["{item:7127}, from the Hillsbrad Miners"] = "{item:7127}, von den Hillsbrad Miners",
		["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads: climb the broad ridge on the north or east side. {quest:1838} is a level 30 quest; take it now and gather on the way. {item:7587} list where each material comes from."] = "Die Hütte von {npc:5878} sitzt auf {area:1699}, östlich der Crossroads: Steig den breiten Grat an der Nord- oder Ostseite hinauf. {quest:1838} ist eine Quest der Stufe 30; nimm sie jetzt an und sammle unterwegs. {item:7587} führt auf, woher jedes Material kommt.",
		["{npc:6408} is in {area:367} on the {zone:1411} coast. He wants 7 Uncloven Satyr Hooves."] = "{npc:6408} ist in {area:367} an der Küste von {zone:1411}. Er will 7 Uncloven Satyr Hooves.",
		["{npc:6410} works on {zone:1456}'s lowest level, close to the blacksmith."] = "{npc:6410} arbeitet auf der untersten Ebene von {zone:1456}, nahe dem Schmied.",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "Mit Stufe 20 schickt dich {npc:5113}, der Kriegerlehrer von {zone:1455}, zu {quest:1698} ins Rotkammgebirge.",
		["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "Mit Stufe 20 schickt dich {npc:5479}, neben {npc:5480} im Gebäude der Kriegerlehrer von {object:2100}, zu {quest:1698} in Redridge.",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "Mit Stufe 20 schickt dich {npc:7315}, der Kriegerlehrer von {zone:1457}, zu {quest:1698} ins Rotkammgebirge.",
		["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "Zurück zu {npc:5413} im {object:28027} für den Brustpanzer. Er schickt dich dann zum Schmied deines Volkes; auch die Teile der anderen zwei Schmiede stehen dir offen: Sprich sie direkt an.",
		["Charred and Galvanized Horns"] = "Verkohlte und Galvanisierte Hörner",
		["Enter the {area:98} and come back"] = "Betritt die {area:98} und komm zurück",
		["Fire Hardened Armor"] = "Feuergehärtete Rüstung",
		["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "Fahr mit der {area:2257} von {zone:1453} nach {zone:1455}. {quest:1704}, ein Gnomenschmied, arbeitet in {object:171524} nahe den Ingenieurlehrern. Er will 20 {item:6848}.",
		["Roogug in {area:1717}"] = "Roogug im Gebiet {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug ist ein Elite-Stacheleber (Stufe 28) in {area:1717}, dem Dungeon am Südende des {zone:1413}; ein Dungeon für fünf Spieler: Du brauchst eine Gruppe aus fünf, und seine Wachen kommen mit ihm. Nimm drinnen an der ersten Gabelung den linken Weg, überquere die Wurzelbrücke, geh am großen leeren Kessel vorbei: Er steht in einer Sackgasse rechts, mit etwa zehn Elites auf dem Weg. Er wirkt {spell:403} und ruft Earth Rumblers. Das Fläschchen fällt immer.",
		["Scorched Spider Fangs"] = "Versengte Spinnenfangzähne",
		["Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths."] = "Beginnt jetzt mit Stufe 20 mit einem Schild; ein Brustpanzer mit 28, dann eine Kettenhaube, Beinschienen und Handschuhe von drei Schmieden.",
		["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. The Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Die Worgen der Nachtheuler in {zone:1431} (Dunkelläufer, Faulreißer, Schattenwirker, Worgs und Besudelte, Stufe 26-31) südlich und westlich von {area:42} lassen {quest:1705} bei vier von fünf Kills fallen. Die Besudelten vergiften und heulen; Faulreißer verursachen {spell:3427}.",
		["The chimaeras live south-west of {area:460} in the {area:465}; the guide waits for level 26 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Die Schimären leben südwestlich von {area:460} in {area:465}; der Guide wartet zuerst auf Stufe 26. Du brauchst 12 Verkohlte Hörner von den Schimärenjungen (Stufe 25-27) und Jungen Schimären (23-25), bei vier von fünf Kills, und {item:6840} von {npc:6167} (28, die große), ebenfalls vier von fünf. Es leben dort nur drei Schimärenjunge, zwei Junge Schimären und eine Matriarchin, jede nach 5 Minuten zurück, rechne also mit Warten. Die Schimärenjungen und die Matriarchin spucken {spell:3396}, die Jungen Schimären wirken {spell:403}. Allianz: Flieg nach {area:467} und geh nach Süden.",
		["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once."] = "Die Panzer liegen auf dem Boden unter den Wyvernnestern bei {area:482} im westlichen {zone:1441}, tiefer in der Schlucht. Es gibt nur neun, und jeder kehrt 3 Minuten nach dem Aufheben zurück, du wirst also warten; einige panzerähnliche Dinge dort lassen sich nicht plündern. Highperch Wyverns (Stufe 28-31) bewachen sie und kommen manchmal zu mehreren.",
		["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and a {item:5996} removes the risk."] = "{quest:1708} wächst auf dem Meeresboden direkt südlich von {area:150}, bei den Murloc-Hütten und einem Schiffswrack: acht dort und zwei südöstlich des Hafens, jede nach 3 Minuten zurück, du wirst also auf Respawns warten, um 20 zu erreichen. Die Murlocs können dich unter Wasser einnetzen: Achte auf deinen Atem, und {item:5996} beseitigt das Risiko.",
		["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "Du hast eine Stunde, und {spell:8553} von {npc:6166} macht dich 8-10 Minuten betrunken. Lauf nordwestlich in {area:98} hinein, halte dich dicht an der Felswand, um die meisten Gnoll-Packs zu umgehen, und geh bis zur ersten Gabelung hinein; komm dann zurück zu {npc:6166} (vom Grat aus kannst du nach {area:69} hinunterspringen). Wenn du stirbst und deinen Geist freilässt, scheitert die Quest: Brich sie ab, und {npc:6166} gibt sie dir erneut.",
		["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang. They poison; back in 5 minutes."] = "Du brauchst 50 Fangzähne. Die Leech Stalkers und Cave Stalkers (Stufe 21-22) kriechen mitten in der {zone:1437}, nördlich von {area:836}; jeder lässt einen Fangzahn fallen. Sie vergiften; nach 5 Minuten wieder da.",
		["{item:6839}, from the young chimaeras"] = "{item:6839}, von den jungen Chimären",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, von {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}, von Roogug",
		["{item:6845}, from {npc:6170}"] = "{item:6845}, von {npc:6170}",
		["{item:6848}, from {quest:1708}"] = "{item:6848}, von {quest:1708}",
		["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416} führt den Waffenladen im Nordwesten des {object:28027}, ein kurzer Weg von {npc:5413}. Er will 20 {quest:1705} und {item:6845}.",
		["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest, with {item:6842} listing what it needs."] = "{npc:5413} arbeitet im Zwergenviertel von Sturmwind. Er nimmt {item:6843} (verloren? Brich die Quest ab, und {npc:6166} gibt dir ein neues) und gibt dir {item:6970}, einen Schild; {quest:1701} ist eine Quest der Stufe 28, {item:6842} führt auf, was sie braucht.",
		["{npc:6170} (level 32, not elite) carries the {item:6845}, four kills in five; the guide waits for level 30 first. He walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. He poisons and howls."] = "{npc:6170} (Stufe 32, kein Elite) trägt {item:6845}, bei vier von fünf Kills; der Guide wartet zuerst auf Stufe 30. Er läuft zwischen dem Inneren und dem Eingang der Mine {area:2161} südöstlich von {area:42} hin und her, warte also am Eingang und zieh ihn nach draußen. Er vergiftet und heult.",
		["{quest:1698} sits in the inn at {area:69}. His test is timed: before you take it, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} sitzt im Gasthaus von {area:69}. Seine Prüfung ist zeitlich begrenzt: Bevor du sie annimmst, räum die Gnolle von Redridge auf dem Weg zu {area:98} in den Hügeln nordwestlich von {area:69}, einschließlich der zwei auf dem Felsen am Höhleneingang (klettere von seiner rechten Seite hinauf).",
		["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703} arbeitet an der Südseite von {area:1660} in {zone:1457}. Er will 20 {quest:1710}.",
		["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}, von den Nightbane-Worgen",
} end)()
t.guides["forever/class/warrior/haggards-weapons"] = (function() return {
		["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "Mit Stufe 10 schickt dich {npc:1229}, der Kriegerlehrer in {area:131}, zu {quest:1679} in {zone:1455}. Jeder Allianz-Krieger darf einen der drei Wege nehmen, nie zwei: Bist du mit 10 sowieso in {zone:1453}? {quest:1638} von {npc:5480} ist die schnellste Haltung (ein Kampf in einer Taverne), danach folgt eine Waffe von Haggard.",
		["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Mit Stufe 10 steht {npc:252377} mit den Lehrern am Westtor von {area:16638}. Ein Kultist, {npc:257196}, hält den Schild ihrer Familie am {area:16629}.",
		["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "Mit Stufe 10 schickt dich {npc:3598}, der Kriegerlehrer in {area:186}, oder {npc:2151}, die auf der Straße westlich von {area:186} patrouilliert, zu {quest:1684} auf {area:1660} in {zone:1457}. Jeder Allianz-Krieger darf einen der drei Wege nehmen, nie zwei: Bist du mit 10 sowieso in {zone:1453}? {quest:1638} von {npc:5480} bringt dieselbe Haltung nach einem Kampf in einer Taverne bei.",
		["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "Mit Stufe 10 schickt dich {npc:913}, der Kriegerlehrer beim Gasthaus in {area:87}, zu {npc:6089} in {zone:1453}; {npc:5480}, die Kriegerlehrerin in {object:2100} von {zone:1453}, bietet sie ebenfalls an.",
		["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "Zurück auf {area:1660}: {npc:4088} gibt dir {item:6812}; {npc:6142} arbeitet auf der fernen Südseite derselben Terrasse, leicht zu übersehen.",
		["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "Zurück zu {npc:252377} in {area:16638}. Sie bringt dir {spell:71} bei und gibt dir {item:275290}, einen Schild dafür. Der Weg von {npc:6090} unten gibt dir trotzdem eine Waffe, sobald du {zone:1453} erreichst.",
		["Back to {npc:294}"] = "Zurück zu {npc:294}",
		["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "Zurück zu {npc:6114} für {spell:71}, dann zu {quest:1680} an {object:32372} mitten in {zone:1455}.",
		["Elunite under {area:442}"] = "Elunite unter {area:442}",
		["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Geh von {area:16638} nach Nordwesten zum {area:16629}. {npc:257196} steht westlich des Schreinzugangs zwischen den Guardians, Spiritcallers und Blademasters des Kults: Pull sie einzeln, bevor du dir ihn vornimmst. Er lässt {item:263993} fallen.",
		["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "Nimm das Boot von {area:702} nach {area:442}. Das Wrack liegt unter Wasser direkt südlich des südlichen Piers von {area:442}, wo das Boot aus Menethil anlegt. Öffne Crates of Elunite auf dem Meeresboden rund um das Wrack, bei einer riesigen versunkenen Schildkröte, zum Strand hin und unter dem Pier, bis du acht hast; jede Kiste enthält Erz und kommt nach 3-5 Minuten zurück. Der graue {npc:6133} (Stufe 11) treibt in der Mitte des Wracks umher und lässt das Medaillon immer fallen: Wähl ihn als Ziel aus, wenn du ihn siehst, damit du ihn nach dem Auftauchen für Luft wiederfindest. Achte auf deinen Atem; Threshers können eingreifen.",
		["from {npc:6093}"] = "von {npc:6093}",
		["{item:263993}, from {npc:257196}"] = "{item:263993}, von {npc:257196}",
		["{item:6782}, from {object:85563}"] = "{item:6782}, aus {object:85563}",
		["{item:6800}, from {object:85562}"] = "{item:6800}, aus {object:85562}",
		["{item:6808}, from Crates of Elunite"] = "{item:6808}, aus Crates of Elunite",
		["{item:6809}, from the {npc:6133}"] = "{item:6809}, von {npc:6133}",
		["{npc:252377} in {area:16638}"] = "{npc:252377} in {area:16638}",
		["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "Das Anwesen von {npc:294} steht am südöstlichen Rand von {area:88} im östlichen Elwynn, am Ende einer kurzen Straße, die nicht auf die Hauptstraße trifft.",
		["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089} und {npc:6090} sind in der Taverne Pig and Whistle in {object:2100}; {npc:6090} ist der Betrunkene am anderen Ende der Theke. {npc:6090} (Stufe 10) schlägt härter zu, als seine Stufe vermuten lässt, fang also mit voller Gesundheit an; bei niedriger Gesundheit gibt er auf, statt zu sterben. Gewinnt er, verschwindet er für etwa drei Minuten: Behalte die Quest und sprich ihn erneut an, wenn er wieder da ist. Ein Zwerg, Gnom oder Nachtelf, der {quest:1638} von {npc:5480} statt seines Heimatwegs genommen hat, wird von hier aus durch {zone:1453} geführt.",
		["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093} (Stufe 11) lagert im äußersten Südosten von Elwynn. Eine Wache steht neben ihm, und Defias und Wölfe sind über das Lager verteilt (ab und zu auch eine seltenere Wache): Räum sie einzeln, dann töte Jack. Er lässt immer {item:6783} fallen; öffne {object:85563} in den Kisten bei ihm für {item:6782}. Jack kehrt 3 Minuten nach seinem Tod zurück, die Kiste 1 Minute nach dem Öffnen.",
		["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678} (Stufe 11, ein einzelner Troll) wartet an seiner Hütte auf einem Hügel südlich von {area:135}, nahe den Bergen am oberen Ende einer kurzen Rampe, ohne andere Trolle in der Nähe; die Hütte vorn bei {area:135} ist die falsche. Er kämpft in {spell:71} und zerreißt deine Rüstung; {spell:6343} verlangsamt ihn. Sein Kopf fällt immer; er kehrt etwa 8 Minuten nach seinem Tod zurück.",
		["{quest:1679} in {zone:1455}"] = "{quest:1679} in {zone:1455}",
		["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679} steht in {object:32390} im {object:32359}.",
		["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681} liegt im östlichen {zone:1426}, unterhalb von {area:212} an der Südseite. Entlang des Weges stehen Dark Iron Spies (Stufe 8-10), weit genug auseinander, um sie einzeln zu pullen. {object:85562} steht im Keller des südlichsten Hauses; {npc:6124} (Stufe 11) steht daneben und greift auf Sicht an. Die Kiste enthält immer das Erz und füllt sich 15 Minuten nach dem Öffnen wieder.",
		["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683} (Stufe 10, ein Satyr) steht an einem versteckten Mondbrunnen einen Hang westlich von {area:186} hinauf. Der Pfad ist schwer zu erkennen: Er beginnt hinter einem Gnarlpine-Lager und führt in Serpentinen hinauf, gesäumt von Laternenpfählen. Die Furbolgs unten können in Gruppen kommen. Sein Horn fällt immer; er kehrt 5 Minuten nach seinem Tod zurück.",
		["{quest:1684} in {zone:1457}"] = "{quest:1684} in {zone:1457}",
		["{quest:1684} stands on the {area:1660}."] = "{quest:1684} steht auf {area:1660}.",
		["{spell:71} and a Weapon (Alliance)"] = "{spell:71} und eine Waffe (Allianz)",
		["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "{spell:71} mit Stufe 10 und eine Einhandwaffe nach Wahl aus {zone:1453}, {zone:1455} oder {zone:1457}.",
} end)()
t.guides["forever/class/warrior/heirloom-weapon"] = (function() return {
		["At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one."] = "Mit Stufe 10 schickt dich {npc:2131}, der Kriegerlehrer im Gasthaus von {area:159}, zu {npc:1496} am Friedhof am Westrand von {area:159}. Dieser Weg und der von {npc:5810} schließen sich gegenseitig aus: Wirf {quest:1505} oder {quest:1498} aus deinem Log, falls du eine hast.",
		["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Mit Stufe 10 steht {npc:252377} mit den Lehrern am Westtor von {area:16638}. Ein Kultist, {npc:257196}, hält den Schild ihrer Familie am {area:16629}.",
		["At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too."] = "Mit Stufe 10 schickt dich {npc:3063}, der Kriegerlehrer von {area:222}, zu {npc:5810} im {zone:1413}. {npc:3041} in {zone:1456} bietet sie ebenfalls an.",
		["At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon."] = "Mit Stufe 10 schickt dich {npc:3169}, der Kriegerlehrer in der Kaserne von {area:362}, zu {npc:5810} im {zone:1413}. Sorek in {object:172958} von {zone:1454} bietet sie ebenfalls an. Jeder Horde-Krieger darf einen der zwei Wege nehmen, nie beide: Gehst du mit 10 sowieso nach {zone:1420}? {npc:2131} im Gasthaus von {area:159} bietet den anderen an: ein Kampf am Friedhof von {area:159} für dieselbe Haltung, dann die Agamand-Gruft für eine Erbstück-Waffe.",
		["Back to {npc:1500}"] = "Zurück zu {npc:1500}",
		["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "Zurück zu {npc:252377} in {area:16638}. Sie bringt dir {spell:71} bei und gibt dir {item:275290}, einen Schild dafür. Der Weg von {npc:5810} unten gibt dir später trotzdem eine Waffe, sobald du Kalimdor erreichst.",
		["Back to {npc:5810} under his tree west of {area:379}."] = "Zurück zu {npc:5810} unter seinem Baum westlich von {area:379}.",
		["Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here."] = "Dillinger steht am Friedhof am Westrand von {area:159}. Ein Orc, Troll, Tauren oder Himmelsgeborener, der {quest:1818} von {npc:2131} statt des Weges von {npc:5810} genommen hat, wird von hier aus durch {area:159} geführt.",
		["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Geh von {area:16638} nach Nordwesten zum {area:16629}. {npc:257196} steht westlich des Schreinzugangs zwischen den Guardians, Spiritcallers und Blademasters des Kults: Pull sie einzeln, bevor du dir ihn vornimmst. Er lässt {item:263993} fallen.",
		["Singed Scales in {area:369}"] = "Singed Scales in {area:369}",
		["The four Agamand Weapon Racks are inside the {area:158} at the north end of {area:157}, north of {area:159}, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them."] = "Die vier Agamand Weapon Racks stehen in {area:158} am Nordende von {area:157}, nördlich von {area:159}, ein Ständer pro Raum: einer im untersten Raum, zwei im Raumpaar die Treppe hinauf, einer im Raum darüber. Der Axtständer steht in einer dunklen Ecke. Die Untoten der Gruft kommen in Gruppen von drei oder mehr und kehren schnell zurück; die im obersten Raum sind nicht verbunden. Die Ständer mit Axt, Dolch und Streitkolben brauchen 15 Minuten, um sich zu füllen, nachdem jemand sie geplündert hat.",
		["The {area:158}"] = "{area:158}",
		["The {object:58369} stands by a broken wagon in the Razormane camp north-west of {npc:5878}, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too)."] = "{object:58369} steht bei einem kaputten Wagen im Razormane-Lager nordwestlich von {npc:5878}, nordöstlich der Crossroads. Zwei Razormanes bewachen sie, und ihre Jäger ziehen weitere Stacheleber heran: Räum sie einzeln, dann öffne die Truhe (sie füllt sich binnen Sekunden wieder, ein Freund kann sie also auch plündern).",
		["You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the {area:369} crevasse in north-west {zone:1411}, south of {zone:1454}: from the {zone:1413} bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast {spell:5401}."] = "Du brauchst fünf Singed Scales. Thunder Lizards (Stufe 9-10) und Lightning Hides (10-11) leben unten in der Schlucht von {area:369} im Nordwesten von {zone:1411}, südlich von {zone:1454}: Biege an der Brücke zum {zone:1413} links ab und folge dem Fluss nach Norden hinein. Beide lassen bei etwa vier von fünf Kills eine Schuppe fallen; beide wirken {spell:5401}.",
		["{item:263993}, from {npc:257196}"] = "{item:263993}, von {npc:257196}",
		["{item:6486}, from the lizards"] = "{item:6486}, von den Echsen",
		["{item:6534}, from the {object:58369}"] = "{item:6534}, aus {object:58369}",
		["{npc:1500} is in the {area:2119}, the inn on {area:159}'s east side."] = "{npc:1500} ist in {area:2119}, dem Gasthaus an der Ostseite von {area:159}.",
		["{npc:252377} in {area:16638}"] = "{npc:252377} in {area:16638}",
		["{npc:5810} at {area:379}"] = "{npc:5810} bei {area:379}",
		["{npc:5810} is easy to miss: he stands under a small canopy by a large tree just west of {area:379}, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From {zone:1411} cross the bridge west; from {zone:1412} head north past the Crossroads."] = "{npc:5810} ist leicht zu übersehen: Er steht unter einem kleinen Vordach an einem großen Baum direkt westlich von {area:379}, unterhalb der Südseite der Straße, mit dem Posten in Sichtweite im Osten. Wenn du vom Posten geradeaus nach Süden gehst, kommst du nicht zu ihm. Überquere von {zone:1411} aus die Brücke nach Westen; von {zone:1412} aus geh nördlich an den Crossroads vorbei.",
		["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side."] = "Die Hütte von {npc:5878} sitzt auf {area:1699}, östlich der Crossroads. Die meisten Hänge sind zu steil: Steig den breiten Grat an der Nord- oder Ostseite hinauf.",
		["{npc:6390} sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and {npc:6390} (level 11, not elite) walks out. Start at full health."] = "{npc:6390} schläft im Mausoleum auf dem Friedhof direkt nördlich von Dillinger. Um ihn zu wecken, klicke die flache Schädelplakette auf dem Boden links des Pfades zur Mausoleumstür an; das Siegel hebt sich und {npc:6390} (Stufe 11, kein Elite) kommt heraus. Fang mit voller Gesundheit an.",
		["{spell:71} and a Weapon (Horde)"] = "{spell:71} und eine Waffe (Horde)",
		["{spell:71} at 10 and a one-hand weapon of your choice: {npc:5810}'s road, {area:159}'s crypt, or the Skybreaker shield."] = "{spell:71} mit Stufe 10 und eine Einhandwaffe nach Wahl: der Weg von {npc:5810}, die Gruft von {area:159} oder der Skybreaker-Schild.",
} end)()
t.guides["forever/class/warrior/quelserrar"] = (function() return {
		["A tank sword at 60: a {area:2577} book, then {npc:10184}'s breath tempers the blade (the sword is not in Forever's items yet)."] = "Ein Tank-Schwert mit Stufe 60: ein Buch aus {area:2577}, dann härtet der Atem von {npc:10184} die Klinge (das Schwert gibt es in den Gegenständen von Forever noch nicht).",
		["Back to {npc:14368} in the Athenaeum of Dire Maul West: through the West door with the {item:18249} again, and a group to reach the library."] = "Zurück zu {npc:14368} im Athenaeum von Dire Maul West: wieder durch die Tür nach Westen mit {item:18249} und mit einer Gruppe, um die Bibliothek zu erreichen.",
		["Kill {npc:10184}, then target her corpse and use the {item:18488} on it before the 20 minutes run out. It becomes the {item:18492}, with no time limit."] = "Töte {npc:10184}, wähle dann ihren Leichnam als Ziel und benutze {item:18488} darauf, bevor die 20 Minuten ablaufen. Sie wird zu {item:18492}, ohne Zeitlimit.",
		["Shen'dralar reputation"] = "Ruf bei den Shen'dralar",
		["The book is a rare random drop from the bosses of all three {area:2577} wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, {npc:11496} and the West, {npc:11501} and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. {area:2577} is a five-player dungeon in the ruins of central {zone:1444}: needs a group of five. Right-click the book to start the quest; it stays in your bags."] = "Das Buch ist ein seltener zufälliger Drop der Bosse aller drei Flügel von {area:2577} (Alzzin, Hydrospawn und der Rest des Ostens, Tendris, Illyanna, Kalendris, {npc:11496} und der Westen, {npc:11501} und die Wachen des Nordens) und sehr selten aus der Tributtruhe; es ist handelbar, im Auktionshaus gibt es also vielleicht eines. {area:2577} ist ein Dungeon für fünf Spieler in den Ruinen des zentralen {zone:1444}: Du brauchst eine Gruppe aus fünf. Rechtsklick auf das Buch startet die Quest; es bleibt in deinen Taschen.",
		["click the heated blade on the ground"] = "klicke die erhitzte Klinge am Boden an",
		["from {item:18401}"] = "aus {item:18401}",
		["{item:18488}, on her corpse"] = "{item:18488}, auf ihrem Leichnam",
		["{item:18489}: plant it in her breath"] = "{item:18489}: platziere sie in ihrem Atem",
		["{npc:10184} is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the {item:18489} to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the {object:179562} to take the {item:18488}: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade."] = "{npc:10184} ist der 40-Spieler-Schlachtzugsboss von {area:2159}, einer Höhle im {area:511} des südlichen {zone:1445}; sie kehrt einmal pro Woche zurück. Sag es zuerst dem Schlachtzug. Spät im Kampf (bei etwa 10-15 % Gesundheit, wenn sie wieder gelandet ist) benutze {item:18489}, um sie in den Weg ihres Feueratems zu stellen, meist bei den Füßen des Haupttanks. Hat ihr Atem sie erhitzt, klicke {object:179562} an, um {item:18488} zu nehmen: Ab dann hast du 20 Minuten. Ihr Atem kann dich töten, während du die Klinge platzierst oder aufhebst; stirbst du und niemand belebt dich wieder, bevor sie stirbt, warte auf nächste Woche. An der falschen Stelle platziert? Brich die Quest ab und nimm sie bei Lydros erneut an, um eine neue Klinge zu bekommen.",
		["{npc:10184}'s breath"] = "Atem von {npc:10184}",
		["{npc:10184}'s corpse"] = "Leichnam von {npc:10184}",
		["{npc:14368} stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the {item:18249}, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you {item:18513} to give straight back, then the {item:18489}. Keep that blade: lose it, and you must abandon the quest and take it again."] = "{npc:14368} steht im Athenaeum, der Bibliothek am äußersten Ende von Dire Maul West, hinter dem Court of the Highborne und dem Prison of Immol'thar. Die Tür nach Westen braucht {item:18249}, den Pusillin in Dire Maul Ost fallen lässt (er rennt weg; jag ihn), oder einen Schurken zum Knacken. Um bis zur Bibliothek zu räumen, brauchst du deine Gruppe aus fünf. Er nimmt das Buch, gibt dir {item:18513}, das du ihm direkt zurückgibst, dann {item:18489}. Behalte diese Klinge: Verlierst du sie, musst du die Quest abbrechen und erneut annehmen.",
		["{npc:14368}, in the Athenaeum"] = "{npc:14368}, im Athenaeum",
		["{npc:14368}: hand back the Dull and Flat Elven Blade"] = "{npc:14368}: gib die Dull and Flat Elven Blade zurück",
} end)()
t.guides["forever/class/warrior/voodoo-feathers"] = (function() return {
		["At 50, {npc:3041}, the warrior trainer of {zone:1456}, sends you to the {npc:7572} in the {zone:1435}."] = "Mit 50 schickt dich {npc:3041}, der Kriegerlehrer von {zone:1456}, zu {npc:7572} in {zone:1435}.",
		["At 50, {npc:3354} in the {object:172958} sends you to the {npc:7572} in the {zone:1435}."] = "Mit 50 schickt dich {npc:3354} in {object:172958} zu {npc:7572} in {zone:1435}.",
		["At 50, {npc:4593}, a warrior trainer of the {zone:1458}, sends you to the {npc:7572} in the {zone:1435}."] = "Mit 50 schickt dich {npc:4593}, ein Kriegerlehrer in {zone:1458}, zu {npc:7572} in {zone:1435}.",
		["At 50, {npc:5113}, the warrior trainer of {zone:1455}, sends you to the {npc:7572} in the {zone:1435}."] = "Mit 50 schickt dich {npc:5113}, der Kriegerlehrer von {zone:1455}, zu {npc:7572} in {zone:1435}.",
		["At 50, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to the {npc:7572} in the {zone:1435}."] = "Mit Stufe 50 schickt dich {npc:5479}, neben {npc:5480} im Gebäude der Kriegerlehrer von {object:2100}, zu {npc:7572} im {zone:1435}.",
		["At 50, {npc:7315}, the warrior trainer of {zone:1457}, sends you to the {npc:7572} in the {zone:1435}."] = "Mit 50 schickt dich {npc:7315}, der Kriegerlehrer von {zone:1457}, zu {npc:7572} in {zone:1435}.",
		["Back to the {npc:10996}"] = "Zurück zu {npc:10996}",
		["Experience"] = "Erfahrung",
		["Experience at 50, ending in the {area:1417}; Classic's item choice may be gone on Forever."] = "Erfahrung mit Stufe 50, endet im {area:1417}; die Gegenstandswahl aus Classic könnte in Forever weg sein.",
		["Helboars"] = "Hölleneber",
		["In Classic the {npc:10996} let you choose the {item:20130}, the {item:20521} or the {item:20517} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "In Classic ließen dich {npc:10996} hier {item:20130}, {item:20521} oder {item:20517} wählen. Die Änderungshinweise von Forever sagen, die Wahl sei weg, doch ihre Questseite führt weiter drei unbenannte Belohnungen auf: Sieh dir das Belohnungsfenster an, bevor du abgibst.",
		["Seven Helboars (level 52-53, not elite) roam the north-west of the {zone:1419}, south-west of {area:1438}; some stand near the ogres on the mountainside by the road. They charge from 25 yards and cast {spell:8349}. They share spawn points with the Felbeasts and scorpids: if no boars are around, kill those and boars may appear instead. Back in 5 minutes."] = "Sieben Helboars (Stufe 52-53, kein Elite) streifen im Nordwesten des {zone:1419}, südwestlich von {area:1438}; einige stehen bei den Ogern am Berghang an der Straße. Sie stürmen aus 25 Metern los und wirken {spell:8349}. Sie teilen sich Spawnpunkte mit den Felbeasts und Skorpiden: Sind keine Eber da, töte jene, und stattdessen erscheinen vielleicht Eber. Nach 5 Minuten zurück.",
		["Shadowsworn camps"] = "Lager der Schattenanbeter",
		["The Shadowsworn camp around the mouth of the {area:1440} cave, south of {area:1438} on the way to the {area:72}. You need 20 Adepts (level 52-53, they leech blood and heal hurt allies: kill them first), 10 Cultists (51-52, they throw from range, so close in) and 20 Thugs (52-53, Thrash and {spell:1766}). Thugs can run short before the others: kill every Shadowsworn you pass."] = "Die Shadowsworn lagern rund um den Eingang der Höhle {area:1440}, südlich von {area:1438} auf dem Weg zu {area:72}. Du brauchst 20 Adepts (Stufe 52-53, sie saugen Blut und heilen verletzte Verbündete: Töte sie zuerst), 10 Cultists (51-52, sie werfen aus der Distanz, geh also nah ran) und 20 Thugs (52-53, Thrash und {spell:1766}). Von den Thugs können dir welche ausgehen, bevor die anderen fertig sind: Töte jeden Shadowsworn, an dem du vorbeikommst.",
		["The {area:1417}"] = "{area:1417}",
		["The {npc:7572}"] = "{npc:7572}",
		["The {npc:7572}, a ghost, stands in the south-west of the {zone:1435}, at the pass into the {zone:1419}, a short ride south-west of {area:75}. Horde: fly to {area:75}. Alliance: fly to {area:1438} in the {zone:1419} and ride north through the pass. High-level beasts roam the way."] = "{npc:7572}, ein Geist, steht im Südwesten von {zone:1435}, am Pass ins {zone:1419}, einen kurzen Ritt südwestlich von {area:75}. Horde: Flieg nach {area:75}. Allianz: Flieg nach {area:1438} im {zone:1419} und reite durch den Pass nach Norden. Auf dem Weg streifen hochstufige Bestien umher.",
		["You need two feathers of each colour from the six Atal'ai troll guardians (level 51-52, elite) on the {area:1417}'s balcony, who hold the barrier in front of {npc:5710}: Gasher and {npc:5716} drop the amber, Hukku and Mijan the blue, Zolo and Loro the green, every kill; each player on the quest loots their own set. The {area:1417} is a five-player dungeon: needs a group of five. It lies in the {area:74} in eastern {zone:1435}: climb the temple's outer steps, dive into the flooded hall and follow the stairs down to the entrance. Inside, reach the balcony by the stairs or the path on the right, not the spiral stairs. Hukku calls guardians and casts {spell:9081} and {spell:8282}; Mijan heals the others ({spell:139}, a {npc:3560}, {spell:331} below half health): kill her or her ward fast; {npc:5716} cleaves."] = "Du brauchst zwei Federn jeder Farbe von den sechs Atal'ai-Troll-Wächtern (Stufe 51-52, Elite) auf dem Balkon von {area:1417}, die die Barriere vor {npc:5710} halten: Gasher und {npc:5716} lassen die bernsteinfarbene fallen, Hukku und Mijan die blaue, Zolo und Loro die grüne, bei jedem Kill; jeder Spieler mit der Quest plündert sein eigenes Set. {area:1417} ist ein Dungeon für fünf Spieler: Du brauchst eine Gruppe aus fünf. Er liegt im {area:74} im östlichen {zone:1435}: Steig die äußeren Stufen des Tempels hinauf, tauch in die geflutete Halle und folge den Treppen nach unten zum Eingang. Erreiche drinnen den Balkon über die Treppe oder den Pfad rechts, nicht über die Wendeltreppe. Hukku ruft Wächter und wirkt {spell:9081} und {spell:8282}; Mijan heilt die anderen ({spell:139}, ein {npc:3560}, {spell:331} unter halber Gesundheit): Töte sie oder ihren Schutz schnell; {npc:5716} spaltet.",
		["{item:20606}, from Gasher and {npc:5716}"] = "{item:20606}, von Gasher und {npc:5716}",
		["{item:20607}, from Hukku and Mijan"] = "{item:20607}, von Hukku und Mijan",
		["{item:20608}, from Zolo and Loro"] = "{item:20608}, von Zolo und Loro",
} end)()
t.guides["forever/class/warrior/whirlwind-weapon"] = (function() return {
		["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Mit Stufe 30 schickt dich {npc:3041}, der Kriegerlehrer von {zone:1456}, zu {npc:6236} auf {area:720} in {zone:1413}.",
		["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Mit Stufe 30 schickt dich {npc:3354} im {object:172958} zu {npc:6236} auf {area:720} in {zone:1413}.",
		["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Mit Stufe 30 schickt dich {npc:4595}, ein Kriegerlehrer in {zone:1458}, zu {npc:6236} auf {area:720} in {zone:1413}.",
		["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Mit Stufe 30 schickt dich {npc:5113}, der Kriegerlehrer von {zone:1455}, zu {npc:6236} auf {area:720} in {zone:1413}.",
		["At 30, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Mit Stufe 30 schickt dich {npc:5479}, neben {npc:5480} im Gebäude der Kriegerlehrer von {object:2100}, zu {npc:6236} auf {area:720} im {zone:1413}.",
		["Back to {npc:6176}. Accepting {quest:1713} starts his ritual, and {quest:1712} appears just north of his camp. {quest:1712} is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a {item:6052} soaks it), whirls, and {spell:10101} throws you far while it heals itself as you run back: fight with your back to a slope or rock. The {item:6894} always drops. If the fight fails {npc:6176} stops answering: abandon {quest:1713} and take it again for a new summon; the earlier items are not needed again."] = "Zurück zu {npc:6176}. Mit dem Annehmen von {quest:1713} beginnt sein Ritual, und {quest:1712} erscheint direkt nördlich seines Lagers. {quest:1712} ist ein Elite (Stufe 40): Eine Gruppe wird empfohlen; du brauchst eine Gruppe aus zwei oder drei Spielern um Stufe 40. Er verursacht Naturschaden (ein {item:6052} fängt ihn ab), wirbelt und {spell:10101} schleudert dich weit weg, während er sich heilt, wenn du zurückläufst: Kämpf mit dem Rücken zu einem Hang oder Felsen. {item:6894} fällt immer. Schlägt der Kampf fehl, antwortet {npc:6176} nicht mehr: Brich {quest:1713} ab und nimm sie für eine neue Beschwörung erneut an; die früheren Gegenstände brauchst du nicht noch einmal.",
		["Bloodscalp Tusks"] = "Bloodscalp Tusks",
		["Click {object:89931} with the 24 charms in your bags and {quest:1712} in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the {quest:1714}."] = "Klicke {object:89931} an, mit den 24 Glücksbringern in deinen Taschen und {quest:1712} im Questlog. Sein Fenster verlangt die Glücksbringer sofort, ohne dass du etwas annimmst: „Weiter“, dann „Abschließen“, und er gibt dir {quest:1714}.",
		["Fly to {area:392} and go south along the {area:391}. {area:720} lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. {npc:6236} stands by the arena."] = "Flieg nach {area:392} und geh südlich an der {area:391} entlang. {area:720} liegt vor der Küste im Südosten: Wate auf der flachen Sandbank hinüber; daneben ist das Wasser tief und Erschöpfung setzt ein. {npc:6236} steht bei der Arena.",
		["The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite: the guide waits for level 37 first, and a friend helps. Burning Exiles (fire) by the {area:334} in the north-west, north-west of {area:320}; Thundering Exiles (air) by the {area:336} south-east of {area:320}, casting {spell:403} from 40 yards; Cresting Exiles (water) by the {area:333}, north-west of {area:321}, with {spell:122}. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning)."] = "Der Kessel will 8 von jedem Glücksbringer, insgesamt 24, und jeder Verbannte lässt seinen Glücksbringer bei etwa jedem dritten Kill fallen, plane also etwa 70 Kills ein. Alle haben Stufe 38-39 und sind keine Elites: Der Guide wartet zuerst auf Stufe 37, und ein Freund hilft. Brennende Verbannte (Feuer) beim {area:334} im Nordwesten, nordwestlich von {area:320}; Donnernde Verbannte (Luft) beim {area:336} südöstlich von {area:320}, die aus 40 Metern {spell:403} wirken; Schäumende Verbannte (Wasser) beim {area:333}, nordwestlich von {area:321}, mit {spell:122}. Etwa ein Dutzend von jeder Sorte, in unter 7 Minuten zurück. Die Glücksbringer sind handelbar und im Auktionshaus erhältlich; einer davon verbannt eine Weile eine andere Sorte Verbannter (Brennende gegen Donnernde, Donnernde gegen Schäumende, Schäumende gegen Brennende).",
		["The exiles of Arathi"] = "Die Verbannten des Arathihochlands",
		["You have 10 minutes. Eat and drink to full, then step onto the grate in the middle of the crowd: {npc:6248} announces the challengers (level 26-27), who come one at a time, 15-20 seconds apart, and only while you stand near the grate. After each kill, step off the grate to eat or bandage; step back on when ready for the next. Six of them, then {npc:6238} (level 33, not elite) walks out; he stays neutral until you attack him, so bandage or eat first. Do not use {spell:1160}: it sends the challengers running and more of them pile in at once. If nothing starts, step off and on the grate again, or abandon the quest and take it again."] = "Du hast 10 Minuten. Iss und trink bis zum Maximum, tritt dann auf das Gitter mitten in der Menge: {npc:6248} kündigt die Herausforderer (Stufe 26-27) an, die einzeln im Abstand von 15-20 Sekunden kommen, und nur solange du in der Nähe des Gitters stehst. Tritt nach jedem Kill vom Gitter, um zu essen oder zu verbinden; tritt wieder darauf, wenn du für den nächsten bereit bist. Sechs von ihnen, dann kommt {npc:6238} (Stufe 33, kein Elite) heraus; er bleibt neutral, bis du ihn angreifst, also verbinde oder iss zuerst. Benutze nicht {spell:1160}: Er schickt die Herausforderer in die Flucht, und es strömen auf einmal mehr herein. Startet nichts, tritt vom Gitter und wieder darauf, oder brich die Quest ab und nimm sie erneut an.",
		["You need 30 tusks. Every Bloodscalp troll (level 33-37) of north-west Stranglethorn drops one about one kill in three, so plan on some 80 kills: the camps and ruins north and north-west of {area:117} and around the {area:123} on the coast. They enrage below 30% health and the Warriors disarm; back in 5 minutes."] = "Du brauchst 30 Hauer. Jeder Bloodscalp-Troll (Stufe 33-37) im Nordwesten von Stranglethorn lässt bei etwa jedem dritten Kill einen fallen, plane also etwa 80 Kills ein: die Lager und Ruinen nördlich und nordwestlich von {area:117} und rund um {area:123} an der Küste. Unter 30 % Gesundheit werden sie wütend, und die Warriors entwaffnen; nach 5 Minuten zurück.",
		["You need 8 {item:3357}. Herbalists pick it by rivers and lakes in the {zone:1437}, {zone:1417} and {zone:1434}; otherwise the auction house. Herb vendors keep only one at a time and restock every two hours: {npc:1302} and {npc:1313} in {zone:1453}, {npc:844} on the road in eastern Elwynn, Jeeda at {area:460} in Stonetalon, Montarr in {zone:1441}. Kurzen Medicine Men in northern Stranglethorn drop one about one kill in twelve."] = "Du brauchst 8 {item:3357}. Kräuterkundler pflücken sie an Flüssen und Seen in der {zone:1437}, in {zone:1417} und {zone:1434}; sonst das Auktionshaus. Kräuterhändler haben immer nur eines vorrätig und füllen alle zwei Stunden nach: {npc:1302} und {npc:1313} in {zone:1453}, {npc:844} an der Straße im östlichen Elwynn, Jeeda bei {area:460} in Stonetalon, Montarr in {zone:1441}. Kurzen Medicine Men im nördlichen Stranglethorn lassen bei etwa jedem zwölften Kill eines fallen.",
		["{item:4479}, from Burning Exiles"] = "{item:4479}, von Burning Exiles",
		["{item:4480}, from Thundering Exiles"] = "{item:4480}, von Thundering Exiles",
		["{item:4481}, from Cresting Exiles"] = "{item:4481}, von Cresting Exiles",
		["{item:6894}, from {quest:1712}"] = "{item:6894}, von {quest:1712}",
		["{npc:6176} camps by ruins on the east bank of the river that runs past {area:272}, a short walk north-east of the town, just over the border in {zone:1416}; his cauldron stands beside him. Horde: fly to {area:272}. Alliance: fly to {area:271} and go north along the river; {area:272}'s guards are level 42 elites, so keep away from the town. Accepting {quest:1712} gives you {item:6929}, the list of what he needs: 8 {item:3357}, 30 Bloodscalp Tusks and the {item:6851} from his cauldron. The cauldron's {item:6851} is not a quest you take: it never shows in your quest log. Come back with its charms and hand them in at the cauldron."] = "{npc:6176} lagert bei Ruinen am Ostufer des Flusses, der an {area:272} vorbeiführt, einen kurzen Fußweg nordöstlich der Stadt, knapp hinter der Grenze in {zone:1416}; sein Kessel steht neben ihm. Horde: Flieg nach {area:272}. Allianz: Flieg nach {area:271} und geh am Fluss entlang nach Norden; die Wachen von {area:272} sind Elites der Stufe 42, halte dich also von der Stadt fern. Mit dem Annehmen von {quest:1712} erhältst du {item:6929}, die Liste dessen, was er braucht: 8 {item:3357}, 30 Hauer der Bloodscalp und {item:6851} aus seinem Kessel. Die {item:6851} des Kessels ist keine Quest, die du annimmst: Sie erscheint nie in deinem Questlog. Komm mit ihren Glücksbringern zurück und gib sie am Kessel ab.",
		["{npc:6176}: {item:6975}, Sword or Warhammer"] = "{npc:6176}: {item:6975}, Schwert oder Kriegshammer",
		["{quest:1714}, from the cauldron by {npc:6176}"] = "{quest:1714}, aus dem Kessel bei {npc:6176}",
		["{spell:2458} at 30 and a {spell:1680} axe, sword or warhammer at 40."] = "{spell:2458} mit Stufe 30 und mit Stufe 40 eine Axt, ein Schwert oder ein Kriegshammer für {spell:1680}.",
} end)()
t.guides["forever/collectibles/mounts/alliance/black-war-mounts"] = (function() return {
		["Black War Mounts"] = "Schwarze Kriegsreittiere",
		["PvP rank 11"] = "PvP-Rang 11",
		["{item:18243}, {spell:10907}, 100g"] = "{item:18243}, {spell:10907}, 100g",
		["{item:18244}, {spell:826}, 100g"] = "{item:18244}, {spell:826}, 100g",
		["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783} verkauft die Reittiere in der {object:2100} von {zone:1453} bei der {area:2918}, neben den anderen Ehren-Rüstmeistern. Der Forever-Client führt jedes für 100g. Jedes braucht außerdem das Reiten seiner Art: Menschen reiten das Ross, Nachtelfen den Tiger, Gnome den Mechanostrider, Zwerge den Widder. Ein Himmelsgeborener oder jeder, der das Reittier einer anderen Rasse wählt, braucht dieses Reiten zuerst bei dessen Lehrer (Ehrfürchtig bei der Stadt der Rasse).",
		["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}, {spell:824}, 100g",
		["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "{spell:1299382} stammen aus Schlachtfeldern, PvP-Quests und den Wochenaufgaben der Saison, mit einer Wochengrenze; Kommandant (Rang 11) schaltet die Schwarzen Kriegsreittiere frei. Der Reiter-Tab im PvP-Reiter deines Charakterfensters zeigt deinen Rang und was du kaufen darfst. Um eines davon mit voller Geschwindigkeit zu reiten ({skill:762}), brauchst du {skill:762} (Geselle) (Stufe 60). Polestar kann deinen Rang nicht lesen, deshalb wartet dieser Schritt auf Stufe 60 und {skill:762} (Geselle).",
		["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}, {spell:828}, 100g",
} end)()
t.guides["forever/collectibles/mounts/alliance/horse"] = (function() return {
		["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Jede Allianzrasse kann diese Pferde kaufen, aber um eines zu reiten, braucht man auch {spell:824}, das nur Menschen mit {skill:762} bekommen. {npc:4732} lehrt es andere Rassen, sobald sie bei {faction:72} Ehrfürchtig sind (der Ruf-Guide für Stormwind zeigt den Weg). Bis dahin kaufe für diesen Charakter kein Pferd.",
		["Horse"] = "Pferd",
		["Learn to ride"] = "Reiten lernen",
		["Pick a colour"] = "Wähle eine Farbe",
		["The {npc:5404} is not at {npc:384}: {npc:1460} sells it, at the stables of {area:150} in the {zone:1437} (20g in the Forever client). Skip this unless you want that colour."] = "Das {npc:5404} gibt es nicht bei {npc:384}: {npc:1460} verkauft es in den Ställen von {area:150} in den {zone:1437} (20g im Forever-Client). Überspringe das, es sei denn, du willst genau diese Farbe.",
		["{item:2411}, 20g, {npc:1460}"] = "{item:2411}, 20g, {npc:1460}",
		["{item:2414}, 20g"] = "{item:2414}, 20g",
		["{item:5655}, 20g"] = "{item:5655}, 20g",
		["{item:5656}, 20g"] = "{item:5656}, 20g",
		["{npc:384} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} verkauft die anderen Farben (je 20g im Forever-Client). Kauf, welche du willst, oder keine, wenn dir das Reittier gefällt, das du bekommen hast.",
		["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 40 {npc:4732} teaches {skill:762} to Humans for 100g (10% less at Honored with {faction:72}), and it comes with a horse. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4732} und das Pferdegehege von {npc:384} liegen bei {area:88} im Osten von {zone:1429}. Auf Stufe 40 lehrt {npc:4732} Menschen {skill:762} für 100g (10% weniger bei Wohlwollend mit {faction:72}), und ein Pferd gehört dazu. Andere Rassen lernen {skill:762}, mit ihrem eigenen ersten Reittier, beim Reitlehrer ihrer eigenen Rasse.",
		["{npc:4732}, riding trainer"] = "{npc:4732}, Reitlehrer",
		["{npc:5404} in {area:150}"] = "{npc:5404} in {area:150}",
		["{spell:824} for other races"] = "{spell:824} für andere Rassen",
} end)()
t.guides["forever/collectibles/mounts/alliance/mechanostrider"] = (function() return {
		["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "Jede Allianzrasse kann diese Mechanostrider kaufen, aber um einen zu reiten, braucht man auch {spell:10907}, das nur Gnome mit {skill:762} bekommen. {npc:7954} lehrt es andere Rassen, sobald sie bei {faction:54} Ehrfürchtig sind (der Ruf-Guide für die Gnomeregan-Exilanten zeigt den Weg). Bis dahin kaufe für diesen Charakter keinen Mechanostrider.",
		["In Classic only Dwarves and Gnomes could ride mechanostriders; in Forever every Alliance race can learn {spell:10907}."] = "In Classic konnten nur Zwerge und Gnome Mechanostrider reiten; in Forever kann jede Allianzrasse {spell:10907} lernen.",
		["Learn to ride"] = "Lerne reiten",
		["Mechanostrider"] = "Roboschreiter",
		["Pick a colour"] = "Wähle eine Farbe",
		["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 40 {npc:7954} teaches {skill:762} to Gnomes for 100g (10% less at Honored with {faction:54}), and it comes with a mechanostrider. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:189} liegt gleich östlich von {area:131}; {npc:7954} steht neben den Mechanostridern von {npc:7955}. Auf Stufe 40 lehrt {npc:7954} Gnome {skill:762} für 100g (10% weniger bei Wohlwollend mit {faction:54}), und ein Mechanostrider gehört dazu. Andere Rassen lernen {skill:762}, mit ihrem eigenen ersten Reittier, beim Reitlehrer ihrer eigenen Rasse.",
		["{item:13321}, 20g"] = "{item:13321}, 20g",
		["{item:13322}, 20g"] = "{item:13322}, 20g",
		["{item:8563}, 20g"] = "{item:8563}, 20g",
		["{item:8595}, 20g"] = "{item:8595}, 20g",
		["{npc:7954}, riding trainer"] = "{npc:7954}, Reitlehrer",
		["{npc:7955} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:7955} verkauft die anderen Farben (im Forever-Client je 20g). Kauf, was du willst, oder nichts, wenn dir das erhaltene Reittier gefällt.",
		["{spell:10907} for other races"] = "{spell:10907} für andere Rassen",
} end)()
t.guides["forever/collectibles/mounts/alliance/pack-kodo"] = (function() return {
		["6,000 Merchant's Favor"] = "6,000 Merchant's Favor",
		["The camp is at {area:1002} in western {zone:1433}, where the roads from {zone:1429}, {zone:1431} and {area:69} meet. {npc:256736} sells the {npc:10636} only once you are Exalted with the {faction:2586}, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time {item:280179}, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside."] = "Das Lager liegt bei {area:1002} im Westen von {zone:1433}, wo sich die Straßen aus {zone:1429}, {zone:1431} und {area:69} treffen. {npc:256736} verkauft das {npc:10636} erst, wenn du bei der {faction:2586} Ehrfürchtig bist, und es kostet 6.000 Gunst der Händler. Kisten zahlen nur Gunst (etwa 15 pro abgegebener Kiste); der Ruf kommt von den Schriftstücken der Handwerker und dem einmaligen {item:280179}. Folge also dem Ruf-Guide für die Versorgungsfraktionen und lege 6.000 Gunst beiseite.",
		["The reins need level 60 and Journeyman Riding to ride (Forever client); you can buy them earlier."] = "Die Zügel erfordern zum Reiten Stufe 60 und Geübtes Reiten (Forever-Client); kaufen kannst du sie schon früher.",
		["{faction:2586} camp"] = "Lager der {faction:2586}",
} end)()
t.guides["forever/collectibles/mounts/alliance/paladin-charger"] = (function() return {
		["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "Ein {item:12800} stammt aus Thoriumadern und Obsidian, etwa eine Ader von hundert; ein {item:18335} fällt selten von Elites ab Stufe 59 (Revanchion und {npc:14695}, etwa bei jedem neunten und bei jedem hundertsten Kill). Das Auktionshaus ist die übliche Quelle für beide.",
		["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "Arkanitbarren x6: ein Alchemist oder das Auktionshaus im Handelsdistrikt",
		["At 60 {npc:5149} in the {object:32362} sends you to {quest:7638} in {zone:1453}'s Cathedral of Light."] = "Mit 60 schickt dich {npc:5149} ({object:32362}) zu {quest:7638} in der Kathedrale des Lichts in {zone:1453}.",
		["Back to Lord Grayson"] = "Zurück zu Lord Grayson",
		["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "Bring die Materialien und 150 Gold, die bei der Abgabe genommen werden. {npc:1416} geht zu seiner Schmiede und gibt dir die {item:18753}.",
		["Dire Maul West's door"] = "Tür von Düsterbruch West",
		["Enriched Manna Biscuits"] = "Angereicherte Manakekse",
		["Enriched Manna Biscuits: {npc:10857}, {area:3197}"] = "Angereicherte Manakekse: {npc:10857}, {area:3197}",
		["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "Lord Grayson segnet das Räuchergefäß zum {item:18752} für {area:2627}.",
		["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "Lord Grayson gibt dir {item:18804}: Öffne es für den {item:18746} und die {item:18792}. Behalte beide.",
		["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "Lord Grayson behält die Pferderüstung vorerst: Du bekommst sie mit der nächsten Quest zurück.",
		["Lord Grayson takes the censer back."] = "Lord Grayson nimmt das Räuchergefäß zurück.",
		["Paladin Charger"] = "Paladin-Streitross",
		["Stratholme Supply Crates, inside"] = "Stratholme Supply Crates, drinnen",
		["Terrordale Spirits x25"] = "Terrordale Spirits x25",
		["The {spell:23214} chain is long: {area:2279}, Dire Maul West and {area:2057} with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 {item:14047}, 10 {item:8836}, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, {npc:6171} nearby."] = "Die Kette der {spell:23214} ist lang: {area:2279}, Düsterbruch West und {area:2057} mit einer Gruppe, 350 Gold an Spenden und Materialien für mehrere hundert weitere (6 Arkanitbarren, 40 {item:14047}, 10 {item:8836}, zwei Diamanten). Fang früh an zu sparen. Lord Grayson steht in der Kathedrale des Lichts, {npc:6171} in der Nähe.",
		["Two diamonds"] = "Zwei Diamanten",
		["Your epic mount at 60, summoned at will: the faster step up from the Warhorse."] = "Dein episches Reittier mit 60, jederzeit beschworen: die schnellere Stufe nach dem Schlachtross.",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057} liegt unter {area:2298}, der Inselstadt im Südosten der {zone:1422}; die Tür braucht den {item:13704} (Der Schlüssel zu {area:2057}). Räume den {object:179746}, Rattlegores Raum im Keller, und benutze dann den {item:18746} in dessen Mitte. Vier Wellen von Geistern kommen, jede endet mit einem Aspekt: Spieler richten sie mit {spell:1105}, Gerechtigkeit, Rechtschaffenheit und dann Licht, das sie betäubt. {npc:14516} (Elite der Stufe 62) kommt nach der letzten; er kontrolliert Spieler mental. Plündere den {item:18749}, benutze ihn im Ossuarium, um ihn einzulösen, und gib ihn mit der {item:18792} an {npc:14568}. Wenn die Gruppe stirbt, verriegeln sich die Tore und der Seher ist fort: Brich die Quest ab und nimm sie bei Lord Grayson erneut an, um eine neue Tasche zu bekommen. Eine Gruppe von fünf auf Stufe 60. Mit Again Into the {object:179746} kannst du ihn nach dem Reittier erneut bekämpfen.",
		["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279} ist ein Dungeon für eine Gruppe von fünf auf Stufe 58-60 am nördlichen Ende der {zone:1423}. Stratholme Supply Crates in den Straßen beider Hälften enthalten das Weihwasser, je ein bis drei; sie kehren nach drei Minuten wieder. Manche Kisten lassen einen Schwarm verseuchter Ratten oder Maden frei: Sei darauf gefasst. Das Haupttor (die scharlachrote Hälfte) braucht keinen Schlüssel.",
		["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577} liegt im Zentrum von {zone:1444}. Geh vom Tor am Fuß der Ruinen durch die äußeren Höfe hinauf zur Tür des Westflügels an deren Nordende; sie braucht einen {item:18249} (von Pusillin in Düsterbruch Ost) oder das Schlossknacken eines Schurken. {npc:11489} (Elite der Stufe 60) steht am Ende des ersten Hofs des Westflügels. Sobald er angegriffen wird, ruft er jeden {npc:11459} im Hof, der noch lebt: Töte diese zuerst. Sein Tod befreit das {quest:7643}: Sprich es an, um ihm das Pferdefutter und die {item:18753} zu geben, und es segnet die Rüstung. Eine Gruppe von fünf auf Stufe 60.",
		["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627} liegt im äußersten Nordwesten der {zone:1423}, westlich der Tore von {area:2279}. Stell dich in eine grün leuchtende Stelle am Boden (ein {object:179747}; manche liegen in den zerstörten Häusern) und benutze das {item:18752}: Bis zu drei Terrordale Spirits (Stufe 59-60) erheben sich und greifen an. Ihr {spell:7713} senkt alle deine Werte um 30%: Bekämpfe sie einzeln und benutze {spell:2878}. Die Stellen kehren schnell zurück; mehrere Paladine können Seite an Seite arbeiten.",
		["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "{item:14047} fällt von Humanoiden ab Stufe 50 ({area:2255}s Schläger, den Scharlachroten im Pestland, den Ogern von {area:2577}). {item:8836} ist ein Kraut des Pestlands ({skill:182} 220), häufig um {area:3197}. Ein {item:12360} ist die Transmutation eines Alchemisten aus einem {item:12359} und einem {item:12363}, einmal alle zwei Tage pro Alchemist: Frag früh einen Gildenalchemisten oder kaufe die Barren. Das Auktionshaus verkauft alle drei.",
		["{item:14047} x40"] = "{item:14047} x40",
		["{item:18749}, inside the {object:179746}"] = "{item:18749}, im {object:179746}",
		["{item:18752}, inside a green patch"] = "{item:18752}, in einer grünen Stelle",
		["{item:18792}, from the satchel"] = "{item:18792}, aus der Tasche",
		["{item:8836} x10"] = "{item:8836} x10",
		["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}, der Priesterlehrer, geht in der {object:32362} von {zone:1455} um die {object:32386} herum. Er gibt dir sein Räuchergefäß für eine Spende von 150 Gold, die bei der Abgabe genommen wird. Behalte das Räuchergefäß.",
		["{npc:11406}: 150 gold"] = "{npc:11406}: 150 Gold",
		["{npc:11489}, inside the West wing"] = "{npc:11489}, im Westflügel",
		["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416} arbeitet im {object:28027} von {zone:1453}. Er schmiedet aus deinen Materialien und 150 Gold die {item:18753}.",
		["{npc:1416}'s materials"] = "{npc:1416}s Materialien",
		["{npc:1416}: 150 gold"] = "{npc:1416}: 150 Gold",
		["{npc:2357} breeds horses in {area:271}'s stable. She makes the {quest:7645} from the 20 biscuits and 50 gold, taken at the hand-in."] = "{npc:2357} züchtet Pferde im Stall von {area:271}. Aus den 20 Keksen und 50 Gold, die bei der Abgabe genommen werden, macht sie die {quest:7645}.",
		["{npc:6171}, Cathedral of Light"] = "{npc:6171}, Kathedrale des Lichts",
		["{npc:928}: the {item:18753}"] = "{npc:928}: {item:18753}",
		["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "Die Rüstmeister von {object:2160} verkaufen Enriched Manna Biscuits, fünf für 60 Silber, sobald die {object:92525} dir freundlich gesinnt ist: {npc:10857} bei {area:3197} oder {npc:11536} bei {area:2268}. Scourgestones und die Quests im Pestland steigern den Ruf.",
} end)()
t.guides["forever/collectibles/mounts/alliance/paladin-warhorse"] = (function() return {
		["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "Auf Stufe 40 schickt dich {npc:6179}, oben in der {object:32386}, zu {npc:6171} in {zone:1453} ({npc:5149} unten gibt denselben Auftrag; nimm einen). Nimm die {area:2257} nach {zone:1453}.",
		["Paladin Warhorse"] = "Schlachtross des Paladins",
		["Your first mount at 40, summoned at will: a paladin buys no horse."] = "Dein erstes Reittier auf Stufe 40, jederzeit beschworen: Ein Paladin kauft kein Pferd.",
		["{npc:6171} stands in the Cathedral of Light. At 40 he offers {quest:1661}: accept it and hand it straight back to learn {spell:13819}. Paladins do not buy a horse."] = "{npc:6171} steht in der Kathedrale des Lichts. Auf Stufe 40 bietet er {quest:1661} an: Nimm sie an und gib sie sofort zurück, um {spell:13819} zu lernen. Paladine kaufen kein Pferd.",
} end)()
t.guides["forever/collectibles/mounts/alliance/ram"] = (function() return {
		["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "Jede Allianzrasse kann diese Widder kaufen, aber um einen zu reiten, braucht man auch {spell:826}, das nur Zwerge mit {skill:762} bekommen. {npc:4772} lehrt es andere Rassen, sobald sie bei {faction:47} Ehrfürchtig sind (der Ruf-Guide für Ironforge zeigt den Weg). Bis dahin kaufe für diesen Charakter keinen Widder.",
		["Learn to ride"] = "Lerne reiten",
		["Pick a colour"] = "Wähle eine Farbe",
		["Ram"] = "Widder",
		["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 40 {npc:4772} teaches {skill:762} to Dwarves for 100g (10% less at Honored with {faction:47}), and it comes with a ram. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:803} liegt östlich von {area:131} an der Straße nach {zone:1432}; {npc:4772} steht neben den Widdern von {npc:1261}. Auf Stufe 40 lehrt {npc:4772} Zwerge {skill:762} für 100g (10% weniger bei Wohlwollend mit {faction:47}), und ein Widder gehört dazu. Andere Rassen lernen {skill:762}, mit ihrem eigenen ersten Reittier, beim Reitlehrer ihrer eigenen Rasse.",
		["{item:5864}, 20g"] = "{item:5864}, 20g",
		["{item:5872}, 20g"] = "{item:5872}, 20g",
		["{item:5873}, 20g"] = "{item:5873}, 20g",
		["{npc:1261} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:1261} verkauft die anderen Farben (im Forever-Client je 20g). Kauf, was du willst, oder nichts, wenn dir das erhaltene Reittier gefällt.",
		["{npc:4772}, riding trainer"] = "{npc:4772}, Reitlehrer",
		["{spell:826} for other races"] = "{spell:826} für andere Rassen",
} end)()
t.guides["forever/collectibles/mounts/alliance/saber"] = (function() return {
		["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "Jede Allianzrasse kann diese Nachtsäbler kaufen, aber um einen zu reiten, braucht man auch {spell:828}, das nur Nachtelfen mit {skill:762} bekommen. {npc:4753} lehrt es andere Rassen, sobald sie bei {faction:69} Ehrfürchtig sind (der Ruf-Guide für Darnassus zeigt den Weg). Bis dahin kaufe für diesen Charakter keinen Nachtsäbler.",
		["Learn to ride"] = "Reiten lernen",
		["Pick a colour"] = "Wähle eine Farbe",
		["Saber"] = "Säbler",
		["new in Forever, 20g; beta players found it here"] = "neu in Forever, 20g; Beta-Spieler fanden es hier",
		["{item:8629}, 20g"] = "{item:8629}, 20g",
		["{item:8631}, 20g"] = "{item:8631}, 20g",
		["{item:8632}, 20g"] = "{item:8632}, 20g",
		["{npc:4730} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:4730} verkauft die anderen Farben (je 20g im Forever-Client). Kauf, welche du willst, oder keine, wenn dir das erhaltene Reittier gefällt.",
		["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 40 {npc:4753} teaches {skill:762} to Night Elves for 100g (10% less at Honored with {faction:69}), and it comes with a saber. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4753} und die Nachtsäbler von {npc:4730} stehen auf dem Reitgelände der {area:1658} bei {faction:69}. Auf Stufe 40 lehrt {npc:4753} Nachtelfen {skill:762} für 100g (10% weniger bei Wohlwollend mit {faction:69}), und ein Nachtsäbler gehört dazu. Andere Rassen lernen {skill:762}, mit ihrem eigenen ersten Reittier, beim Reitlehrer ihrer eigenen Rasse.",
		["{npc:4753}, riding trainer"] = "{npc:4753}, Reitlehrer",
		["{spell:828} for other races"] = "{spell:828} für andere Rassen",
} end)()
t.guides["forever/collectibles/mounts/alliance/stormpike-battle-charger"] = (function() return {
		["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Alliance race can ride it."] = "Der Forever-Client führt es für 200g und Stufe 60. Es läuft mit voller Geschwindigkeit, also braucht man zum Reiten {skill:762} (Geselle); jede Allianzrasse kann es reiten.",
		["{area:2839} (level 51+) raises {faction:730}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13217} waits outside the battleground on the {zone:1416} border above {area:287}; {npc:13216} inside {area:2839} sells the same mount."] = "{area:2839} (ab Stufe 51) steigert {faction:730}: Gewinne, erobere Türme und Friedhöfe und gib die Abgaben des Schlachtfelds ab; der Ruf-Guide für das Alteractal zeigt den schnellsten Weg. {npc:13217} wartet vor dem Schlachtfeld an der Grenze zum {zone:1416} oberhalb von {area:287}; {npc:13216} im Inneren von {area:2839} verkauft dasselbe Reittier.",
		["{npc:13217}, 200g"] = "{npc:13217}, 200g",
} end)()
t.guides["forever/collectibles/mounts/alliance/swift-horse"] = (function() return {
		["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Jede Allianzrasse kann diese Pferde kaufen, aber um eines zu reiten, braucht man auch {spell:824}, das nur Menschen mit {skill:762} bekommen. {npc:4732} lehrt es andere Rassen, sobald sie bei {faction:72} Ehrfürchtig sind (der Ruf-Guide für Stormwind zeigt den Weg). Bis dahin kaufe für diesen Charakter kein Pferd.",
		["Journeyman {skill:762}"] = "Geselle: {skill:762}",
		["Pick a colour"] = "Wähle eine Farbe",
		["Swift Horse"] = "Schnelles Pferd",
		["{item:18776}, 200g"] = "{item:18776}, 200g",
		["{item:18777}, 200g"] = "{item:18777}, 200g",
		["{item:18778}, 200g"] = "{item:18778}, 200g",
		["{npc:384} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} verkauft die anderen Farben (je 200g im Forever-Client). Kaufe, was du willst, oder nichts, wenn dir dein erhaltenes Reittier gefällt.",
		["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 60 {npc:4732} teaches Journeyman {skill:762} to Humans for 1,000g (10% less at Honored with {faction:72}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift horse costs 200g here."] = "{npc:4732} und das Pferdegehege von {npc:384} liegen bei {area:88} im Osten von {zone:1429}. Auf Stufe 60 lehrt {npc:4732} Menschen {skill:762} (Geselle) für 1.000g (10% weniger bei Wohlwollend mit {faction:72}); laut Blizzard gehört ein Reittier dazu. Andere Rassen lernen es beim Reitlehrer ihrer eigenen Rasse. Jedes schnelle Pferd kostet hier 200g.",
		["{npc:4732}, riding trainer"] = "{npc:4732}, Reitlehrer",
		["{spell:824} for other races"] = "{spell:824} für andere Rassen",
} end)()
