		["Alliance guards: touch the edge of {zone:1453} and move on; any one of these names counts"] = "Allianzwachen: Streife nur den Rand des Gebiets {zone:1453} und zieh weiter; jeder dieser Namen zählt",
		["At the south end of Silverpine the road turns east into {zone:1424} by {area:285}. {area:272} in the north-east is the Horde town; {area:271} is Alliance."] = "Am Südende des Silberwalds biegt die Straße bei {area:285} nach Osten ins {zone:1424} ab. {area:272} im Nordosten ist der Hordeort; {area:271} gehört der Allianz.",
		["Discovering an area gives experience scaled to its level, so this runs alongside leveling. Alliance starts in {zone:1429}; dwarves and gnomes can begin at the {zone:1426} step. 12 areas to discover here, levels 5-10."] = "Ein Gebiet zu entdecken gibt Erfahrung passend zu seiner Stufe, also läuft das neben dem Leveln. Die Allianz beginnt in {zone:1429}; Zwerge und Gnome können beim Schritt {zone:1426} anfangen. Hier gibt es 12 Gebiete zu entdecken, Stufe 5-10.",
		["Discovering an area gives experience scaled to its level, so this runs alongside leveling. Horde starts in {zone:1420}; orcs, trolls and tauren arrive by zeppelin from {zone:1454}. 17 areas to discover here, levels 5-10."] = "Ein Gebiet zu entdecken gibt Erfahrung passend zu seiner Stufe, also läuft das neben dem Leveln. Die Horde beginnt in {zone:1420}; Orcs, Trolle und Tauren kommen per Zeppelin aus {zone:1454}. Hier gibt es 17 Gebiete zu entdecken, Stufe 5-10.",
		["Exploration: {zone:1415} 1-30"] = "Erkundung: {zone:1415} 1-30",
		["Exploring the entire world map on one character is a Forever Legacy Challenge (1 account-wide Legacy Point)."] = "Die gesamte Weltkarte mit einem Charakter zu erkunden ist eine Vermächtnisherausforderung von Forever (1 accountweiter Vermächtnispunkt).",
		["Flight path here: {area:108} (Thor)."] = "Flugroute hier: {area:108} (Thor).",
		["Flight path here: {area:144} ({npc:1572})."] = "Flugroute hier: {area:144} ({npc:1572}).",
		["Flight path here: {area:150} ({npc:1571})."] = "Flugroute hier: {area:150} ({npc:1571}).",
		["Flight path here: {area:228} ({npc:2226})."] = "Flugroute hier: {area:228} ({npc:2226}).",
		["Flight path here: {area:271} ({npc:2432})."] = "Flugroute hier: {area:271} ({npc:2432}).",
		["Flight path here: {area:272} (Zarise)."] = "Flugroute hier: {area:272} (Zarise).",
		["Flight path here: {area:42} ({npc:2409})."] = "Flugroute hier: {area:42} ({npc:2409}).",
		["Flight path here: {area:69} ({npc:931})."] = "Flugroute hier: {area:69} ({npc:931}).",
		["Fly from {area:144} to {zone:1453} if you have its flight path; otherwise ride back to {zone:1455} and take the {area:2257}. Walk west out of {zone:1429} past the {area:120} into {zone:1436}."] = "Fliege von {area:144} nach {zone:1453}, wenn du die Flugroute dorthin hast; sonst reite zurück nach {zone:1455} und nimm die {area:2257}. Geh von {zone:1429} aus nach Westen, am {area:120} vorbei, nach {zone:1436}.",
		["Fly from {area:42} to {area:144} in {zone:1432} and ride north through the {area:836} pass into the {zone:1437}."] = "Fliege von {area:42} nach {area:144} in {zone:1432} und reite durch den Pass {area:836} nach Norden in die {zone:1437}.",
		["Follow the road west from {area:287} past {area:285} into {zone:1421}, Horde country with Horde guards at the {area:228}."] = "Folge der Straße von {area:287} nach Westen an {area:285} vorbei in den {zone:1421}, Hordegebiet mit Hordewachen beim Ort {area:228}.",
		["From {area:1002} take the road south into {zone:1431}; {area:42} is east along its main road. Most of Duskwood is level 24-30: come with Redridge behind you."] = "Nimm von {area:1002} aus die Straße nach Süden in den {zone:1431}; {area:42} liegt weiter östlich an der Hauptstraße. Der Großteil des Dämmerwalds ist Stufe 24-30: Komm erst, wenn du das Rotkammgebirge hinter dir hast.",
		["From {area:925} take the {area:807} tunnel west into {zone:1426}. {area:131} and {zone:1455}'s gates are Alliance ground."] = "Nimm von {area:925} aus den Tunnel {area:807} nach Westen in {zone:1426}. {area:131} und die Tore von {zone:1455} sind Allianzgebiet.",
		["Go back east through {zone:1429}: the road past the {area:88} enters Redridge at {area:1002}, where the roads from {zone:1429} and {zone:1431} meet."] = "Geh durch {zone:1429} zurück nach Osten: Die Straße am {area:88} vorbei führt bei {area:1002} ins Rotkammgebirge, wo sich die Straßen aus {zone:1429} und {zone:1431} treffen.",
		["Go east through {zone:1429} to {area:1002}, where Redridge starts. {area:69} is an Alliance town."] = "Geh nach Osten durch den {zone:1429} nach {area:1002}, wo das Rotkammgebirge beginnt. {area:69} ist ein Ort der Allianz.",
		["Hearth or fly back to the {zone:1458} (or go to {zone:1454}), take the zeppelin to {area:117} in {zone:1434} and walk north along the road into {zone:1431}. Northern Stranglethorn is level 30+ off the road."] = "Nimm den Ruhestein oder flieg zurück nach {zone:1458} (oder geh nach {zone:1454}), nimm den Zeppelin zum Ort {area:117} im {zone:1434} und geh die Straße nach Norden in den {zone:1431}. Das nördliche Schlingendorntal ist abseits der Straße ab Stufe 30.",
		["Horde guards: touch the edge of {area:153} and move on"] = "Hordewachen: Streife nur den Rand des Gebiets {area:153} und zieh weiter",
		["Horde guards: touch the edge of {area:154} and move on"] = "Hordewachen: Streife nur den Rand des Gebiets {area:154} und zieh weiter",
		["Horde guards: touch the edge of {area:159} and move on"] = "Hordewachen: Streife nur den Rand des Gebiets {area:159} und zieh weiter",
		["Horde guards: touch the edge of {area:228} and move on"] = "Hordewachen: Streife nur den Rand von {area:228} und zieh weiter",
		["Horde guards: touch the edge of {area:272} and move on"] = "Hordewachen: Streife nur den Rand des Gebiets {area:272} und zieh weiter",
		["Leave {zone:1426} east through the South Gate tunnel; it opens into {zone:1432} by the dwarf king statues of the {area:924}."] = "Verlasse {zone:1426} nach Osten durch den Tunnel am Südtor; er mündet in {zone:1432} bei den Zwergenkönig-Statuen im {area:924}.",
		["Silverpine's road north leads into {zone:1420}. {area:159}, {area:154} and the {zone:1458} ruins are Horde ground."] = "Die Straße des Silberwalds führt nach Norden nach {zone:1420}. {area:159}, {area:154} und die Ruinen von {zone:1458} sind Hordegebiet.",
		["Take the boat from {area:150} to {area:271}."] = "Nimm das Boot von {area:150} nach {area:271}.",
		["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}, then leave the city through its gates."] = "Nimm die {area:2257} vom {object:28027} in {zone:1453} nach {zone:1455} und verlasse die Stadt dann durch ihre Tore.",
		["The {area:836} pass in south-eastern {zone:1437} leads down into {zone:1432} by {area:925}."] = "Der Pass {area:836} im Südosten des {zone:1437} führt bei {area:925} hinunter nach {zone:1432}.",
		["Walk east from {area:287} into the {zone:1417} (level 30+ creatures off the road), south to the {area:881} bridge, and across it into the {zone:1437}. {area:150} is an Alliance town."] = "Geh von {area:287} nach Osten ins {zone:1417} (abseits der Straße Kreaturen ab Stufe 30), nach Süden zur Brücke {area:881} und über sie ins {zone:1437}. {area:150} ist ein Ort der Allianz.",
		["any one of these names counts"] = "jeder dieser Namen zählt",
		["the discovery triggers at the {area:1038}: do not go into {area:1037} itself"] = "die Entdeckung löst an den {area:1038} aus: Geh nicht nach {area:1037} selbst hinein",
		["{area:154} opens onto {zone:1420}; {area:159} is east along the road. Orcs, trolls and tauren arrive at the zeppelin tower by the {zone:1458}."] = "{area:154} öffnet sich nach {zone:1420}; {area:159} liegt östlich an der Straße. Orcs, Trolle und Tauren kommen am Zeppelinturm bei {zone:1458} an.",
		["{area:9} opens onto {zone:1429}; {area:87} is south down the road."] = "{area:9} öffnet sich nach {zone:1429}; {area:87} liegt südlich die Straße hinunter.",
		["{zone:1421} is south of {zone:1420}: follow the road south from {area:159}."] = "{zone:1421} liegt südlich von {zone:1420}: Folge der Straße von {area:159} nach Süden.",
		["{zone:1429} is north of {zone:1436} and {zone:1431}. {area:87}, {area:9} and {zone:1453}'s gates are Alliance ground with guards."] = "Der {zone:1429} liegt nördlich von {zone:1436} und {zone:1431}. {area:87}, {area:9} und die Tore von {zone:1453} sind Allianzgebiet mit Wachen.",
		["{zone:1436} borders {zone:1431} to the west. {area:108} is an Alliance town."] = "{zone:1436} grenzt im Westen an den {zone:1431}. {area:108} ist ein Ort der Allianz.",
} end)()
t.guides["forever/exploration/eastern-kingdoms-30-45"] = (function() return {
		["11 areas to discover here, levels 36-43."] = "Hier gibt es 11 Gebiete zu entdecken, Stufe 36-43.",
		["14 areas to discover here, levels 36-44. Flight paths: {area:16724} in the south-east (Alliance), {area:16743} in the middle (Horde)."] = "Hier gibt es 14 Gebiete zu entdecken, Stufe 36-44. Flugrouten: {area:16724} im Südosten (Allianz), {area:16743} in der Mitte (Horde).",
