		["{area:1276} tunnel in eastern Stonetalon leads north into {zone:1440}. {area:431} and {area:2897} are Horde; {area:415} is Alliance."] = "Der Tunnel ({area:1276}) im Osten des Steinkrallengebirges führt nach Norden ins {zone:1440}. {area:431} und {area:2897} gehören der Horde; {area:415} der Allianz.",
		["{area:188} opens onto {zone:1438}; {area:186} is south along the road. {area:702}, at the foot of the tree, is reached through the portal in {zone:1457}."] = "{area:188} öffnet sich nach {zone:1438}; {area:186} liegt südlich an der Straße. {area:702} am Fuß des Baums erreichst du durch das Portal in {zone:1457}.",
} end)()
t.guides["forever/exploration/kalimdor-30-45"] = (function() return {
		["16 areas to discover here, levels 41-60."] = "Hier gibt es 16 Gebiete zu entdecken, Stufe 41-60.",
		["7 areas to discover here, levels 36-61."] = "Hier gibt es 7 Gebiete zu entdecken, Stufe 36-61.",
