		["Flight path here: {area:976} ({npc:7823})."] = "Flugroute hier: {area:976} ({npc:7823}).",
		["Flight path here: {area:976} ({npc:7824})."] = "Flugroute hier: {area:976} ({npc:7824}).",
		["Flight path here: {zone:1450} (Faustron)."] = "Flugroute hier: {zone:1450} (Faustron).",
		["Flight path here: {zone:1450} (Sindrayl)."] = "Flugroute hier: {zone:1450} (Sindrayl).",
		["Fly to {area:1237} if you have it, otherwise to {area:431}, and walk east out of {zone:1440} into {zone:1447}."] = "Flieg nach {area:1237}, falls du die Route hast, sonst zum {area:431}, und lauf nach Osten aus {zone:1440} hinaus nach {zone:1447}.",
		["Fly to {area:3137} if you have it, otherwise to {area:415}, and walk east out of {zone:1440} into {zone:1447}."] = "Flieg nach {area:3137}, falls du die Route hast, sonst nach {area:415}, und lauf nach Osten aus {zone:1440} hinaus nach {zone:1447}.",
		["From western {zone:1446} take the path down into {zone:1449}. {area:541} in the north is a neutral camp."] = "Nimm vom westlichen {zone:1446} den Pfad hinab in den {zone:1449}. {area:541} im Norden ist ein neutrales Lager.",
		["Horde town: Alliance characters only need to touch its edge (guards)"] = "Hordenort: Allianzcharaktere müssen nur den Rand berühren (Wachen)",
		["Starts in {zone:1446}, south of {zone:1445}. The last area of this guide completes the {zone:1414} map. 20 areas to discover here, levels 40-50."] = "Beginnt in {zone:1446}, südlich der {zone:1445}. Das letzte Gebiet dieses Guides vervollständigt die Karte von {zone:1414}. Hier gibt es 20 Gebiete zu entdecken, Stufe 40-50.",
		["Take the {area:1769} tunnel in northern {zone:1448} through to {zone:1450} (druids: {spell:18960}). {area:2361} is neutral."] = "Nimm den Tunnel der {area:1769} im nördlichen {zone:1448} hindurch nach {zone:1450} (Druiden: {spell:18960}). {area:2361} ist neutral.",
		["The other exit of the {area:1769} tunnel leads into {zone:1452}. {area:2255} is a neutral goblin town with flight masters for both factions."] = "Der andere Ausgang des Tunnels der {area:1769} führt nach {zone:1452}. {area:2255} ist eine neutrale Goblinstadt mit Flugmeistern für beide Fraktionen.",
		["any one of these names counts"] = "jeder dieser Namen zählt",
		["{zone:1446} is south of {zone:1445} and {zone:1441}. {area:976} is a neutral goblin town."] = "{zone:1446} liegt südlich der {zone:1445} und von {zone:1441}. {area:976} ist eine neutrale Goblinstadt.",
		["{zone:1448} is north of {zone:1440}."] = "Der {zone:1448} liegt nördlich von {zone:1440}.",
		["{zone:1451} is west of {zone:1449}, through the pass in its north-west. {area:3425} is neutral."] = "{zone:1451} liegt westlich von {zone:1449}, durch den Pass im Nordwesten. {area:3425} ist neutral.",
		["{zone:2482} is reached from {zone:1452} through {area:2256} in the south. It is Forever's endgame leveling zone."] = "{zone:2482} erreichst du von {zone:1452} aus durch die {area:2256} im Süden. Es ist das Endgame-Levelgebiet von Forever.",
} end)()
t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "Erkundung: {zone:2521}",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "Himmelsgeborene starten hier. Alle anderen nehmen ein Himmelsboot, etwa alle fünf Minuten; jede Fraktion darf jedes nehmen.",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "Das Himmelsboot legt an den Klippen südlich des {area:17045} ab, nördlich von {zone:1456} (ein weiteres fliegt von {area:279}).",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "Das Himmelsboot legt an der Nordseite von {area:279} im {zone:1416} ab (ein weiteres fliegt nördlich von {zone:1456}).",
		["any one of these names counts"] = "jeder dieser Namen zählt",
		["{zone:2521} is the Skyborne starting island, a world of its own in {area:17221}; anyone may visit. 20 areas to discover here, levels 3-12."] = "{zone:2521} ist die Startinsel der Himmelsgeborenen, eine eigene Welt in {area:17221}; jeder darf sie besuchen. Hier gibt es 20 Gebiete zu entdecken, Stufe 3-12.",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Hilf {npc:261366}: Bleib bei ihm, wenn {npc:261367} und die Marinesoldaten von {area:21} den Kamm heraufkommen",
		["At the {area:2362}"] = "Am {area:2362}",
		["At the {object:147538}: summons {quest:882}"] = "Am toten Baum: beschwört {quest:882}",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438}: pull {npc:3438} and the quilboar away from them one at a time."] = "Zurück zum Lager der Grimmhauer. Geomanten und Verteidiger halten die östliche Hälfte; {npc:3438} läuft zwischen ihnen herum.\nVorsicht: Fleischfresser und Berserker der Grimmhauer (18-19) sind Elites im Nordosten des Lagers, nahe {npc:3438}: Zieh {npc:3438} und die Stacheleber einzeln von ihnen weg.",
		["Bristleback camps"] = "Lager der Borstennacken",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}; they drop the {item:6652}. The {item:5026} comes from the Razormane on your next visit to their camp."] = "Kultisten der Burning Blade halten {area:1898} im Norden von {zone:1411}; sie lassen {item:6652} fallen. {item:5026} bekommst du bei deinem nächsten Besuch im Lager der Grimmhauer.",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}. {npc:11802} steht oben in seinem Gebäude in {area:2361}: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran ist im Stacheleberlager westlich der Straße angekettet.",
		["Down the {area:458} to {area:378} again."] = "Die {area:458} wieder hinunter zum {area:378}.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Füll {item:7766} am Wasserloch der Stacheleber",
		["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "Flieg von Crossroads nach {area:1638}. {quest:853} wartet in {area:2197}, der Höhle unter {area:1640}: Gib dort zuerst die Sporen ab, solange ihre Zeit läuft. Dann lässt dich {npc:3033} auf {area:1639} trainieren.",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "Flieg zum Trainieren nach {area:1638}: {npc:3033} ist auf der {area:1639}.",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Follow the road east to the outpost above the {area:814}."] = "Folge der Straße nach Osten zum Außenposten über dem {area:814}.",
		["Follow the road south-east to {area:392} on the coast."] = "Folge der Straße nach Südosten nach {area:392} an der Küste.",
		["Follow the {area:458} south to {area:378}."] = "Folge der {area:458} nach Süden zum {area:378}.",
		["Grimtotem camp"] = "Lager der Grimmtotem",
		["He gives you the {item:15826}"] = "Er gibt dir {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Als Nächstes bietet er {quest:1838} an (1838, Stufe 30): Sie erfordert {area:1717} und schickt dich durch ganz Kalimdor und die Östlichen Königreiche. Der Kriegerklassen-Guide {quest:1838} deckt sie ab.",
		["In from the north gate: {npc:3464} first, {npc:3338} by the inn, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "Durch das Nordtor hinein: zuerst {npc:3464}, {npc:3338} beim Gasthaus, dann hinauf zu {npc:3449} und {npc:3429} auf der Turmplattform, wo der Flugmeister steht.",
		["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Im Lager halten Wassersucher und Dornenwirker die westliche Hälfte, Jäger die Mitte; die Vorratskisten stehen am östlichen Ende.\nEbenenschreiter hier zählen für die Schnäbel.\nVorsicht: Fleischfresser und Berserker der Grimmhauer (18-19) sind Elites; sie stehen im Nordosten des Lagers neben den Vorratskisten: Zieh die Stacheleber einzeln von ihnen weg.",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Behalte sie: {npc:12696} in {zone:1440}, nächster Guide",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "Nach Norden zu {area:383}. {npc:3682} lagert unterhalb der Hügel; {npc:261366}, der Einsiedler auf dem Kamm hinter ihm, hat erst Arbeit für dich, wenn {npc:3682} dich hinaufschickt.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate."] = "Nach Norden die {area:458} hinauf nach Crossroads: {npc:3448} am Südtor, {npc:3432} beim Gasthaus, {npc:3428} westlich des Nordtors.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "Die {area:458} hinauf nach Norden zum Wegekreuz: {npc:3448} am Südtor, {npc:3432} beim Gasthaus, {npc:3428} westlich des Nordtors. Behalte {item:5075}: {npc:3430} nimmt ihn beim nächsten Halt im {area:378} entgegen.",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "Auf dem Rückweg den {area:1076} hinunter wird {npc:11856} in der Hütte von {npc:11858} an der Straßenbiegung festgehalten. Sobald du ihre Quest annimmst, läuft sie ohne zu warten direkt nach Südosten zum {area:2538}, dem niedergebrannten Dorf: Bleib dicht bei ihr, sonst schlägt die Quest fehl.\nVorsicht: Drei Grimmtotem lauern ihr im niedergebrannten Dorf auf und greifen sie an, nicht dich: Zieh sie von ihr weg und töte schnell ihren Zauberwirker.",
		["Over the {area:814} bridge below {area:379} and south along the {zone:1411} bank to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Über die Brücke von {area:814} unterhalb von {area:379} und am Ufer von {zone:1411} entlang nach Süden, bis ein schmaler Pfad den Berg hinaufführt: {npc:5900} hütet den Schrein oben. Pass auf dem Weg hinauf an den Kanten auf und komm denselben Pfad wieder herunter.",
		["Raptor nests"] = "Raptornester",
		["Razormane camp"] = "Lager der Grimmhauer",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "Von {area:392} nach Südwesten über die Ebenen zu {area:1697}: Die drei Nester liegen zusammen südwestlich der Oase; Bluthornsensenklauen bewachen sie. Jedes Nest braucht {item:5165}: Töte Raptoren der Bluthorn (die meisten lassen eine fallen), bis du drei hast, und benutze dann an jedem Nest eine Feder.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "Tauren: {npc:11957} wartet auf dem südlichen Hügel über der Brücke. Himmelsgeborene: {npc:272054} steht südlich der Zwillingsbrücken. Dann die Grabhügel östlich des Sees: Verlass deine Gestalt, klick die Statue am Eingang an für fünf Minuten Verstohlenheit, halte dich von den Geistern darin fern und nimm von jedem Relikt eins; {item:280680} liegt am Fuß der weißen Katzenstatue.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Die Vorarbeiter und Vollstrecker der Venture Co. an der Mine in der Nordostecke des Gebiets lassen {item:5097} fallen.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "Die Straße steigt als {area:1076} nach Norden an. {quest:1483} hat eine Hütte, wo die Straße nach Osten zum {area:461} abzweigt.",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} ist die Schlucht unter dem {object:172982}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792} liegt am Nordrand von {area:382}, beim Turm der Venture Co. Darin ist {item:15883} für {quest:30}.",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Donnerechsen und Blitzechsen grasen gleich jenseits der Brücke unterhalb von {area:379}.\nVorsicht: Halikor, eine Elite der Stufe 12, streift zwischen den Echsen über {area:369}: Achte auf ihn, bevor du pullst.",
		["Thunder lizards across the river"] = "Donnerechsen jenseits des Flusses",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "Donnerfalkenwolkenkitzler kreisen über denselben Ebenen südlich des Lagers.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "Donnerköpfe grasen auf den Ebenen gleich südlich vom {area:378}. {quest:884}, eine blaue Donnerechse, streift zwischen ihnen umher: Ihr Schwanzstachel startet eine Quest.",
		["Twitching Antennae"] = "Zuckende Fühler",
		["Twitching Antennae from the silithid"] = "Zuckende Fühler von den Silithiden",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "Vom niedergebrannten Dorf nach Westen nach {area:2539}: {npc:12816} steht gleich davor, noch vor dem Dorf.",
		["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Wenn du schon im Lager bist: die Wassersucher und Dornenwirker für {npc:3429} in der westlichen Hälfte, die Jäger in der Mitte, die Vorratskisten am östlichen Ende.\nVorsicht: Fleischfresser und Berserker der Grimmhauer (18-19) sind Elites; sie stehen im Nordosten des Lagers neben den Vorratskisten: Zieh die Stacheleber einzeln von ihnen weg.",
		["{area:1898} cultists"] = "Kultisten in {area:1898}",
		["{item:10338}, from any zhevra; Zhevra Chargers graze around the tree"] = "{item:10338}, von jedem Zhevra; Zhevra-Stürmer grasen rund um den Baum",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, aus einem {object:177785} im See",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} von {npc:3490}; Kräuterkundige pflücken es auf den Ebenen",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} in {area:2361} fliegt Druiden dorthin",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, am Schrein: {area:2362}",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: der Willkommensgruß von {npc:3033}",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, in der Hütte von {npc:11858}",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857}: Behalte sie, {npc:11864} am {area:460} im Guide für {zone:1413} & Steinkrallengebirge",
		["{npc:16227}, beside {npc:3442}"] = "{npc:16227}, neben {npc:3442}",
		["{npc:246344} teaches Paladins in {area:1638}. You have no flight path there yet: fly to {area:378}, head west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "{npc:246344} lehrt Paladine in {area:1638}. Du hast dort noch keinen Flugpunkt: Flieg nach {area:378}, geh nach Westen durch {zone:1412} und einen Aufzug hinauf und nimm den Flugpunkt bei {npc:2995} auf der mittleren Anhöhe.",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal."] = "{npc:262119} und seine Marinesoldaten halten die zerstörte Karawane südlich von {npc:261366}. Die Marinesoldaten sind verbunden: Pullst du einen, rufst du den Rest. Zieh vom Rand und lauf; sie lassen schnell ab, sodass du das Lager einzeln ausdünnen kannst, bevor du den Korporal angehst.",
		["{npc:3338} by the inn first, then the innkeeper, Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate last. His seed test waits for the {npc:3395} pass at the {area:388}: go straight on north-west to the {area:383}. After the spores Helbrim offers {quest:853}, a delivery to {zone:1456} within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to {zone:1456})."] = "Zuerst {npc:3338} beim Gasthaus, dann der Gastwirt, Helbrim beim Nordtor, {npc:3429} und {npc:3449} auf der Turmplattform, {npc:3432} beim Gasthaus und zuletzt {npc:3448} am Südtor. Sein Samentest wartet auf den Abstecher zu {npc:3395} bei {area:388}: Geh direkt weiter nach Nordwesten zu {area:383}. Nach den Sporen bietet Helbrim {quest:853} an, eine Lieferung nach {zone:1456} innerhalb von 45 Minuten: Diese Route geht nicht dorthin, also lass sie liegen (Druiden nehmen sie beim nächsten Halt in Crossroads an, direkt vor ihrem Flug nach {zone:1456}).",
		["{npc:3390}: 45 minutes, for Zamah on the {zone:1456} step next"] = "{npc:3390}: 45 Minuten, für Zamah im nächsten Schritt in {zone:1456}",
		["{npc:3391}, upstairs"] = "{npc:3391}, oben",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the Crossroads. Test {npc:3448}'s seeds at the bubbling fissure on the oasis' east bank while you are there."] = "{npc:3395} läuft zwischen den Kolkar bei {area:388} südöstlich von Crossroads herum. Teste die Samen von {npc:3448} an der blubbernden Spalte am Ostufer der Oase, wenn du schon dort bist.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for {npc:3448}."] = "{npc:3396} führt die Kolkar am Westufer von {area:387} an, südlich von {npc:3389}. Er läuft dieses Ufer ab, von etwa 46,36 im Norden bis 46,42 im Süden: Ist er nicht am Pfeil, folge dem Ufer, bis du ihn triffst. Gib seinen Kopf bei deinem letzten Halt in Crossroads bei {npc:3389} ab. Oasenschnappkiefer kriechen dort im Wasser der Oase: Ihre Panzer sind für {npc:3448}.",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, oben auf dem Turm",
		["{npc:3430}, in the cage"] = "{npc:3430}, im Käfig",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} bietet {quest:95774} an, sobald {quest:4921} abgegeben ist",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: Die Konsole ist in {area:382}, später",
		["{npc:3448}: the Oasis Snapjaws at {area:387}, with {npc:3396} after the {zone:1454} trip"] = "{npc:3448}: die Oasenschnappkiefer bei {area:387}, mit {npc:3396} nach dem Ausflug nach {zone:1454}",
		["{npc:3448}: the bubbling fissure at the {area:388}, on the {npc:3395} pass"] = "{npc:3448}: die blubbernde Spalte bei {area:388}, beim Abstecher zu {npc:3395}",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: Die Harpyien kommen später, in {area:383}",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} ist in der Feste angekettet. Sprich mit ihm, um die Eskorte zu starten, und bleib dicht dran: Soldaten von Theramore greifen auf dem Weg hinaus an. Er führt dich zurück nach {area:392}.",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197} lebt in {area:2539}, dem Trolldorf gleich hinter der Grenze zum Steinkrallengebirge, am Ende der Straße westlich von {npc:3389}.",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201}: für {npc:3442}, neben dem Flugmeister von {area:392}, am Ende des Guides für {zone:1413} & Steinkrallengebirge",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} lagert an der Straße nach Osten Richtung {area:392}.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} macht aus dem Teer und dem Beutel {item:6636}. Benutze es am Kohlenbecken neben ihm, um {npc:5893} sichtbar zu machen, töte sie für {item:6655} und leg die Glut dann ins Kohlenbecken.",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} wartet auf dem Hügel südlich von {area:392}, auf deinem Weg nach Norden.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} steht auf dem Kamm nördlich des Lagers der Grimmhauer.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, dein {item:5176} und {item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}, ein paar Schritte entfernt",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018} steht im {object:172961} auf der Westseite der Stadt.",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} steht im {object:172961}, auf der Westseite der Stadt.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: {npc:4606} in {zone:1458}, zwei Guides weiter",
		["{object:3972} poster"] = "Plakat „{object:3972}“",
		["{quest:1492}, on the dock"] = "{quest:1492}, am Kai",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, nächster Guide",
		["{quest:853}, in the {area:2197}"] = "{quest:853}, in {area:2197}",
		["{quest:865}, if still open: Sunscale Scytheclaws prowl among the lions"] = "{quest:865}, falls noch offen: Bluthornsensenklauen streifen zwischen den Löwen umher",
		["{zone:1454} class quests"] = "Klassenquests in {zone:1454}",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Class trainer"] = "Klassenlehrer",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Folge der Straße nach Nordosten zum Haus der Yoricks bei {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "Folge der Straße nach Süden. Die {object:1627} steht daneben, nördlich von Pyrewood.",
		["Mottled Worgs"] = "Scheckige Worgs",
		["Mottled Worgs prowl the hills around the house."] = "Scheckige Worgs streifen durch die Hügel um das Haus.",
		["North again to the Yoricks' house."] = "Wieder nach Norden zum Haus der Yoricks.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "Nördlich von {area:228}. {npc:1983} spukt auf dem {area:240}: Töte sie und geh dann über das Feld.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Sprich mit {npc:10181} im {object:36126}: {quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "Sprich mit {npc:10540} in Grommash Hold",
		["Speak with {npc:3230}, in Grommash Hold"] = "Sprich mit {npc:3230} in Grommash Hold",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "Nimm die Straße nach Norden Richtung {zone:1420}: Das Haus der Yoricks bei {area:238} liegt auf dem Weg. {quest:425} lauert ein kurzes Stück westlich davon.",
		["Talk to {npc:10181}"] = "Sprich mit {npc:10181}",
		["Talk to {npc:10540}"] = "Sprich mit {npc:10540}",
		["Talk to {npc:3230}"] = "Sprich mit {npc:3230}",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Rohrkolben und Speergras wachsen am Wasser im {object:172958}, östlich der Gasse.",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960} ist die Schlucht unter dem {object:172982}; {quest:829} steht an ihrem hinteren Ende.",
		["Vile Fin murlocs"] = "Murlocs der Finsterflossen",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} ist die Gruftstadt der Verlassenen mitten im Wald. Alle, die du brauchst, stehen um den Grufteingang; {npc:2226}, der Fledermausführer, steht gleich östlich davon.",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, im Apothekarium",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}, der Alchemielehrer, steht gleich neben {npc:3348}.",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}, der Verzauberkunstlehrer, arbeitet in der Gasse.",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}: für Quinn, am Ende auf der Straße nach Norden",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} wartet nordöstlich des Hauses. Eskortiere ihn zurück zu {npc:1950}; unterwegs greifen Worgs an.",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226}: {npc:4556} in {zone:1458}, am Ende dieses Guides; den Flug musst du nicht kaufen",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} bildet in {area:159} Paladine aus, ein kurzer Weg die Straße hinauf nach Norden von den Zeppelintürmen. Für den Silberwald kommst du dieselbe Straße zurück.",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}, der Schneiderlehrer, ist im {object:172958}.",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} und {npc:3347} führen den Alchemieladen in der Gasse; {npc:11046} ist nebenan.",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}, der Lederverarbeitungslehrer, arbeitet im {object:172958}.",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}, die Kräuterkundelehrerin, hat ihren Laden in der Gasse.",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{npc:4551}, the bat handler"] = "{npc:4551}, der Fledermausführer",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}: Behalte {item:16210}, Podrig nimmt sie beim nächsten Halt in {area:228} mit 22 entgegen",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}, der Waffenhändler neben dem Fledermausführer",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}, der Ingenieurskunstlehrer, arbeitet in {zone:1458}.",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}: Camping 101, von {npc:265812}s Lagerfeuer in Tirisfal",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}, der Bergbaulehrer, arbeitet in {zone:1458}.",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}: Camping 101, von {npc:265812}s Lagerfeuer in Tirisfal",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}, der Schmiedekunstlehrer, arbeitet in {zone:1458}.",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}: Camping 101, von {npc:265812}s Lagerfeuer in Tirisfal",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, in Grommash Hold",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, eine Tour zu den Anführern der Horde",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}, der Kürschnerlehrer, steht im {object:172958}.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}: Camping 101, von Brakks Lagerfeuer in {zone:1411}",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} wird an {object:24776} abgegeben, einem Grab ein paar Schritte südlich des Grufteingangs, nicht bei einer Person.",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Bael'dun fortress"] = "Festung von Bael'dun",
		["East along the road from {area:2539} to {npc:4049}'s camp, on the way to {area:378}."] = "Nach Osten die Straße entlang von {area:2539} zum Lager von {npc:4049}, auf dem Weg zum {area:378}.",
		["Fly to the Crossroads from the wind rider master: {npc:2995} on {zone:1456}'s central rise."] = "Flieg vom Windreitermeister zum Wegekreuz: {npc:2995} auf der mittleren Anhöhe von {zone:1456}.",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:1638} first: two of its elders give quests worked on this guide's and the next guide's walks."] = "Flieg zuerst nach {area:1638}: Zwei seiner Ältesten vergeben Quests, die auf den Wegen dieses und des nächsten Guides erledigt werden.",
		["Fly to {area:378}"] = "Flieg zum {area:378}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Folge der Straße nach Norden Richtung {area:467}. Gehörnte Renner grasen am Weg; die Blutsaftbestien, Mondlichtläufer und Siechdrachen streifen durch die Wälder unterhalb des Gipfels, und die Cenarischen Druiden halten den Hain dort.",
		["Follow the road west past Regthar's bunkers and {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Folge der Straße nach Westen an Regthars Bunkern und dem Lager von {npc:4049} vorbei ins Steinkrallengebirge: {npc:3995} wartet unter der Erde in {area:2539}, am Fuß des {area:1076}.",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "Folge der Straße nach Westen an Regthars Bunkern vorbei: {npc:4049} lagert an ihrem Rand am Übergang zum Steinkrallengebirge.",
		["From {area:2539} follow the road east to {npc:4049}'s camp, then south-east across the plains to {area:378}."] = "Folge von {area:2539} der Straße nach Osten zum Lager von {npc:4049}, dann nach Südosten über die Ebenen zum {area:378}.",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "Folge vom {area:378} der Straße nach Westen durch das Tor nach {zone:1412}, dann nach Norden an {area:222} vorbei nach {zone:1456}; ein Aufzug am Fuß der Klippen bringt dich hinauf.",
		["Gaea Dirt Mounds"] = "Gaeaerdhügel",
		["Gaea Seeds"] = "Gaeasamenkörner",
		["Head back down the {area:1076} to {area:2539}."] = "Geh den {area:1076} zurück hinunter nach {area:2539}.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "Südwestlich vom Sonnenfels liegt das {area:465}. Pflanz die Gaeasamenkörner in die Erdhügel auf dem Talgrund; die Feuerelementare lassen {item:16312} fallen. Harpyien und Wegelagerinnen der Blutfurien nisten auf der Nordseite, Töterinnen und Wildfedern im Süden.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "Die Flugmaschine der Zwerge steht auf ihrer Plattform in der Grabungsstätte. Benutze {item:5021}, den dir {npc:3341} gegeben hat, an ihr.",
		["The flying machine"] = "Die Flugmaschine",
		["The road west past {npc:4049}'s camp"] = "Die Straße nach Westen am Lager von {npc:4049} vorbei",
		["The {area:1718}"] = "{area:1718}",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362} wächst auf dem Grund des {area:464}, vor demselben Südufer: Tauch zu den Pflanzen und den Haufen getrockneten Düsterkrauts; beide geben Schoten. Achte auf deinen Atem.",
		["To {zone:1456}"] = "Nach {zone:1456}",
		["Up the {area:1076} past {npc:4201} and west to {area:460}; coming from {npc:4073}, back west past Ziz's hut."] = "Den {area:1076} hinauf an {npc:4201} vorbei und nach Westen zum {area:460}; wenn du von {npc:4073} kommst, zurück nach Westen an Ziz' Hütte vorbei.",
		["Up the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Den {area:1076} hinauf zur Hütte von {npc:4201}, dann nach Osten die Straße entlang Richtung {area:461}: {npc:4074} patrouilliert auf der Straße gleich östlich der Gabelung, {npc:4073} an den Hängen weiter nordöstlich unterhalb des Felsens. Beide sind einzelne Schredderroboter; sie wandern umher, also folge der Straße, bis du auf sie triffst.",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, von jeder Harpyie der Blutfurien",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}, oben am Aufzug",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: Glitzernde Sonnensteine von den Harpyien der Blutfurien",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, neben {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, oben auf dem Felsvorsprung",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864} steht am Freudenfeuer im Sonnenfels: Makabas Nachricht, dass Kaya lebt, ist für sie bestimmt.",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, oben im Baum gleich östlich von {npc:3341}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, der Windreitermeister, steht auf der mittleren Anhöhe: Hol dir seine Flugroute, falls du sie noch nicht hast. {npc:3024} und {npc:4721} stehen ein kurzes Stück östlich von ihm.",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}: {object:667362} wächst im {area:464}, beim Sonnenfels",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, oben auf dem Turm",
		["{npc:3430}, in the cage"] = "{npc:3430}, im Käfig",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, am Nordrand des Lagers",
		["{npc:3442} stands beside the flight master you land at."] = "{npc:3442} steht neben dem Flugmeister, bei dem du landest.",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}: {quest:1094}, von {npc:4201}",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way up"] = "{npc:4049}: {npc:4074} und {npc:4073} streifen östlich von {npc:4201} umher, auf dem Weg nach oben",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}s nächste Quest, Ordanus, liegt auf der Allianzseite von {zone:1440}. Überspring sie.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, vor dem Tor",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}: Die Phiole kommt aus dem {zone:1440}, nächster Guide",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "Die Hütte von {npc:5899} steht auf dem Grat über dem Wasserloch der Stacheleber, südlich von {area:378}, auf dem Weg nach {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: Der blaue Wasserschlauch wird im {zone:1440} gefüllt, nächster Guide",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: der rote Wasserschlauch aus {area:272}",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, ein großer Dreschadon, schwimmt im seichten Wasser vor der Küste ({area:391}), östlich von {npc:3388} Skyseer.",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
		["{zone:1456} first: two of its elders give quests worked on this guide's and the next guide's walks. Fly to {area:378}; from there it is a walk west into {zone:1412} and north to the bluffs."] = "Zuerst {zone:1456}: Zwei seiner Ältesten vergeben Quests, die auf den Wegen dieses und des nächsten Guides erledigt werden. Flieg zum {area:378}; von dort geht es zu Fuß nach Westen nach {zone:1412} und nach Norden zu den Klippen.",
		["{zone:1456}'s central rise"] = "Mittlere Anhöhe von {zone:1456}",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "Zurück auf die Straße nach Süden. Wo sie nach Osten nach {area:287} abbiegt, wartet {npc:2214} am {area:285}.",
		["Below ground"] = "Unter der Erde",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177790}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "Die Straße durch den Silberwald hinunter zum {area:228}: von den Zeppelintürmen nach Süden durch Tirisfal; von {object:177790} nach Südosten von der Küste zur Straße. {npc:2121} und {npc:1937} stehen am Eingang der Gruft.",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Jeder Naga der Rächerflossen am Strand nördlich des Außenpostens lässt Köpfe fallen.",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "Geh von Seereths Lager nach Nordosten durch {zone:1413} zur Straße nördlich des Wegekreuzes; Schurken, die von Fizzules Turm kommen, gehen nach Westen dorthin. {npc:8582} steht auf dem Wachturm am {area:1703}, wo die Straße nach {zone:1440} führt.",
		["Naga brazier"] = "Nagakohlenpfanne",
		["Naga heads"] = "Nagaköpfe",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "Auf dem Weg nach Westen steckt {npc:267214} in einer Schlucht südlich der Hauptstraße fest, südöstlich von {area:415}. Schattenhornhirsche und Ashenvalebären streifen rundherum durch die Wälder.",
		["Out of the inn to the {area:431} flight master and fly to {area:1637}."] = "Raus aus dem Gasthaus zum Flugmeister von {area:431} und flieg nach {area:1637}.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Steuere {npc:267214}s {npc:271181} innerhalb von vier Minuten aus der Schlucht zur Hauptstraße; bricht die Kanalisierung ab, frag {npc:267214} erneut.",
		["Thistlefur Hold"] = "Höhle der Distelfelle",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers Ashenvale Outrunners: leave it for the next {zone:1440} visit, at 26."] = "{area:431} liegt gleich nördlich die Straße hinauf. Von Süden kommend sind zuerst der Flugmeister und das Jagdbrett von {npc:12696} bei {area:428} dran, dann die Händler. {npc:12867} im Holzfällerlager bietet „Die Kundschafter von Ashenvale“ an: Heb sie dir für den nächsten Besuch in {zone:1440} auf, mit 26.",
		["{item:15882}, from the {object:177790}"] = "{item:15882}, aus {object:177790}",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, von einem {npc:1973}",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Darthalia in {area:272}",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{npc:2391} in {area:272} lehrt Gifte: behalte sie",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} bildet in {area:159} Paladine aus, ein kurzer Weg die Straße hinauf nach Norden von den Zeppelintürmen. Für den Silberwald kommst du dieselbe Straße zurück.",
		["{npc:271181}, on the road"] = "{npc:271181}, auf der Straße",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} steht in {object:172960}. Benutze dort {item:6626} am Beschwörungskreis und besiege die Sukkubus, um sie zu binden.",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389} steht gleich westlich des Eingangs der Gruft: Übergib ihm {item:16210} aus {zone:1458}.",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "Hast du „Mission: Possible But Not Probable“ bei Shenthul abgegeben, bring {quest:2479} zu {npc:2391} in {area:272}. Bleib neben ihm, bis das Brauziel abgeschlossen ist, und gib dann die Folgequest ab, um Gifte zu lernen. Schließe sie auch dann ab, wenn das Zanzilgift schon entfernt wurde; das Entfernen des Debuffs allein lehrt die Fertigkeit nicht.",
		["Back to {area:272}"] = "Zurück nach {area:272}",
		["Bears, creepers and lions"] = "Bären, Krabbler und Löwen",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "Drull und {npc:2238} sind in Gebäuden im Hof der {area:275} angekettet. Für ihre Schlösser brauchst du Schlüssel: {npc:2427} trägt den {item:3467} und {npc:2428} den {item:3499}, beide in der Burg. Töte sie und öffne dann beide Schlösser.\nGeh von {area:272} nach Südosten in die Hügel auf dem Weg zur {area:275}. Schurken und Wachmänner des Syndikats halten die Lager unterwegs.",
		["Drull's ball and chain"] = "Drulls Kugel und Kette",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Füll den {item:7768} am {object:107045} neben dem Gasthaus",
		["Fly to the {area:1497}"] = "Flieg nach {area:1497}",
		["Just south of Masoj, the {item:3502} grow on the hillsides above the river."] = "Direkt südlich von Masoj wachsen die {item:3502} an den Hängen über dem Fluss.",
		["Keep it: the {area:287} coast, later on the route"] = "Behalte es: die Küste von {area:287}, später auf der Route",
		["Masoj hides on the hillside above {area:290}, south-west of Durnholde, on the way down to the blossoms."] = "Masoj versteckt sich am Hang über {area:290}, südwestlich von Burg Durnholde, auf dem Weg hinunter zu den Blüten.",
		["Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above {area:290}, south-east of the blossoms: use a vial at the top."] = "Masoj will, dass du eine Apothekerphiole auf drei Gipfeln platzierst. Der südliche ist die Hügelkuppe über {area:290}, südöstlich der Blüten: Benutze oben eine Phiole.",
		["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "Giftreihe unvollendet? Setze deine aktuelle Stufe im Klassen-Guide Gifte (Horde) fort; abgeschlossene Quests müssen nicht neu begonnen werden. Organisiere eine Gruppe für Gallywix, schließe die Folgequest von Hinott ab und kehre dann zu diesem Leveling-Guide zurück.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "Die Höfe östlich des Orts {area:287}. {npc:232} bestellt das Feld beim nördlichen Bauernhaus, {npc:2403} das weiter südöstlich; Landarbeiter und Bauern von Hillsbrad sind überall. {npc:2451} pflegt das Feld südlich der Höfe.",
		["The smithy"] = "Die Schmiede",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "Die Schmiede steht mitten im Ort {area:287}. {npc:2404} und seine Lehrlinge arbeiten an der Esse; die {object:1736} ist daneben gestapelt. {npc:2449} läuft die Straße nördlich davon entlang.",
		["The {object:556670} poster by the inn"] = "Das Plakat {object:556670} beim Gasthaus",
		["Train with {npc:3033}. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Trainiere bei {npc:3033}. Bevor du weiterfliegst, geben dir {npc:3024} und {npc:4721}, ein kurzes Stück östlich des Windreitermeisters, zwei Quests, die auf den Wegen der nächsten Guides erledigt werden; flieg dann weiter zum Wegekreuz, wo der nächste Guide beginnt.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "Westlich von Tarrens Mühle streifen Graubären, Waldmooskrabbler und Verhungernde Berglöwen auf dem Weg hinunter zu den Höfen durch die Hügel. Die Krabbler droppen {item:3477} selten; du brauchst nur eins.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272} ist dein Stützpunkt für diesen Guide: Der Ruhestein bringt dich zweimal hierher zurück. Alle stehen rund um den Dorfplatz.",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: Benutze eine Hälfte beim {area:2362}",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}: die Arbeiter auf den Feldern",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} in {area:2361} fliegt Druiden dorthin",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, im Apothekarium",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, in {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}: Befehle für {npc:270438}, auf dem Weg nach Burg Durnholde",
		["{npc:2238}'s ball and chain"] = "Kugel und Kette von {npc:2238}",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} ist der Hund von {npc:232}, beim nördlichen Bauernhaus im Gebiet {area:286}.",
		["{npc:2391}: Poisons"] = "{npc:2391}: Gifte",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}: {quest:97538}, das Dunkelkraut am {area:464} beim Sonnenfels",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} steht im {object:36070}.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}: {quest:1195}, die Phiole von den Lachenden Schwestern im {zone:1440}",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "Ein kurzes Stück nördlich der Lager der Galak führt die Höhle von {area:1557} hinab in ihre tiefste Kammer, wo die {object:20807} brennt. Benutze die {item:5868} daran und plündere dann sofort den {item:5869}: Die Flamme bleibt nur kurz aus, und wenn sie wieder auflodert, ist die Phiole verloren. Dann nach Osten zum Tafelberg von {npc:2986}.\nVorsicht: Zwei Flammenwachen der Galak (30) stehen bei der Kohlenpfanne und eine Zentaurenwache läuft durch die Höhle: Zieh sie einzeln weg, bevor du die Flamme löschst.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Zurück nach Süden zum Lager, dann hinauf nach {zone:1456} für den Flug nach {area:378}.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Zurück zu {npc:12867} im Holzfällerlager, an der Straße nach Norden zum Splintertreeposten.",
		["Class trainer"] = "Klassenlehrer",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Steig den Pfad hinauf auf den {area:2097}. {npc:10646} wird neben {npc:10896} (29) gefangen gehalten: Besiege zuerst die Wachen und {npc:10896}, befreie sie dann und beschütze sie auf dem Weg hinunter; unterwegs greifen dich Grimmtotem aus dem Hinterhalt an.",
		["Felmusk satyrs"] = "Satyrn der Teufelshufe",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "Flieg von Zoram'gar nach {area:1638}. Wenn du die Flugroute nicht kennst, flieg stattdessen nach {area:378} und geh nach Norden durch {zone:1412}.",
		["Fly to {area:378}"] = "Flieg nach {area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Folge der Hauptstraße nach Osten an {area:415} vorbei (Allianz: bleib auf der Straße). {npc:12678}, ein großer Grizzly, streift durch die Ruinen ({area:418}) südlich der Straße, westlich von {area:421}. Seine Pranke startet die nächste Jagdquest.",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "Geh von {area:2360} nach Nordosten zum Holzfällerlager der Warsong an der Straße: {npc:12867} steht dort.",
		["Galak centaurs"] = "Zentauren der Galak",
		["Gazebo"] = "Pavillon",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Toxinproben der Düsteranhöhe, von den Angenagten Leichnamen",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Bleib auf der Straße nach Osten. {npc:12858} wartet südwestlich vom Holzfällerlager der Warsong. Er und seine Grunzer stürmen den {area:2360}: Lass sie die Aggro ziehen und bleib bei {npc:12858}, bis {npc:12860} tot ist.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Töte den {npc:10720}, der für {npc:10638} kommt",
		["Laughing Sisters"] = "Lachende Schwestern",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "Nördlich des Lagers überrennen Spinnen die Grabstätte {area:17044}. Benutze den {item:273015} von {npc:264074} an den Angenagten Leichnamen; die Spinner lassen {item:273181} fallen. {npc:264082} sitzt am Nordende: Ihr {item:273658} startet {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "Nordwestlich vom Splintertreeposten lagern die Satyrn der Teufelshufe im Wald. Jeder Satyr kann Hörner fallen lassen.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp."] = "Auf dem Rückweg nach Nordosten zum Splintertreeposten: {npc:12676} streift durch die Wälder südöstlich vom Holzfällerlager der Warsong.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "Nur wenn {npc:10617} dir seinen Plan hinterlassen hat: {npc:10638} steht bei {area:2237}.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Fahr mit dem Aufzug hinunter und folge dann der Straße nach Osten durch die Schluchten zum {area:484}, einem Taurendorf oben auf den Tafelbergen. Sein Aufzug ist auf der Nordseite.",
		["Sapphires of Aku'Mai"] = "Saphire von Aku'Mai",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "Südlich von Raynewood liegt der Mondbrunnen in einer Senke westlich des Flusses, von der Straße aus schwer zu sehen; {area:421} liegt westlich davon. Benutze die {item:5867} am Mondbrunnen, um sie zu füllen.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Sprich mit {npc:3057} in {area:1638}: {quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Fahr mit dem Aufzug hinunter. Das Ei liegt in einem Nest am Schluchtboden an einer von drei Stellen: südöstlich der Tafelberge (52.3,55.2), östlich (56.4,50.4) oder südwestlich (37.6,56.1).",
		["Talk to {npc:3057}"] = "Sprich mit {npc:3057}",
		["The Earthen Ring"] = "Der Irdene Ring",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Die Furbolgs der Fäulnisklauen halten die Wälder östlich von {area:421}, südlich der Straße. Stell {item:16972} auf den {object:178206} und bewache es: Die Furbolgs kommen, um es niederzureißen. {npc:12918} kommt zuletzt; sein Totem fällt in den Korb.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him."] = "Die Lager der Galak füllen die Schlucht nördlich vom Freiwindposten; Späher, Zänker und Windhetzerinnen der Galak teilen sich jedes Lager. Ein einzelner {npc:10617} läuft einen langen Weg zwischen den Lagern: Triffst du ihn, töte ihn, seine Notiz startet eine Quest für den {area:2237}. Warte nicht auf ihn.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "Die Kichernden Schwestern, Dryaden, wandern durch {area:426} um die Wälder von {npc:12677}; eine von ihnen lässt die {item:5867} von {npc:4721} fallen, was mehrere Kills dauern kann.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Die Saphire sind blaue Kristalle an den Wänden der Tunnel zum Portal der {area:2797}, unterirdisch und außerhalb der Instanz: Schwimm aus der Grube hinab, unter der Mauer hindurch, in die Höhle. Die Satyrn und Naga in den Tunneln sind Elite: Eine Gruppe wird empfohlen. Die Kristalle erscheinen schnell wieder, du musst also nicht tief hinein.",
		["The Wanted poster beside {npc:10537}"] = "Der Steckbrief neben {npc:10537}",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "{quest:6503} (23-24), Nachtelfen, pirschen durch die Wälder südlich und südöstlich des Holzfällerlagers; sie sind getarnt, also halte nach ihnen Ausschau.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "Der Weg zu den Saphiren führt durch die versunkenen Ruinen am Nordende des Strands: Geh die Treppe hinunter in die Grube.",
		["Warsong lumber camp"] = "Holzfällerlager der Warsong",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "Westlich vom Freiwindposten liegen die Lager der Grimmtotem unterhalb vom {area:2097}. Die Geheimnotizen liegen in Dokumententruhen im südöstlichen, südwestlichen und nordwestlichen Lager.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "Westlich vom Mystralsee streift {npc:12678}, ein großer Grizzly, durch die Ruinen ({area:418}): Seine Pranke fällt jetzt für dich.",
		["for {npc:5901}, south of {area:392}: next guide"] = "für {npc:5901}, südlich von {area:392}: nächster Guide",
		["{area:2797} ruins"] = "Ruinen: {area:2797}",
		["{area:418} fountain"] = "Brunnen: {area:418}",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, von Spinnern der Düsteranhöhe",
		["{item:5867}, at the {object:20806}"] = "{item:5867}, am {object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}, von einer {npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}, an der {object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}, von der {object:20807}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, beim Windreitermeister",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "{npc:10428}s nächste Quest, Hochheiliges Feuer, endet in {zone:1456}, abseits dieser Route. Überspring sie.",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} von {npc:10617}, falls du ihm begegnest",
		["{npc:12676}, a big nightsaber, prowls the same woods further east, on the way north to Splintertree. Her claw starts the next hunt quest."] = "{npc:12676}, ein großer Nachtsäbler, streift weiter östlich durch dieselben Wälder, auf dem Weg nach Norden zum Splintertreeposten. Ihre Klaue startet die nächste Jagdquest.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, ein Schattenpanther, pirscht durch die Wälder um {area:426}, westlich vom Lager der Teufelshufe. Ihr Kopf startet die nächste Jagdquest.",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696} betreut das Jagdbrett in {area:428}, beim Flugmeister: Nimm {quest:6383} an und gib sie sofort wieder ab. {npc:12678}, {npc:12676} und {npc:12677} lassen ihre Trophäen erst danach fallen.",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: nur, wenn du die Handbuchseiten dabeihast",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} bietet als Nächstes eine Quest für die {area:2797} an; lass sie aus, außer du hast eine Gruppe.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, eine Ergänzung von Forever, steht am Westufer von {area:421} mit drei schnellen Drachentöter-Quests.",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} steht oben auf einem Tafelberg östlich der Lager der Galak. Für {quest:1149} geh über das Ende der Planken neben ihm hinaus: Du landest sicher.",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} steht neben {npc:4721}, östlich von {npc:2995}.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} steht ein kurzes Stück östlich von {npc:2995}.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}: {npc:4722} am {area:484}, später in diesem Guide",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} steht am {area:484}: Die gefüllte Phiole von {npc:4721} ist für ihn.",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}: die {object:20807} in {area:1557}, zwischen den Lagern der Galak",
		["{object:176344}, north-west camp"] = "{object:176344}, nordwestliches Lager",
		["{object:176344}, south-east camp"] = "{object:176344}, südöstliches Lager",
		["{object:176344}, south-west camp"] = "{object:176344}, südwestliches Lager",
		["{zone:1456}'s central rise"] = "Mittlere Anhöhe von {zone:1456}",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "Zurück zu den Feldern: Die Arbeiter von Hillsbrad schuften südlich der Bauernhäuser. Vorsicht: Ein fliehender Arbeiter, der das Rathaus erreicht, kann Verstärkung mitbringen; Verlangsamungen oder Wurzeln halten sie von der Flucht ab.",
		["Back to {area:272}"] = "Zurück nach {area:272}",
		["Back to {area:272}."] = "Zurück nach {area:272}.",
		["Below ground"] = "Unter der Erde",
		["Boulderfist camp"] = "Lager der Felsfäuste",
		["Daggerspine naga"] = "Naga der Säbelflossen",
		["Daggerspine shore"] = "Ufer der Säbelflossen",
		["Drull's ball and chain"] = "Drulls Kugel und Kette",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["For characters of 29 to 33, but most quests here are level 32-34, a few up to 36: on purpose, for their experience. The Syndicate, {area:279}'s guards and the Boulderfist ogres are 31-35, so pull them one at a time."] = "Für Charaktere der Stufe 29 bis 33, aber die meisten Quests hier sind Stufe 32-34, einige bis 36: mit Absicht, wegen ihrer Erfahrung. Das Syndikat, die Wachen von {area:279} und die Oger der Felsfäuste sind 31-35, also zieh sie einzeln.",
		["From {area:271} head north past {area:272} and follow the road on into the Alterac foothills. {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "Geh von {area:271} nach Norden an {area:272} vorbei und folge der Straße weiter in die Ausläufer von Alterac. {quest:535} wartet beim Lager des Syndikats. Er bietet seinen Auftrag nur an, solange du „Unterwanderung“ von {npc:2229} dabeihast: Gib ihm gleich das Starkbier, und seine Belohnung ist das Schreiben des Syndikats, das Krusk will. Ein Schreiben des Syndikats von hier tut es auch: Hast du eins in deinen Taschen, überspringt der Guide {quest:535}.",
		["Head back south down the road to {area:272}."] = "Geh die Straße zurück nach Süden bis {area:272}.",
		["Hillsbrad Peasants"] = "Arbeiter von Hillsbrad",
		["Only if {quest:535}'s missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one. Careful: at 31-32 they are still above you and stand close together, with Wizards (34-35) among them: pull one at a time from the camp's edge."] = "Nur wenn das Schreiben von {quest:535} nicht bei dir gelandet ist: Die Schleicher und Diebe des Syndikats (32-34) um die Lager westlich der Straße tragen auch Schreiben; etwa jeder dritte lässt eins fallen. Vorsicht: Mit 31-32 sind sie noch über dir und stehen dicht beieinander, mit Hexern (34-35) dazwischen: Zieh sie einzeln vom Rand des Lagers.",
		["Shindigger keg"] = "Fässchen Shindigger-Starkbier",
		["South-east of Tarren Mill. Drull and {npc:2238} are chained in the keep's courtyard buildings: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks."] = "Südöstlich von Tarrens Mühle. Drull und {npc:2238} sind in den Gebäuden im Hof der Burg angekettet: {npc:2427} trägt {item:3467} und {npc:2428} {item:3499}, beide in der Burg. Töte sie und öffne dann beide Schlösser.",
		["South-west, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills west of {area:272}; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but at 29-30 they hit hard and come in pairs."] = "Im Südwesten füllen die Höhlenyetis und Wilden Yetis (30-32) {area:277} in den Hügeln westlich von {area:272}; etwa jeder sechzehnte trägt die Rute. Bleib in diesen Höhlen: Die Berg- und Riesenyetis (32-34) der Höhle weiter nördlich tragen sie auch, aber mit 29-30 schlagen sie hart zu und kommen zu zweit.",
		["Syndicate missives"] = "Schreiben des Syndikats",
		["The smithy"] = "Die Schmiede",
		["The third flame burns in the smaller cave up in the hills north of the caverns.\nCareful: Giant and Mountain Yetis (32-34) stand around the flame, often in pairs, and Frostmaw, a rare yeti (37), roams nearby. At 30-31 they are over your level: pull the yetis one at a time from the cave mouth before you use the Rod, and watch for Frostmaw before you go in."] = "Die dritte Flamme brennt in der kleineren Höhle oben in den Hügeln nördlich der Höhlen.\nVorsicht: Riesen- und Bergyetis (32-34) stehen um die Flamme, oft zu zweit, und Frostrachen, ein seltener Yeti (37), streift in der Nähe umher. Mit 30-31 sind sie über deiner Stufe: Zieh die Yetis einzeln vom Höhleneingang, bevor du die Rute benutzt, und achte auf Frostrachen, bevor du hineingehst.",
		["The {area:279} crater's eastern rim"] = "Der Ostrand des Kraters von {area:279}",
		["Torn Fin beach"] = "Strand der Fetzenflossen",
		["Torn Fin murlocs"] = "Murlocs der Fetzenflossen",
		["Town hall"] = "Rathaus",
		["Train"] = "Trainieren",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Trainiere, solange du in {zone:1458} bist: Die Lehrer stehen im {object:36070}, im {object:36073} und im {object:36082} (Paladine: {npc:260093}).",
		["Train your new spells."] = "Lerne deine neuen Zauber.",
		["West across the foothills to {area:287} town: the smithy stands in the middle of it. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it."] = "Nach Westen über die Ausläufer zum Ort {area:287}: Die Schmiede steht in seiner Mitte. {npc:2404} und seine Lehrlinge arbeiten an der Esse; die {object:1736} ist daneben gestapelt.",
		["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere."] = "Nach Westen an den Hügeln vorbei zu den Höfen östlich des Orts {area:287}. {npc:232} bestellt das Feld beim nördlichen Bauernhaus, {npc:2403} das weiter südöstlich; Landarbeiter und Bauern sind überall.",
		["You missed Darthalia's first errands, from the 22-25 {area:287} guide: they come first now. They are a few levels below you and quick, and they open the rest of the {quest:527} in this guide."] = "Du hast Darthalias erste Aufträge aus dem Guide {area:287} 22-25 verpasst: Sie kommen jetzt zuerst. Sie liegen ein paar Stufen unter dir, gehen schnell und öffnen den Rest von {quest:527} in diesem Guide.",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}: Auktionshaus oder ein Alchemist, für {quest:515}.",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, für {npc:2333}",
		["{npc:2229} wants his two scouts freed from {area:275} before he trusts you with Infiltration."] = "{npc:2229} will, dass du seine zwei Späher aus {area:275} befreist, bevor er dir „Unterwanderung“ anvertraut.",
		["{npc:2238}'s ball and chain"] = "Kugel und Kette von {npc:2238}",
		["{npc:2792}, by the gate"] = "{npc:2792}, am Tor",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Grommash Hold, falls du sie dabeihast",
		["{zone:1458} trainers"] = "Lehrer in {zone:1458}",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back south to {npc:11863}'s tower."] = "Zurück nach Süden zu {npc:11863}s Turm.",
		["Clam beds"] = "Muschelbänke",
		["Fly to {area:460}"] = "Flieg nach {area:460}",
		["Fly to {area:484}"] = "Flieg zum {area:484}",
		["Head north along the coast, then inland to the ruined tower of {area:2405}: {npc:11863} waits inside. The coast's clams and naga come after {area:599}, on one walk north to {area:2406}."] = "Geh die Küste entlang nach Norden, dann landeinwärts zum verfallenen Turm von {area:2405}: {npc:11863} wartet darin. Die Muscheln und Naga der Küste kommen nach {area:599}, auf einem Weg nach Norden bis zur {area:2406}.",
		["Keep north to {area:598}. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time. Any Slitherblade can drop {item:15881}."] = "Geh weiter nach Norden zum {area:598}. Die Myrmidonen, Naga und Zauberinnen der Schlangenschuppen halten den Strand; zieh sie einzeln. Jede Schlangenschuppe kann {item:15881} droppen.",
		["Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}. He is well above you: rest to full first. {object:177786} stands on the shore beside the statue: open it with both keys."] = "Schwimm vor der äußersten Nordspitze hinaus zur {area:2406} und benutze den {item:15766} an der {object:177673}: {npc:12369} (38) erhebt sich; töte ihn für das {quest:6027}. Er ist deutlich stärker als du: Ruh dich vorher voll aus. {object:177786} steht am Ufer neben der Statue: Öffne sie mit beiden Schlüsseln.",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "Der Zeppelin landet am Turm vor dem Haupttor von {zone:1454}. {npc:5639} läuft durch die Gasse: Wenn er nicht am Pfeil ist, such ihn in ihren Straßen im Südwesten. {npc:5640} steht im {object:172961} auf der Westseite der Stadt.",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "Geh nach Westen zum Ufer. Riesen-Weichpanzermuscheln liegen im Flachwasser, und die Wütenden Riffkriecher laufen am Strand: Jede Muschel, die du am Meeresgrund öffnest, und manche Kriecher geben eine {item:15874}. Öffne jede davon in deinen Taschen für ihr Fleisch.\nDie Trockenschnappkriecher und -zwicker am selben Strand tragen {item:15878}, etwa jeder siebte.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, an {object:177673}",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, von den Trockenschnappkrabben",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, von den Schlangenschuppen-Naga",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}s nächster Auftrag schickt dich zu einem Dämonenfürsten mit Elitewache: Überspring ihn.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} steht im {object:172957}.",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} und dein {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} startet auch Elementare Hilfe ({area:1717}), die Kette (33-40) zu The Tempest's Weapons: forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: dein {item:5178}",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} liegt knapp südwestlich von {npc:11863}s Turm auf dem Boden, auf dem Weg hinunter zum Ufer: Lies es. Seine beiden Schlüssel droppen nur, solange du die Quest hast.",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Zurück nach Norden zum Lager.",
		["Back to {object:3202}."] = "Zurück nach {object:3202}.",
		["Boat to {area:35}"] = "Schiff nach {area:35}",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Dizzywigs Teile gehen zurück zu Kravel in {area:439}, abseits der Route: Lass sie liegen.",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of {quest:338} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "Folge der Straße von {object:3202} nach Norden; Nesingwarys Jagdlager liegt auf dem Hügel nordöstlich des Flusses. {npc:773} will, dass es untersucht wird: Geh zwischen den Zelten umher. Ab hier behältst du jede Seite von {quest:338}, die du erbeutest: {npc:716} nimmt sie bei deinem nächsten Besuch im Schlingendorntal.",
		["Green Hills pages"] = "Seiten der Grünen Hügel",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "Verlass {area:35} durch den Tunnel und folge der Straße nach Norden nach {object:3202}, dem Orclager auf der Westseite des Tals. Bleib auf der Straße: Der Dschungel daneben liegt über deiner Stufe.",
		["Mosh'Ogg camp"] = "Lager der Mosh'Ogg",
		["Nesingwary's camp"] = "Lager von Nesingwary",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "Nordwestlich von Grom'gol liegt {area:104} unter Wasser vor der Küste. Die {item:4094} liegt auf dem Meeresgrund bei den versunkenen Ruinen; achte auf deinen Atem und die Murlocs.",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "Flusskrokilisken liegen am Fluss unterhalb des Lagers. Junge Schlingendorntiger streifen westlich des Lagers umher, junge Panther östlich davon. Geh westlich am Lager vorbei. Schlingendornraptoren (33-34) jagen auf den Lichtungen, und die Trolle der Blutskalpe halten die Ruinen an der Küste: Jeder Blutskalp kann einen Hauer droppen. Ein {item:4614} ist ein sehr seltener Drop von ihnen: Falls einer droppt, lies ihn. Vorsicht: In den Trolllagern patrouillieren viele Mobs, daher greifen oft weitere Trolle in einen Kampf ein.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Die Schattentatzenpanther kommen viel später, bei {object:3202}",
		["from {npc:4723}"] = "von {npc:4723}",
		["{area:2408} flight master"] = "Flugmeister: {area:2408}",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "Zuerst {area:35}: Das Schiff der Goblins fährt von {area:392} dorthin, und alle Quests aus {area:35} führen in den Norden des Tals, in den du dann hinaufläufst.",
		["{item:5852}, in {object:20691}"] = "{item:5852}, in {object:20691}",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464} steht mitten in {object:3202}, {npc:2497} beim Zeppelinturm, {npc:2465} neben dem Flugmeister.",
		["{npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs beside the flight master."] = "{npc:2495}s Laden ist im Gebäude östlich des Gasthauses; {npc:2498} ist im Erdgeschoss des Gasthauses, {npc:2496}, {npc:737} und {npc:773} oben neben dem Flugmeister.",
		["{npc:2496}, upstairs"] = "{npc:2496}, oben",
		["{npc:2496}: Cozzle's footlocker is at {area:37}, later in this guide"] = "{npc:2496}: Cozzles Schließkiste steht am {area:37}, später in diesem Guide",
		["{npc:2496}: for Pozzik at the {area:2240}, on the way to {zone:1446} around level 43"] = "{npc:2496}: für Pozzik an der {area:2240}, auf dem Weg nach {zone:1446} um Stufe 43",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: für das Arathihochland, später auf der Route",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} wartet oben im Haus beim Flugmeister; {quest:1111} steht auf den Docks neben dem Schiff.",
		["{npc:3391}, upstairs"] = "{npc:3391}, oben",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}: für {npc:4631} in {area:35}, wohin das Schiff fährt",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631} steht auf dem Pier, an dem das Schiff anlegt. {npc:2495}s Laden ist im Gebäude östlich des Gasthauses; {npc:2498} ist im Erdgeschoss des Gasthauses, {npc:2496}, {npc:737} und {npc:773} oben, {npc:2858}, der Flugmeister, auf dem oberen Deck.",
		["{npc:4631}, on the pier"] = "{npc:4631}, auf dem Pier",
		["{npc:4723} (38) is inside the Venture Co. house on {area:37}'s west shore, among the geologists: his key opens {object:20691} in the same house, which holds the blueprints for {npc:2496}."] = "{npc:4723} (38) ist im Haus der Venture Co. am Westufer des {area:37}, zwischen den Geologen: Sein Schlüssel öffnet {object:20691} im selben Haus, in der die Baupläne für {npc:2496} liegen.",
		["{quest:1111}, on the docks"] = "{quest:1111}, auf den Docks",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:378}"] = "Flieg nach {area:378}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Head east back to the {area:497}."] = "Geh nach Osten zurück zum {area:497}.",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Geh von {area:378} entlang der Straße nach Osten in den Sumpf. Das ausgebrannte {area:403} steht direkt hinter der Grenze neben ihr; der Schild, das Abzeichen und die Hufspuren sind in und neben der Ruine.",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Geh nach Norden zum {area:502}. Stinki steht am Fuß des Hügels; eskortiere ihn, während er Sumpfbohnenblätter direkt südlich davon sammelt.",
		["Head south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "Geh von {area:392} an der Küste nach Süden zu {area:720}. {npc:6236} steht an der Arena: Betritt das Gitter, um den Kampf zu beginnen; die Herausforderer kommen einzeln, dann {npc:6238} (33).",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Jarl wohnt im {area:497} südöstlich vom {area:502}.",
		["Mirefin murlocs"] = "Murlocs der Schlammflossen",
		["South-east from the manor to {area:513}: the {object:20925} lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57."] = "Vom Gutshaus nach Südosten zu {area:513}: {object:20925} liegt auf dem Meeresgrund vor den Docks an der Ostseite der Insel. Schwimm hinein und wieder hinaus und halte dich von den Piers und der Stadt fern: Die Wachen von Theramore sind Stufe 53-57.",
		["Stinky Ignatz"] = "Stinki Ignatz",
		["Swamp Eye Jarl"] = "Sumpfauge Jarl",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "Nimm an der Gabelung die Straße nach Norden zum Ogerdorf Brackenwall.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Die Murlocs der Schlammflossen drängen sich an der Küste östlich und nordöstlich vom {area:502}; jede Art lässt Köpfe fallen.",
		["The {area:2657}"] = "Das {area:2657}",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "nur, wenn du ein {item:3853} dabeihast ({skill:164} oder Auktionshaus)",
		["{area:2408} flight master"] = "Flugmeister: {area:2408}",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, für Sumpfauge Jarl",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446} steht unterhalb von Gazlowes Haus beim Flugmeister, in Richtung der Docks.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, am Südrand des Dorfs, wo die Straße hereinkommt",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983} wartet im Morast ({area:2302}) östlich des Dorfs. Folge ihm zu Reethe und halte ihn im ausbrechenden Kampf am Leben.",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} wartet im Goblinlager auf der Westseite des Friedhofs ({area:596}).",
		["{object:20985}, beside the manor"] = "{object:20985}, neben dem Anwesen",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, jetzt wo {npc:4791} den Bericht gelesen hat",
		["{zone:1454} flight master"] = "Flugmeister: {zone:1454}",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "Zurück nach {area:321}",
		["Below ground"] = "Unter der Erde",
		["Fleshstalker raptors"] = "Hochlandfleischpirscher",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["Head back east to {area:272}."] = "Geh zurück nach Osten zu {area:272}.",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Hochlandfleischpirscher (36-37) jagen im südlichen Hochland, ein Rudel nördlich von {area:316} und ein weiteres auf der Ebene westlich davon. Zieh sie einzeln.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Der innere Kreis liegt südlich des westlichen Kreises, östlich von Stromgarde.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:1763} poster by the inn"] = "Das Plakat {object:1763} beim Gasthaus",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} liegen am hinteren Ende der Schlucht.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Trainiere, solange du in {zone:1458} bist: Die Lehrer stehen im {object:36070}, im {object:36073} und im {object:36082} (Paladine: {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "Westlich der Bucht halten die Räuber und Zauberhexerinnen der Säbelflossen (38-40) das Ufer: Zieh sie einzeln. Die beiden Wracks liegen davor im seichten Wasser, die Karten und Logbücher darin; die Edelsteine liegen um die Wracks auf dem Meeresgrund.",
		["Zeppelin to {zone:1458}"] = "Zeppelin nach {zone:1458}",
		["{npc:2792}, by the gate"] = "{npc:2792}, am Tor",
		["{zone:1458} trainers"] = "Lehrer in {zone:1458}",
} end)()
