		["{npc:15350}: {quest:98887} again, 100 for 3 marks"] = "{npc:15350}: wieder {quest:98887}, 100 für 3 Abzeichen",
		["{npc:15351}: 100 for 3 marks"] = "{npc:15351}: 100 für 3 Abzeichen",
		["{npc:15351}: {quest:98895} again, 100 for 3 marks"] = "{npc:15351}: wieder {quest:98895}, 100 für 3 Abzeichen",
		["{npc:263569}: Exalted rewards"] = "{npc:263569}: Belohnungen bei Ehrfürchtig",
